                {/* Speed */}
                <div className={`bg-stone-800/50 border rounded-lg p-4 flex flex-col items-center justify-center space-y-2 md:col-span-2 ${getOverride('speed') ? 'border-gold/50' : 'border-stone-700/50'}`}>
                    <div className="flex items-center gap-1.5">
                        <RulesTooltip term="Action">
                            <span className="text-xs text-stone-400 uppercase font-bold tracking-wider cursor-help">Walking Speed</span>
                        </RulesTooltip>
                        {getOverride('speed') && <span className="text-gold text-[10px]" title={getOverride('speed')!.reason}>⚙️</span>}
                    </div>
                    <input
                        type="text" value={getVal('speed', '30 ft')}
                        onChange={e => onChange('speed', e.target.value)}
                        className={`w-full max-w-[120px] bg-transparent text-center text-2xl font-bold focus:outline-none border-b border-transparent focus:border-gold ${getOverride('speed') ? 'text-gold' : 'text-parchment focus:text-gold'}`}
                        placeholder="30 ft"
                    />
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Health */}
                <div className="bg-stone-900/40 border-t-2 border-blood/20 shadow-[0_0_20px_rgba(153,27,27,0.05)] rounded-xl p-6 space-y-6 relative overflow-hidden group hover:border-blood/40 transition-colors col-span-1 md:col-span-2">
                    <Heart size={160} className="text-blood opacity-5 absolute -right-6 -bottom-6 group-hover:scale-[1.15] transition-transform duration-700 pointer-events-none" />

                    <h3 className="font-cinzel text-blood-light text-xl border-b border-blood/20 pb-2 drop-shadow-sm flex items-center gap-2 relative z-10 w-48">
                        <Heart size={18} className="text-blood" fill="currentColor" fillOpacity={0.2} />
                        Hit Points
                    </h3>

                    <div className="grid grid-cols-2 gap-8 relative z-10 mt-10">
                        <div className="space-y-1 relative">
                            <label className="text-[10px] text-stone-500 uppercase font-bold tracking-widest absolute -top-5 left-0">Current HP</label>
                            <input
                                type="number" value={data.currentHp}
                                onChange={e => onChange('currentHp', parseInt(e.target.value) || 0)}
                                className="w-full bg-transparent border-b border-stone-700/80 hover:border-blood text-center text-blood font-bold text-5xl focus:border-blood outline-none transition-colors py-2 focus:bg-stone-950/30 rounded-t"
                            />
                        </div>
                        <div className="space-y-1 relative h-full flex items-end">
                            <label className="text-[10px] text-stone-500 uppercase font-bold tracking-widest absolute -top-5 left-0">Max HP</label>
                            <input
                                type="number" value={data.maxHp}
                                onChange={e => onChange('maxHp', parseInt(e.target.value) || 0)}
                                className="w-full bg-transparent border-b border-stone-700/50 hover:border-stone-400 text-center text-stone-300 font-bold text-2xl focus:border-gold outline-none transition-colors py-2 focus:bg-stone-950/30 rounded-t"
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-8 pt-6 border-t border-stone-800/60 relative z-10">
                        <div className="space-y-1 relative">
                            <label className="text-[10px] text-stone-500 uppercase font-bold tracking-widest absolute -top-5 left-0">Temp HP</label>
                            <input
                                type="number" value={data.tempHp || ''}
                                onChange={e => onChange('tempHp', parseInt(e.target.value) || 0)}
                                className="w-full bg-transparent border-b border-stone-700/50 hover:border-blue-500/50 text-center text-blue-400 font-bold focus:border-blue-500 outline-none transition-colors py-1.5 focus:bg-stone-950/30 rounded-t"
                                placeholder="0"
                            />
                        </div>
                        <div className="space-y-1 relative">
                            <label className="text-[10px] text-stone-500 uppercase font-bold tracking-widest absolute -top-5 left-0">Hit Dice</label>
                            <input
                                type="text" value={data.hitDice}
                                onChange={e => onChange('hitDice', e.target.value)}
                                className="w-full bg-transparent border-b border-stone-700/50 hover:border-stone-400 text-center text-parchment font-bold focus:border-gold outline-none transition-colors py-1.5 focus:bg-stone-950/30 rounded-t"
                                placeholder="e.g. 1d10"
                            />
                        </div>
                    </div>
                </div>

                {/* Status / Death Saves */}
                <div className="bg-stone-900/40 border border-stone-800/60 rounded-xl p-6 space-y-6 shadow-inner col-span-1 md:col-span-2">
                    <div className="flex items-center justify-between border-b border-stone-700/50 pb-2 mb-4">
                        <h3 className="font-cinzel text-gold text-xl flex items-center gap-2 drop-shadow-sm">
                            <Skull size={18} className="text-stone-500" />
                            Status & Conditions
                        </h3>
                        <div className="flex items-center gap-2">
                            <button onClick={() => setIsSearchOpen(true)} className="flex items-center justify-center w-7 h-7 bg-stone-800/80 text-arcane-light rounded-md border border-stone-700 hover:border-arcane/50 hover:bg-stone-800 transition-colors shadow-sm" title="Search 5e.tools">
                                <Search size={14} />
                            </button>
                            <button onClick={addCondition} className="flex items-center justify-center w-7 h-7 bg-stone-800/80 text-parchment rounded-md border border-stone-700 hover:border-gold/50 hover:bg-stone-800 transition-colors shadow-sm" title="Add Custom Condition">
                                <Plus size={14} />
                            </button>
                        </div>
                    </div>

                    {/* Conditions */}
                    {data.conditions.length > 0 && (
                        <div className="space-y-1.5 mb-6 max-h-[160px] overflow-y-auto custom-scrollbar pr-1">
                            {data.conditions.map(c => (
                                <div key={c.id} className="flex items-center justify-between bg-stone-950/50 border border-stone-800/80 rounded-md px-3 py-2 group focus-within:border-gold/50 transition-colors hover:bg-stone-900/80">
                                    <div className="flex items-center gap-3 flex-1 overflow-hidden">
                                        <RulesTooltip term={c.name}>
                                            <Skull size={14} className="text-blood shrink-0" />
                                        </RulesTooltip>
                                        <input
                                            type="text" value={c.name}
                                            onChange={e => updateCondition(c.id, { name: e.target.value })}
                                            className="w-full bg-transparent text-sm text-stone-300 font-bold outline-none focus:text-parchment"
                                            placeholder="Condition Name"
                                        />
                                    </div>
                                    <div className="flex items-center gap-1 shrink-0">
                                        <InfoTooltip query={c.name} />
                                        <button onClick={() => removeCondition(c.id)} className="text-stone-600 hover:text-blood/80 opacity-0 group-hover:opacity-100 p-1.5 rounded-md hover:bg-stone-800 transition-all" title="Remove Condition">
                                            <Trash2 size={14} />
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-2">
                        <div className="space-y-3 relative">
                            <label className="text-[10px] text-stone-500 uppercase font-bold tracking-widest absolute -top-5 left-0">Death Saves</label>
                            <div className="flex justify-between items-center bg-stone-950/40 p-2.5 rounded-lg border border-stone-800/50 h-10 shadow-inner">
                                <div className="flex items-center gap-2">
                                    <span className="text-[10px] text-stone-500 uppercase font-bold tracking-wider w-12 pt-0.5">Success</span>
                                    <div className="flex items-center gap-1.5">
                                        {[1, 2, 3].map(num => (
                                            <button
                                                key={`succ-${num}`}
                                                onClick={() => onChange('deathSaves', { ...data.deathSaves, successes: data.deathSaves.successes === num ? num - 1 : num })}
                                                className={`w-3.5 h-3.5 rounded-full border transition-all ${data.deathSaves.successes >= num ? 'bg-green-500 border-green-400 shadow-[0_0_8px_rgba(34,197,94,0.4)] scale-110' : 'bg-stone-900 border-stone-700 hover:border-green-500/50 hover:bg-stone-800'
                                                    }`}
                                            />
                                        ))}
                                    </div>
                                </div>
                                <div className="w-px h-6 bg-stone-800/80 mx-2"></div>
                                <div className="flex items-center gap-2">
                                    <span className="text-[10px] text-stone-500 uppercase font-bold tracking-wider w-12 text-right pt-0.5">Failure</span>
                                    <div className="flex items-center gap-1.5">
                                        {[1, 2, 3].map(num => (
                                            <button
                                                key={`fail-${num}`}
                                                onClick={() => onChange('deathSaves', { ...data.deathSaves, failures: data.deathSaves.failures === num ? num - 1 : num })}
                                                className={`w-3.5 h-3.5 rounded-full border transition-all ${data.deathSaves.failures >= num ? 'bg-blood border-red-400 shadow-[0_0_8px_rgba(153,27,27,0.4)] scale-110' : 'bg-stone-900 border-stone-700 hover:border-red-900/50 hover:bg-stone-800'
                                                    }`}
                                            />
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-3 relative">
                            <label className="text-[10px] text-stone-500 uppercase font-bold tracking-widest absolute -top-5 left-0">Exhaustion Level</label>
                            <div className="flex gap-1 justify-between bg-stone-950/40 p-1.5 rounded-lg border border-stone-800/50 h-10 shadow-inner">
                                {[0, 1, 2, 3, 4, 5, 6].map(level => (
                                    <button
                                        key={`exh-${level}`}
                                        onClick={() => onChange('exhaustion', level)}
                                        className={`flex-1 rounded-md border font-bold text-xs transition-all flex items-center justify-center ${data.exhaustion === level
                                            ? level === 6 ? 'bg-blood border-red-400 text-white shadow-[0_0_10px_rgba(153,27,27,0.5)]' : 'bg-stone-700 border-stone-500 text-parchment shadow-sm'
                                            : 'bg-transparent border-transparent text-stone-600 hover:bg-stone-800/80 hover:text-stone-400'
                                            }`}
                                        title={level === 6 ? 'Death' : `Level ${level}`}
                                    >
                                        {level === 0 ? '-' : level}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <FiveEToolsModal
                isOpen={isSearchOpen}
                onClose={() => setIsSearchOpen(false)}
                initialCategory="Conditions"
                fixedCategory={true}
                onImport={(item, cat) => {
                    if (cat === 'Conditions') {
                        onChange('conditions', [...data.conditions, { id: crypto.randomUUID(), name: item.name, description: item.description }]);
                    }
                }}
            />
        </div>
    );
}

import { Character } from '../../../types/character';
import { useState } from 'react';
import { FiveEToolsModal, Category } from '../../common/FiveEToolsModal';
import { ChoiceWizardModal } from '../../common/ChoiceWizardModal';
import { buildRaceWizard, buildClassWizard, buildBackgroundWizard, ImportWizardData } from '../../../engine/importWizardBuilder';
import { is2024Source } from '../../../engine/fiveEToolsParser';
import { detectFixedProficiencies, resolveAllChoices } from '../../../engine/rulesChoiceEngine';
import { DMOverridePanel } from './DMOverridePanel';

interface Props {
    data: Character;
    onChange: (field: keyof Character, value: any) => void;
}

export function CoreTab({ data, onChange }: Props) {
    const [searchCategory, setSearchCategory] = useState<Category | null>(null);
    const [wizardData, setWizardData] = useState<ImportWizardData | null>(null);
    const [pendingLangs, setPendingLangs] = useState<string>('');
    const [pendingSkills, setPendingSkills] = useState<{ name: string, proficient: boolean }[]>([]);

    const calculatePendingProficiencies = (item: any, category: Category) => {
        const langs = data.languages ? data.languages.split(',').map(l => l.trim()).filter(Boolean) : [];
        const skills = [...data.skills];

        if (category === 'Races' || category === 'Backgrounds') {
            // Fixed Languages
            if (item.languageProficiencies && item.languageProficiencies.length > 0) {
                const lp = item.languageProficiencies[0];
                Object.keys(lp).forEach(langKey => {
                    if (lp[langKey] === true) {
                        const langName = langKey.charAt(0).toUpperCase() + langKey.slice(1);
                        if (!langs.includes(langName)) langs.push(langName);
                    }
                });
            }

            // Fixed Skills
            if (item.skillProficiencies && item.skillProficiencies.length > 0) {
                item.skillProficiencies.forEach((sp: any) => {
                    const fixed = Object.keys(sp).filter(k => sp[k] === true);
                    fixed.forEach(s => {
                        const index = skills.findIndex(sk => sk.name.toLowerCase() === s.toLowerCase());
                        if (index >= 0) skills[index] = { ...skills[index], proficient: true };
                    });
                });
            }

            // FALLBACK Scanning (Captures Common and other text-only proficiencies)
            const is2024 = is2024Source(item.source);
            const { languages, skills: detectedSkills } = detectFixedProficiencies(item, is2024);
            languages.forEach(l => {
                if (!langs.includes(l)) langs.push(l);
            });
            detectedSkills.forEach(s => {
                const index = skills.findIndex(sk => sk.name.toLowerCase() === s.toLowerCase());
                if (index >= 0) skills[index] = { ...skills[index], proficient: true };
            });
        }

        setPendingLangs(langs.join(', '));
        setPendingSkills(skills);
    };

    const handleImport = (item: any, category: Category) => {
        calculatePendingProficiencies(item, category);
        if (category === 'Races') {
            setWizardData(buildRaceWizard(item));
        } else if (category === 'Classes') {
            setWizardData(buildClassWizard(item));
        } else if (category === 'Backgrounds') {
            setWizardData(buildBackgroundWizard(item));
        } else if (category === 'Subclasses') {
            // Subclass doesn't strictly need a wizard for now, just apply it
            onChange('subclass', item.name);
            onChange('importedData', { ...data.importedData, subclass: item });
            setSearchCategory(null);
        }
    };

    const handleWizardComplete = async (selections: Record<string, any[]>) => {
        if (!wizardData) return;

        const { type, originalData } = wizardData;

        // Use the rulesChoiceEngine to resolve all choices and character updates
        const updatedChar = await resolveAllChoices(data, selections, originalData, type as any);

        // Batch update character fields that changed
        Object.keys(updatedChar).forEach(key => {
            const k = key as keyof Character;
            if (JSON.stringify(data[k]) !== JSON.stringify(updatedChar[k])) {
                onChange(k, updatedChar[k]);
            }
        });

        // Special handling for header fields
        const newImportedData = { ...data.importedData };
        if (type === 'class') {
            newImportedData.class = originalData;
            onChange('className', originalData.name);
            if (originalData.hd) onChange('hitDice', `1d${originalData.hd.faces}`);
            if (originalData.spellcastingAbility) onChange('spellcastingAbility', originalData.spellcastingAbility);
            if (originalData.savesRaw && Array.isArray(originalData.savesRaw)) {
                onChange('savingThrows', originalData.savesRaw.map((s: string) => s.toLowerCase()));
            }
        } else if (type === 'race') {
            newImportedData.race = originalData;
        } else if (type === 'background') {
            newImportedData.background = originalData;
        }
        onChange('importedData', newImportedData);

        setWizardData(null);
        setSearchCategory(null);
    };

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 animate-in fade-in">
            <div className="space-y-1">
                <label className="text-[10px] text-stone-500 uppercase font-bold tracking-wider">Alignment</label>
                <input type="text" value={data.alignment} onChange={e => onChange('alignment', e.target.value)} className="w-full bg-transparent border-b border-stone-700/50 hover:border-stone-500 px-1 py-1 text-parchment focus:border-gold outline-none transition-colors" placeholder="Neutral Good" />
            </div>

            <div className="space-y-1 lg:col-span-2">
                <label className="text-[10px] text-stone-500 uppercase font-bold tracking-wider">Player Name</label>
                <input type="text" value={data.playerName} onChange={e => onChange('playerName', e.target.value)} className="w-full bg-transparent border-b border-stone-700/50 hover:border-stone-500 px-1 py-1 text-parchment focus:border-gold outline-none transition-colors" placeholder="Your Name" />
            </div>

            <div className="col-span-full pt-4 space-y-4">
                <DMOverridePanel data={data} onChange={onChange} />
            </div>

            <div className="col-span-full pt-4 space-y-4">
                <h3 className="text-gold font-cinzel text-xl border-b border-stone-700/50 pb-2 mb-4 drop-shadow-sm">Personality & Flavor</h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1 relative group">
                        <label className="text-[10px] text-stone-500 uppercase font-bold tracking-wider absolute -top-2 left-2 bg-stone-900/90 px-1 z-10 transition-colors group-focus-within:text-gold">Personality Traits</label>
                        <textarea value={data.personalityTraits || ''} onChange={e => onChange('personalityTraits', e.target.value)} className="w-full h-24 bg-stone-900/30 border border-stone-700/50 hover:border-stone-500 rounded-md px-3 py-3 text-parchment text-sm resize-none focus:border-gold outline-none transition-colors shadow-inner" />
                    </div>
                    <div className="space-y-1 relative group">
                        <label className="text-[10px] text-stone-500 uppercase font-bold tracking-wider absolute -top-2 left-2 bg-stone-900/90 px-1 z-10 transition-colors group-focus-within:text-gold">Ideals</label>
                        <textarea value={data.ideals || ''} onChange={e => onChange('ideals', e.target.value)} className="w-full h-24 bg-stone-900/30 border border-stone-700/50 hover:border-stone-500 rounded-md px-3 py-3 text-parchment text-sm resize-none focus:border-gold outline-none transition-colors shadow-inner" />
                    </div>
                    <div className="space-y-1 relative group">
                        <label className="text-[10px] text-stone-500 uppercase font-bold tracking-wider absolute -top-2 left-2 bg-stone-900/90 px-1 z-10 transition-colors group-focus-within:text-gold">Bonds</label>
                        <textarea value={data.bonds || ''} onChange={e => onChange('bonds', e.target.value)} className="w-full h-24 bg-stone-900/30 border border-stone-700/50 hover:border-stone-500 rounded-md px-3 py-3 text-parchment text-sm resize-none focus:border-gold outline-none transition-colors shadow-inner" />
                    </div>
                    <div className="space-y-1 relative group">
                        <label className="text-[10px] text-stone-500 uppercase font-bold tracking-wider absolute -top-2 left-2 bg-stone-900/90 px-1 z-10 transition-colors group-focus-within:text-gold">Flaws</label>
                        <textarea value={data.flaws || ''} onChange={e => onChange('flaws', e.target.value)} className="w-full h-24 bg-stone-900/30 border border-stone-700/50 hover:border-stone-500 rounded-md px-3 py-3 text-parchment text-sm resize-none focus:border-gold outline-none transition-colors shadow-inner" />
                    </div>
                </div>
            </div>

            <FiveEToolsModal
                isOpen={searchCategory !== null}
                onClose={() => setSearchCategory(null)}
                initialCategory={searchCategory || 'Classes'}
                fixedCategory={true}
                classNameForSubclass={data.className}
                onImport={handleImport}
            />

            {wizardData && (
                <ChoiceWizardModal
                    title={wizardData.title}
                    steps={wizardData.steps}
                    characterLanguages={pendingLangs}
                    characterSkills={pendingSkills as any}
                    onComplete={handleWizardComplete}
                    onCancel={() => setWizardData(null)}
                />
            )}
        </div>
    );
}

import { useState } from 'react';
import { Character } from '../../../types/character';
import { Plus, Trash2, ToggleLeft, ToggleRight, Crown, ChevronDown, ChevronUp } from 'lucide-react';

interface Props {
    data: Character;
    onChange: (field: keyof Character, value: any) => void;
}

const OVERRIDABLE_FIELDS = [
    { field: 'ac', label: 'Armor Class (AC)', type: 'number' },
    { field: 'maxHp', label: 'Max HP', type: 'number' },
    { field: 'speed', label: 'Speed', type: 'text' },
    { field: 'proficiencyBonus', label: 'Proficiency Bonus', type: 'number' },
    { field: 'initiativeMod', label: 'Initiative Modifier', type: 'number' },
    { field: 'spellSaveDc', label: 'Spell Save DC', type: 'number' },
    { field: 'spellAttackMod', label: 'Spell Attack Modifier', type: 'number' },
    { field: 'senses', label: 'Senses', type: 'text' },
    { field: 'languages', label: 'Languages', type: 'text' },
    { field: 'proficiencies', label: 'Proficiencies', type: 'text' },
    { field: 'hitDice', label: 'Hit Dice', type: 'text' },
    { field: 'currentHp', label: 'Current HP', type: 'number' },
    { field: 'tempHp', label: 'Temp HP', type: 'number' },
];

export function DMOverridePanel({ data, onChange }: Props) {
    const [isOpen, setIsOpen] = useState(false);
    const [newField, setNewField] = useState('');
    const [newValue, setNewValue] = useState('');
    const [newReason, setNewReason] = useState('');

    const overrides = data.customOverrides?.overrides || [];

    const updateOverrides = (newOverrides: typeof overrides) => {
        onChange('customOverrides', {
            ...data.customOverrides,
            overrides: newOverrides
        });
    };

    const addOverride = () => {
        if (!newField) return;
        const fieldInfo = OVERRIDABLE_FIELDS.find(f => f.field === newField);
        const override = {
            id: crypto.randomUUID(),
            field: newField,
            label: fieldInfo?.label || newField,
            value: fieldInfo?.type === 'number' ? parseInt(newValue) || 0 : newValue,
            isActive: true,
            reason: newReason || 'DM Override'
        };
        updateOverrides([...overrides, override]);
        setNewField('');
        setNewValue('');
        setNewReason('');
    };

    const toggleOverride = (id: string) => {
        updateOverrides(overrides.map(o => o.id === id ? { ...o, isActive: !o.isActive } : o));
    };

    const removeOverride = (id: string) => {
        updateOverrides(overrides.filter(o => o.id !== id));
    };

    const activeCount = overrides.filter(o => o.isActive).length;

    return (
        <div className="border border-gold/30 rounded-lg bg-stone-900/50 overflow-hidden">
            {/* Toggle Header */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="w-full flex items-center justify-between p-3 hover:bg-stone-800/50 transition-colors group"
            >
                <div className="flex items-center gap-2">
                    <Crown size={16} className="text-gold" />
                    <span className="font-cinzel font-bold text-gold text-sm">DM Overrides</span>
                    {activeCount > 0 && (
                        <span className="text-[10px] bg-gold/20 text-gold px-1.5 py-0.5 rounded-full border border-gold/30">
                            {activeCount} active
                        </span>
                    )}
                </div>
                {isOpen ? <ChevronUp size={14} className="text-stone-500" /> : <ChevronDown size={14} className="text-stone-500" />}
            </button>

            {isOpen && (
                <div className="border-t border-gold/20 p-4 space-y-4 animate-in slide-in-from-top-2 duration-200">
                    {/* Existing Overrides */}
                    {overrides.length > 0 && (
                        <div className="space-y-2">
                            <div className="flex justify-between items-center mb-1 px-1">
                                <span className="text-[10px] text-stone-500 uppercase font-bold tracking-widest">Active Modifiers</span>
                                <button
                                    onClick={() => updateOverrides([])}
                                    className="text-[10px] text-blood hover:text-red-400 font-bold uppercase tracking-widest transition-colors flex items-center gap-1"
                                >
                                    <Trash2 size={10} /> Clear All
                                </button>
                            </div>
                            {overrides.map(override => (
                                <div
                                    key={override.id}
                                    className={`flex items-center gap-3 p-2.5 rounded-lg border transition-all
                                        ${override.isActive
                                            ? 'bg-gold/5 border-gold/30'
                                            : 'bg-stone-900/50 border-stone-800 opacity-60'
                                        }`}
                                >
                                    <button
                                        onClick={() => toggleOverride(override.id)}
                                        className="flex-shrink-0 text-gold hover:text-gold/80 transition-colors"
                                        title={override.isActive ? 'Disable override' : 'Enable override'}
                                    >
                                        {override.isActive
                                            ? <ToggleRight size={20} />
                                            : <ToggleLeft size={20} className="text-stone-600" />
                                        }
                                    </button>

                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 text-sm">
                                            <span className="font-medium text-parchment">{override.label}</span>
                                            <span className="text-gold font-bold">→</span>
                                            <span className="font-mono text-gold">{override.value}</span>
                                        </div>
                                        <div className="text-[10px] text-stone-500 truncate">{override.reason}</div>
                                    </div>

                                    <button
                                        onClick={() => removeOverride(override.id)}
                                        className="flex-shrink-0 text-stone-600 hover:text-red-400 transition-colors p-1"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Add New Override */}
                    <div className="border border-stone-800 rounded-lg p-3 bg-stone-950/50 space-y-2">
                        <div className="text-[10px] text-gold font-bold uppercase tracking-wider flex items-center gap-1">
                            <Plus size={10} /> Add Override
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                            <select
                                value={newField}
                                onChange={e => setNewField(e.target.value)}
                                className="bg-stone-900 border border-stone-700 text-parchment rounded px-2 py-1.5 text-xs focus:border-gold outline-none"
                            >
                                <option value="">Select field...</option>
                                {OVERRIDABLE_FIELDS.map(f => (
                                    <option key={f.field} value={f.field}>{f.label}</option>
                                ))}
                            </select>
                            <input
                                type={OVERRIDABLE_FIELDS.find(f => f.field === newField)?.type === 'number' ? 'number' : 'text'}
                                value={newValue}
                                onChange={e => setNewValue(e.target.value)}
                                placeholder="New value"
                                className="bg-stone-900 border border-stone-700 text-parchment rounded px-2 py-1.5 text-xs focus:border-gold outline-none"
                            />
                        </div>
                        <input
                            type="text"
                            value={newReason}
                            onChange={e => setNewReason(e.target.value)}
                            placeholder="Reason (e.g., Magic item bonus, DM ruling...)"
                            className="w-full bg-stone-900 border border-stone-700 text-parchment rounded px-2 py-1.5 text-xs focus:border-gold outline-none"
                        />
                        <button
                            onClick={addOverride}
                            disabled={!newField || !newValue}
                            className="w-full py-1.5 bg-gold/20 hover:bg-gold/30 text-gold border border-gold/30 rounded text-xs font-medium transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
                        >
                            Apply Override
                        </button>
                    </div>

                    <p className="text-[9px] text-stone-600 text-center">
                        Overrides bypass calculated values. Use responsibly, DM!
                    </p>
                </div>
            )}
        </div>
    );
}

import { Character, Feature, Resource } from '../../../types/character';
import { Sparkles, Plus, Trash2, Battery, Search, Dna, RotateCcw } from 'lucide-react';
import { useState } from 'react';
import { FiveEToolsModal } from '../../common/FiveEToolsModal';
import { InfoTooltip } from '../../common/InfoTooltip';
import { RulesTooltip } from '../../common/RulesTooltip';
import { extractActionsFromFeature, extractItemsFromFeature } from '../../../engine/fiveEToolsParser';

interface Props {
    data: Character;
    onChange: (field: keyof Character, value: any) => void;
    onTriggerChoice?: (featureId: string) => void;
    onTriggerReplace?: (featureId: string, slotName: string) => void;
}

export function FeaturesTab({ data, onChange, onTriggerChoice, onTriggerReplace }: Props) {
    const [isSearchOpen, setIsSearchOpen] = useState(false);

    const addFeature = () => {
        const newFeature: Feature = {
            id: crypto.randomUUID(),
            name: 'New Feature',
            source: 'Class',
            description: '',
            hasUses: false,
        };
        onChange('features', [...data.features, newFeature]);
    };

    const addRacialTrait = () => {
        const newTrait: Feature = {
            id: crypto.randomUUID(),
            name: 'New Racial Trait',
            source: `Race: ${data.race || 'Unknown'}`,
            description: '',
            hasUses: false,
        };
        onChange('racialTraits', [...(data.racialTraits || []), newTrait]);
    };

    const updateFeature = (id: string, updates: Partial<Feature>) => {
        onChange('features', data.features.map(f => f.id === id ? { ...f, ...updates } : f));
    };

    const removeFeature = (id: string) => {
        onChange('features', data.features.filter(f => f.id !== id));
    };

    const updateRacialTrait = (id: string, updates: Partial<Feature>) => {
        onChange('racialTraits', (data.racialTraits || []).map(f => f.id === id ? { ...f, ...updates } : f));
    };

    const removeRacialTrait = (id: string) => {
        onChange('racialTraits', (data.racialTraits || []).filter(f => f.id !== id));
    };

    const updateFeat = (id: string, updates: Partial<Feature>) => {
        onChange('feats', (data.feats || []).map(f => f.id === id ? { ...f, ...updates } : f));
    };

    const removeFeat = (id: string) => {
        onChange('feats', (data.feats || []).filter(f => f.id !== id));
    };

    const addResource = () => {
        const newRes: Resource = {
            id: crypto.randomUUID(),
            name: 'New Resource',
            current: 1,
            max: 1,
            resetOn: 'long'
        };
        onChange('resources', [...data.resources, newRes]);
    };

    const updateResource = (id: string, updates: Partial<Resource>) => {
        onChange('resources', data.resources.map(r => r.id === id ? { ...r, ...updates } : r));
    };

    const removeResource = (id: string) => {
        onChange('resources', data.resources.filter(r => r.id !== id));
    };

    const racialTraits = data.racialTraits || [];

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in">

            {/* Resources Tracker (Left) */}
            <div className="lg:col-span-1 space-y-6">
                {/* Resources */}
                <div className="space-y-4">
                    <div className="flex items-center justify-between border-b border-stone-700 pb-2">
                        <div className="flex items-center gap-2">
                            <Battery size={18} className="text-blue-400" />
                            <h3 className="font-cinzel text-blue-400 text-lg">Resources</h3>
                        </div>
                        <button
                            onClick={addResource}
                            className="flex items-center gap-1 text-xs bg-stone-800 hover:bg-stone-700 text-parchment px-2 py-1 rounded border border-stone-600 transition-colors"
                        >
                            <Plus size={14} /> Add
                        </button>
                    </div>

                    <p className="text-xs text-stone-500 mb-2">Track Ki points, Sorcery Points, Rages, Bardic Inspiration, etc.</p>

                    <div className="space-y-3">
                        {data.resources.length === 0 ? (
                            <div className="text-center py-6 opacity-50 bg-stone-800/30 rounded-lg border border-stone-700 border-dashed">
                                <span className="text-sm text-stone-400">No resources tracked.</span>
                            </div>
                        ) : (
                            data.resources.map(res => (
                                <div key={res.id} className="bg-transparent border-b border-stone-800/40 py-2 pl-2 pr-1 relative group hover:bg-stone-900/40 focus-within:bg-stone-900/40 transition-colors">
                                    <input
                                        type="text" value={res.name}
                                        onChange={e => updateResource(res.id, { name: e.target.value })}
                                        className="w-[calc(100%-24px)] bg-transparent font-bold text-parchment text-sm border-none focus:text-blue-400 outline-none mb-1 truncate transition-colors"
                                        placeholder="Resource Name"
                                    />
                                    <div className="flex flex-wrap items-center justify-between gap-2 mt-1">
                                        <div className="flex items-center gap-1.5 bg-stone-950/50 border border-stone-800/50 rounded px-1.5 py-0.5">
                                            <input
                                                type="number" min="0" value={res.current}
                                                onChange={e => updateResource(res.id, { current: parseInt(e.target.value) || 0 })}
                                                className="w-10 bg-transparent text-blue-400 text-center font-bold text-sm outline-none"
                                            />
                                            <span className="text-stone-600 text-[10px] font-bold">/</span>
                                            <input
                                                type="number" min="1" value={res.max}
                                                onChange={e => updateResource(res.id, { max: parseInt(e.target.value) || 1 })}
                                                className="w-10 bg-transparent text-stone-400 focus:text-parchment text-center font-bold text-xs outline-none transition-colors"
                                            />
                                        </div>
                                        <div className="flex items-center gap-1.5 text-[10px] text-stone-500 uppercase tracking-widest font-bold">
                                            <span>Resets:</span>
                                            <select
                                                value={res.resetOn}
