    combatant: Combatant;
    onActionClick?: (action: CombatAction) => void;
    onActionHover?: (action: CombatAction | null) => void;
}

export function ActionPanel({ combatant, onActionClick, onActionHover }: ActionPanelProps) {
    const characters = useCharacterStore(s => s.characters);
    const activeEncounter = useCombatStore(s => s.activeEncounter);

    const [activeTab, setActiveTab] = useState<string>('');
    const [hoveredAction, setHoveredAction] = useState<CombatAction | null>(null);

    const [dmOverride, setDmOverride] = useState(false);
    const hoveredElementRef = useRef<HTMLDivElement | null>(null);
    const [hoverRect, setHoverRect] = useState<DOMRect | null>(null);
    const isHoveringRef = useRef(false);

    useEffect(() => {

        setHoveredAction(null);
        hoveredElementRef.current = null;
    }, [combatant.id]);

    useEffect(() => {
        setHoveredAction(null);
        hoveredElementRef.current = null;
    }, [activeTab]);

    const altPressed = useAltKey();

    useEffect(() => {
        if (!hoveredAction || !hoveredElementRef.current) return;
        const updateRect = () => {
            if (hoveredElementRef.current) {
                setHoverRect(hoveredElementRef.current.getBoundingClientRect());
            }
        };
        updateRect();
        window.addEventListener('scroll', updateRect, true);
        window.addEventListener('resize', updateRect);
        return () => {
            window.removeEventListener('scroll', updateRect, true);
            window.removeEventListener('resize', updateRect);
        };
    }, [hoveredAction]);

    useEffect(() => {
        if (!altPressed && !isHoveringRef.current) {
            setHoveredAction(null);
        }
    }, [altPressed]);

    // Build action list based on combatant type
    const allActions = useMemo(() => {
        if (combatant.type === 'player' && combatant.sourceId) {
            const char = characters.find(c => c.id === combatant.sourceId);
            if (char) return getPlayerCombatActions(char);
        }
        if (combatant.type === 'monster' || combatant.type === 'npc') {
            return getMonsterCombatActions(combatant.monsterData);
        }
        return [];
    }, [combatant, characters]);

    // Group by category (tab)
    const categories = useMemo(() => {
        const grouped: Record<string, CombatAction[]> = {};
        allActions.forEach(a => {
            const cat = a.category;
            if (!grouped[cat]) grouped[cat] = [];
            grouped[cat].push(a);
        });
        return grouped;
    }, [allActions]);

    const tabKeys = Object.keys(categories);

    // Auto-select first tab
    if (!activeTab && tabKeys.length > 0) {
        const preferred = tabKeys.find(t => t !== 'Standard') || tabKeys[0];
        setActiveTab(preferred);
    }

    const currentActions = categories[activeTab] || [];

    // ---- Handlers ----
    const handleActionClick = (action: CombatAction) => {
        onActionClick?.(action);
    };

    const handleSavingThrow = (ability: string) => {
        const abilityScores = combatant.abilityScores;
        if (!abilityScores) return;

        const score = Number((abilityScores as any)[ability]) || 10;
        const mod = Math.floor((score - 10) / 2);
        const profBonus = combatant.savingThrowProficiencies?.includes(ability) ? (combatant.proficiencyBonus || 2) : 0;
        const totalMod = mod + profBonus;

        const saveAction: CombatAction = {
            id: `save-${ability}`,
            name: `${ABILITY_NAMES[ability]} Saving Throw`,
            economy: 'free',
            category: 'Saves',
            description: SAVE_DESCRIPTIONS[ability] || '',
            saveDc: 0,
            saveAbility: ability,
            sourceType: 'generic',
            icon: '🛡️',
            toHit: totalMod,
            actionType: 'save-spell'
        };

        onActionClick?.(saveAction);
    };

    const handleDeathSave = () => {
        const deathSaveAction: CombatAction = {
            id: 'death-save',
            name: 'Death Saving Throw',
            economy: 'action',
            category: 'Standard',
            description: 'You are at 0 HP. Roll a d20 to see if you stabilize or die.',
            sourceType: 'generic',
            icon: '💀',
            actionType: 'death-save'
        };
        onActionClick?.(deathSaveAction);
    };



    const triggerReadiedAction = () => {
        useCombatStore.getState().addLog({ message: `${combatant.name} triggers their readied action! "${combatant.readiedAction?.description}"`, type: 'system', combatantId: combatant.id });
        if (activeEncounter?.turnState.hasReaction) useCombatStore.getState().consumeReaction();
        useCombatStore.getState().setReadiedAction(combatant.id, null);
    };

    const cancelReadiedAction = () => {
        useCombatStore.getState().addLog({ message: `${combatant.name} cancelled their readied action.`, type: 'system', combatantId: combatant.id });
        useCombatStore.getState().setReadiedAction(combatant.id, null);
    };

    // ---- Render ----
    if (combatant.type === 'player' && combatant.currentHp <= 0 && !dmOverride) {
        const dSaves = combatant.deathSaves || { successes: 0, failures: 0 };
        const isDead = dSaves.failures >= 3;
        const isStable = dSaves.successes >= 3;

        return (
            <div className="flex flex-col gap-4 animate-in fade-in duration-200">
                <div className="bg-stone-950 border border-blood/50 rounded-lg overflow-hidden shadow-2xl">
                    <div className="bg-blood/20 p-4 border-b border-blood/50 flex flex-col items-center justify-center relative">
                        <h3 className="text-blood font-bold text-xl uppercase tracking-widest flex items-center gap-2">
                            {isDead && <Skull size={24} className="animate-pulse" />}
                            {isDead ? 'DECEASED' : isStable ? 'STABILIZED' : 'UNCONSCIOUS'}
                        </h3>
                        <p className="text-blood/70 text-xs mt-1">Make death saving throws on your turn.</p>

                        <button
                            onClick={() => setDmOverride(true)}
                            className="absolute right-4 top-1/2 -translate-y-1/2 bg-stone-900/50 hover:bg-blood/30 border border-blood/30 p-2 rounded-lg text-blood/50 hover:text-white transition-all group flex items-center gap-2"
                            title="DM Override: Show actions anyway (for special rulings)"
                        >
                            <ShieldAlert size={14} className="group-hover:animate-pulse" />
                            <span className="text-[9px] font-black uppercase tracking-widest">DM Override</span>
                        </button>
                    </div>
                    {!isDead && !isStable && (
                        <div className="p-6 flex flex-col items-center gap-6">
                            <div className="flex w-full justify-around max-w-sm">
                                <div className="flex flex-col items-center gap-2">
                                    <span className="text-parchment text-xs font-bold uppercase tracking-wider">Successes</span>
                                    <div className="flex gap-2">
                                        {[1, 2, 3].map(i => (
                                            <div key={i} className={`w-4 h-4 rounded-full border-2 ${dSaves.successes >= i ? 'bg-green-500 border-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]' : 'bg-transparent border-stone-700'}`} />
                                        ))}
                                    </div>
                                </div>
                                <div className="flex flex-col items-center gap-2">
                                    <span className="text-blood text-xs font-bold uppercase tracking-wider">Failures</span>
                                    <div className="flex gap-2">
                                        {[1, 2, 3].map(i => (
                                            <div key={i} className={`w-4 h-4 rounded-full border-2 ${dSaves.failures >= i ? 'bg-blood border-blood shadow-[0_0_10px_rgba(220,38,38,0.5)]' : 'bg-transparent border-stone-700'}`} />
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="max-w-md w-full bg-stone-900 shadow-inner rounded-xl p-4 border border-stone-800/80 space-y-3">
                                <div className="space-y-1">
                                    <h5 className="text-[10px] font-black uppercase text-blood tracking-widest flex items-center gap-2">
                                        <Info size={12} /> The Rules of Dying
                                    </h5>
                                    <p className="text-[11px] text-stone-300 leading-relaxed italic">
                                        Roll a <span className="text-parchment font-bold">d20</span>. On a <span className="text-gold font-bold text-xs">10 or higher</span>, you succeed!
                                        3 successes and you stabilize. 3 failures and you're gone.
                                    </p>
                                </div>
                                <div className="pt-2 border-t border-stone-800 space-y-1">
                                    <h5 className="text-[10px] font-black uppercase text-gold tracking-widest flex items-center gap-2">
                                        <BookOpen size={12} /> DM Coaching
                                    </h5>
                                    <p className="text-[11px] text-parchment font-bold leading-relaxed border-l-2 border-gold/30 pl-2 text-pretty">
                                        Tell your player: "Roll for your life!" <br />
                                        <span className="text-cyan-400">Natural 20:</span> You instantly regain 1 HP and stand up. <br />
                                        <span className="text-blood">Natural 1:</span> TWO failures at once.
                                    </p>
                                </div>
                            </div>

                            <button
                                onClick={handleDeathSave}
                                className="bg-stone-900 hover:bg-stone-800 border border-stone-700 hover:border-gold px-8 py-3 rounded-lg text-gold font-bold transition-all shadow-lg active:scale-95 flex items-center gap-2 font-medieval"
                            >
                                <Zap size={16} /> Roll Death Save
                            </button>
                        </div>
                    )}
                </div>
            </div>
        );
    }

    // ---- Render - Main View ----
    return (
        <div className="flex flex-col gap-4 animate-in fade-in duration-300 max-w-[calc(100vw-450px)]">
            <div className="bg-stone-900/40 backdrop-blur-xl border border-gold/20 rounded-xl overflow-hidden shadow-[0_8px_32px_rgba(0,0,0,0.5)]">
                {/* Tab Bar Container */}
                <div className="flex items-center justify-between bg-stone-950/40 border-b border-stone-800/50">
                    {dmOverride && (
                        <div className="pl-4 pr-2 border-r border-stone-800 animate-in slide-in-from-left-2 duration-300">
                            <button
                                onClick={() => setDmOverride(false)}
                                className="flex items-center gap-2 bg-blood/10 hover:bg-blood/20 border border-blood/30 px-2 py-1 rounded text-[9px] text-blood font-black uppercase tracking-widest"
                            >
                                <X size={10} /> Exit Override
                            </button>
                        </div>
                    )}
                    <div className="flex overflow-x-auto custom-scrollbar flex-1">
                        {tabKeys.map(tab => {
                            const Icon = TAB_ICONS[tab] || Zap;
                            const count = categories[tab].length;
                            return (
                                <button
                                    key={tab}
                                    onClick={() => setActiveTab(tab)}
                                    className={`flex items-center gap-1.5 px-4 py-2.5 text-xs font-bold uppercase tracking-wider whitespace-nowrap transition-all border-b-2 ${activeTab === tab
                                        ? 'border-gold text-gold bg-stone-950/60'
                                        : 'border-transparent text-stone-500 hover:text-stone-300 hover:bg-stone-900'
                                        }`}
                                >
                                    <Icon size={14} />
                                    {tab}
                                    <span className={`ml-1 text-[10px] px-1.5 py-0.5 rounded-full ${activeTab === tab ? 'bg-gold/20 text-gold' : 'bg-stone-800 text-stone-500'}`}>
                                        {count}
                                    </span>
                                </button>
                            );
                        })}
                    </div>

                </div>



                {/* Readied Action Banner */}
                {combatant.readiedAction && (
                    <div className="bg-arcane/20 border-b border-arcane/40 p-3 flex items-center justify-between flex-wrap gap-2">
                        <div>
                            <span className="text-arcane font-bold text-[10px] uppercase tracking-wider block flex items-center gap-1"><Zap size={10} /> Readied Action</span>
                            <span className="text-parchment text-xs font-medium">{combatant.readiedAction.description}</span>
                            <span className="text-stone-400 text-xs italic ml-2">Trigger: {combatant.readiedAction.trigger}</span>
                        </div>
                        <div className="flex gap-2">
                            <button onClick={triggerReadiedAction} className="px-3 py-1 bg-arcane/30 text-arcane text-xs font-bold rounded hover:bg-arcane/50 border border-arcane/50 transition-colors">Trigger</button>
                            <button onClick={cancelReadiedAction} className="px-3 py-1 bg-stone-800/80 text-stone-400 text-xs font-bold rounded hover:bg-stone-700 border border-stone-700">Cancel</button>
                        </div>
                    </div>
                )}

                {/* Saving Throw Quick Bar */}
                {combatant.abilityScores && (
                    <div className="flex items-center justify-between px-4 py-2 bg-stone-900/40 border-b border-stone-800">
                        <div className="flex items-center gap-1">
                            <span className="text-[10px] font-bold text-stone-500 uppercase tracking-widest mr-2">Saves:</span>
                            {Object.entries(combatant.abilityScores).map(([ability, score]) => {
                                const mod = Math.floor((Number(score) - 10) / 2);
                                const profBonus = combatant.savingThrowProficiencies?.includes(ability) ? (combatant.proficiencyBonus || 2) : 0;
                                const total = mod + profBonus;
                                const isProficient = combatant.savingThrowProficiencies?.includes(ability);
                                return (
                                    <button
                                        key={ability}
                                        onClick={() => handleSavingThrow(ability)}
                                        className={`flex flex-col items-center px-2 py-1 rounded text-[10px] transition-all ${isProficient ? 'bg-gold/10 border border-gold/30 text-gold' : 'bg-stone-900 border border-stone-800 text-stone-400'}`}
                                    >
                                        <span className="uppercase font-bold">{ability}</span>
                                        <span className={`font-mono ${total >= 0 ? 'text-green-400' : 'text-blood'}`}>{total >= 0 ? '+' : ''}{total}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* Action Cards Grid */}
                <div className="p-4">
                    {activeTab === 'Spells' && <SpellSlotTracker combatant={combatant} />}
                    {currentActions.length === 0 ? (
                        <div className="text-center text-stone-500 text-sm italic py-8">No actions in this category.</div>
                    ) : (
                        <div className="grid grid-cols-1 gap-2.5">
                            {currentActions.map(action => {
                                // Rule Enforcements
                                const turnState = activeEncounter?.turnState;
                                let isRestricted = false;
                                let restrictionReason = "";

                                if (turnState && !dmOverride) {
                                    // 1. Bonus Action Spell Rule (PHB p.202)
                                    // "If you cast a spell as a bonus action, you can't cast another spell
                                    //  during the same turn, except a cantrip with a casting time of 1 action."
                                    // This works BOTH directions in practice.
                                    const isSpell = action.category === 'Spells';
                                    const isCantrip = action.spellLevel === 0;
                                    const isBonusSpell = isSpell && action.economy === 'bonus';

                                    // Direction 1: BA spell was cast → only cantrips allowed as Action spells
                                    if (turnState.hasCastBonusActionSpell && isSpell && !isCantrip && action.economy === 'action') {
                                        isRestricted = true;
                                        restrictionReason = "BA Spell Cast — Only Cantrips Allowed";
                                    }
                                    // Direction 2: Leveled Action spell was cast → no BA leveled spells
                                    if (turnState.hasCastLeveledSpell && isBonusSpell && !isCantrip) {
                                        isRestricted = true;
                                        restrictionReason = "Leveled Spell Cast — BA Spell Blocked";
                                    }

                                    // 2. Haste Restricted Action
                                    // If only Haste Action remains, only specific actions are valid
                                    const onlyHasteLeft = !turnState.hasAction && turnState.hasHasteAction;
                                    if (onlyHasteLeft) {
                                        const allowedHasteNames = ['Attack', 'Dash', 'Disengage', 'Hide', 'Use Object'];
                                        const isAllowedHaste = allowedHasteNames.some(n => action.name.includes(n));
                                        if (!isAllowedHaste) {
                                            isRestricted = true;
                                            restrictionReason = "Haste Restriction";
                                        } else if (action.name.includes('Attack') && action.attacksPerAction && action.attacksPerAction > 1) {
                                            // Haste Attack is ONE weapon attack only
                                            // We'll let the user click but maybe the wizard should handle the limit
                                        }
                                    }

                                    // 3. Economy Check
                                    const hasEconomy = (action.economy === 'action' && (turnState.hasAction || turnState.extraActions > 0 || turnState.hasHasteAction)) ||
                                        (action.economy === 'bonus' && turnState.hasBonusAction) ||
                                        (action.economy === 'reaction' && turnState.hasReaction) ||
                                        (action.economy === 'free' || action.economy === 'trait');

                                    if (!hasEconomy) {
                                        isRestricted = true;
                                        restrictionReason = "No Economy";
                                    }
                                }

                                return (
                                    <div
                                        key={action.id}
                                        className={`relative group ${isRestricted ? 'opacity-40 grayscale-[0.5]' : ''}`}
                                        title={restrictionReason}
                                        onMouseEnter={(e) => {
                                            setHoveredAction(action);
                                            hoveredElementRef.current = e.currentTarget;
                                            isHoveringRef.current = true;
                                            onActionHover?.(action);
                                        }}
                                        onMouseLeave={() => {
                                            isHoveringRef.current = false;
                                            if (!altPressed) {
                                                setHoveredAction(null);
                                                onActionHover?.(null);
                                            }
                                        }}
                                    >
                                        <button
                                            onClick={() => handleActionClick(action)}
                                            disabled={isRestricted && !dmOverride}
                                            className={`w-full text-left p-3 rounded-lg border transition-all duration-200 ${isRestricted
                                                ? 'bg-stone-900/10 border-stone-800/50'
                                                : 'bg-stone-800/30 backdrop-blur-md border-stone-700/50 hover:border-gold/50 hover:bg-stone-800/50 hover:shadow-[0_0_15px_rgba(217,119,6,0.1)] hover:-translate-y-0.5 active:translate-y-0'
                                                }`}
                                        >
                                            <div className="flex items-start justify-between gap-2 mb-1">
                                                <div className="flex items-center gap-2.5 truncate">
                                                    <span className="text-lg">{action.icon}</span>
                                                    <span className={`font-bold text-base leading-tight ${isRestricted ? 'text-stone-500' : 'text-parchment'}`}>{action.name}</span>
                                                </div>
                                                <div className="flex items-center gap-1.5 flex-shrink-0">
                                                    {isRestricted && (
                                                        <span className="text-[8px] px-1.5 py-0.5 rounded bg-blood/10 text-blood border border-blood/30 font-black uppercase tracking-tighter">
                                                            {restrictionReason}
                                                        </span>
                                                    )}
                                                    {action.source && (
                                                        <span className={`text-[10px] px-2 py-0.5 rounded border font-bold uppercase tracking-wider ${getSourceBadgeColor(action.source)}`}>
                                                            {action.source}
                                                        </span>
                                                    )}
                                                    <span className={`text-[10px] px-2 py-0.5 rounded border font-bold uppercase ${ECONOMY_COLORS[action.economy]}`}>{ECONOMY_LABELS[action.economy]}</span>
                                                </div>
                                            </div>

                                            {action.requiresConcentration && combatant.concentratingOn && (
                                                <div className="flex items-center gap-1.5 px-2 py-1 mb-2 rounded bg-amber-900/20 border border-amber-700/50 text-amber-500 animate-in slide-in-from-top-1 duration-200">
                                                    <Info size={10} />
                                                    <span className="text-[9px] font-black uppercase tracking-widest shadow-text">Warn: Already Concentrating on {combatant.concentratingOn.name}</span>
                                                </div>
                                            )}

                                            <div className="flex gap-2.5 mt-2">
                                                {action.toHit !== undefined && <span className="text-xs text-arcane font-medium">+{action.toHit} hit</span>}
                                                {action.damageNotation && <span className="text-xs text-blood font-medium">{action.damageNotation}</span>}

                                                {/* Weapon Mastery Display */}
                                                {action.sourceType === 'weapon' && action.weaponBaseName && (
                                                    (() => {
                                                        const char = combatant.type === 'player' ? characters.find(c => c.id === combatant.sourceId) : null;
                                                        if (char && hasMastery(char, action.weaponBaseName)) {
                                                            const mastery = getMasteryProperty(action.weaponBaseName);
                                                            if (mastery) {
                                                                return (
                                                                    <div className="flex items-center gap-1 bg-gold/10 text-gold px-1.5 py-0.5 rounded border border-gold/30 animate-in fade-in zoom-in-95 duration-300 group/mastery relative">
                                                                        <Zap size={10} className="text-gold" />
                                                                        <span className="text-[9px] font-black uppercase tracking-widest">{mastery.name}</span>

                                                                        {/* Tooltip for the mastery property */}
                                                                        <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 hidden group-hover/mastery:block w-48 p-2 bg-stone-900 border border-gold/40 rounded shadow-xl z-50 pointer-events-none">
                                                                            <p className="text-[10px] text-parchment leading-tight">{mastery.description}</p>
                                                                            <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-gold/40" />
                                                                        </div>
                                                                    </div>
                                                                );
                                                            }
                                                        }
                                                        return null;
                                                    })()
                                                )}

                                                {action.attacksPerAction && action.attacksPerAction > 1 && !isRestricted && (
                                                    <span className="text-[10px] bg-gold/10 text-gold px-1.5 py-0.5 rounded font-black uppercase tracking-tighter self-center ml-auto">
                                                        {action.attacksPerAction} Attacks
                                                    </span>
                                                )}
                                            </div>
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            {/* Action Tooltip Portal */}
            {hoveredAction && hoverRect && createPortal(
                <div
                    className="fixed z-[99999] p-4 bg-stone-950/90 backdrop-blur-xl border border-gold/40 rounded-xl shadow-[0_20px_50px_rgba(0,0,0,0.7)] w-80 max-h-[320px] overflow-y-auto custom-scrollbar animate-in fade-in zoom-in-95 duration-200"
                    style={{
                        left: `${Math.max(10, Math.min(window.innerWidth - 330, hoverRect.left + hoverRect.width / 2 - 160))}px`,
                        top: hoverRect.top < 320 ? `${hoverRect.bottom + 10}px` : `${hoverRect.top - 10}px`,
                        transform: hoverRect.top < 320 ? 'none' : 'translateY(-100%)'
                    }}
                >
                    <div className="flex items-center justify-between mb-3 border-b border-gold/10 pb-2">
                        <span className="font-cinzel font-bold text-gold tracking-wide">{hoveredAction.name}</span>
                        <span className={`text-[9px] px-2 py-0.5 rounded border font-black uppercase tracking-widest ${ECONOMY_COLORS[hoveredAction.economy]}`}>{ECONOMY_LABELS[hoveredAction.economy]}</span>
                    </div>
                    <p className="text-xs text-stone-200 whitespace-pre-wrap leading-relaxed opacity-90">{hoveredAction.description}</p>

                    {altPressed && (
                        <div className="mt-4 pt-3 border-t border-gold/5 text-[10px] text-stone-500 italic flex items-center gap-2">
                            <Info size={12} className="text-gold/50" />
                            Use mouse to scroll or click links
                        </div>
                    )}
                </div>,
                document.body
            )}
        </div>
    );
}

import { useState, useMemo } from 'react';
import { createPortal } from 'react-dom';
import {
    X,
    ChevronRight,
    ChevronLeft,
    Target,
    Zap,
    Shield,
    Sparkles,
    CheckCircle2,
    Info,
    Skull,
    Activity,
    BookOpen,
    Dice5,
    AlertCircle,
    Crosshair,
    Star
} from 'lucide-react';
import { Combatant, CombatAction } from '../../types/combat';
import { CORE_RULE_DESCRIPTIONS, ABILITY_DESCRIPTIONS } from '../../data/dnd5e/tooltipDescriptions';
import { ABILITY_NAMES } from '../../engine/combatActions';
import { evaluateCombatConditions, resolveAdvantageMode, rollD20 } from '../../engine/diceEngine';

export type WizardStep = 'level' | 'target' | 'roll' | 'result' | 'target-saves' | 'damage' | 'effect' | 'summary';

interface ActionWizardProps {
    isOpen: boolean;
    onClose: () => void;
    action: CombatAction;
    actor: Combatant;
    allCombatants: Combatant[];
    onConfirm: (result: any) => void;
    initialTargets?: Combatant[];
}

const COMMON_CONDITIONS = [
    { id: 'blinded', name: 'Blinded', icon: '🌑' },
    { id: 'charmed', name: 'Charmed', icon: '❤️' },
    { id: 'deafened', name: 'Deafened', icon: '🙉' },
    { id: 'frightened', name: 'Frightened', icon: '😱' },
    { id: 'grappled', name: 'Grappled', icon: '🤼' },
    { id: 'incapacitated', name: 'Incapacitated', icon: '😵' },
    { id: 'invisible', name: 'Invisible', icon: '👻' },
    { id: 'paralyzed', name: 'Paralyzed', icon: '⚡' },
    { id: 'petrified', name: 'Petrified', icon: '🗿' },
    { id: 'poisoned', name: 'Poisoned', icon: '🤢' },
    { id: 'prone', name: 'Prone', icon: '🛌' },
    { id: 'restrained', name: 'Restrained', icon: '🕸️' },
    { id: 'stunned', name: 'Stunned', icon: '💫' },
    { id: 'unconscious', name: 'Unconscious', icon: '💤' }
];

/**
 * ActionWizard — Interactive DM Tutor for Combat
 * Guides the DM through every step of a combat action.
 */
export function ActionWizard({
    isOpen,
    onClose,
    action,
    actor,
    allCombatants,
    onConfirm,
    initialTargets
}: ActionWizardProps) {
    const hasInitialTargets = initialTargets && initialTargets.length > 0;
    const initialStep: WizardStep = (action.spellLevel !== undefined && action.spellLevel > 0) ? 'level' : (hasInitialTargets ? 'roll' : 'target');
    const [step, setStep] = useState<WizardStep>(initialStep);
    const [wizardContext, setWizardContext] = useState<any>({
        selectedTargets: initialTargets || [],
        rollResult: null,
        damageResult: null,
        isCrit: false,
        isFumble: false,
        advantageMode: 'normal' as 'normal' | 'advantage' | 'disadvantage',
        damageMod: 'Normal',
        overrideAc: null,
        overrideToHit: null,
        selectedConditions: [],
        applyConcentration: false,
        showRules: false,
        activeRuleId: null,
        conditionToSave: null, // Track which condition is currently prompting for a save
        saveTargetId: null,
        manualRollInput: '', // For manual roll input in condition saves
        multiTargetResults: [], // For AOE or multi-attack tracking [{targetId, roll, damage, isHit, saveResult}]
        concentrationSaveTargetId: null, // New: Target ID needing a concentration save
        concentrationSaveDc: 0, // New: DC for the concentration save
        castLevel: action.spellLevel || 0,
        isHitOverride: null as boolean | null, // New: DM override for hit/miss
        slowSpellFailed: false, // New: Track if a spell was delayed by Slow
        targetSaves: {} as Record<string, { roll?: number, total?: number, saved?: boolean, isManual?: boolean }>,
        targetAdvStates: {} as Record<string, 'normal' | 'advantage' | 'disadvantage'>,
    });

    // Determine the sequence of steps based on action type
    const steps: WizardStep[] = useMemo(() => {
        const flow: WizardStep[] = [];
        const actionName = action.name.toLowerCase();

        // 0. Spells with slots get a configuration step if not a cantrip
        if (action.spellLevel !== undefined && action.spellLevel > 0) {
            flow.push('level');
        }

        // Skip targeting for dedicated self-rolls like saves
        const isStandaloneRoll = action.actionType === 'saving-throw' || action.id === 'death-save';
        const isSelfRange = action.range === 'Self' || action.range === 'self';
        const isSelfRoll = isStandaloneRoll || isSelfRange;

        if (!isSelfRoll) {
            flow.push('target');
        }

        // 1. Special Case: Magic Missile (Auto-hit, Multi-target)
        if (actionName.includes('magic missile')) {
            flow.push('damage', 'effect', 'summary');
            return flow;
        }

        // 2. Attack Actions (Roll to Hit)
        if (action.toHit !== undefined) {
            flow.push('roll', 'result');
        }

        // 3. Save Actions (Targets roll saves)
        if (isStandaloneRoll) {
            flow.push('roll', 'result');
        } else if (action.saveDc !== undefined || action.saveAbility || actionName === 'grapple' || actionName === 'shove') {
            flow.push('target-saves');
        }

        // 4. Follow-up: Damage and Effects
        if (action.damageNotation || action.damageType || (action.description && action.description.toLowerCase().includes('damage'))) {
            flow.push('damage');
        }

        flow.push('effect');
        flow.push('summary');
        return flow;
    }, [action]);

    // Calculate dynamic limits based on level
    const targetLimit = useMemo(() => {
        const actionName = action.name.toLowerCase();
        const level = wizardContext.castLevel || action.spellLevel || 1;

        if (actionName.includes('magic missile')) return level + 2;
        if (actionName.includes('scorching ray')) return level + 1;

        // NEW: Support Multiattack / Extra Attack
        if (action.attacksPerAction && action.attacksPerAction > 1) {
            return action.attacksPerAction;
        }

        // Default: Area effects often have "unlimited" targets in a zone
        const isAOE = action.description?.toLowerCase().includes('each creature in') ||
            action.description?.toLowerCase().includes('radius');
        if (isAOE) return 99;

        return 1; // Single target default
    }, [action, wizardContext.castLevel]);

    if (!isOpen) return null;

    const currentStepIndex = steps.indexOf(step);
    const canGoBack = currentStepIndex > 0;
    const isLastStep = currentStepIndex === steps.length - 1;

    const handleNext = () => {
        if (isLastStep) {
            // Build final results object with targetDetails for CombatBoard
            const finalResults = { ...wizardContext };

            // Populate targetDetails based on results
            const targetDetails: Record<string, { saved?: boolean, hit?: boolean }> = {};

            wizardContext.selectedTargets.forEach((target: Combatant, idx: number) => {
                const saveResult = wizardContext.targetSaves[target.id];
                const attackResult = wizardContext.multiTargetResults.find((r: any) => r.targetId === target.id && r.instanceIdx === idx);

                const isAttack = action.toHit !== undefined;
                const isSave = action.saveDc !== undefined || action.saveAbility;

                let hit = false;
                if (isAttack && attackResult) {
                    const effectiveAc = wizardContext.overrideAc !== null && idx === 0 ? wizardContext.overrideAc : target.ac;
                    hit = (attackResult.isCrit || attackResult.total >= effectiveAc) && !attackResult.isFumble;
                    if (wizardContext.isHitOverride !== null && idx === 0) hit = wizardContext.isHitOverride;
                }

                targetDetails[target.id] = {
                    saved: isSave ? saveResult?.saved : undefined,
                    hit: isAttack ? hit : undefined
                };
            });

            finalResults.targetDetails = targetDetails;
            onConfirm(finalResults);
            onClose();
        } else {
            // Logic to check if we can move to next step
            if (step === 'target' && wizardContext.selectedTargets.length === 0) {
                return; // Must select target
            }
            if (step === 'roll' && wizardContext.rollResult === null) {
                return; // Must have a roll
            }
            if (step === 'target-saves') {
                const allDone = wizardContext.selectedTargets.every((t: Combatant) => wizardContext.targetSaves[t.id]?.saved !== undefined);
                if (!allDone) return;
            }

            // Auto-advance logic for misses
            if (step === 'result' || step === 'target-saves') {
                const isAttack = action.toHit !== undefined;
                const isSave = action.saveDc !== undefined || action.saveAbility;

                const anyEffective = wizardContext.selectedTargets.some((target: Combatant, idx: number) => {
                    const saveResult = wizardContext.targetSaves[target.id];
                    const attackResult = wizardContext.multiTargetResults.find((r: any) => r.targetId === target.id && r.instanceIdx === idx);

                    if (isAttack && attackResult) {
                        const effectiveAc = wizardContext.overrideAc !== null && idx === 0 ? wizardContext.overrideAc : target.ac;
                        const hit = (attackResult.isCrit || attackResult.total >= effectiveAc) && !attackResult.isFumble;
                        if (hit) return true;
                    }
                    if (isSave && saveResult && !saveResult.saved) {
                        return true;
                    }
                    return false;
                });

                const actionName = action.name.toLowerCase();
                const hasDamageStep = steps.includes('damage');
                const isHalfDamageSpell = actionName.includes('fireball') || actionName.includes('breath') || actionName.includes('lightning bolt');

                if (!anyEffective && !isHalfDamageSpell && hasDamageStep && !actionName.includes('magic missile')) {
                    // Skip damage if everyone missed/saved (unless it's a half-damage spell)
                    setStep('summary');
                    return;
                }
            }

            // Handle Slow Condition for Spells: 50% chance to fail
            if (step === 'level' || (step === 'target' && steps[0] !== 'level')) {
                const isSlowed = actor.conditions.some(c => c.name.toLowerCase() === 'slowed' || c.name.toLowerCase() === 'slow');
                const isLeveledSpell = action.spellLevel !== undefined && action.spellLevel > 0;

                if (isSlowed && isLeveledSpell && !wizardContext.slowSpellFailed) {
                    const roll = Math.random();
                    if (roll < 0.5) {
                        setWizardContext({ ...wizardContext, slowSpellFailed: true });
                        setStep('summary');
                        return;
                    }
                }
            }

            setStep(steps[currentStepIndex + 1]);
        }
    };

    const handleBack = () => {
        if (canGoBack) {
            setStep(steps[currentStepIndex - 1]);
        }
    };

    const isActorPlayer = actor.type === 'player';

    // Helper to get relative rule for the current step
    const getCurrentStepRule = () => {
        if (step === 'target') return CORE_RULE_DESCRIPTIONS['target-selection'] || { name: 'Targeting', description: 'Choose a creature within range of your action.' };
        if (step === 'target-saves' || step === 'roll' || step === 'result') {
            const saveAbility = action.saveAbility || 'dex';
            if (step === 'target-saves') return CORE_RULE_DESCRIPTIONS['saving-throw'] || ABILITY_DESCRIPTIONS[saveAbility];
            if (action.actionType === 'saving-throw' && action.saveAbility) return ABILITY_DESCRIPTIONS[action.saveAbility];
            if (action.toHit !== undefined) return CORE_RULE_DESCRIPTIONS['attack-action'];
            if (action.saveDc !== undefined) return CORE_RULE_DESCRIPTIONS['saving-throw'];
        }
        if (step === 'damage') return CORE_RULE_DESCRIPTIONS['damage-roll'] || { name: 'Damage', description: 'Roll the dice specified by your attack or spell to determine how much health the target loses.' };
        if (step === 'effect') return CORE_RULE_DESCRIPTIONS['conditions'] || { name: 'Conditions', description: 'Certain effects impose conditions that change what a creature can do.' };
        return null;
    };

    const currentRule = wizardContext.activeRuleId ?
        (CORE_RULE_DESCRIPTIONS[wizardContext.activeRuleId] || ABILITY_DESCRIPTIONS[wizardContext.activeRuleId]) :
        getCurrentStepRule();

    return createPortal(
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-in fade-in duration-300">
            <div className="w-full max-w-4xl bg-stone-950 border border-stone-800 rounded-xl shadow-2xl flex flex-row max-h-[90vh] overflow-hidden transition-all duration-500">

                {/* Main Wizard Content */}
                <div className="flex-1 flex flex-col min-w-0 border-r border-stone-800 relative">
                    {/* Header */}
                    <div className="p-4 border-b border-stone-800 bg-stone-900/50 flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-lg bg-gold/10 border border-gold/30 flex items-center justify-center text-gold">
                                <Zap size={20} />
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-parchment leading-tight">{action.name}</h2>
                                <p className="text-xs text-stone-500 uppercase tracking-widest font-bold">
                                    {actor.name}'s Turn • {action.economy}
                                </p>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <button
                                onClick={() => setWizardContext({ ...wizardContext, showRules: !wizardContext.showRules })}
                                className={`p-2 rounded-lg border transition-all flex items-center gap-2 text-xs font-bold ${wizardContext.showRules ? 'bg-gold/20 border-gold text-gold' : 'bg-stone-800 border-stone-700 text-stone-400 hover:text-parchment'}`}
                            >
                                <BookOpen size={16} />
                                {wizardContext.showRules ? 'Hide Rules' : 'Rules'}
                            </button>
                            <button
                                onClick={onClose}
                                className="p-2 text-stone-500 hover:text-parchment hover:bg-stone-800 rounded-lg transition-colors"
                            >
                                <X size={20} />
                            </button>
                        </div>
                    </div>

                    {/* Progress Bar */}
                    <div className="px-6 py-3 bg-stone-900/30 flex items-center justify-center gap-2 border-b border-stone-900">
                        {steps.map((s, idx) => (
                            <div key={s} className="flex items-center">
                                <div
                                    className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${idx <= currentStepIndex ? 'bg-gold shadow-[0_0_8px_rgba(255,215,0,0.5)]' : 'bg-stone-800'}`}
                                />
                                {idx < steps.length - 1 && (
                                    <div className={`w-8 h-0.5 mx-1 transition-all duration-300 ${idx < currentStepIndex ? 'bg-gold/50' : 'bg-stone-800'}`} />
                                )}
                            </div>
                        ))}
                    </div>

                    {/* Content Area */}
                    <div className="flex-1 overflow-y-auto custom-scrollbar p-6">
                        {step === 'level' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                                <div className="text-center space-y-2">
                                    <h3 className="text-xl font-cinzel font-bold text-parchment tracking-widest">Cast at what level?</h3>
                                    <p className="text-xs text-stone-500 uppercase tracking-tighter">Higher levels often increase damage or number of targets.</p>
                                </div>
                                <div className="grid grid-cols-3 gap-3">
                                    {[1, 2, 3, 4, 5, 6, 7, 8, 9].filter(l => l >= (action.spellLevel || 1)).map(lvl => (
                                        <button
                                            key={lvl}
                                            onClick={() => setWizardContext({ ...wizardContext, castLevel: lvl })}
                                            className={`
                                                p-4 rounded-lg border-2 transition-all flex flex-col items-center justify-center gap-1
                                                ${wizardContext.castLevel === lvl
                                                    ? 'bg-gold/20 border-gold shadow-[0_0_15px_rgba(255,215,0,0.2)]'
                                                    : 'bg-stone-900 border-stone-800 hover:border-stone-700 text-stone-500'}
                                            `}
                                        >
                                            <span className="text-lg font-cinzel font-black">{lvl}</span>
                                            <span className="text-[9px] uppercase font-bold tracking-widest">Level</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        )}

                        {step === 'target' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                                <div className="bg-gold/5 border border-gold/20 p-4 rounded-lg">
                                    <h3 className="text-gold font-bold text-xs uppercase tracking-widest mb-2 flex items-center gap-2">
                                        <Info size={14} /> DM coaching: {isActorPlayer ? 'Player Prompt' : 'Monster Action'}
                                    </h3>
                                    <p className="text-parchment italic text-sm">
                                        {isActorPlayer
                                            ? `Ask ${actor.name}: "Who do you want to target with ${action.name}?"`
                                            : `${actor.name} prepares to use ${action.name}. Select the intended target.`}
                                    </p>
                                    {action.range && (
                                        <p className="mt-2 text-[10px] text-stone-500 uppercase tracking-widest font-bold flex items-center gap-1">
                                            <Target size={12} /> Range: {action.range}
                                        </p>
                                    )}
                                </div>

                                {wizardContext.selectedTargets.length > 0 && (
                                    <div className="flex items-center justify-between px-1">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[10px] font-bold text-gold uppercase tracking-[0.2em]">Targets Selected</span>
                                            <span className={`px-2 py-0.5 rounded-full border border-gold/30 font-mono text-xs ${wizardContext.selectedTargets.length >= targetLimit ? 'bg-blood/20 text-blood border-blood/50' : 'bg-gold/20 text-gold'}`}>
                                                {wizardContext.selectedTargets.length} / {targetLimit}
                                            </span>
                                        </div>
                                        <button
                                            onClick={() => setWizardContext({ ...wizardContext, selectedTargets: [] })}
                                            className="text-[10px] text-stone-500 hover:text-blood uppercase tracking-widest font-bold transition-colors"
                                        >
                                            Clear All
                                        </button>
                                    </div>
                                )}

                                <div className="space-y-4">
                                    {(['monster', 'player'] as const).map(type => {
                                        const filtered = allCombatants.filter(c => c.type === type && !c.isDead && !c.isLair);
                                        if (filtered.length === 0) return null;

                                        return (
                                            <div key={type} className="space-y-2">
                                                <h4 className="text-[10px] font-bold text-stone-500 uppercase tracking-[0.2em] px-1">
                                                    {type === 'monster' ? 'Hostile Targets' : 'Friendly Targets'}
                                                </h4>
                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                                    {filtered.map(c => {
                                                        const isSelected = wizardContext.selectedTargets.some((t: Combatant) => t.id === c.id);
                                                        const hpPercent = (c.currentHp / c.maxHp) * 100;

                                                        return (
                                                            <button
                                                                key={c.id}
                                                                onClick={() => {
                                                                    const name = action.name.toLowerCase();
                                                                    const isMultiTarget = name.includes('magic missile') || (action.saveDc !== undefined) || (action.saveAbility);

                                                                    if (isMultiTarget) {
                                                                        // For Magic Missile, we can select same target multiple times
                                                                        // For AOEs, just toggle
                                                                        if (name.includes('magic missile')) {
                                                                            if (wizardContext.selectedTargets.length < targetLimit) {
                                                                                setWizardContext({
                                                                                    ...wizardContext,
                                                                                    selectedTargets: [...wizardContext.selectedTargets, c]
                                                                                });
                                                                            }
                                                                        } else {
                                                                            const isAlreadyIn = wizardContext.selectedTargets.some((t: Combatant) => t.id === c.id);
                                                                            if (!isAlreadyIn && wizardContext.selectedTargets.length >= targetLimit) return;

                                                                            setWizardContext({
                                                                                ...wizardContext,
                                                                                selectedTargets: isAlreadyIn
                                                                                    ? wizardContext.selectedTargets.filter((t: Combatant) => t.id !== c.id)
                                                                                    : [...wizardContext.selectedTargets, c]
                                                                            });
                                                                        }
                                                                    } else {
                                                                        setWizardContext({
                                                                            ...wizardContext,
                                                                            selectedTargets: [c]
                                                                        });
                                                                    }
                                                                }}
                                                                className={`text-left p-3 rounded-lg border transition-all flex items-center gap-3 ${isSelected
                                                                    ? 'bg-gold/10 border-gold shadow-[0_0_10px_rgba(255,215,0,0.1)]'
                                                                    : 'bg-stone-900/50 border-stone-800 hover:border-stone-700'
                                                                    }`}
                                                            >
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="flex items-center justify-between mb-1">
                                                                        <span className={`font-bold text-sm truncate ${isSelected ? 'text-gold' : 'text-parchment'}`}>
                                                                            {c.name}
                                                                        </span>
                                                                        <div className="flex items-center gap-1 bg-stone-950 px-1.5 py-0.5 rounded border border-stone-800">
                                                                            <Shield size={10} className="text-stone-500" />
                                                                            <span className="text-[10px] font-mono text-stone-300">{c.ac}</span>
                                                                        </div>
                                                                    </div>
                                                                    <div className="h-1 w-full bg-stone-800 rounded-full overflow-hidden">
                                                                        <div
                                                                            className={`h-full transition-all duration-500 ${hpPercent > 50 ? 'bg-green-600' : hpPercent > 20 ? 'bg-yellow-600' : 'bg-blood'}`}
                                                                            style={{ width: `${hpPercent}%` }}
                                                                        />
                                                                    </div>
                                                                </div>
                                                                <div className="flex flex-col items-center gap-1">
                                                                    {isSelected && (
                                                                        <CheckCircle2 size={16} className="text-gold flex-shrink-0 animate-in zoom-in duration-200" />
                                                                    )}
                                                                    {wizardContext.selectedTargets.filter((t: Combatant) => t.id === c.id).length > 1 && (
                                                                        <span className="bg-gold text-stone-950 text-[10px] font-black px-1.5 rounded-full animate-in scale-in duration-200">
                                                                            x{wizardContext.selectedTargets.filter((t: Combatant) => t.id === c.id).length}
                                                                        </span>
                                                                    )}
                                                                </div>
                                                            </button>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {step === 'roll' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                                <div className="bg-gold/5 border border-gold/20 p-4 rounded-lg">
                                    <h3 className="text-gold font-bold text-xs uppercase tracking-widest mb-2 flex items-center gap-2">
                                        <Info size={14} /> DM coaching: {isActorPlayer ? 'Ask Player' : 'Monster Roll'}
                                    </h3>
                                    <div className="space-y-2">
                                        <p className="text-parchment text-sm">
                                            {isActorPlayer ? (
                                                action.id === 'death-save'
                                                    ? <>Ask {actor.name} to roll a <span className="text-gold font-bold">Death Saving Throw</span>.</>
                                                    : action.actionType === 'saving-throw'
                                                        ? <>Ask {actor.name} for a <span className="text-gold font-bold">{action.name}</span>.</>
                                                        : <>Ask {actor.name} for an <span className="text-gold font-bold">Attack Roll</span> (d20 + {wizardContext.overrideToHit !== null ? wizardContext.overrideToHit : (action.toHit || 0)}).</>
                                            ) : (
                                                action.actionType === 'saving-throw'
                                                    ? <>Roll a <span className="text-gold font-bold">{action.name}</span> for {actor.name}.</>
                                                    : <>Roll for {actor.name}: <span className="text-gold font-bold">1d20 + {wizardContext.overrideToHit !== null ? wizardContext.overrideToHit : (action.toHit || 0)}</span></>
                                            )}
                                        </p>
                                        {action.name.toLowerCase().includes('magic missile') && (
                                            <div className="mt-3 p-3 bg-arcane/10 border border-arcane/20 rounded text-[11px] leading-relaxed animate-in slide-in-from-left duration-500">
                                                <div className="flex items-center gap-2 mb-1">
                                                    <Star size={12} className="text-arcane" />
                                                    <span className="font-black uppercase tracking-widest text-arcane">DM Pro-Tip</span>
                                                </div>
                                                Officially (RAW), you roll 1d4+1 <span className="font-bold underline">once</span> and apply that number to all darts. However, many DMs prefer rolling for each dart separately. Choose the method that fits your table's speed!
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Target AC Summary (Desktop only) */}
                                {wizardContext.selectedTargets.length > 0 && (
                                    <div className="hidden sm:flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
                                        {wizardContext.selectedTargets.reduce((acc: any[], t: Combatant) => {
                                            if (!acc.find(x => x.id === t.id)) acc.push(t);
                                            return acc;
                                        }, []).map((t: Combatant) => (
                                            <div key={t.id} className="bg-stone-900 border border-stone-800 px-3 py-1 rounded flex items-center gap-2 flex-shrink-0">
                                                <span className="text-[10px] font-bold text-stone-500 uppercase">{t.name}</span>
                                                <span className="text-xs font-mono font-black text-gold">AC {wizardContext.overrideAc !== null && t.id === wizardContext.selectedTargets[0].id ? wizardContext.overrideAc : t.ac}</span>
                                            </div>
                                        ))}
                                    </div>
                                )}

                                {/* Roll Inputs List */}
                                <div className="space-y-4 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                    {wizardContext.selectedTargets.map((target: Combatant, idx: number) => {
                                        const actionType = action.range?.toLowerCase().includes('melee') || action.range?.toLowerCase() === 'touch' ? 'melee' : 'ranged';
                                        const condEval = evaluateCombatConditions(actor, target, actionType);
                                        const resolvedAdv = resolveAdvantageMode([condEval]);

                                        // Use DM override if set, otherwise fallback to the automatic calculation
                                        const currentAdvMode = wizardContext.targetAdvStates[target.id] || resolvedAdv.mode;

                                        return (
                                            <div key={`${target.id}-${idx}`} className="bg-stone-900 border border-stone-800 p-4 rounded-lg space-y-3">
                                                <div className="flex flex-col gap-2">
                                                    <div className="flex items-center justify-between">
                                                        <h4 className="text-xs font-black text-parchment uppercase tracking-widest flex items-center gap-2">
                                                            <Crosshair size={14} className="text-blood" />
                                                            {wizardContext.selectedTargets.length > 1 ? `Attack ${idx + 1}: ${target.name}` : `Attack vs ${target.name}`}
                                                        </h4>
                                                        <div className="text-[10px] text-stone-500 font-bold">
                                                            AC {target.id === wizardContext.selectedTargets[0].id && wizardContext.overrideAc !== null ? wizardContext.overrideAc : target.ac}
                                                        </div>
                                                    </div>

                                                    {/* Advantage / Disadvantage Toggle */}
                                                    <div className="flex items-center justify-between bg-stone-950 p-1.5 rounded border border-stone-800/50">
                                                        <div className="flex gap-1">
                                                            {(['disadvantage', 'normal', 'advantage'] as const).map(mode => (
                                                                <button
                                                                    key={mode}
                                                                    onClick={() => setWizardContext({
                                                                        ...wizardContext,
                                                                        targetAdvStates: { ...wizardContext.targetAdvStates, [target.id]: mode }
                                                                    })}
                                                                    className={`px-3 py-1 rounded text-[10px] font-black uppercase transition-all ${currentAdvMode === mode
                                                                        ? (mode === 'advantage' ? 'bg-green-600 border-green-500 text-white' : mode === 'disadvantage' ? 'bg-blood border-blood text-white' : 'bg-stone-700 text-white')
                                                                        : 'bg-transparent text-stone-500 hover:bg-stone-800'
                                                                        }`}
                                                                >
                                                                    {mode === 'normal' ? 'Norm' : mode.substring(0, 3)}
                                                                </button>
                                                            ))}
                                                        </div>
                                                        {resolvedAdv.reasons.length > 0 && (
                                                            <div className="text-[9px] text-stone-500 italic max-w-[150px] truncate text-right">
                                                                {resolvedAdv.reasons.join(', ')}
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>

                                                {condEval.autoCrit && (
                                                    <div className="bg-gold/10 border border-gold/30 rounded p-1.5 flex items-center justify-center gap-2 animate-pulse mb-3">
                                                        <Sparkles size={12} className="text-gold" />
                                                        <span className="text-[10px] font-black uppercase tracking-widest text-gold">Any Hit is a Critical (Condition)</span>
                                                    </div>
                                                )}

                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                                    <div className="space-y-1">
                                                        <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest">Manual Roll</label>
                                                        <div className="flex items-center gap-2">
                                                            <input
                                                                type="number"
                                                                placeholder="d20"
                                                                className="w-full bg-stone-950 border border-stone-700 rounded px-3 py-2 text-sm font-mono text-parchment focus:border-gold outline-none"
                                                                value={wizardContext.multiTargetResults.find((r: any) => r.targetId === target.id && r.instanceIdx === idx)?.roll ?? ''}
                                                                onChange={(e) => {
                                                                    const val = parseInt(e.target.value);
                                                                    if (isNaN(val)) return;

                                                                    let bonus = 0;
                                                                    if (action.actionType === 'saving-throw') {
                                                                        const abilityKey = (action.saveAbility as keyof NonNullable<Combatant['abilityScores']>) || 'wis';
                                                                        const score = actor.abilityScores?.[abilityKey] || 10;
                                                                        const mod = Math.floor((score - 10) / 2);
                                                                        const isProficient = actor.savingThrowProficiencies?.includes(abilityKey);
                                                                        bonus = mod + (isProficient ? (actor.proficiencyBonus || 2) : 0);
                                                                    } else {
                                                                        bonus = wizardContext.overrideToHit !== null ? wizardContext.overrideToHit : (action.toHit || 0);
                                                                    }

                                                                    const total = val + bonus;
                                                                    const effectiveAc = wizardContext.overrideAc !== null ? wizardContext.overrideAc : target.ac;
                                                                    const isHitRaw = total >= effectiveAc;
                                                                    const finalIsCrit = val === 20 || (condEval.autoCrit && isHitRaw && val !== 1);

                                                                    const newResults = [...wizardContext.multiTargetResults.filter((r: any) => !(r.targetId === target.id && r.instanceIdx === idx))];
                                                                    newResults.push({
                                                                        targetId: target.id,
                                                                        instanceIdx: idx,
                                                                        roll: val,
                                                                        total: total,
                                                                        isCrit: finalIsCrit,
                                                                        isFumble: val === 1
                                                                    });

                                                                    const updates: any = { multiTargetResults: newResults };
                                                                    if (wizardContext.selectedTargets.length === 1) {
                                                                        updates.rollResult = total;
                                                                        updates.isCrit = finalIsCrit;
                                                                        updates.isFumble = val === 1;
                                                                    }
                                                                    setWizardContext({ ...wizardContext, ...updates });
                                                                }}
                                                            />
                                                        </div>
                                                    </div>
                                                    <div className="space-y-1">
                                                        <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest">Digital</label>
                                                        <button
                                                            onClick={() => {
                                                                let bonus = 0;
                                                                if (action.actionType === 'saving-throw') {
                                                                    const abilityKey = (action.saveAbility as keyof NonNullable<Combatant['abilityScores']>) || 'wis';
                                                                    const score = actor.abilityScores?.[abilityKey] || 10;
                                                                    const mod = Math.floor((score - 10) / 2);
                                                                    const isProficient = actor.savingThrowProficiencies?.includes(abilityKey);
                                                                    bonus = mod + (isProficient ? (actor.proficiencyBonus || 2) : 0);
                                                                } else {
                                                                    bonus = wizardContext.overrideToHit !== null ? wizardContext.overrideToHit : (action.toHit || 0);
                                                                }

                                                                // NEW: Use rollD20 to handle advantage naturally
                                                                const res = rollD20(bonus, currentAdvMode);

                                                                // We extract the base d20 result(s) for the UI if needed
                                                                // rollD20 total includes modifier.
                                                                // For manual compatibility, we'll store the raw d20 roll (highest/lowest if Adv/Dis).
                                                                const rawRoll = res.rolls.length > 0 ? (currentAdvMode === 'advantage' ? Math.max(...res.rolls) : currentAdvMode === 'disadvantage' ? Math.min(...res.rolls) : res.rolls[0]) : 1;

                                                                const effectiveAc = wizardContext.overrideAc !== null ? wizardContext.overrideAc : target.ac;
                                                                const isHitRaw = res.total >= effectiveAc;
                                                                const finalIsCrit = res.isCrit || (condEval.autoCrit && isHitRaw && !res.isFumble);

                                                                const newResults = [...wizardContext.multiTargetResults.filter((r: any) => !(r.targetId === target.id && r.instanceIdx === idx))];
                                                                newResults.push({
                                                                    targetId: target.id,
                                                                    instanceIdx: idx,
                                                                    roll: rawRoll,
                                                                    total: res.total,
                                                                    isCrit: finalIsCrit,
                                                                    isFumble: res.isFumble
                                                                });

                                                                const updates: any = { multiTargetResults: newResults };
                                                                if (wizardContext.selectedTargets.length === 1) {
                                                                    updates.rollResult = res.total;
                                                                    updates.isCrit = finalIsCrit;
                                                                    updates.isFumble = res.isFumble;
                                                                }
                                                                setWizardContext({ ...wizardContext, ...updates });
                                                            }}
                                                            className="w-full h-[38px] bg-arcane/10 hover:bg-arcane/20 border border-arcane/30 text-arcane rounded flex items-center justify-center gap-2 transition-all active:scale-95"
                                                        >
                                                            <Dice5 size={14} />
                                                            <span className="text-xs font-bold uppercase">
                                                                {currentAdvMode === 'advantage' ? 'Roll (Adv)' : currentAdvMode === 'disadvantage' ? 'Roll (Dis)' : 'Roll'}
                                                            </span>
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                        )
                                    })}
                                </div>

                                <div className="pt-4 border-t border-stone-800 flex justify-end">
                                    <button
                                        onClick={() => setStep('result')}
                                        disabled={wizardContext.multiTargetResults.length < wizardContext.selectedTargets.length}
                                        className="bg-gold text-stone-950 px-8 py-3 rounded-lg font-black uppercase tracking-widest text-sm hover:scale-105 transition-all disabled:opacity-30 disabled:grayscale disabled:cursor-not-allowed"
                                    >
                                        Compare & Continue
                                    </button>
                                </div>
                            </div>
                        )}

                        {step === 'target-saves' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                                <div className="bg-gold/5 border border-gold/20 p-4 rounded-lg">
                                    <div className="space-y-2">
                                        <p className="text-parchment text-sm">
                                            {(action.name.toLowerCase() === 'grapple' || action.name.toLowerCase() === 'shove') ? (
                                                <>Ask the target for a <span className="font-bold text-gold">Strength or Dexterity Saving Throw</span> (their choice) against a <span className="font-bold text-gold">DC of {8 + (Math.floor(((Number((actor.abilityScores as any).str) || 10) - 10) / 2)) + (Number(actor.proficiencyBonus) || 2)}</span>.</>
                                            ) : (
                                                <>The following targets must roll a <span className="text-gold font-bold">{(action.saveAbility || 'DEX').toUpperCase()} Save (DC {action.saveDc || 10})</span>.</>
                                            )}
                                        </p>
                                        <div className="mt-3 p-3 bg-stone-900/50 border border-stone-800 rounded text-[11px] leading-relaxed">
                                            <span className="font-black uppercase tracking-widest text-gold block mb-1">DM Help</span>
                                            {isActorPlayer
                                                ? "Players often force saves with spells or abilities. You manage the monsters' reaction."
                                                : "Your monster is forcing a save. Tell your players what to roll."}
                                        </div>
                                    </div>
                                </div>

                                <div className="space-y-3">
                                    {wizardContext.selectedTargets.map((target: Combatant) => {
                                        const isPlayer = target.type === 'player';
                                        const result = wizardContext.targetSaves[target.id] || {};
                                        const hasResult = result.saved !== undefined;

                                        // Calculate NPC modifiers
                                        const abilityKey = (action.saveAbility as keyof NonNullable<Combatant['abilityScores']>) || 'wis';
                                        const score = target.abilityScores?.[abilityKey] || 10;
                                        const mod = Math.floor((score - 10) / 2);
                                        const isProficient = target.savingThrowProficiencies?.includes(abilityKey);
                                        const bonus = mod + (isProficient ? (target.proficiencyBonus || 2) : 0);

                                        // Condition evaluation
                                        const condEval = evaluateCombatConditions(actor, target, 'save', abilityKey);
                                        const resolvedAdv = resolveAdvantageMode([condEval]);
                                        const currentAdvMode = wizardContext.targetAdvStates[target.id] || resolvedAdv.mode;
                                        const autoFail = condEval.autoFailSave;

                                        // Calculate DC for 2024 rules or standard saves
                                        const actionName = action.name.toLowerCase();
                                        const dc = (actionName === 'grapple' || actionName === 'shove')
                                            ? (8 + (Math.floor(((Number((actor.abilityScores as any).str) || 10) - 10) / 2)) + (Number(actor.proficiencyBonus) || 2))
                                            : (action.saveDc || 10);

                                        return (
                                            <div key={target.id} className={`p-4 rounded-lg border-2 transition-all ${hasResult ? (result.saved ? 'bg-green-600/10 border-green-600/30' : 'bg-blood/10 border-blood/30') : 'bg-stone-900/50 border-stone-800'}`}>
                                                <div className="flex items-center justify-between mb-2">
                                                    <div className="flex items-center gap-3">
                                                        <div className={`w-8 h-8 rounded bg-stone-950 border border-stone-700 flex items-center justify-center font-bold text-xs ${isPlayer ? 'text-blue-400' : 'text-blood'}`}>
                                                            {target.name.charAt(0)}
                                                        </div>
                                                        <div>
                                                            <h4 className="text-sm font-bold text-parchment">{target.name}</h4>
                                                            <p className="text-[10px] text-stone-500 uppercase tracking-tighter">{isPlayer ? 'Player' : 'Monster'} • {abilityKey.toUpperCase()} Save</p>
                                                        </div>
                                                    </div>
                                                    {hasResult && (
                                                        <div className={`px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-widest ${result.saved ? 'bg-green-600/20 text-green-500' : 'bg-blood/20 text-blood'}`}>
                                                            {result.saved ? 'Success ✓' : 'Failed ✗'}
                                                        </div>
                                                    )}
                                                </div>

                                                {/* Advantage / Disadvantage Toggle */}
                                                <div className="flex items-center justify-between bg-stone-950 p-1.5 rounded border border-stone-800/50 mb-3">
                                                    <div className="flex gap-1">
                                                        {(['disadvantage', 'normal', 'advantage'] as const).map(mode => (
                                                            <button
                                                                key={mode}
                                                                onClick={() => setWizardContext({
                                                                    ...wizardContext,
                                                                    targetAdvStates: { ...wizardContext.targetAdvStates, [target.id]: mode }
                                                                })}
                                                                className={`px-3 py-1 rounded text-[10px] font-black uppercase transition-all ${currentAdvMode === mode
                                                                    ? (mode === 'advantage' ? 'bg-green-600 border-green-500 text-white' : mode === 'disadvantage' ? 'bg-blood border-blood text-white' : 'bg-stone-700 text-white')
                                                                    : 'bg-transparent text-stone-500 hover:bg-stone-800'
                                                                    }`}
                                                            >
                                                                {mode === 'normal' ? 'Norm' : mode.substring(0, 3)}
                                                            </button>
                                                        ))}
                                                    </div>
                                                    {resolvedAdv.reasons.length > 0 && (
                                                        <div className="text-[9px] text-stone-500 italic max-w-[150px] truncate text-right">
                                                            {resolvedAdv.reasons.join(', ')}
                                                        </div>
                                                    )}
                                                </div>

                                                {autoFail && (
                                                    <div className="bg-blood/20 border border-blood/40 rounded p-2 flex items-center justify-center gap-2 mb-3 animate-pulse">
                                                        <Skull size={14} className="text-blood" />
                                                        <span className="text-[10px] font-black uppercase tracking-widest text-blood">Auto-Fails {abilityKey.toUpperCase()} Save (Condition)</span>
                                                    </div>
                                                )}

                                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                                    {isPlayer ? (
                                                        <div className="col-span-2 bg-stone-950 p-3 rounded border border-stone-800 text-center">
                                                            <p className="text-xs text-stone-400 mb-2 italic">"Ask {target.name} for a <span className="text-parchment font-bold underline">DC {dc} {abilityKey.toUpperCase()} Save</span>."</p>
                                                            <div className="flex gap-2 justify-center">
                                                                <button
                                                                    onClick={() => setWizardContext({
                                                                        ...wizardContext,
                                                                        targetSaves: { ...wizardContext.targetSaves, [target.id]: { saved: true } }
                                                                    })}
                                                                    className={`flex-1 py-1.5 rounded text-[10px] font-black uppercase transition-all ${result.saved === true ? 'bg-green-600 text-white' : 'bg-stone-800 text-stone-400 hover:bg-stone-700'}`}
                                                                >
                                                                    Success
                                                                </button>
                                                                <button
                                                                    onClick={() => setWizardContext({
                                                                        ...wizardContext,
                                                                        targetSaves: { ...wizardContext.targetSaves, [target.id]: { saved: false } }
                                                                    })}
                                                                    className={`flex-1 py-1.5 rounded text-[10px] font-black uppercase transition-all ${result.saved === false ? 'bg-blood text-white' : 'bg-stone-800 text-stone-400 hover:bg-stone-700'}`}
                                                                >
                                                                    Fail
                                                                </button>
                                                            </div>
                                                        </div>
                                                    ) : (
                                                        <>
                                                            <div className="space-y-1">
                                                                <label className="text-[9px] font-black text-stone-500 uppercase">Manual Roll</label>
                                                                <input
                                                                    type="number"
                                                                    placeholder="d20"
                                                                    className="w-full bg-stone-950 border border-stone-800 rounded px-2 py-1.5 text-xs text-parchment font-mono outline-none focus:border-gold"
                                                                    value={result.roll || ''}
                                                                    onChange={(e) => {
                                                                        const val = parseInt(e.target.value);
                                                                        if (isNaN(val)) return;
                                                                        setWizardContext({
                                                                            ...wizardContext,
                                                                            targetSaves: {
                                                                                ...wizardContext.targetSaves,
                                                                                [target.id]: { roll: val, saved: val >= dc, isManual: true }
                                                                            }
                                                                        });
                                                                    }}
                                                                />
                                                            </div>
                                                            <div className="space-y-1">
                                                                <label className="text-[9px] font-black text-stone-500 uppercase">Digital</label>
                                                                <button
                                                                    onClick={() => {
                                                                        if (autoFail) {
                                                                            setWizardContext({
                                                                                ...wizardContext,
                                                                                targetSaves: {
                                                                                    ...wizardContext.targetSaves,
                                                                                    [target.id]: { roll: 1, total: 1 + bonus, saved: false, isManual: false }
                                                                                }
                                                                            });
                                                                            return;
                                                                        }

                                                                        const d20 = Math.floor(Math.random() * 20) + 1;
                                                                        // Simulating adv/dis if needed
                                                                        let finalRoll = d20;
                                                                        if (currentAdvMode === 'advantage') finalRoll = Math.max(d20, Math.floor(Math.random() * 20) + 1);
                                                                        if (currentAdvMode === 'disadvantage') finalRoll = Math.min(d20, Math.floor(Math.random() * 20) + 1);

                                                                        const total = finalRoll + bonus;
                                                                        setWizardContext({
                                                                            ...wizardContext,
                                                                            targetSaves: {
                                                                                ...wizardContext.targetSaves,
                                                                                [target.id]: { roll: finalRoll, total, saved: total >= dc, isManual: false }
                                                                            }
                                                                        });
                                                                    }}
                                                                    className={`w-full h-[32px] flex items-center justify-center gap-2 rounded text-[10px] font-black uppercase transition-all ${hasResult && !result.isManual ? 'bg-arcane text-white' : 'bg-arcane/10 text-arcane border border-arcane/30 hover:bg-arcane/20'}`}
                                                                >
                                                                    <Dice5 size={12} /> {hasResult && !result.isManual ? `Result: ${result.total}` : autoFail ? 'Force Fail' : `Roll (${currentAdvMode === 'normal' ? '' : currentAdvMode === 'advantage' ? 'Adv' : 'Dis'})`}
                                                                </button>
                                                            </div>
                                                        </>
                                                    )}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        )}

                        {step === 'result' && (
                            <div className="space-y-6 animate-in fade-in zoom-in duration-300">
                                <div className="flex flex-col items-center justify-center p-4">
                                    {wizardContext.selectedTargets.length === 1 ? (
                                        (() => {
                                            const target = wizardContext.selectedTargets[0];
                                            const effectiveAc = wizardContext.overrideAc !== null ? wizardContext.overrideAc : target.ac;
                                            const isAttack = action.toHit !== undefined;

                                            if (wizardContext.isCrit) {
                                                return (
                                                    <div className="text-center">
                                                        <div className="w-20 h-20 rounded-full bg-gold/20 border-2 border-gold flex items-center justify-center text-gold mx-auto mb-4 animate-bounce shadow-2xl">
                                                            <Sparkles size={40} />
                                                        </div>
                                                        <h3 className="text-4xl font-black text-gold uppercase underline decoration-gold/30">CRITICAL HIT!</h3>
                                                    </div>
                                                );
                                            }

                                            if (wizardContext.isFumble) {
                                                return (
                                                    <div className="text-center">
                                                        <div className="w-20 h-20 rounded-full bg-blood/20 border-2 border-blood flex items-center justify-center text-blood mx-auto mb-4 animate-pulse">
                                                            <Skull size={40} />
                                                        </div>
                                                        <h3 className="text-4xl font-black text-blood uppercase">CRITICAL MISS!</h3>
                                                    </div>
                                                );
                                            }

                                            if (isAttack) {
                                                const autoHit = wizardContext.rollResult >= effectiveAc;
                                                const isHit = wizardContext.isHitOverride !== null ? wizardContext.isHitOverride : autoHit;
                                                const isOverridden = wizardContext.isHitOverride !== null;

                                                return (
                                                    <div className="text-center">
                                                        <div className={`w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4 border-2 ${isHit ? 'bg-green-500/20 border-green-500 text-green-500' : 'bg-stone-800 border-stone-700 text-stone-500'}`}>
                                                            {isHit ? <CheckCircle2 size={40} /> : <X size={40} />}
                                                        </div>
                                                        <h3 className={`text-4xl font-black uppercase ${isHit ? 'text-green-500' : 'text-stone-500'}`}>
                                                            {isHit ? 'HIT!' : 'MISS'}
                                                        </h3>
                                                        <div className="flex flex-col items-center gap-1 mt-2">
                                                            <p className="text-parchment font-mono text-xl">
                                                                {wizardContext.rollResult} <span className="text-stone-500 text-sm mx-1">vs</span> {effectiveAc} AC
                                                            </p>
                                                            <div className="flex items-center gap-2 mt-2">
                                                                {isOverridden && (
                                                                    <span className="text-[10px] font-black uppercase text-gold bg-gold/10 px-2 py-0.5 rounded border border-gold/30 animate-pulse">
                                                                        DM Override Active
                                                                    </span>
                                                                )}
                                                                <button
                                                                    onClick={() => setWizardContext({
                                                                        ...wizardContext,
                                                                        isHitOverride: !isHit
                                                                    })}
                                                                    className="text-[10px] font-black uppercase text-stone-500 hover:text-parchment border border-stone-800 px-2 py-0.5 rounded bg-stone-900 transition-colors"
                                                                >
                                                                    Flip Result
                                                                </button>
                                                                {isOverridden && (
                                                                    <button
                                                                        onClick={() => setWizardContext({
                                                                            ...wizardContext,
                                                                            isHitOverride: null
                                                                        })}
                                                                        className="text-[10px] font-black uppercase text-blood hover:text-white border border-blood/30 px-2 py-0.5 rounded bg-blood/10 transition-colors"
                                                                    >
                                                                        Reset
                                                                    </button>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            }

                                            // Save result for single target
                                            // Save result for single target
                                            if (action.saveDc) {
                                                const autoSaveFail = wizardContext.rollResult < (action.saveDc || 10);
                                                const isFail = wizardContext.isHitOverride !== null ? wizardContext.isHitOverride : autoSaveFail;
                                                const isOverridden = wizardContext.isHitOverride !== null;

                                                return (
                                                    <div className="text-center">
                                                        <div className={`w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4 border-2 ${isFail ? 'bg-blood/20 border-blood text-blood' : 'bg-green-500/20 border-green-500 text-green-500'}`}>
                                                            {isFail ? <X size={40} /> : <CheckCircle2 size={40} />}
                                                        </div>
                                                        <h3 className={`text-4xl font-black uppercase ${isFail ? 'text-blood' : 'text-green-500'}`}>
                                                            {isFail ? 'FAILED SAVE' : 'SUCCESS!'}
                                                        </h3>
                                                        <div className="flex flex-col items-center gap-1 mt-2">
                                                            <p className="text-parchment font-mono text-xl">
                                                                {wizardContext.rollResult} <span className="text-stone-500 text-sm mx-1">vs</span> DC {action.saveDc}
                                                            </p>
                                                            <div className="flex items-center justify-center gap-2 mt-4">
                                                                {isOverridden && (
                                                                    <span className="text-[10px] font-black uppercase text-gold bg-gold/10 px-2 py-0.5 rounded border border-gold/30 animate-pulse">
                                                                        DM Override Active
                                                                    </span>
                                                                )}
                                                                <button
                                                                    onClick={() => {
                                                                        setWizardContext({ ...wizardContext, isHitOverride: !isFail });
                                                                    }}
                                                                    className="text-[10px] font-black uppercase text-stone-500 hover:text-parchment border border-stone-800 px-3 py-1 rounded bg-stone-900 transition-colors"
                                                                >
                                                                    Flip Result
                                                                </button>
                                                                {isOverridden && (
                                                                    <button
                                                                        onClick={() => setWizardContext({ ...wizardContext, isHitOverride: null })}
                                                                        className="text-[10px] font-black uppercase text-blood border border-blood/30 px-3 py-1 rounded bg-blood/10 transition-colors"
                                                                    >
                                                                        Reset
                                                                    </button>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            }

                                            return null;
                                        })()
                                    ) : (
                                        <div className="w-full space-y-4">
                                            <h3 className="text-gold font-bold text-xs uppercase tracking-widest text-center">Multi-Target Results</h3>
                                            <div className="grid grid-cols-1 gap-2 max-h-60 overflow-y-auto p-2">
                                                {wizardContext.selectedTargets.map((t: Combatant, idx: number) => {
                                                    const res = wizardContext.multiTargetResults.find((r: any) => r.targetId === t.id && r.instanceIdx === idx);
                                                    const isAttack = action.toHit !== undefined;
                                                    const effectiveAc = t.ac; // No individual overrides for multi-target yet to keep it simple
                                                    const isFail = isAttack
                                                        ? (res ? res.total < effectiveAc : false)
                                                        : (res ? res.roll < (action.saveDc || 10) : false);

                                                    return (
                                                        <div key={`${t.id}-${idx}`} className="bg-stone-900 border border-stone-800 p-3 rounded-lg flex items-center justify-between">
                                                            <span className="text-parchment font-bold text-sm truncate">{t.name} (Ray {idx + 1})</span>
                                                            <div className="flex items-center gap-3">
                                                                <input
                                                                    type="number"
                                                                    placeholder="Roll"
                                                                    className="w-16 bg-stone-950 border border-stone-700 rounded px-2 py-1 text-xs font-mono text-gold text-right"
                                                                    value={res?.roll || ''}
                                                                    onChange={(e) => {
                                                                        const val = parseInt(e.target.value);
                                                                        const bonus = wizardContext.overrideToHit !== null ? wizardContext.overrideToHit : (action.toHit || 0);
                                                                        const newResults = [...wizardContext.multiTargetResults.filter((r: any) => !(r.targetId === t.id && r.instanceIdx === idx))];
                                                                        if (!isNaN(val)) {
                                                                            newResults.push({
                                                                                targetId: t.id,
                                                                                instanceIdx: idx,
                                                                                roll: val,
                                                                                total: val + (action.toHit !== undefined ? bonus : 0),
                                                                                isCrit: val === 20,
                                                                                isFumble: val === 1
                                                                            });
                                                                        }
                                                                        setWizardContext({ ...wizardContext, multiTargetResults: newResults });
                                                                    }}
                                                                />
                                                                {res && (
                                                                    <div className={`p-1 rounded ${isFail ? 'bg-blood/20 text-blood' : 'bg-green-500/20 text-green-500'}`}>
                                                                        {isFail ? <X size={14} /> : <CheckCircle2 size={14} />}
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                            <p className="text-[10px] text-stone-500 text-center italic">Enter individual rolls for each target above.</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}

                        {step === 'damage' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                                {/* coaching */}
                                <div className="bg-gold/5 border border-gold/20 p-4 rounded-lg">
                                    <h3 className="text-gold font-bold text-xs uppercase tracking-widest mb-2 flex items-center gap-2">
                                        <Info size={14} /> DM coaching: {isActorPlayer ? 'Ask for Damage' : 'Monster Damage'}
                                    </h3>
                                    <p className="text-parchment text-sm">
                                        {isActorPlayer
                                            ? `Say this: "${actor.name}, great hit! Roll your damage: ${action.damageNotation || '1d6'} ${action.damageType || ''}."`
                                            : `${actor.name} deals damage to the target. Roll ${action.damageNotation || '1d6'}.`}
                                    </p>
                                </div>

                                {/* Target Resistance Analysis */}
                                <div className="bg-stone-900 border border-stone-800 p-4 rounded-lg">
                                    <h4 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                        <Shield size={14} /> Target Resistance Check
                                    </h4>
                                    <div className="flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="text-sm">
                                                <p className="font-bold text-parchment">{wizardContext.selectedTargets[0].name}</p>
                                                <p className="text-xs text-stone-500">Damage Type: <span className="text-gold uppercase font-black">{action.damageType || 'Typeless'}</span></p>
                                            </div>
                                        </div>
                                        <div className="flex gap-2">
                                            {(['Normal', 'Resistant', 'Immune', 'Vulnerable'] as const).map(mode => (
                                                <button
                                                    key={mode}
                                                    onClick={() => setWizardContext({ ...wizardContext, damageMod: mode })}
                                                    className={`px-3 py-1.5 rounded text-[10px] font-black uppercase transition-all border ${wizardContext.damageMod === mode
                                                        ? 'bg-gold border-gold text-stone-950'
                                                        : 'bg-stone-950 border-stone-800 text-stone-500 hover:text-stone-300'
                                                        }`}
                                                >
                                                    {mode}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                {/* Damage Inputs */}
                                <div className="space-y-6">
                                    {/* Multi-Instance Damage (MM, Scorching Ray) */}
                                    {(action.name.toLowerCase().includes('magic missile') || action.name.toLowerCase().includes('scorching ray')) ? (
                                        <div className="space-y-4">
                                            <div className="flex items-center justify-between">
                                                <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest flex items-center gap-1.5">
                                                    <Zap size={12} className="text-gold" /> Damage per Instance
                                                </label>
                                                <button
                                                    onClick={() => {
                                                        const notation = action.damageNotation || '1d4+1';
                                                        const match = notation.match(/(\d+)d(\d+)(?:\s*([+-])\s*(\d+))?/);
                                                        const newResults = [...wizardContext.multiTargetResults];

                                                        wizardContext.selectedTargets.forEach((_item: any, idx: number) => {
                                                            let total = 0;
                                                            if (match) {
                                                                const num = parseInt(match[1]);
                                                                const sides = parseInt(match[2]);
                                                                const op = match[3];
                                                                const mod = parseInt(match[4] || '0');

                                                                const isCrit = wizardContext.multiTargetResults[idx]?.isCrit || false;
                                                                const numDice = isCrit ? num * 2 : num;

                                                                for (let i = 0; i < numDice; i++) total += Math.floor(Math.random() * sides) + 1;
                                                                if (op === '-') total -= mod;
                                                                else total += mod;
                                                            }

                                                            const existing = newResults.find((r: any) => r.instanceIdx === idx);
                                                            if (existing) {
                                                                existing.damage = total;
                                                            } else {
                                                                newResults.push({ targetId: wizardContext.selectedTargets[idx].id, instanceIdx: idx, damage: total });
                                                            }
                                                        });
                                                        setWizardContext({ ...wizardContext, multiTargetResults: newResults });
                                                    }}
                                                    className="text-[10px] text-gold hover:text-white uppercase font-bold tracking-tight px-2 py-1 bg-gold/10 border border-gold/30 rounded"
                                                >
                                                    Roll All Instances ({action.damageNotation || '1d4+1'})
                                                </button>
                                            </div>
                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar">
                                                {wizardContext.selectedTargets.map((t: Combatant, idx: number) => {
                                                    const res = wizardContext.multiTargetResults.find((r: any) => r.instanceIdx === idx);
                                                    return (
                                                        <div key={`${t.id}-${idx}`} className="bg-stone-900 border border-stone-800 p-3 rounded-lg flex items-center justify-between gap-4">
                                                            <div className="flex-1 min-w-0">
                                                                <p className="text-xs font-bold text-parchment truncate">{t.name}</p>
                                                                <p className="text-[10px] text-stone-500 uppercase">Instance {idx + 1}</p>
                                                            </div>
                                                            <input
                                                                type="number"
                                                                placeholder="Dmg"
                                                                className="w-16 bg-stone-950 border border-stone-700 rounded px-2 py-1.5 text-sm font-mono text-center focus:border-gold outline-none"
                                                                value={res?.damage || ''}
                                                                onChange={(e) => {
                                                                    const val = parseInt(e.target.value);
                                                                    const newResults = [...wizardContext.multiTargetResults];
                                                                    const existing = newResults.find((r: any) => r.instanceIdx === idx);
                                                                    if (existing) {
                                                                        existing.damage = isNaN(val) ? 0 : val;
                                                                    } else {
                                                                        newResults.push({ targetId: t.id, instanceIdx: idx, damage: isNaN(val) ? 0 : val });
                                                                    }
                                                                    setWizardContext({ ...wizardContext, multiTargetResults: newResults });
                                                                }}
                                                            />
                                                        </div>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                            <div className="space-y-4">
                                                <div className="space-y-2">
                                                    <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest flex items-center gap-1.5">
                                                        <Activity size={12} className="text-blood" /> Total Damage Rolled
                                                    </label>
                                                    <input
                                                        type="number"
                                                        placeholder="Enter total damage"
                                                        className="w-full bg-stone-950 border border-stone-700 rounded-lg px-4 py-3 text-lg font-mono text-parchment focus:border-gold focus:outline-none"
                                                        value={wizardContext.damageResult || ''}
                                                        onChange={(e) => {
                                                            const val = parseInt(e.target.value);
                                                            setWizardContext({
                                                                ...wizardContext,
                                                                damageResult: isNaN(val) ? null : val
                                                            });
                                                        }}
                                                    />
                                                </div>

                                                {wizardContext.selectedTargets.length > 1 && (
                                                    <div className="bg-stone-900/50 border border-stone-800 p-4 rounded-lg space-y-3">
                                                        <h4 className="text-[10px] font-bold text-gold uppercase tracking-widest">Damage Breakdown</h4>
                                                        <div className="space-y-2 max-h-40 overflow-y-auto">
                                                            {wizardContext.selectedTargets.map((t: Combatant, idx: number) => {
                                                                const saveResult = wizardContext.targetSaves[t.id];
                                                                const saved = saveResult?.saved === true;

                                                                const actionName = action.name.toLowerCase();
                                                                const isHalfOnSave = actionName.includes('fireball') || actionName.includes('breath') || actionName.includes('lightning bolt') || actionName.includes('shatter');

                                                                let multiplier = 1;
                                                                if (saved) multiplier = isHalfOnSave ? 0.5 : 0;

                                                                const count = wizardContext.selectedTargets.filter((st: any) => st.id === t.id).length;
                                                                const isFirstInstance = wizardContext.selectedTargets.findIndex((st: any) => st.id === t.id) === idx;
                                                                if (!isFirstInstance) return null;

                                                                const finalDmg = Math.floor((wizardContext.damageResult || 0) * multiplier);

                                                                return (
                                                                    <div key={t.id} className="flex justify-between items-center text-xs">
                                                                        <span className="text-stone-400 truncate">{t.name} {count > 1 ? `(x${count})` : ''}</span>
                                                                        <span className="text-blood font-mono font-bold">
                                                                            {finalDmg}
                                                                            {multiplier !== 1 && <span className="text-[10px] text-stone-600 ml-1">(half)</span>}
                                                                        </span>
                                                                    </div>
                                                                );
                                                            })}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>

                                            <div className="space-y-2">
                                                <label className="text-[10px] font-bold text-stone-400 uppercase tracking-widest flex items-center gap-1.5">
                                                    <Dice5 size={12} className="text-arcane" /> Roll Digitally
                                                </label>
                                                <button
                                                    onClick={() => {
                                                        const notation = action.damageNotation || '1d6';
                                                        const match = notation.match(/(\d+)d(\d+)(?:\s*([+-])\s*(\d+))?/);
                                                        if (match) {
                                                            const num = parseInt(match[1]);
                                                            const sides = parseInt(match[2]);
                                                            const op = match[3];
                                                            const mod = parseInt(match[4] || '0');

                                                            let numDice = num;
                                                            if (wizardContext.isCrit) {
                                                                numDice *= 2; // Official 5e: Roll twice the number of dice
                                                            }

                                                            let total = 0;
                                                            for (let i = 0; i < numDice; i++) total += Math.floor(Math.random() * sides) + 1;

                                                            if (op === '-') total -= mod;
                                                            else total += mod;

                                                            setWizardContext({ ...wizardContext, damageResult: total });
                                                        }
                                                    }}
                                                    className="w-full h-[52px] bg-stone-900 border border-stone-800 hover:border-gold/50 text-parchment rounded-lg font-mono flex items-center justify-center gap-2 transition-all"
                                                >
                                                    <Dice5 size={18} className="text-gold" />
                                                    <span>Roll {action.damageNotation || '1d6'}</span>
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {/* Damage Preview */}
                                {wizardContext.damageResult !== null && (
                                    <div className="bg-stone-900 border border-stone-800 p-4 rounded-lg space-y-4 animate-in zoom-in duration-300">
                                        <div className="grid grid-cols-1 gap-3 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                                            {wizardContext.selectedTargets.reduce((acc: any[], t: Combatant) => {
                                                if (!acc.find(x => x.id === t.id)) acc.push(t);
                                                return acc;
                                            }, []).map((t: Combatant) => {
                                                const count = wizardContext.selectedTargets.filter((st: any) => st.id === t.id).length;
                                                const isMultiInstance = action.name.toLowerCase().includes('magic missile') ||
                                                    action.name.toLowerCase().includes('scorching ray');

                                                const isSplit = !isMultiInstance && (action.toHit !== undefined && wizardContext.selectedTargets.length > 1);

                                                let baseDmg = 0;
                                                if (isMultiInstance) {
                                                    // Sum up damage for all instances targeting this creature
                                                    baseDmg = wizardContext.multiTargetResults
                                                        .filter((r: any) => r.targetId === t.id)
                                                        .reduce((sum: number, r: any) => sum + (r.damage || 0), 0);
                                                } else {
                                                    baseDmg = isSplit
                                                        ? (wizardContext.damageResult || 0) / wizardContext.selectedTargets.length
                                                        : (wizardContext.damageResult || 0);
                                                }

                                                const saveResult = wizardContext.targetSaves[t.id];
                                                const saved = saveResult?.saved === true;

                                                const actionName = action.name.toLowerCase();
                                                const isHalfOnSave = actionName.includes('fireball') || actionName.includes('breath') || actionName.includes('lightning bolt') || actionName.includes('shatter');

                                                let multiplier = 1;
                                                if (saved) multiplier = isHalfOnSave ? 0.5 : 0;

                                                if (wizardContext.damageMod === 'Resistant') multiplier *= 0.5;
                                                if (wizardContext.damageMod === 'Immune') multiplier = 0;
                                                if (wizardContext.damageMod === 'Vulnerable') multiplier *= 2;

                                                const finalDmg = Math.floor(baseDmg * count * multiplier);
                                                const newHp = Math.max(0, t.currentHp - finalDmg);

                                                return (
                                                    <div key={t.id} className="flex items-center justify-between border-b border-stone-800/50 pb-2 last:border-0 last:pb-0">
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-xs font-bold text-parchment truncate">{t.name} {count > 1 ? `(x${count})` : ''}</p>
                                                            <p className="text-[10px] text-stone-500 font-mono">
                                                                HP: {t.currentHp} → <span className={newHp < t.currentHp ? 'text-blood font-bold' : 'text-stone-300'}>{newHp}</span>
                                                            </p>
                                                        </div>
                                                        <div className="text-right ml-4">
                                                            <p className="text-[10px] text-stone-500 uppercase font-black">Dealt</p>
                                                            <p className="text-xs font-mono font-black text-blood">-{finalDmg}</p>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {step === 'effect' && (
                            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">
                                <div className="bg-gold/5 border border-gold/20 p-4 rounded-lg">
                                    <h3 className="text-gold font-bold text-xs uppercase tracking-widest mb-2 flex items-center gap-2">
                                        <Info size={14} /> DM coaching: {isActorPlayer ? 'Additional Effects' : 'Monster Effects'}
                                    </h3>
                                    <p className="text-parchment text-sm">
                                        {isActorPlayer
                                            ? `Does ${action.name} apply any conditions to ${wizardContext.selectedTargets[0].name}?`
                                            : `Apply any additional effects from ${action.name}.`}
                                    </p>
                                </div>

                                <div className="space-y-4">
                                    {/* Condition Save Prompt Sub-module */}
                                    {wizardContext.conditionToSave && (
                                        <div className="bg-arcane/10 border border-arcane/30 p-4 rounded-lg animate-in zoom-in duration-300 space-y-4 shadow-[0_0_20px_rgba(139,92,246,0.1)]">
                                            <div className="flex items-center justify-between">
                                                <h4 className="text-sm font-black text-arcane flex items-center gap-2 uppercase tracking-widest">
                                                    <AlertCircle size={16} /> Save Required: {wizardContext.conditionToSave.name}
                                                </h4>
                                                <button
                                                    onClick={() => setWizardContext({ ...wizardContext, conditionToSave: null })}
                                                    className="text-stone-500 hover:text-parchment transition-colors"
                                                >
                                                    <X size={16} />
                                                </button>
                                            </div>

                                            <div className="p-3 bg-stone-950/50 border border-arcane/20 rounded-lg">
                                                <p className="text-xs text-parchment leading-relaxed text-center">
                                                    Ask the target for a <span className="text-gold font-bold">{ABILITY_NAMES[action.saveAbility || 'dex'] || 'DEX'} Saving Throw</span>
                                                    <br />
                                                    <span className="text-stone-500 font-black">DC {action.saveDc || 10}</span>
                                                </p>
                                            </div>

                                            <div className="grid grid-cols-1 gap-2">
                                                <div className="flex items-center gap-2">
                                                    <input
                                                        type="number"
                                                        placeholder="Dice roll result"
                                                        className="flex-1 bg-stone-950 border border-arcane/30 rounded px-3 py-2 text-sm font-mono text-gold focus:border-gold focus:outline-none"
                                                        value={wizardContext.manualRollInput}
                                                        onChange={(e) => setWizardContext({ ...wizardContext, manualRollInput: e.target.value })}
                                                    />
                                                    <button
                                                        onClick={() => {
                                                            const val = parseInt(wizardContext.manualRollInput);
                                                            if (isNaN(val)) return;

                                                            const dc = action.saveDc || 10;
                                                            if (val >= dc) {
                                                                setWizardContext({ ...wizardContext, conditionToSave: null, manualRollInput: '' });
                                                            } else {
                                                                setWizardContext({
                                                                    ...wizardContext,
                                                                    selectedConditions: [...wizardContext.selectedConditions, wizardContext.conditionToSave],
                                                                    conditionToSave: null,
                                                                    manualRollInput: ''
                                                                });
                                                            }
                                                        }}
                                                        disabled={!wizardContext.manualRollInput}
                                                        className="bg-arcane text-stone-950 px-4 py-2 rounded font-black text-[10px] uppercase hover:bg-arcane/80 disabled:opacity-50 disabled:cursor-not-allowed"
                                                    >
                                                        Confirm
                                                    </button>
                                                </div>

                                                <div className="grid grid-cols-2 gap-2">
                                                    <button
                                                        onClick={() => {
                                                            const d20 = Math.floor(Math.random() * 20) + 1;
                                                            const dc = action.saveDc || 10;
                                                            if (d20 >= dc) {
                                                                setWizardContext({ ...wizardContext, conditionToSave: null });
                                                            } else {
                                                                setWizardContext({
                                                                    ...wizardContext,
                                                                    selectedConditions: [...wizardContext.selectedConditions, wizardContext.conditionToSave],
                                                                    conditionToSave: null
                                                                });
                                                            }
                                                        }}
                                                        className="bg-stone-900 border border-stone-800 p-3 rounded-lg text-[10px] font-black text-parchment hover:border-arcane hover:bg-arcane/5 transition-all flex flex-col items-center gap-1 uppercase"
                                                    >
                                                        <Dice5 size={14} className="text-arcane" /> Digital Save
                                                    </button>
                                                    <button
                                                        onClick={() => {
                                                            setWizardContext({
                                                                ...wizardContext,
                                                                selectedConditions: [...wizardContext.selectedConditions, wizardContext.conditionToSave],
                                                                conditionToSave: null
                                                            });
                                                        }}
                                                        className="bg-stone-900 border border-stone-800 p-3 rounded-lg text-[10px] font-black text-gold hover:border-gold hover:bg-gold/5 transition-all flex flex-col items-center gap-1 uppercase"
                                                    >
                                                        <Zap size={14} className="text-gold" /> DM Override
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    )}

                                    {/* Concentration Toggle */}
                                    {action.requiresConcentration && (
                                        <button
                                            onClick={() => setWizardContext({ ...wizardContext, applyConcentration: !wizardContext.applyConcentration })}
                                            className={`w-full p-4 rounded-lg border flex items-center justify-between transition-all ${wizardContext.applyConcentration ? 'bg-arcane/10 border-arcane shadow-[0_0_15px_rgba(139,92,246,0.1)]' : 'bg-stone-900/50 border-stone-800'}`}
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className={`w-10 h-10 rounded-lg flex items-center justify-center border transition-all ${wizardContext.applyConcentration ? 'bg-arcane/20 border-arcane text-arcane' : 'bg-stone-800 border-stone-700 text-stone-500'}`}>
                                                    <Activity size={20} />
                                                </div>
                                                <div className="text-left">
                                                    <p className={`font-bold text-sm ${wizardContext.applyConcentration ? 'text-arcane' : 'text-parchment'}`}>Begin Concentration</p>
                                                    <p className="text-[10px] text-stone-500 uppercase font-black">Actor will be marked as concentrating</p>
                                                </div>
                                            </div>
                                            <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${wizardContext.applyConcentration ? 'bg-arcane border-arcane' : 'bg-transparent border-stone-600'}`}>
                                                {wizardContext.applyConcentration && <CheckCircle2 size={12} className="text-white" />}
                                            </div>
                                        </button>
                                    )}

                                    {/* Concentration Save Prompt */}
                                    {wizardContext.selectedTargets.some((t: any) => t.isConcentrating) && !wizardContext.concentrationSaveTargetId && (
                                        <div className="bg-blood/5 border border-blood/20 p-4 rounded-lg flex items-center justify-between animate-in fade-in slide-in-from-top duration-300">
                                            <div className="flex items-center gap-3">
                                                <Activity size={20} className="text-blood" />
                                                <div className="text-left">
                                                    <p className="font-bold text-sm text-parchment">Concentration Check Needed</p>
                                                    <p className="text-[10px] text-stone-500 uppercase font-black">Target is Concentrating and took damage</p>
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => {
                                                    const target = wizardContext.selectedTargets.find((t: any) => t.isConcentrating);
                                                    if (target) {
                                                        const dmg = wizardContext.damageResult || 0;
                                                        const dc = Math.max(10, Math.floor(dmg / 2));
                                                        setWizardContext({
                                                            ...wizardContext,
                                                            concentrationSaveTargetId: target.id,
                                                            concentrationSaveDc: dc
                                                        });
                                                    }
                                                }}
                                                className="px-4 py-2 bg-blood/10 hover:bg-blood/20 border border-blood/30 text-blood rounded text-[10px] font-black uppercase transition-all"
                                            >
                                                Resolve Now
                                            </button>
                                        </div>
                                    )}

                                    {/* Concentration Save Resolver UI */}
                                    {wizardContext.concentrationSaveTargetId && (
                                        <div className="bg-blood/10 border border-blood/30 p-4 rounded-xl space-y-4 animate-in slide-in-from-top duration-500">
                                            <div className="flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-blood/20 border border-blood/50 flex items-center justify-center text-blood">
                                                    <Activity size={22} className="animate-pulse" />
                                                </div>
                                                <div>
                                                    <h4 className="text-blood font-black uppercase text-xs tracking-widest leading-none">Concentration Save Required</h4>
                                                    <p className="text-[10px] text-stone-500 uppercase mt-1">
                                                        {allCombatants.find(c => c.id === wizardContext.concentrationSaveTargetId)?.name} must make a DC {wizardContext.concentrationSaveDc} CON Save
                                                    </p>
                                                </div>
                                            </div>

                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                                <div className="space-y-1">
                                                    <label className="text-[9px] font-black text-stone-500 uppercase">Digital Prompt</label>
                                                    <button
                                                        onClick={() => {
                                                            const d20 = Math.floor(Math.random() * 20) + 1;
                                                            const target = allCombatants.find(c => c.id === wizardContext.concentrationSaveTargetId);
                                                            const conMod = target ? Math.floor(((target.abilityScores?.con || 10) - 10) / 2) : 0;
                                                            const total = d20 + conMod;
                                                            setWizardContext({
                                                                ...wizardContext,
                                                                manualRollInput: `Roll: ${d20} + ${conMod} = ${total}`
                                                            });
                                                        }}
                                                        className="w-full h-10 bg-stone-900 hover:bg-stone-800 border border-stone-800 text-parchment rounded-lg flex items-center justify-center gap-2 transition-all font-mono text-xs"
                                                    >
                                                        <Dice5 size={16} className="text-gold" /> Roll for them
                                                    </button>
                                                </div>
                                                <div className="space-y-1">
                                                    <label className="text-[9px] font-black text-stone-500 uppercase">Effect</label>
                                                    <div className="flex gap-2">
                                                        <button
                                                            onClick={() => {
                                                                setWizardContext({
                                                                    ...wizardContext,
                                                                    concentrationSaveTargetId: null,
                                                                    manualRollInput: ''
                                                                });
                                                            }}
                                                            className="flex-1 h-10 bg-green-500/10 hover:bg-green-500/20 border border-green-500/30 text-green-500 rounded-lg font-black uppercase text-[10px]"
                                                        >
                                                            Success
                                                        </button>
                                                        <button
                                                            onClick={() => {
                                                                setWizardContext({
                                                                    ...wizardContext,
                                                                    concentrationSaveTargetId: null,
                                                                    manualRollInput: '',
                                                                    selectedConditions: [...wizardContext.selectedConditions, { id: 'lost-con', name: 'Broke Concentration', icon: '💥' }]
                                                                });
                                                            }}
                                                            className="flex-1 h-10 bg-blood/10 hover:bg-blood/20 border border-blood/30 text-blood rounded-lg font-black uppercase text-[10px]"
                                                        >
                                                            Fail
                                                        </button>
                                                    </div>
                                                </div>
                                            </div>
                                            {wizardContext.manualRollInput && (
                                                <p className="text-center text-[10px] text-stone-400">
                                                    {wizardContext.manualRollInput}
                                                </p>
                                            )}
                                        </div>
                                    )}

                                    {/* Conditions Grid */}
                                    <div className="space-y-2">
                                        <h4 className="text-[10px] font-bold text-stone-500 uppercase tracking-[0.2em] px-1">Conditions to Apply</h4>
                                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                                            {COMMON_CONDITIONS.map(condition => {
                                                const isSelected = wizardContext.selectedConditions.some((c: any) => c.id === condition.id);
                                                const isPending = wizardContext.conditionToSave?.id === condition.id;

                                                return (
                                                    <button
                                                        key={condition.id}
                                                        onClick={() => {
                                                            if (isSelected) {
                                                                setWizardContext({
                                                                    ...wizardContext,
                                                                    selectedConditions: wizardContext.selectedConditions.filter((c: any) => c.id !== condition.id)
                                                                });
                                                            } else {
                                                                setWizardContext({ ...wizardContext, conditionToSave: condition });
                                                            }
                                                        }}
                                                        className={`p-2 rounded-lg border text-left transition-all flex items-center justify-between ${isSelected ? 'bg-gold/10 border-gold shadow-[0_0_10px_rgba(255,215,0,0.1)]' : isPending ? 'bg-arcane/10 border-arcane border-dashed animate-pulse' : 'bg-stone-900 border-stone-800 hover:border-stone-700'}`}
                                                    >
                                                        <span className="text-[10px] font-bold text-parchment flex items-center gap-1">
                                                            <span className="text-base">{condition.icon}</span>
                                                            {condition.name}
                                                        </span>
                                                        {isSelected && <CheckCircle2 size={12} className="text-gold" />}
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}

                        {step === 'summary' && (
                            <div className="space-y-6 text-center animate-in zoom-in duration-500">
                                {wizardContext.slowSpellFailed ? (
                                    <>
                                        <div className="w-16 h-16 rounded-full bg-blood/10 border border-blood/30 flex items-center justify-center text-blood mx-auto mb-4 animate-pulse">
                                            <AlertCircle size={32} />
                                        </div>
                                        <h3 className="text-2xl font-black text-blood uppercase">Spell Delayed!</h3>
                                        <p className="text-sm text-stone-400 max-w-sm mx-auto">
                                            The <span className="text-gold font-bold">Slow</span> condition has caused the magical energies to falter. The spell is delayed until your next turn (or lost if concentration breaks).
                                        </p>
                                    </>
                                ) : (
                                    <>
                                        <div className="w-16 h-16 rounded-full bg-gold/10 border border-gold/30 flex items-center justify-center text-gold mx-auto mb-4">
                                            <CheckCircle2 size={32} />
                                        </div>
                                        <h3 className="text-2xl font-black text-parchment uppercase">Action Complete</h3>
                                    </>
                                )}
                                <div className="bg-stone-900/50 border border-stone-800 rounded-xl divide-y divide-stone-800 text-left max-w-sm mx-auto">
                                    <div className="p-4 flex justify-between">
                                        <span className="text-xs text-stone-500 uppercase">Target{wizardContext.selectedTargets.length > 1 ? 's' : ''}</span>
                                        <span className="text-sm font-bold text-parchment text-right">
                                            {wizardContext.selectedTargets.length > 3
                                                ? `${wizardContext.selectedTargets.length} Creatures`
                                                : wizardContext.selectedTargets.reduce((acc: any[], t: Combatant) => {
                                                    if (!acc.find(x => x.id === t.id)) acc.push(t);
                                                    return acc;
                                                }, []).map((t: any) => t.name).join(', ')
                                            }
                                        </span>
                                    </div>
                                    <div className="p-4 flex justify-between">
                                        <span className="text-xs text-stone-500 uppercase">Roll Result</span>
                                        <span className="text-sm font-bold text-parchment font-mono">{wizardContext.rollResult}</span>
                                    </div>
                                    {wizardContext.selectedConditions.length > 0 && (
                                        <div className="p-4 flex flex-col gap-2">
                                            <span className="text-xs text-stone-500 uppercase">Conditions Applied</span>
                                            <div className="flex flex-wrap gap-2">
                                                {wizardContext.selectedConditions.map((c: any) => (
                                                    <span key={c.id} className="text-[10px] font-bold bg-gold/10 text-gold border border-gold/30 px-2 py-0.5 rounded flex items-center gap-1">
                                                        <span>{c.icon}</span> {c.name}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                    {wizardContext.applyConcentration && (
                                        <div className="p-4 flex justify-between bg-arcane/5">
                                            <span className="text-xs text-arcane uppercase font-black">Concentration</span>
                                            <span className="text-[10px] font-black text-arcane uppercase">Active</span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Footer Actions */}
                    <div className="p-4 border-t border-stone-800 bg-stone-900/50 flex items-center justify-between">
                        <button
                            onClick={handleBack}
                            disabled={!canGoBack}
                            className="flex items-center gap-2 px-4 py-2 text-stone-500 hover:text-parchment disabled:opacity-0 transition-all font-bold text-sm"
                        >
                            <ChevronLeft size={16} /> Back
                        </button>

                        <button
                            onClick={handleNext}
                            className="flex items-center gap-2 px-8 py-3 bg-gold/20 hover:bg-gold/30 border border-gold/50 text-gold rounded-lg text-sm font-black uppercase tracking-wider transition-all shadow-[0_0_15px_rgba(255,215,0,0.1)] active:scale-[0.98]"
                        >
                            {isLastStep ? 'Finalize Action' : 'Continue'} <ChevronRight size={16} />
                        </button>
                    </div>
                </div>

                {/* Rules Side Panel */}
                {wizardContext.showRules && (
                    <div className="w-80 bg-stone-900 border-l border-stone-800 flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden">
                        <div className="p-4 border-b border-stone-800 flex items-center justify-between bg-stone-950">
                            <h3 className="text-xs font-black text-gold uppercase tracking-[0.2em] flex items-center gap-2">
                                <BookOpen size={14} /> Rule Reference
                            </h3>
                            <button
                                onClick={() => setWizardContext({ ...wizardContext, showRules: false })}
                                className="text-stone-500 hover:text-parchment"
                            >
                                <X size={16} />
                            </button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                            {currentRule ? (
                                <div className="space-y-4">
                                    <div className="p-4 bg-stone-950/50 border border-gold/10 rounded-lg">
                                        <h4 className="text-parchment font-bold text-sm mb-2 underline decoration-gold/30">{currentRule.name}</h4>
                                        <p className="text-xs text-stone-400 leading-relaxed whitespace-pre-wrap">{currentRule.description}</p>
                                    </div>

                                    {(currentRule as any).whenToUse && (
                                        <div className="p-4 bg-gold/5 border border-gold/10 rounded-lg">
                                            <h5 className="text-[10px] font-black text-gold uppercase mb-2">When to use:</h5>
                                            <p className="text-[11px] text-parchment italic leading-relaxed">{(currentRule as any).whenToUse}</p>
                                        </div>
                                    )}

                                    {(currentRule as any).saves && (
                                        <div className="p-4 bg-arcane/5 border border-arcane/10 rounded-lg">
                                            <h5 className="text-[10px] font-black text-arcane uppercase mb-2">Saving Throws:</h5>
                                            <p className="text-[11px] text-parchment italic leading-relaxed">{(currentRule as any).saves}</p>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div className="flex flex-col items-center justify-center py-12 text-center">
                                    <Info size={32} className="text-stone-700 mb-2" />
                                    <p className="text-xs text-stone-500 italic">No specific rule found for this step.</p>
                                </div>
                            )}

                            {/* Quick Links */}
                            <div className="pt-4 border-t border-stone-800 space-y-2">
                                <h5 className="text-[9px] font-black text-stone-500 uppercase tracking-widest px-1">Common Rules</h5>
                                <div className="flex flex-wrap gap-1.5">
                                    {['attack-action', 'saving-throw', 'magic-action', 'study-action'].map(id => (
                                        <button
                                            key={id}
                                            onClick={() => setWizardContext({ ...wizardContext, activeRuleId: id })}
                                            className={`px-2 py-1 rounded text-[9px] font-bold transition-all ${wizardContext.activeRuleId === id ? 'bg-gold text-stone-950' : 'bg-stone-800 text-stone-400 hover:text-parchment'}`}
                                        >
                                            {CORE_RULE_DESCRIPTIONS[id]?.name || id}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div >,
        document.body
    );
}

import { useState } from 'react';
import { useCombatStore } from '../../store/combatStore';
import { useCharacterStore } from '../../store/characterStore';
import { X, Plus, UserPlus, Search, Ghost, Users, Shield } from 'lucide-react';
import { Combatant } from '../../types/combat';
import { FiveEToolsModal } from '../common/FiveEToolsModal';
import { parseMonsterSpellSlots } from '../../engine/fiveEToolsParser';

interface AddCombatantModalProps {
    onClose: () => void;
}

export function AddCombatantModal({ onClose }: AddCombatantModalProps) {
    const activeEncounter = useCombatStore((state) => state.activeEncounter);
    const addCombatant = useCombatStore((state) => state.addCombatant);
    const addLog = useCombatStore((state) => state.addLog);
    const characters = useCharacterStore((state) => state.characters);

    const [activeTab, setActiveTab] = useState<'manual' | 'players' | 'monsters'>('manual');
    const [isMonsterSearchOpen, setIsMonsterSearchOpen] = useState(false);

    // Manual tab state
    const [initiative, setInitiative] = useState('');
    const [name, setName] = useState('');

    // Import state
    const [importInitiative, setImportInitiative] = useState<{ [key: string]: string }>({});

    if (!activeEncounter) return null;

    const handleAddCustom = () => {
        if (!name || !initiative) return;

        const newCombatant: Combatant = {
            id: crypto.randomUUID(),
            name,
            type: 'npc',
            ac: 10,
            maxHp: 10,
            currentHp: 10,
            tempHp: 0,
            initiativeScore: parseInt(initiative),
            initiativeMod: 0,
            dexterityScore: 10,
            conditions: [],
            speed: '30 ft',
            isJoinedMidRound: true // New mid-combat additions wait for next round
        };

        addCombatant(newCombatant);
        addLog({
            message: `[System] ${name} joined the combat (Initiative ${initiative}).`,
            type: 'system'
        });
        onClose();
    };

    const handleAddPlayer = (char: any) => {
        const initRoll = importInitiative[char.id] || '10';

        const getVal = (field: string, fallback: any) => {
            const ov = char.customOverrides?.overrides?.find((o: any) => o.field === field && o.isActive);
            return ov ? ov.value : char[field] ?? fallback;
        };

        const combatant: Combatant = {
            id: crypto.randomUUID(),
            type: 'player',
            name: char.name,
            ac: Number(getVal('ac', 10)),
            maxHp: Number(char.maxHp) || 10,
            currentHp: Number(char.currentHp) || 10,
            tempHp: Number(char.tempHp) || 0,
            speed: getVal('speed', '30 ft'),
            initiativeMod: Number(getVal('initiativeMod', 0)),
            initiativeScore: parseInt(initRoll) || 10,
            dexterityScore: Number(char.abilityScores?.dex) || 10,
            conditions: [...char.conditions],
            abilityScores: char.abilityScores ? {
                str: Number(char.abilityScores.str) || 10,
                dex: Number(char.abilityScores.dex) || 10,
                con: Number(char.abilityScores.con) || 10,
                int: Number(char.abilityScores.int) || 10,
                wis: Number(char.abilityScores.wis) || 10,
                cha: Number(char.abilityScores.cha) || 10,
            } : undefined,
            savingThrowProficiencies: char.savingThrows,
            proficiencyBonus: Number(char.proficiencyBonus) || 2,
            spellcastingAbility: char.spellcastingAbility,
            spellSaveDc: Number(char.spellSaveDc) || 0,
            spellAttackMod: Number(char.spellAttackMod) || 0,
            spellSlots: char.spellSlots ? [...char.spellSlots] : undefined,
            isConcentrating: false,
            sourceId: char.id,
            isJoinedMidRound: true
        };

        addCombatant(combatant);
        addLog({
            message: `[System] ${char.name} (Player) joined the combat.`,
            type: 'system'
        });
        onClose();
    };

    const handleImportMonster = (item: any) => {
        const initRoll = importInitiative['next_monster'] || importInitiative[item.name] || '10';

        const dexMod = Math.floor(((item.dex || 10) - 10) / 2);
        const speed = item.speed && typeof item.speed === 'string' ? item.speed :
            (item.speed ? Object.entries(item.speed).map(([k, v]: [string, any]) =>
                typeof v === 'number' ? `${k} ${v} ft` : (v?.number ? `${k} ${v.number} ft` : '')).filter(Boolean).join(', ') : '30 ft');

        const crNum = parseFloat(item.cr) || 0;
        const profBonus = crNum < 5 ? 2 : crNum < 9 ? 3 : crNum < 13 ? 4 : crNum < 17 ? 5 : crNum < 21 ? 6 : crNum < 25 ? 7 : crNum < 29 ? 8 : 9;
        const legendaryMax = item.legendary ? (item.legendaryActions ?? 3) : 0;

        const saveProfs: string[] = [];
        if (item.save) Object.keys(item.save).forEach(k => saveProfs.push(k));

        const combatant: Combatant = {
            id: crypto.randomUUID(),
            type: 'monster',
            name: item.name,
            ac: item.ac || 10,
            maxHp: item.hp || 10,
            currentHp: item.hp || 10,
            tempHp: 0,
            speed,
            initiativeMod: dexMod,
            initiativeScore: parseInt(initRoll) || 10,
            dexterityScore: item.dex || 10,
            abilityScores: {
                str: item.str || 10, dex: item.dex || 10, con: item.con || 10,
                int: item.int || 10, wis: item.wis || 10, cha: item.cha || 10
            },
            proficiencyBonus: profBonus,
            savingThrowProficiencies: saveProfs,
            legendaryActionsMax: legendaryMax,
            legendaryActionsRemaining: legendaryMax,
            conditions: [],
            monsterData: item,
            cr: item.cr ? (typeof item.cr === 'string' ? item.cr : item.cr.cr) : undefined,
            resistances: item.resistances,
            immunities: item.immunities,
            vulnerabilities: item.vulnerabilities,
            conditionImmunities: item.conditionImmunities,
            damageNotes: item.damageNotes,
            spellSlots: item.spellcasting ? parseMonsterSpellSlots(item.spellcasting) : undefined,
            isConcentrating: false,
            isJoinedMidRound: true
        };

        addCombatant(combatant);
        addLog({
            message: `[System] ${item.name} (Monster) joined the combat.`,
            type: 'system'
        });
        setIsMonsterSearchOpen(false);
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-stone-950/80 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-stone-900 border border-stone-800 rounded-xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                {/* Header */}
                <div className="px-6 py-4 border-b border-stone-800 flex justify-between items-center bg-stone-950/50">
                    <div className="flex items-center gap-2">
                        <UserPlus className="text-gold" size={20} />
                        <h2 className="text-xl font-cinzel font-bold text-parchment">Add Combatant</h2>
                    </div>
                    <button onClick={onClose} className="text-stone-500 hover:text-parchment transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-0 flex flex-col h-[400px]">
                    {/* Tab Navigation */}
                    <div className="flex bg-stone-950/30 border-b border-stone-800">
                        <button
                            onClick={() => setActiveTab('manual')}
                            className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider transition-colors border-b-2 ${activeTab === 'manual' ? 'border-gold text-gold bg-gold/5' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
                        >
                            <Plus size={14} className="inline mr-2" /> Manual
                        </button>
                        <button
                            onClick={() => setActiveTab('players')}
                            className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider transition-colors border-b-2 ${activeTab === 'players' ? 'border-gold text-gold bg-gold/5' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
                        >
                            <Users size={14} className="inline mr-2" /> Players
                        </button>
                        <button
                            onClick={() => setActiveTab('monsters')}
                            className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-wider transition-colors border-b-2 ${activeTab === 'monsters' ? 'border-gold text-gold bg-gold/5' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
                        >
                            <Ghost size={14} className="inline mr-2" /> Monsters
                        </button>
                    </div>

                    <div className="p-6 flex-1 overflow-y-auto custom-scrollbar">
                        {activeTab === 'manual' && (
                            <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] uppercase font-bold text-stone-500 tracking-widest pl-1">Name</label>
                                        <input
                                            type="text"
                                            placeholder="E.g. Reinforcement"
                                            value={name}
                                            onChange={(e) => setName(e.target.value)}
                                            className="w-full bg-stone-950 border border-stone-800 rounded-lg px-3 py-2 text-sm text-parchment focus:outline-none focus:border-gold transition-colors"
                                        />
                                    </div>
                                    <div className="space-y-1.5">
                                        <label className="text-[10px] uppercase font-bold text-stone-500 tracking-widest pl-1">Initiative</label>
                                        <input
                                            type="number"
                                            placeholder="Roll result"
                                            value={initiative}
                                            onChange={(e) => setInitiative(e.target.value)}
                                            className="w-full bg-stone-950 border border-stone-800 rounded-lg px-3 py-2 text-sm text-parchment focus:outline-none focus:border-gold transition-colors"
                                        />
                                    </div>
                                </div>
                                <button
                                    disabled={!name || !initiative}
                                    onClick={handleAddCustom}
                                    className={`
                                        w-full py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-all mt-4
                                        ${(!name || !initiative)
                                            ? 'bg-stone-800 text-stone-500 cursor-not-allowed'
                                            : 'bg-gold hover:bg-gold-bright text-stone-950 shadow-lg shadow-gold/10 hover:scale-[1.02]'}
                                    `}
                                >
                                    <Plus size={18} />
                                    Inject Custom NPC
                                </button>
                            </div>
                        )}

                        {activeTab === 'players' && (
                            <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                                {characters.map(char => {
                                    const isAlreadyIn = activeEncounter.combatants.some(c => c.sourceId === char.id);
                                    return (
                                        <div key={char.id} className="flex items-center justify-between p-3 bg-stone-950/50 border border-stone-800/50 rounded-lg hover:border-stone-700 transition-colors group">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-indigo-900/30 flex items-center justify-center border border-indigo-500/20">
                                                    <Shield size={14} className="text-indigo-400" />
                                                </div>
                                                <div>
                                                    <div className="text-sm font-bold text-parchment font-cinzel">{char.name}</div>
                                                    <div className="text-[10px] text-stone-500 uppercase tracking-widest">Level {char.level} {char.className}</div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <input
                                                    type="number"
                                                    placeholder="Init"
                                                    value={importInitiative[char.id] || ''}
                                                    onChange={(e) => setImportInitiative({ ...importInitiative, [char.id]: e.target.value })}
                                                    className="w-12 bg-stone-950 border border-stone-800 rounded px-1.5 py-1 text-[10px] text-center text-gold focus:outline-none focus:border-gold"
                                                />
                                                <button
                                                    disabled={isAlreadyIn}
                                                    onClick={() => handleAddPlayer(char)}
                                                    className={`px-3 py-1.5 rounded text-[10px] font-bold transition-all ${isAlreadyIn ? 'bg-stone-800 text-stone-600' : 'bg-arcane/20 text-arcane hover:bg-arcane hover:text-stone-950'}`}
                                                >
                                                    {isAlreadyIn ? 'In Encounter' : '+ Import'}
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                                {characters.length === 0 && (
                                    <div className="text-center py-8 text-stone-600">No characters found in vault.</div>
                                )}
                            </div>
                        )}

                        {activeTab === 'monsters' && (
                            <div className="space-y-4 animate-in fade-in slide-in-from-top-2 text-center py-4">
                                <div className="p-8 border-2 border-dashed border-stone-800 rounded-xl bg-stone-950/50">
                                    <Ghost size={40} className="mx-auto text-stone-700 mb-4" />
                                    <h3 className="text-parchment font-bold mb-2">Import from Bestiary</h3>
                                    <p className="text-stone-500 text-xs mb-6">Search thousands of monsters from 5e.tools libraries.</p>
                                    <div className="flex flex-col items-center gap-2 mx-auto">
                                        <div className="flex items-center gap-2 mb-2">
                                            <label className="text-[10px] text-stone-500 font-bold uppercase">Initiative for Import:</label>
                                            <input
                                                type="number"
                                                value={importInitiative['next_monster'] || '10'}
                                                onChange={(e) => setImportInitiative({ ...importInitiative, next_monster: e.target.value })}
                                                className="w-16 bg-stone-950 border border-stone-800 rounded px-2 py-1 text-xs text-center text-gold focus:outline-none focus:border-gold"
                                            />
                                        </div>
                                        <button
                                            onClick={() => {
                                                // Reset the specific name-based init if we want to use the global one as a fallback
                                                setIsMonsterSearchOpen(true);
                                            }}
                                            className="bg-stone-800 hover:bg-stone-700 text-gold font-bold px-6 py-3 rounded-lg border border-stone-700 transition-all flex items-center gap-2"
                                        >
                                            <Search size={18} /> Open Monster Lookup
                                        </button>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                <div className="px-6 py-4 bg-stone-950/50 border-t border-stone-800">
                    <p className="text-[10px] text-stone-500 text-center italic">
                        New combatants will act starting next round and are marked as 'WAIT'.
                    </p>
                </div>

                <FiveEToolsModal
                    isOpen={isMonsterSearchOpen}
                    onClose={() => setIsMonsterSearchOpen(false)}
                    onImport={(item) => handleImportMonster(item)}
                    initialCategory="Monsters"
                />
            </div>
        </div>
    );
}

import React, { useState, useRef, useMemo } from 'react';
import { BattleMapCanvas } from './BattleMapCanvas';
import { AmbientOverlay } from './AmbientOverlay';
import { Token } from './Token';
import { DrawingMode } from './ShapeControls';
import { getReachableCells } from '../../engine/gridEngine';
import { buildTargetingOverlay } from '../../engine/targetingEngine';
import { ZoomIn, ZoomOut, Maximize, Ruler, Plus, Minus, ArrowUp, ArrowDown, ArrowLeft, ArrowRight } from 'lucide-react';
import { BattleMapState, MapToken, GridPosition, MapShape, FreehandPath, TargetingMode, TargetingOverlay } from '../../types/battleMap';
import { TokenContextMenu } from './TokenContextMenu';
import { DraggablePanel } from '../common/DraggablePanel';
import { TokenTooltip } from './TokenTooltip';

interface BattleMapProps {
    mapState: BattleMapState;
    tokens: MapToken[];
    combatants?: import('../../types/combat').Combatant[];
    activeCombatantId?: string | null;
    activeCombatantConditions?: string[];
    selectedTokenId?: string | null;
    drawingMode?: DrawingMode;
    movementRemaining?: number;
    movementMax?: number; // New: Total speed for the meter
    movementOverlay?: GridPosition[];
    targeting?: TargetingMode | null;
    onTokenClick?: (tokenId: string) => void;
    onTokenMove?: (tokenId: string, position: GridPosition) => void;
    onShapeAdd?: (shape: MapShape) => void;
    onFreehandPathAdd?: (path: FreehandPath) => void;
    onFogOfWarAdd?: (shape: MapShape) => void;
    onFogOfWarFreehandAdd?: (path: FreehandPath) => void;
    onTargetSelect?: (targetIds: string[]) => void;
    contextMenu?: { x: number; y: number; tokenId: string; combatantId?: string | null } | null;
    onContextMenuOpen?: (x: number, y: number, tokenId: string, combatantId?: string | null) => void;
    onContextMenuClose?: () => void;
    onTokenUpdate?: (tokenId: string, updates: Partial<MapToken>) => void;
    onTokenRemove?: (tokenId: string) => void;
    onMarkDead?: (combatantId: string) => void;
    onRevive?: (combatantId: string) => void;
    onApplyCondition?: (combatantId: string, conditionId: string) => void;
    onActionClick?: (combatantId: string, action: import('../../types/combat').CombatAction) => void;
    onDrawingModeChange?: (mode: DrawingMode) => void;
    onEndTurn?: () => void;
    onResizeGrid?: (side: 'top' | 'bottom' | 'left' | 'right', delta: number) => void;
    hoveredAction?: import('../../types/combat').CombatAction | null;
    onConditionHover?: (name: string, e: React.MouseEvent) => void;
    onConditionLeave?: () => void;
    onViewStatBlock?: (combatantId: string) => void;
    onZoomChange?: (zoom: number) => void;
    onHoverGridChange?: (pos: GridPosition | null) => void;
    onBackgroundUpdate?: (updates: { offsetDelta?: { dx: number, dy: number }, offset?: { x: number, y: number }, scaleX?: number, scaleY?: number }) => void;
    className?: string;
    children?: React.ReactNode;
}

export const BattleMap: React.FC<BattleMapProps> = ({
    mapState,
    tokens,
    combatants = [],
    activeCombatantId,
    activeCombatantConditions = [],
    selectedTokenId,
    drawingMode = 'select',
    movementRemaining = 30,
    movementMax = 30,
    targeting = null,
    onTokenClick,
    onTokenMove,
    onShapeAdd,
    onFreehandPathAdd,
    onFogOfWarAdd,
    onFogOfWarFreehandAdd,
    onTargetSelect,
    onTokenUpdate,
    onTokenRemove,
    onMarkDead,
    onRevive,
    onApplyCondition,
    onActionClick,
    onDrawingModeChange,
    onEndTurn,
    onResizeGrid,
    hoveredAction = null,
    onConditionHover,
    onConditionLeave,
    onViewStatBlock,
    onZoomChange,
    onHoverGridChange,
    onBackgroundUpdate,
    movementOverlay = [],
    contextMenu: externalContextMenu,
    onContextMenuOpen,
    onContextMenuClose,
    className = "",
    children
}) => {
    // --- State & Refs ---
    const [draggingTokenId, setDraggingTokenId] = useState<string | null>(null);
    const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
    const [currentDragPos, setCurrentDragPos] = useState({ x: 0, y: 0 });

    const [drawingStartPos, setDrawingStartPos] = useState<GridPosition | null>(null);
    const [freehandPoints, setFreehandPoints] = useState<{ x: number, y: number }[]>([]);
    const [targetingOverlay, setTargetingOverlay] = useState<TargetingOverlay | null>(null);

    const [zoom, setZoom] = useState(1);
    const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
    const [isPanning, setIsPanning] = useState(false);
    const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 });

    const [internalContextMenu, setInternalContextMenu] = useState<{ x: number, y: number, tokenId: string, combatantId?: string | null } | null>(null);
    const contextMenu = externalContextMenu !== undefined ? externalContextMenu : internalContextMenu;
    const setContextMenu = (val: any) => {
        if (onContextMenuOpen && val) onContextMenuOpen(val.x, val.y, val.tokenId, val.combatantId);
        else if (onContextMenuClose && !val) onContextMenuClose();
        else setInternalContextMenu(val);
    };
    const [measurementStart, setMeasurementStart] = useState<GridPosition | null>(null);
    const [measurementCurrent, setMeasurementCurrent] = useState<GridPosition | null>(null);
    const [hoveredGridPos, setHoveredGridPos] = useState<GridPosition | null>(null);
    const [hoveredTokenId, setHoveredTokenId] = useState<string | null>(null);
    const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });
    const hasDragged = useRef(false);
    const dragStartMousePos = useRef({ x: 0, y: 0 });

    const containerRef = useRef<HTMLDivElement>(null);

    const isActiveCombat = !!activeCombatantId;

    // --- Keyboard Shortcuts ---
    React.useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            // Ignore if in an input/textarea
            if (['INPUT', 'TEXTAREA'].includes(document.activeElement?.tagName || '')) return;

            switch (e.key) {
                case '1': onDrawingModeChange?.('select'); break;
                case '2': onDrawingModeChange?.('rectangle'); break;
                case '3': onDrawingModeChange?.('circle'); break;
                case '4': onDrawingModeChange?.('line'); break;
                case '5': onDrawingModeChange?.('freehand'); break;
                case 'c': onDrawingModeChange?.('calibrate'); break;
                case 'f': onDrawingModeChange?.('fow-reveal'); break;
                case 'g': onDrawingModeChange?.('fow-hide'); break;
                case 'e': onDrawingModeChange?.('eraser'); break;
                case 'Escape':
                    if (targeting) onTargetSelect?.([]);
                    if (contextMenu) setContextMenu(null);
                    if (drawingMode !== 'select') onDrawingModeChange?.('select');
                    if (measurementStart) setMeasurementStart(null);
                    break;
                case ' ':
                    e.preventDefault();
                    if (isActiveCombat) onEndTurn?.();
                    break;
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [onDrawingModeChange, onEndTurn, targeting, onTargetSelect, contextMenu, isActiveCombat, drawingMode]);

    const width = mapState.gridWidth * mapState.cellSizePx;
    const height = mapState.gridHeight * mapState.cellSizePx;

    // --- Reachable Cells Calculation ---
    const reachableCells = useMemo(() => {
        if (!activeCombatantId) return [];
        const activeToken = (tokens || []).find(t => t.combatantId === activeCombatantId);
        if (!activeToken) return [];

        const blockingTerrain = (mapState.shapes || [])
            .filter(s => s.isBlockingTerrain)
            .flatMap(s => s.points);

        const hostileTokens = (tokens || [])
            .filter(t => {
                if (t.id === activeToken.id) return false;
                // Basic hostility rules
                if (activeToken.faction === 'player' || activeToken.faction === 'ally') {
                    return t.faction === 'enemy';
                }
                if (activeToken.faction === 'enemy') {
                    return t.faction === 'player' || t.faction === 'ally';
                }
                return false;
            })
            .map(t => t.position);

        return getReachableCells(activeToken.position, movementRemaining, blockingTerrain, hostileTokens);
    }, [activeCombatantId, tokens, mapState.shapes, movementRemaining]);

    // --- Helper for coordinate conversion ---
    const getClampedPos = (clientX: number, clientY: number) => {
        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) return { x: 0, y: 0 };

        // 1. Get relative to container viewport
        const relX = clientX - rect.left;
        const relY = clientY - rect.top;

        // 2. Apply inverse transform: (pos - currentOffset) / zoom
        const transformedX = (relX - panOffset.x) / zoom;
        const transformedY = (relY - panOffset.y) / zoom;

        return {
            x: Math.max(-1000, Math.min(width + 1000, transformedX)),
            y: Math.max(-1000, Math.min(height + 1000, transformedY))
        };
    };

    const getGridPosition = (x: number, y: number): GridPosition => {
        const cellSize = mapState.cellSizePx;
        return {
            col: Math.floor(x / cellSize),
            row: Math.floor(y / cellSize)
        };
    };

    // --- Mouse Handlers ---
    const handleMouseDown = (e: React.MouseEvent, token?: MapToken) => {
        const isMiddleClick = e.button === 1;
        const isAltClick = e.button === 0 && e.altKey;
        const isShiftClick = e.button === 0 && e.shiftKey;

        const pos = getClampedPos(e.clientX, e.clientY);
        const gridPos = getGridPosition(pos.x, pos.y);

        if (isShiftClick) {
            setMeasurementStart(gridPos);
            setMeasurementCurrent(gridPos);
            return;
        }

        // Right click, Middle click, or Alt+Click for panning
        if (isMiddleClick || isAltClick || e.button === 2) {
            // ALWAYS allow panning regardless of drawingMode
            if (!targeting) {
                setIsPanning(true);
                setLastMousePos({ x: e.clientX, y: e.clientY });
                dragStartMousePos.current = { x: e.clientX, y: e.clientY };
                hasDragged.current = false;
                return;
            }
        }

        if (e.button !== 0) return; // Left click only

        if (targeting) {
            e.stopPropagation();
            if (targetingOverlay && targetingOverlay.affectedCombatantIds.length > 0) {
                onTargetSelect?.(targetingOverlay.affectedCombatantIds);
            } else {
                onTargetSelect?.([]); // Clicked empty space
            }
        } else if (drawingMode === 'calibrate') {
            setIsPanning(true);
            setLastMousePos({ x: e.clientX, y: e.clientY });
        } else if (drawingMode === 'select') {
            if (token) {
                e.stopPropagation();

                // Clicking a token ALWAYS selects that combatant in the UI
                if (token.combatantId) {
                    onTokenClick?.(token.id);
                }

                setDraggingTokenId(token.id);
                const tokenX = token.position.col * mapState.cellSizePx;
                const tokenY = token.position.row * mapState.cellSizePx;
                setDragOffset({ x: pos.x - tokenX, y: pos.y - tokenY });
                setCurrentDragPos(pos);
            } else {
                // CLICKED EMPTY SPACE (Click-to-Move)
                const activeToken = tokens.find(t => t.combatantId === activeCombatantId);
                const isReachable = reachableCells.some(rc => rc.col === gridPos.col && rc.row === gridPos.row);

                if (activeToken && isReachable) {
                    onTokenMove?.(activeToken.id, gridPos);
                }

                // Deselect
                onTokenClick?.('');
            }
        } else if (drawingMode === 'freehand' || drawingMode === 'fow-hide' || drawingMode === 'fow-reveal') {
            setFreehandPoints([pos]);
        } else if (drawingMode !== 'eraser') {
            setDrawingStartPos(gridPos);
        }
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (isPanning) {
            const dx = e.clientX - lastMousePos.x;
            const dy = e.clientY - lastMousePos.y;

            if (drawingMode === 'calibrate' && onBackgroundUpdate) {
                onBackgroundUpdate({
                    offsetDelta: {
                        dx: dx / zoom,
                        dy: dy / zoom
                    }
                });
            } else {
                // Check if we've moved enough to be considered a drag
                const totalDist = Math.sqrt(
                    Math.pow(e.clientX - dragStartMousePos.current.x, 2) +
                    Math.pow(e.clientY - dragStartMousePos.current.y, 2)
                );
                if (totalDist > 5) {
                    hasDragged.current = true;
                }

                setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
            }
            setLastMousePos({ x: e.clientX, y: e.clientY });
            return;
        }

        const pos = getClampedPos(e.clientX, e.clientY);
        const gridPos = getGridPosition(pos.x, pos.y);
        setCurrentDragPos(pos);

        if (measurementStart) {
            setMeasurementCurrent(gridPos);
            return;
        }

        if (draggingTokenId) {
            // No action needed here, currentDragPos is used for rendering
        } else if (targeting) {
            const activeToken = tokens.find(t => t.combatantId === activeCombatantId);
            if (activeToken) {
                const overlay = buildTargetingOverlay(
                    targeting.action,
                    activeToken.position,
                    gridPos,
                    tokens
                );
                setTargetingOverlay(overlay);
            }
        } else if (freehandPoints.length > 0) {
            setFreehandPoints(prev => [...prev, pos]);
        }

        // Track grid hover for pathing
        const cellSize = mapState.cellSizePx;
        const gridX = Math.floor(pos.x / cellSize);
        const gridY = Math.floor(pos.y / cellSize);

        if (!hoveredGridPos || hoveredGridPos.col !== gridX || hoveredGridPos.row !== gridY) {
            setHoveredGridPos({ col: gridX, row: gridY });
            onHoverGridChange?.({ col: gridX, row: gridY });
        }
    };



    const handleMouseUp = () => {
        setIsPanning(false);
        setMeasurementStart(null);
        setMeasurementCurrent(null);
        onHoverGridChange?.(null);

        if (draggingTokenId) {
            const finalX = currentDragPos.x - dragOffset.x;
            const finalY = currentDragPos.y - dragOffset.y;
            const finalGridPos = getGridPosition(finalX + mapState.cellSizePx / 2, finalY + mapState.cellSizePx / 2);
            onTokenMove?.(draggingTokenId, {
                col: Math.max(0, Math.min(mapState.gridWidth - 1, finalGridPos.col)),
                row: Math.max(0, Math.min(mapState.gridHeight - 1, finalGridPos.row))
            });
            setDraggingTokenId(null);
        } else if (freehandPoints.length > 1) {
            if (drawingMode === 'fow-hide' || drawingMode === 'fow-reveal') {
                onFogOfWarFreehandAdd?.({
                    id: crypto.randomUUID(),
                    points: freehandPoints,
                    color: drawingMode === 'fow-hide' ? 'black' : 'white',
                    width: 20
                });
            } else {
                onFreehandPathAdd?.({
                    id: crypto.randomUUID(),
                    points: freehandPoints,
                    color: '#ef4444',
                    width: 3
                });
            }
            setFreehandPoints([]);
        } else if (drawingStartPos) {
            const endGridPos = getGridPosition(currentDragPos.x, currentDragPos.y);

            if (drawingMode === 'fow-hide' || drawingMode === 'fow-reveal') {
                const newShape: MapShape = {
                    id: crypto.randomUUID(),
                    type: 'rectangle',
                    points: [drawingStartPos, endGridPos],
                    style: {
                        stroke: 'none',
                        strokeWidth: 0,
                        fill: drawingMode === 'fow-hide' ? 'black' : 'white', // Black hides, White reveals
                        dashed: false
                    }
                };
                onFogOfWarAdd?.(newShape);
            } else if (drawingMode !== 'select' && drawingMode !== 'eraser') {
                const newShape: MapShape = {
                    id: crypto.randomUUID(),
                    type: drawingMode as any,
                    points: [drawingStartPos, endGridPos],
                    style: {
                        stroke: '#3b82f6',
                        strokeWidth: 2,
                        fill: 'rgba(59, 130, 246, 0.2)',
                        dashed: false
                    }
                };
                onShapeAdd?.(newShape);
            }
            setDrawingStartPos(null);
        }
    };

    // --- Preview Calculations ---
    const getPreviewShape = (): MapShape | null => {
        if (!drawingStartPos || drawingMode === 'select' || drawingMode === 'eraser' || drawingMode === 'freehand') return null;

        const endGridPos = getGridPosition(currentDragPos.x, currentDragPos.y);

        if (drawingMode === 'fow-hide' || drawingMode === 'fow-reveal') {
            return {
                id: 'preview',
                type: 'rectangle',
                points: [drawingStartPos, endGridPos],
                style: {
                    stroke: drawingMode === 'fow-hide' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.8)',
                    strokeWidth: 2,
                    fill: drawingMode === 'fow-hide' ? 'rgba(0,0,0,0.4)' : 'rgba(255,255,255,0.4)',
                    dashed: true
                }
            };
        }

        return {
            id: 'preview',
            type: drawingMode as any,
            points: [drawingStartPos, endGridPos],
            style: {
                stroke: '#3b82f6',
                strokeWidth: 2,
                fill: 'rgba(59, 130, 246, 0.2)',
                dashed: true
            }
        };
    };

    const getPreviewFreehand = (): FreehandPath | null => {
        if (freehandPoints.length < 2) return null;
        let color = '#ef4444';
        let width = 3;
        if (drawingMode === 'fow-hide') { color = 'rgba(0,0,0,0.5)'; width = 20; }
        else if (drawingMode === 'fow-reveal') { color = 'rgba(255,255,255,0.5)'; width = 20; }

        return {
            id: 'preview-free',
            points: freehandPoints,
            color,
            width
        };
    };

    // --- Mouse Wheel Zoom ---
    const handleWheel = (e: React.WheelEvent) => {
        // Don't zoom if Alt is pressed (reserved for draggable panels)
        if (e.altKey) return;
        e.preventDefault();

        const rect = containerRef.current?.getBoundingClientRect();
        if (!rect) return;

        // Mouse position relative to container
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        if (contextMenu) return; // Lock map movement/zoom while context menu is open

        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
        const newZoom = Math.min(3, Math.max(0.25, zoom * zoomFactor));

        // Adjust pan to zoom toward cursor position
        const zoomRatio = newZoom / zoom;
        const newPanX = mouseX - zoomRatio * (mouseX - panOffset.x);
        const newPanY = mouseY - zoomRatio * (mouseY - panOffset.y);

        setZoom(newZoom);
        setPanOffset({ x: newPanX, y: newPanY });
        onZoomChange?.(newZoom);
    };

    return (
        <div
            ref={containerRef}
            className={`relative overflow-hidden bg-stone-950 select-none ${className}`}
            style={{
                width: '100%',
                height: '100%'
            }}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onMouseDown={(e) => handleMouseDown(e)}
            onWheel={handleWheel}
            onContextMenu={(e) => {
                e.preventDefault();
                setIsPanning(false);

                // If we were dragging, don't show the context menu
                if (hasDragged.current) {
                    hasDragged.current = false;
                    return;
                }

                if (targeting) {
                    onTargetSelect?.([]); // Right-click cancels targeting
                    return;
                }

                // Check if we clicked a token
                const pos = getClampedPos(e.clientX, e.clientY);
                const gridPos = getGridPosition(pos.x, pos.y);
                const clickedToken = (tokens || []).find(t =>
                    gridPos.col >= t.position.col &&
                    gridPos.col < t.position.col + t.size &&
                    gridPos.row >= t.position.row &&
                    gridPos.row < t.position.row + t.size
                );

                if (clickedToken) {
                    if (clickedToken.combatantId) {
                        onTokenClick?.(clickedToken.id); // Select the clicked token to sync UI
                    }
                    setContextMenu({ x: e.clientX, y: e.clientY, tokenId: clickedToken.id, combatantId: clickedToken.combatantId });
                } else {
                    setContextMenu(null);
                }
            }}
        >
            {/* The base grid */}
            <div
                className="relative origin-top-left"
                style={{
                    width: Math.max(1, width),
                    height: Math.max(1, height),
                    transform: `translate(${Number.isFinite(panOffset.x) ? panOffset.x : 0}px, ${Number.isFinite(panOffset.y) ? panOffset.y : 0}px) scale(${Number.isFinite(zoom) ? zoom : 1})`,
                    cursor: isPanning ? 'grabbing' : (drawingMode !== 'select' ? 'crosshair' : 'default')
                }}
            >
                {(width <= 0 || height <= 0) && (
                    <div className="absolute inset-0 flex items-center justify-center bg-stone-900/50 text-stone-500 font-cinzel text-xs">
                        Initializing Tactical Grid...
                    </div>
                )}
                <BattleMapCanvas
                    mapState={mapState}
                    width={width}
                    height={height}
                    previewShape={getPreviewShape()}
                    previewFreehandPath={getPreviewFreehand()}
                    reachableCells={movementOverlay}
                    targetingOverlay={targeting ? targetingOverlay : null}
                    hoveredAction={hoveredAction}
                    hoveredGridPos={hoveredGridPos}
                    activeCombatantPos={(tokens || []).find(t => t.combatantId === activeCombatantId)?.position}
                    activeCombatantConditions={activeCombatantConditions}
                    movementRemaining={movementRemaining}
                    measurementStart={measurementStart}
                    measurementCurrent={measurementCurrent}
                />

                {/* Measurement Line */}
                {measurementStart && measurementCurrent && (
                    <svg className="absolute inset-0 pointer-events-none w-full h-full overflow-visible" style={{ zIndex: 100 }}>
                        <line
                            x1={measurementStart.col * mapState.cellSizePx + mapState.cellSizePx / 2}
                            y1={measurementStart.row * mapState.cellSizePx + mapState.cellSizePx / 2}
                            x2={measurementCurrent.col * mapState.cellSizePx + mapState.cellSizePx / 2}
                            y2={measurementCurrent.row * mapState.cellSizePx + mapState.cellSizePx / 2}
                            stroke="#fbbf24"
                            strokeWidth="3"
                            strokeDasharray="8 4"
                        />
                        <g transform={`translate(${measurementCurrent.col * mapState.cellSizePx}, ${measurementCurrent.row * mapState.cellSizePx})`}>
                            <rect x="-10" y="-35" width="60" height="25" rx="4" fill="rgba(0,0,0,0.8)" />
                            <text x="20" y="-18" textAnchor="middle" fill="white" fontSize="12" fontWeight="bold">
                                {Math.round(Math.sqrt(Math.pow(measurementCurrent.col - measurementStart.col, 2) + Math.pow(measurementCurrent.row - measurementStart.row, 2)) * 5)}ft
                            </text>
                        </g>
                    </svg>
                )}

                {/* Tokens Layer */}
                <div className="absolute inset-0 pointer-events-none">
                    {(tokens || []).map(token => {
                        const isDragging = token.id === draggingTokenId;

                        // Calculate visual position
                        let dragStyle: React.CSSProperties = {};
                        if (isDragging) {
                            dragStyle = {
                                left: `${currentDragPos.x - dragOffset.x} px`,
                                top: `${currentDragPos.y - dragOffset.y} px`,
                                zIndex: 50,
                                opacity: 0.9,
                                pointerEvents: 'none'
                            };
                        }

                        return (
                            <React.Fragment key={token.id}>
                                {/* Ghost preview shown only when dragging this specific token */}
                                {isDragging && (
                                    <div
                                        className="absolute opacity-30 pointer-events-none transition-all duration-150 border-2 border-dashed border-white/50 rounded-full"
                                        style={{
                                            left: `${Math.round((currentDragPos.x - dragOffset.x) / mapState.cellSizePx) * mapState.cellSizePx} px`,
                                            top: `${Math.round((currentDragPos.y - dragOffset.y) / mapState.cellSizePx) * mapState.cellSizePx} px`,
                                            width: `${token.size * mapState.cellSizePx} px`,
                                            height: `${token.size * mapState.cellSizePx} px`,
                                            zIndex: 10
                                        }}
                                    />
                                )}
                                <div className="pointer-events-auto">
                                    <Token
                                        token={token}
                                        combatant={combatants.find(c => c.id === token.combatantId)}
                                        cellSize={mapState.cellSizePx}
                                        isActive={token.combatantId === activeCombatantId || token.id === selectedTokenId}
                                        isAffected={targetingOverlay?.affectedCombatantIds.includes(token.combatantId)}
                                        movementRemaining={token.combatantId === activeCombatantId ? movementRemaining : undefined}
                                        movementMax={token.combatantId === activeCombatantId ? movementMax : undefined}
                                        onClick={() => onTokenClick?.(token.id)}
                                        isDragging={isDragging}
                                        style={dragStyle}
                                        onMouseDown={(e) => handleMouseDown(e, token)}
                                        onMouseEnter={(e) => {
                                            if (!draggingTokenId && !isPanning) {
                                                setHoveredTokenId(token.id);
                                                setTooltipPos({ x: e.clientX, y: e.clientY });
                                            }
                                        }}
                                        onMouseLeave={() => setHoveredTokenId(null)}
                                        onConditionHover={onConditionHover}
                                        onConditionLeave={onConditionLeave}
                                    />
                                </div>
                            </React.Fragment>
                        );
                    })}
                </div>

                <AmbientOverlay
                    width={width}
                    height={height}
                    type={mapState.backgroundColor.toLowerCase().includes('064e3b') ? 'sparks' : 'ash'}
                />

                {/* Custom Navigator Overlays (Room Tags, etc) */}
                {children}
            </div>

            {/* ═══ LAYER 3: FLOATING CONTROLS (DM & SHARED) ═══ */}
            <div className="absolute left-4 top-1/2 -translate-y-1/2 z-[100] flex flex-col gap-4 pointer-events-none">
                <DraggablePanel label="Map Tools" className="flex flex-col gap-4">
                    {/* Zoom Controls */}
                    <div className="flex flex-col bg-stone-900/90 backdrop-blur border border-stone-800 rounded-lg shadow-xl overflow-hidden shadow-black/50 pointer-events-auto">
                        <button
                            onClick={() => setZoom(Math.min(3, zoom * 1.2))}
                            className="p-2.5 hover:bg-stone-800 text-stone-400 hover:text-gold transition-colors border-b border-stone-800"
                            title="Zoom In"
                        >
                            <ZoomIn size={18} />
                        </button>
                        <button
                            onClick={() => setZoom(Math.max(0.25, zoom / 1.2))}
                            className="p-2.5 hover:bg-stone-800 text-stone-400 hover:text-gold transition-colors border-b border-stone-800"
                            title="Zoom Out"
                        >
                            <ZoomOut size={18} />
                        </button>
                        <button
                            onClick={() => { setZoom(1); setPanOffset({ x: 0, y: 0 }); }}
                            className="p-2.5 hover:bg-stone-800 text-stone-400 hover:text-gold transition-colors border-b border-stone-800"
                            title="Reset View"
                        >
                            <Maximize size={18} />
                        </button>
                        <div className="p-2.5 bg-stone-950/40 text-[10px] font-bold text-stone-500 text-center border-b border-stone-800">
                            {Math.round(zoom * 100)}%
                        </div>
                    </div>

                    {/* Grid Resizing Controls - DM Only */}
                    {onResizeGrid && (
                        <div className="flex flex-col bg-stone-900/90 backdrop-blur border border-stone-800 rounded-lg shadow-xl overflow-hidden shadow-black/50 pointer-events-auto">
                            <div className="p-2 bg-stone-950/40 text-[9px] font-black text-stone-500 uppercase tracking-tighter text-center border-b border-stone-800">
                                Grid Editor
                            </div>

                            {/* 4-Way Controls */}
                            <div className="p-3 grid grid-cols-3 gap-2 items-center">
                                {/* Top row */}
                                <div />
                                <div className="flex flex-col items-center gap-1">
                                    <button onClick={() => onResizeGrid('top', 1)} className="p-1 hover:bg-stone-800 text-green-500 rounded" title="Add Row Above">
                                        <Plus size={12} />
                                    </button>
                                    <ArrowUp size={14} className="text-stone-600" />
                                    <button onClick={() => onResizeGrid('top', -1)} className="p-1 hover:bg-stone-800 text-red-500 rounded" title="Remove Row Above">
                                        <Minus size={12} />
                                    </button>
                                </div>
                                <div />

                                {/* Middle row */}
                                <div className="flex items-center gap-1">
                                    <button onClick={() => onResizeGrid('left', 1)} className="p-1 hover:bg-stone-800 text-green-500 rounded" title="Add Column Left">
                                        <Plus size={12} />
                                    </button>
                                    <ArrowLeft size={14} className="text-stone-600" />
                                    <button onClick={() => onResizeGrid('left', -1)} className="p-1 hover:bg-stone-800 text-red-500 rounded" title="Remove Column Left">
                                        <Minus size={12} />
                                    </button>
                                </div>
                                <div className="flex flex-col items-center justify-center p-1 bg-stone-950/40 rounded border border-stone-800">
                                    <span className="text-[10px] font-mono text-gold leading-none">{mapState.gridWidth}</span>
                                    <span className="text-[8px] text-stone-600 font-bold">x</span>
                                    <span className="text-[10px] font-mono text-gold leading-none">{mapState.gridHeight}</span>
                                </div>
                                <div className="flex items-center gap-1">
                                    <button onClick={() => onResizeGrid('right', -1)} className="p-1 hover:bg-stone-800 text-red-500 rounded" title="Remove Column Right">
                                        <Minus size={12} />
                                    </button>
                                    <ArrowRight size={14} className="text-stone-600" />
                                    <button onClick={() => onResizeGrid('right', 1)} className="p-1 hover:bg-stone-800 text-green-500 rounded" title="Add Column Right">
                                        <Plus size={12} />
                                    </button>
                                </div>

                                {/* Bottom row */}
                                <div />
                                <div className="flex flex-col items-center gap-1">
                                    <button onClick={() => onResizeGrid('bottom', -1)} className="p-1 hover:bg-stone-800 text-red-500 rounded" title="Remove Row Below">
                                        <Minus size={12} />
                                    </button>
                                    <ArrowDown size={14} className="text-stone-600" />
                                    <button onClick={() => onResizeGrid('bottom', 1)} className="p-1 hover:bg-stone-800 text-green-500 rounded" title="Add Row Below">
                                        <Plus size={12} />
                                    </button>
                                </div>
                                <div />
                            </div>
                        </div>
                    )}

                    <div
                        className="bg-stone-900/90 backdrop-blur border border-stone-800 rounded-lg p-2.5 shadow-lg group cursor-help transition-all hover:bg-stone-800/95 pointer-events-auto"
                        title="Measurement Tool: Shift + Drag to measure distance"
                    >
                        <Ruler size={18} className="text-stone-400 group-hover:text-gold transition-colors" />
                    </div>
                </DraggablePanel>
            </div>

            {/* Context Menu */}
            {contextMenu && contextMenu.tokenId && (
                <TokenContextMenu
                    x={contextMenu.x}
                    y={contextMenu.y}
                    tokenId={contextMenu.tokenId}
                    onClose={() => setContextMenu(null)}
                    onApplyCondition={(cond) => {
                        if (contextMenu.combatantId) {
                            onApplyCondition?.(contextMenu.combatantId, cond);
                        }
                    }}
                    onMarkDead={() => {
                        if (contextMenu.combatantId) {
                            onMarkDead?.(contextMenu.combatantId);
                        }
                    }}
                    onRevive={() => {
                        if (contextMenu.combatantId) {
                            onRevive?.(contextMenu.combatantId);
                        }
                    }}
                    onRemove={() => {
                        onTokenRemove?.(contextMenu.tokenId);
                    }}
                    onUpdate={(updates) => {
                        onTokenUpdate?.(contextMenu.tokenId, updates);
                    }}
                    onActionClick={(action) => {
                        if (contextMenu.combatantId) {
                            onActionClick?.(contextMenu.combatantId, action);
                        }
                    }}
                    onViewStatBlock={() => {
                        if (contextMenu.combatantId) {
                            onViewStatBlock?.(contextMenu.combatantId);
                        }
                    }}
                    onConditionHover={onConditionHover}
                    onConditionLeave={onConditionLeave}
                    combatant={(combatants || []).find(c => c.id === contextMenu.combatantId)}
                />
            )}

            {/* Token Hover Tooltip */}
            {hoveredTokenId && !contextMenu && !draggingTokenId && (
                (() => {
                    const token = tokens.find(t => t.id === hoveredTokenId);
                    const combatant = combatants?.find(c => c.id === token?.combatantId);
                    if (token && combatant) {
                        return (
                            <TokenTooltip
                                token={token}
                                combatant={combatant}
                                x={tooltipPos.x}
                                y={tooltipPos.y}
                            />
                        );
                    }
                    return null;
                })()
            )}
        </div>
    );
};

import React, { useRef, useEffect } from 'react';
import { BattleMapState, MapShape, FreehandPath, GridPosition, TargetingOverlay } from '../../types/battleMap';
import { CombatAction } from '../../types/combat';
import { parseActionRange } from '../../engine/targetingEngine';
interface BattleMapCanvasProps {
    mapState: BattleMapState;
    width: number;
    height: number;
    className?: string;
    previewShape?: MapShape | null;
    previewFreehandPath?: FreehandPath | null;
    reachableCells?: GridPosition[] | null;
    targetingOverlay?: TargetingOverlay | null;
    hoveredAction?: CombatAction | null;
    hoveredGridPos?: GridPosition | null;
    activeCombatantPos?: GridPosition;
    activeCombatantConditions?: string[];
    movementRemaining?: number;
    measurementStart?: GridPosition | null;
    measurementCurrent?: GridPosition | null;
}

const AOE_COLOR_MAP: Record<string, { stroke: string, fill: string, glow: string }> = {
    fire: { stroke: 'rgba(239, 68, 68, 0.8)', fill: 'rgba(239, 68, 68, 0.2)', glow: 'rgba(239, 68, 68, 0.5)' },
    cold: { stroke: 'rgba(59, 130, 246, 0.8)', fill: 'rgba(59, 130, 246, 0.2)', glow: 'rgba(59, 130, 246, 0.5)' },
    lightning: { stroke: 'rgba(168, 85, 247, 0.8)', fill: 'rgba(168, 85, 247, 0.2)', glow: 'rgba(168, 85, 247, 0.5)' },
    thunder: { stroke: 'rgba(107, 114, 128, 0.8)', fill: 'rgba(107, 114, 128, 0.2)', glow: 'rgba(107, 114, 128, 0.5)' },
    acid: { stroke: 'rgba(34, 197, 94, 0.8)', fill: 'rgba(34, 197, 94, 0.2)', glow: 'rgba(34, 197, 94, 0.5)' },
    poison: { stroke: 'rgba(22, 163, 74, 0.8)', fill: 'rgba(22, 163, 74, 0.2)', glow: 'rgba(22, 163, 74, 0.5)' },
    radiant: { stroke: 'rgba(253, 224, 71, 0.8)', fill: 'rgba(253, 224, 71, 0.2)', glow: 'rgba(253, 224, 71, 0.5)' },
    necrotic: { stroke: 'rgba(88, 28, 135, 0.8)', fill: 'rgba(88, 28, 135, 0.2)', glow: 'rgba(88, 28, 135, 0.5)' },
    force: { stroke: 'rgba(219, 39, 119, 0.8)', fill: 'rgba(219, 39, 119, 0.2)', glow: 'rgba(219, 39, 119, 0.5)' },
    psychic: { stroke: 'rgba(244, 114, 182, 0.8)', fill: 'rgba(244, 114, 182, 0.2)', glow: 'rgba(244, 114, 182, 0.5)' },
    slashing: { stroke: 'rgba(148, 163, 184, 0.8)', fill: 'rgba(148, 163, 184, 0.2)', glow: 'rgba(148, 163, 184, 0.5)' },
    piercing: { stroke: 'rgba(148, 163, 184, 0.8)', fill: 'rgba(148, 163, 184, 0.2)', glow: 'rgba(148, 163, 184, 0.5)' },
    bludgeoning: { stroke: 'rgba(148, 163, 184, 0.8)', fill: 'rgba(148, 163, 184, 0.2)', glow: 'rgba(148, 163, 184, 0.5)' },
    default: { stroke: 'rgba(239, 68, 68, 0.6)', fill: 'rgba(239, 68, 68, 0.1)', glow: 'rgba(239, 68, 68, 0.3)' }
};

export const BattleMapCanvas: React.FC<BattleMapCanvasProps> = ({
    mapState,
    width,
    height,
    className = "",
    previewShape,
    previewFreehandPath,
    reachableCells,
    targetingOverlay,
    hoveredAction,
    hoveredGridPos,
    activeCombatantPos,
    activeCombatantConditions = [],
    movementRemaining = 0,
    measurementStart,
    measurementCurrent
}) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const dashOffsetRef = useRef(0);
    const bgImageRef = useRef<HTMLImageElement | null>(null);

    useEffect(() => {
        if (mapState.backgroundImageUrl) {
            const img = new window.Image();
            img.onload = () => {
                bgImageRef.current = img;
            };
            img.src = mapState.backgroundImageUrl;
        } else {
            bgImageRef.current = null;
        }
    }, [mapState.backgroundImageUrl]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas || width <= 0 || height <= 0) return;

        try {
            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            // Trace logging for debugging black screen in production-like environments
            if (width < 10 || height < 10) {
                console.warn('[BattleMapCanvas] Rendering with suspiciously small dimensions:', { width, height, cellSize: mapState.cellSizePx });
            }

            // Reset transform
            ctx.setTransform(1, 0, 0, 1, 0, 0);

            // Clear main canvas
            ctx.fillStyle = mapState.backgroundColor || '#111827';
            ctx.fillRect(0, 0, width, height);

            const cellSize = Math.max(1, mapState.cellSizePx || 40);
            const gridWidth = mapState.gridWidth || 1;
            const gridHeight = mapState.gridHeight || 1;

            if (!Number.isFinite(cellSize) || !Number.isFinite(gridWidth) || !Number.isFinite(gridHeight)) return;
            if (cellSize <= 0 || gridWidth <= 0 || gridHeight <= 0) return;
            if (gridWidth > 1000 || gridHeight > 1000) return; // Basic safety limit

            // Draw Background Image
            if (bgImageRef.current && bgImageRef.current.complete) {
                const offset = mapState.backgroundOffset || { x: 0, y: 0 };
                const scaleX = mapState.backgroundScaleX || 1.0;
                const scaleY = mapState.backgroundScaleY || 1.0;

                // Image draws relative to grid dimensions to preserve saved map compatibility
                const imgWidth = (mapState.gridWidth * cellSize) * scaleX;
                const imgHeight = (mapState.gridHeight * cellSize) * scaleY;

                ctx.drawImage(
                    bgImageRef.current,
                    offset.x,
                    offset.y,
                    imgWidth,
                    imgHeight
                );
            }

            // --- GRID RENDERING ---
            ctx.strokeStyle = mapState.gridColor || 'rgba(75, 85, 99, 0.3)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (let x = 0; x <= gridWidth * cellSize; x += cellSize) {
                ctx.moveTo(x, 0); ctx.lineTo(x, gridHeight * cellSize);
            }
            for (let y = 0; y <= gridHeight * cellSize; y += cellSize) {
                ctx.moveTo(0, y); ctx.lineTo(gridWidth * cellSize, y);
            }
            ctx.stroke();

            // --- MOVEMENT RANGE ---
            if (reachableCells && reachableCells.length > 0) {
                ctx.fillStyle = 'rgba(59, 130, 246, 0.2)';
                reachableCells.forEach(cell => {
                    ctx.fillRect(cell.col * cellSize, cell.row * cellSize, cellSize, cellSize);
                });
                ctx.strokeStyle = 'rgba(59, 130, 246, 0.4)';
                ctx.lineWidth = 1;
                reachableCells.forEach(cell => {
                    ctx.strokeRect(cell.col * cellSize, cell.row * cellSize, cellSize, cellSize);
                });
            }

            // --- SHAPES & TERRAIN ---
            const drawShape = (ctx: CanvasRenderingContext2D, shape: MapShape, offsetCellSize: number) => {
                ctx.strokeStyle = shape.style.stroke;
                ctx.lineWidth = shape.style.strokeWidth;
                ctx.fillStyle = shape.style.fill;
                ctx.setLineDash(shape.style.dashed ? [5, 5] : []);

                if (shape.type === 'rectangle' && shape.points.length >= 2) {
                    const x1 = shape.points[0].col * offsetCellSize;
                    const y1 = shape.points[0].row * offsetCellSize;
                    const x2 = shape.points[1].col * offsetCellSize;
                    const y2 = shape.points[1].row * offsetCellSize;
                    ctx.beginPath();
                    ctx.rect(x1, y1, x2 - x1, y2 - y1);
                    ctx.fill();
                    ctx.stroke();
                } else if (shape.type === 'circle' && shape.points.length >= 2) {
                    const x1 = shape.points[0].col * offsetCellSize + offsetCellSize / 2;
                    const y1 = shape.points[0].row * offsetCellSize + offsetCellSize / 2;
                    const x2 = shape.points[1].col * offsetCellSize + offsetCellSize / 2;
                    const y2 = shape.points[1].row * offsetCellSize + offsetCellSize / 2;
                    const radius = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
                    ctx.beginPath();
                    ctx.arc(x1, y1, radius, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();
                } else if (shape.type === 'line' && shape.points.length >= 2) {
                    ctx.beginPath();
                    ctx.moveTo(shape.points[0].col * offsetCellSize + offsetCellSize / 2, shape.points[0].row * offsetCellSize + offsetCellSize / 2);
                    ctx.lineTo(shape.points[1].col * offsetCellSize + offsetCellSize / 2, shape.points[1].row * offsetCellSize + offsetCellSize / 2);
                    ctx.stroke();
                }
            };

            (mapState.shapes || []).forEach(shape => drawShape(ctx, shape, cellSize));

            // --- FREEHAND ---
            ctx.setLineDash([]);
            (mapState.freehandPaths || []).forEach(path => {
                ctx.strokeStyle = path.color;
                ctx.lineWidth = path.width;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                if (path.points.length > 1) {
                    ctx.beginPath();
                    ctx.moveTo(path.points[0].x, path.points[0].y);
                    for (let i = 1; i < path.points.length; i++) ctx.lineTo(path.points[i].x, path.points[i].y);
                    ctx.stroke();
                }
            });
            ctx.stroke();

            // --- TOKEN AURAS ---
            (mapState.tokens || []).forEach(token => {
                if (token.auras && token.auras.length > 0) {
                    const centerX = token.position.col * cellSize + (token.size * cellSize) / 2;
                    const centerY = token.position.row * cellSize + (token.size * cellSize) / 2;

                    token.auras.forEach(aura => {
                        const radiusPx = (aura.radiusFt / 5) * cellSize;

                        // Draw fill
                        ctx.beginPath();
                        ctx.fillStyle = aura.color;
                        ctx.globalAlpha = aura.opacity * 0.3; // Fill is softer
                        ctx.arc(centerX, centerY, radiusPx, 0, Math.PI * 2);
                        ctx.fill();

                        // Draw ring
                        ctx.beginPath();
                        ctx.strokeStyle = aura.color;
                        ctx.lineWidth = 2;
                        ctx.globalAlpha = aura.opacity;
                        ctx.setLineDash([10, 5]); // Soft dashed ring for auras
                        ctx.arc(centerX, centerY, radiusPx, 0, Math.PI * 2);
                        ctx.stroke();
                        ctx.setLineDash([]);

                        // Add subtle glow
                        ctx.shadowBlur = 10;
                        ctx.shadowColor = aura.color;
                        ctx.stroke();
                        ctx.shadowBlur = 0;

                        ctx.globalAlpha = 1.0;
                    });
                }
            });

            // --- FOG OF WAR RENDERING ---
            // Create an off-screen canvas for the fog mask
            const fogCanvas = document.createElement('canvas');
            fogCanvas.width = width;
            fogCanvas.height = height;
            const fogCtx = fogCanvas.getContext('2d');

            if (fogCtx) {
                // 1. Initial Fog State: Semi-Transparent (DM Shading)
                fogCtx.fillStyle = 'rgba(0, 0, 0, 0.4)';
                fogCtx.fillRect(0, 0, width, height);

                // 2. Clear Revealed Areas using destination-out
                fogCtx.globalCompositeOperation = 'destination-out';

                // Revealed areas are stored as shapes with fill 'white' in mapState.fogOfWar
                (mapState.fogOfWar || []).forEach(fow => {
                    if (fow.style.fill === 'white') {
                        // Always use full opacity for the cutout operation
                        fogCtx.fillStyle = 'rgba(255, 255, 255, 1.0)';
                        drawShape(fogCtx, fow, cellSize);
                    }
                });

                // Handle Freehand Reveals/Hides
                if (mapState.fogOfWarFreehand) {
                    mapState.fogOfWarFreehand.forEach(path => {
                        const isReveal = path.color === 'white' || path.color === '#ffffff';

                        if (isReveal) {
                            fogCtx.globalCompositeOperation = 'destination-out';
                            fogCtx.strokeStyle = 'white';
                        } else {
                            fogCtx.globalCompositeOperation = 'source-over';
                            fogCtx.strokeStyle = 'rgba(0, 0, 0, 0.4)'; // Match initial fog opacity
                        }

                        fogCtx.lineWidth = path.width;
                        fogCtx.lineCap = 'round';
                        fogCtx.lineJoin = 'round';
                        if (path.points.length > 1) {
                            fogCtx.beginPath();
                            fogCtx.moveTo(path.points[0].x, path.points[0].y);
                            for (let i = 1; i < path.points.length; i++) fogCtx.lineTo(path.points[i].x, path.points[i].y);
                            fogCtx.stroke();
                        }
                    });
                }

                // Restore for final shape-based hide overrides if any
                fogCtx.globalCompositeOperation = 'source-over';
                (mapState.fogOfWar || []).forEach(fow => {
                    if (fow.style.fill === 'black') {
                        fogCtx.fillStyle = 'rgba(0, 0, 0, 0.4)';
                        drawShape(fogCtx, fow, cellSize);
                    }
                });

                // 4. Draw the fog mask onto the main canvas
                ctx.drawImage(fogCanvas, 0, 0);
            }

            // --- PREVIEWS ---
            if (previewShape) {
                ctx.strokeStyle = previewShape.style.stroke;
                ctx.lineWidth = previewShape.style.strokeWidth;
                ctx.setLineDash([5, 5]);
                drawShape(ctx, previewShape, cellSize);
            }

            if (previewFreehandPath && previewFreehandPath.points.length > 1) {
                ctx.setLineDash([]);
                ctx.strokeStyle = previewFreehandPath.color;
                ctx.lineWidth = previewFreehandPath.width;
                ctx.beginPath();
                ctx.moveTo(previewFreehandPath.points[0].x, previewFreehandPath.points[0].y);
                for (let i = 1; i < previewFreehandPath.points.length; i++) ctx.lineTo(previewFreehandPath.points[i].x, previewFreehandPath.points[i].y);
                ctx.stroke();
            }

            // --- TARGETING OVERLAY ---
            if (targetingOverlay) {
                const { originPosition, targetPosition, rangeFt, radiusFt, type, affectedCells } = targetingOverlay;
                if (rangeFt > 0) {
                    ctx.beginPath(); ctx.setLineDash([5, 5]);
                    ctx.strokeStyle = 'rgba(255, 215, 0, 0.4)'; ctx.lineWidth = 1;
                    const originX = originPosition.col * cellSize + cellSize / 2;
                    const originY = originPosition.row * cellSize + cellSize / 2;
                    const rangePx = (rangeFt / 5) * cellSize;
                    ctx.arc(originX, originY, rangePx, 0, Math.PI * 2); ctx.stroke(); ctx.setLineDash([]);
                }
                ctx.fillStyle = 'rgba(239, 68, 68, 0.15)';
                affectedCells.forEach(cell => ctx.fillRect(cell.col * cellSize, cell.row * cellSize, cellSize, cellSize));

                if (targetPosition) {
                    const targetX = (targetPosition?.col || 0) * cellSize + cellSize / 2;
                    const targetY = (targetPosition?.row || 0) * cellSize + cellSize / 2;
                    const originX = (originPosition?.col || 0) * cellSize + cellSize / 2;
                    const originY = (originPosition?.row || 0) * cellSize + cellSize / 2;
                    const radiusPx = ((radiusFt || 0) / 5) * cellSize;

                    if (isNaN(targetX) || isNaN(targetY) || isNaN(originX) || isNaN(originY) || isNaN(radiusPx)) return;

                    const damageType = (targetingOverlay.damageType || hoveredAction?.damageType || "").toLowerCase();
                    const colors = AOE_COLOR_MAP[damageType] || AOE_COLOR_MAP.default;

                    ctx.setLineDash([]); ctx.strokeStyle = colors.stroke; ctx.lineWidth = 2; ctx.fillStyle = colors.fill;
                    ctx.shadowBlur = 15; ctx.shadowColor = colors.glow;

                    if (type === 'circle') {
                        const centerX = rangeFt === 0 ? originX : targetX;
                        const centerY = rangeFt === 0 ? originY : targetY;
                        ctx.beginPath(); ctx.arc(centerX, centerY, radiusPx, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
                    } else if (type === 'cone') {
                        const lengthPx = radiusFt / 5 * cellSize;
                        const angle = Math.atan2(targetY - originY, targetX - originX);
                        const halfAngle = Math.atan(0.5);
                        ctx.beginPath(); ctx.moveTo(originX, originY);
                        ctx.arc(originX, originY, lengthPx, angle - halfAngle, angle + halfAngle);
                        ctx.closePath(); ctx.fill(); ctx.stroke();
                    } else if (type === 'line') {
                        const lengthPx = radiusFt / 5 * cellSize;
                        const angle = Math.atan2(targetY - originY, targetX - originX);
                        const endX = originX + Math.cos(angle) * lengthPx;
                        const endY = originY + Math.sin(angle) * lengthPx;
                        ctx.beginPath(); ctx.moveTo(originX, originY); ctx.lineTo(endX, endY);
                        ctx.lineWidth = cellSize; ctx.lineCap = 'round'; ctx.stroke();
                        ctx.lineCap = 'butt'; ctx.lineWidth = 2;
                    } else if (type === 'cube') {
                        ctx.beginPath();
                        if (rangeFt === 0) {
                            const angle = Math.atan2(targetY - originY, targetX - originX);
                            let cubeX = originX, cubeY = originY;
                            if (angle > -Math.PI / 4 && angle <= Math.PI / 4) { cubeX = originX; cubeY = originY - radiusPx / 2; }
                            else if (angle > Math.PI / 4 && angle <= 3 * Math.PI / 4) { cubeX = originX - radiusPx / 2; cubeY = originY; }
                            else if (angle > -3 * Math.PI / 4 && angle <= -Math.PI / 4) { cubeX = originX - radiusPx / 2; cubeY = originY - radiusPx; }
                            else { cubeX = originX - radiusPx; cubeY = originY - radiusPx / 2; }
                            ctx.rect(cubeX, cubeY, radiusPx, radiusPx);
                        } else {
                            ctx.rect(targetX - radiusPx / 2, targetY - radiusPx / 2, radiusPx, radiusPx);
                        }
                        ctx.fill(); ctx.stroke();
                    }
                    ctx.shadowBlur = 0;
                }
            }

            // --- ACTION HOVER RANGE ---
            if (hoveredAction && !targetingOverlay && activeCombatantPos) {
                const rangeStr = (hoveredAction.range || "").toLowerCase();
                const reachFt = hoveredAction.reach || 0;
                const info = parseActionRange(hoveredAction);
                let normalRangeFt = info.rangeFt;
                let longRangeFt = 0;

                if (rangeStr.includes('/')) {
                    const parts = rangeStr.match(/(\d+)\s*\/\s*(\d+)/);
                    if (parts) { normalRangeFt = parseInt(parts[1], 10); longRangeFt = parseInt(parts[2], 10); }
                }

                if (!activeCombatantPos) return;

                const originX = (activeCombatantPos.col || 0) * cellSize + cellSize / 2;
                const originY = (activeCombatantPos.row || 0) * cellSize + cellSize / 2;

                const drawRangeCircle = (ft: number, color: string, isDashed: boolean, opacity: number, label?: string) => {
                    const rangePx = (ft / 5) * cellSize;
                    ctx.beginPath();
                    if (isDashed) ctx.setLineDash([8, 4]); else ctx.setLineDash([]);
                    ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.globalAlpha = opacity;
                    ctx.arc(originX, originY, rangePx, 0, Math.PI * 2);
                    ctx.stroke();
                    if (ft === normalRangeFt || ft === reachFt) {
                        ctx.shadowBlur = 10; ctx.shadowColor = color; ctx.stroke(); ctx.shadowBlur = 0;
                    }
                    if (label && ft > 0) {
                        ctx.globalAlpha = 0.7; ctx.fillStyle = color; ctx.font = 'bold 10px Inter, sans-serif';
                        ctx.fillText(`${label} (${ft}ft)`, originX + 5, originY - rangePx - 5);
                    }
                };

                if (longRangeFt > 0) drawRangeCircle(longRangeFt, 'rgba(255, 69, 0, 0.6)', true, 0.6, 'Long');
                if (normalRangeFt > 0) drawRangeCircle(normalRangeFt, reachFt > 0 ? 'rgba(255, 215, 0, 0.6)' : 'rgba(255, 215, 0, 0.9)', true, 0.9, reachFt > 0 ? 'Thrown' : 'Range');
                if (reachFt > 0) drawRangeCircle(reachFt, 'rgba(0, 191, 255, 0.9)', false, 0.9, 'Reach');
                ctx.globalAlpha = 1.0; ctx.setLineDash([]);
            }

            // --- MANUAL MEASUREMENT (Shift+Drag) ---
            if (measurementStart && measurementCurrent) {
                const sPos = measurementStart, cPos = measurementCurrent;
                const startX = sPos.col * cellSize + cellSize / 2, startY = sPos.row * cellSize + cellSize / 2;
                const endX = cPos.col * cellSize + cellSize / 2, endY = cPos.row * cellSize + cellSize / 2;
                const distFt = Math.max(Math.abs(cPos.col - sPos.col), Math.abs(cPos.row - sPos.row)) * 5;

                ctx.save(); ctx.beginPath(); ctx.setLineDash([10, 5]);
                ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
                ctx.shadowBlur = 10; ctx.shadowColor = 'rgba(251, 191, 36, 0.5)';
                ctx.moveTo(startX, startY); ctx.lineTo(endX, endY); ctx.stroke();

                // Draw end circle
                ctx.beginPath(); ctx.setLineDash([]); ctx.arc(endX, endY, 4, 0, Math.PI * 2); ctx.fillStyle = '#fbbf24'; ctx.fill();

                // Distance text
                ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 14px Inter, sans-serif'; ctx.textAlign = 'center';
                ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(`${distFt} ft`, endX, endY - 20);
                ctx.fillText(`${distFt} ft`, endX, endY - 20); ctx.restore();
            }

            // --- MOVEMENT PATH ---
            if (hoveredGridPos && activeCombatantPos && !targetingOverlay && !measurementStart) {
                const hPos = hoveredGridPos, aPos = activeCombatantPos;
                if (hPos.col !== aPos.col || hPos.row !== aPos.row) {
                    const startX = aPos.col * cellSize + cellSize / 2, startY = aPos.row * cellSize + cellSize / 2;
                    const endX = hPos.col * cellSize + cellSize / 2, endY = hPos.row * cellSize + cellSize / 2;
                    const distFt = Math.max(Math.abs(hPos.col - aPos.col), Math.abs(hPos.row - aPos.row)) * 5;
                    const hasZeroSpeed = activeCombatantConditions.some(c => ['Grappled', 'Restrained', 'Paralyzed', 'Petrified', 'Stunned', 'Unconscious'].includes(c));
                    const isValid = distFt <= movementRemaining && !hasZeroSpeed;

                    ctx.save(); ctx.beginPath(); ctx.setLineDash([8, 4]); ctx.lineDashOffset = -dashOffsetRef.current;
                    ctx.strokeStyle = isValid ? 'rgba(255, 255, 255, 0.6)' : 'rgba(239, 68, 68, 0.8)';
                    ctx.lineWidth = 2; ctx.moveTo(startX, startY); ctx.lineTo(endX, endY); ctx.stroke();
                    ctx.fillStyle = isValid ? 'white' : '#ef4444'; ctx.font = 'bold 12px Inter, sans-serif'; ctx.textAlign = 'center';
                    ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.strokeText(`${distFt} ft`, endX, endY - 15);
                    ctx.fillText(`${distFt} ft`, endX, endY - 15); ctx.restore();
                }
            }
        } catch (err) {
            console.error('[BattleMapCanvas] Critical error during render cycle:', err);
        }
    }, [mapState, width, height, previewShape, previewFreehandPath, reachableCells, targetingOverlay, hoveredAction, activeCombatantPos, hoveredGridPos, measurementStart, measurementCurrent]);

    useEffect(() => {
        const animate = () => {
            dashOffsetRef.current = (dashOffsetRef.current + 0.3) % 20;
            animationFrameRef.current = requestAnimationFrame(animate);
        };
        animationFrameRef.current = requestAnimationFrame(animate);
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, []);

    if (width <= 0 || height <= 0) return null;

    return (
        <canvas
            ref={canvasRef}
            width={width}
            height={height}
            className={`shadow-2xl rounded-lg border border-gray-700 ${className}`}
            style={{ imageRendering: 'pixelated' }}
        />
    );
};

import { useState, useEffect } from 'react';
import { useCombatStore } from '../../store/combatStore';
import { InitiativeTracker } from './InitiativeTracker';
import { MultiTargetModal } from './MultiTargetModal';
import { CombatLog } from './CombatLog';
import { DiceRoller } from './DiceRoller';
import { PortraitRibbon } from './PortraitRibbon';
import { AddCombatantModal } from './AddCombatantModal';
import { ActionWizard } from './ActionWizard';
import { BattleMap } from './BattleMap';
import { ConditionTooltip } from './ConditionTooltip';
import { useCombatTargeting } from '../../hooks/useCombatTargeting';
import { useMapInteraction } from '../../hooks/useMapInteraction';
import { Combatant, CombatAction } from '../../types/combat';
import { parseSpeed } from '../../engine/combatEngine';
import { useCharacterStore } from '../../store/characterStore';
import {
    Map as MapIcon, Swords, X, Play, SkipForward, Undo2, UserPlus, Zap, ShieldAlert
} from 'lucide-react';
import { CombatSidebar } from './CombatSidebar';
import { TurnEconomyHUD } from './TurnEconomyHUD';
import { DraggablePanel } from '../common/DraggablePanel';
import { QuickHPOverlay } from './QuickHPOverlay';
import { MonsterStatBlock } from './MonsterStatBlock';
import { CombatSummary } from './CombatSummary';
import { ConfirmationModal } from '../common/ConfirmationModal';
import conditions from '../../data/dnd5e/conditions.json';
import { useNavigate } from 'react-router-dom';


export function CombatBoard() {
    const activeEncounter = useCombatStore((state) => state.activeEncounter);
    const beginCombat = useCombatStore((state) => state.beginCombat);
    const nextTurn = useCombatStore((state) => state.nextTurn);
    const undo = useCombatStore((state) => state.undo);
    const pastStates = useCombatStore((state) => state.pastStates);
    const damageCombatant = useCombatStore((state) => state.damageCombatant);
    const healCombatant = useCombatStore((state) => state.healCombatant);
    const rollAllInitiative = useCombatStore((state) => state.rollAllInitiative);
    const setConcentration = useCombatStore((state) => state.setConcentration);
    const manualRollsEnabled = useCombatStore((state) => state.manualRollsEnabled);
    const toggleManualRolls = useCombatStore((state) => state.toggleManualRolls);
    const refreshPlayerStats = useCombatStore((state) => state.refreshPlayerStats);
    const selectedCombatantId = useCombatStore((state) => state.selectedCombatantId);
    const setSelectedCombatant = useCombatStore((state) => state.setSelectedCombatant);
    const updateToken = useCombatStore((state) => state.updateToken);
    const updateBattleMap = useCombatStore((state) => state.updateBattleMap);
    const setWizardAction = useCombatStore((state) => state.setWizardAction);
    const wizardAction = useCombatStore((state) => state.wizardAction);
    const addLog = useCombatStore((state) => state.addLog);
    const updateCombatant = useCombatStore((state) => state.updateCombatant);
    const resizeGrid = useCombatStore((state) => state.resizeGrid);
    const endEncounter = useCombatStore((state) => state.endEncounter);
    const navigate = useNavigate();

    const combatants = activeEncounter?.combatants ?? [];
    const isActive = activeEncounter?.isActive ?? false;
    const activeCombatantId = activeEncounter?.activeCombatantId ?? null;
    const activeCombatant = combatants.find((c: Combatant) => c.id === activeCombatantId) || null;

    const {
        targetingMode,
        handleActionSelect,
        handleTargetSelect,
        clearTargeting
    } = useCombatTargeting({
        activeEncounter,
        activeCombatant,
        setWizardAction
    });

    const {
        drawingMode,
        setDrawingMode,
        movementOverlay,
        showMovementRange,
        clearMovementRange,
        contextMenu,
        openContextMenu,
        closeContextMenu
    } = useMapInteraction();

    const [showDiceRoller, setShowDiceRoller] = useState(false);
    const [showEndConfirm, setShowEndConfirm] = useState(false);
    const [showEndTurnConfirm, setShowEndTurnConfirm] = useState(false);
    const [showEndSummary, setShowEndSummary] = useState(false);
    const [showMultiTarget, setShowMultiTarget] = useState(false);
    const [showAddCombatant, setShowAddCombatant] = useState(false);
    const [hoveredAction, setHoveredAction] = useState<CombatAction | null>(null);
    const [isLogExpanded, setIsLogExpanded] = useState(false);
    const [isReadyActionFormOpen, setIsReadyActionFormOpen] = useState(false);
    const [hoveredCondition, setHoveredCondition] = useState<{ name: string, x: number, y: number } | null>(null);
    const [statBlockTarget, setStatBlockTarget] = useState<Combatant | null>(null);

    // Auto-refresh player stats from characterStore when combat board loads
    useEffect(() => {
        refreshPlayerStats();
    }, [refreshPlayerStats]);

    // ═══ KEYBOARD SHORTCUTS ═══
    useEffect(() => {
        const handler = (e: KeyboardEvent) => {
            // Block shortcuts when typing in inputs
            const tag = (e.target as HTMLElement)?.tagName;
            if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

            // Block shortcuts when any modal is open
            const modalOpen = showEndConfirm || showEndSummary || showMultiTarget
                || showAddCombatant || isReadyActionFormOpen || !!statBlockTarget || !!wizardAction;

            const key = e.key.toLowerCase();

            // Escape always works — closes targeting first, then modals
            if (key === 'escape') {
                e.preventDefault();
                if (targetingMode) { clearTargeting(); return; }
                if (showDiceRoller) { setShowDiceRoller(false); return; }
                return;
            }

            // All other shortcuts blocked during modals or pre-combat
            if (modalOpen || !isActive) return;

            switch (key) {
                case 'n': // Next Turn
                    e.preventDefault();
                    nextTurn();
                    break;
                case 'u': // Undo
                    if (!e.ctrlKey && !e.metaKey) {
                        e.preventDefault();
                        if (pastStates.length > 0) undo();
                    }
                    break;
                case 'd': // Dice Roller toggle
                    e.preventDefault();
                    setShowDiceRoller(prev => !prev);
                    break;
                case 'h': // Quick HP focus
                    // Prevent default to avoid typing 'h' in the input 
                    e.preventDefault();
                    document.getElementById('floating-hp-amt')?.focus();
                    break;
                case 'l': // Combat Log toggle
                    e.preventDefault();
                    setIsLogExpanded(prev => !prev);
                    break;
            }
        };

        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [
        isActive, targetingMode, clearTargeting, showDiceRoller, showEndConfirm,
        showEndSummary, showMultiTarget, showAddCombatant, isReadyActionFormOpen,
        statBlockTarget, wizardAction, pastStates, undo, nextTurn
    ]);

    const selectedCombatant = combatants.find((c: Combatant) => c.id === selectedCombatantId) || activeCombatant || null;

    // --- Target Selection Sync ---
    useEffect(() => {
        if (targetingMode) {
            setDrawingMode('select');
        }
    }, [targetingMode, setDrawingMode]);

    if (!activeEncounter || combatants.length === 0) return null;

    const handleReadyActionConfirm = () => {
        const descEl = document.getElementById('ready-desc-board') as HTMLInputElement;
        const triggerEl = document.getElementById('ready-trigger-board') as HTMLInputElement;
        if (!descEl || !triggerEl || !descEl.value || !triggerEl.value || !activeCombatant) return;

        if (activeEncounter?.turnState.hasAction) useCombatStore.getState().consumeAction();
        useCombatStore.getState().setReadiedAction(activeCombatant.id, { description: descEl.value, trigger: triggerEl.value });
        setIsReadyActionFormOpen(false);
    };

    const handleEndTurnShortcut = () => {
        if (!isActive || !activeCombatant) return;

        // Safety: If it's a player's turn, or they haven't used actions, confirm before ending
        // hasAction: true means AVAILABLE. So !hasAction means USED.
        const hasUsedMainAction = !activeEncounter.turnState.hasAction;
        const hasUsedBonusAction = !activeEncounter.turnState.hasBonusAction;
        const needsConfirmation = activeCombatant.type === 'player' || (!hasUsedMainAction && !hasUsedBonusAction);

        if (needsConfirmation) {
            setShowEndTurnConfirm(true);
        } else {
            nextTurn();
        }
    };

    return (
        <div className="relative h-full w-full overflow-hidden bg-combat">

            {/* ═══ LAYER 0: MAP FOUNDATION ═══ */}
            <div className="absolute inset-0">
                {activeEncounter.battleMap ? (
                    <BattleMap
                        mapState={activeEncounter.battleMap}
                        tokens={activeEncounter.battleMap.tokens}
                        combatants={activeEncounter.combatants}
                        activeCombatantId={activeCombatantId}
                        selectedTokenId={activeEncounter.battleMap.tokens.find(t => t.combatantId === selectedCombatantId)?.id}
                        drawingMode={drawingMode}
                        onDrawingModeChange={setDrawingMode}
                        onEndTurn={handleEndTurnShortcut}
                        onResizeGrid={resizeGrid}
                        onTokenClick={(id) => {
                            const token = activeEncounter.battleMap?.tokens.find(t => t.id === id);
                            if (token) {
                                setSelectedCombatant(token.combatantId);
                                const combatant = activeEncounter.combatants.find(c => c.id === token.combatantId);
                                if (combatant && activeCombatantId === combatant.id) {
                                    showMovementRange(token.position, parseSpeed(combatant.speed), activeEncounter.battleMap!.tokens, token.id);
                                }
                            }
                        }}
                        onTokenMove={(id, pos) => {
                            updateToken(id, { position: pos });
                            clearMovementRange();
                        }}
                        onTokenUpdate={(id, updates) => updateToken(id, updates)}
                        onShapeAdd={(shape) => updateBattleMap({
                            shapes: [...(activeEncounter.battleMap?.shapes || []), shape]
                        })}
                        onFreehandPathAdd={(path) => updateBattleMap({
                            freehandPaths: [...(activeEncounter.battleMap?.freehandPaths || []), path]
                        })}
                        onFogOfWarAdd={(shape) => updateBattleMap({
                            fogOfWar: [...(activeEncounter.battleMap?.fogOfWar || []), shape]
                        })}
                        onFogOfWarFreehandAdd={(path) => updateBattleMap({
                            fogOfWarFreehand: [...(activeEncounter.battleMap?.fogOfWarFreehand || []), path]
                        })}
                        movementRemaining={activeEncounter.turnState.movementRemaining}
                        activeCombatantConditions={activeCombatant?.conditions.map(c => c.name)}
                        movementMax={parseSpeed(activeCombatant?.speed)}
                        movementOverlay={movementOverlay}
                        targeting={targetingMode}
                        onTargetSelect={(targetIds) => {
                            if (targetIds) handleTargetSelect(targetIds);
                        }}
                        onTokenRemove={(id) => {
                            updateToken(id, { position: { col: -1, row: -1 } });
                        }}
                        onMarkDead={(combatantId) => {
                            const combatant = activeEncounter?.combatants.find(c => c.id === combatantId);
                            if (combatant) {
                                updateCombatant(combatantId, {
                                    currentHp: 0,
                                    isDead: true,
                                    conditions: [
                                        ...(combatant.conditions || []),
                                        {
                                            id: crypto.randomUUID(),
                                            name: 'Dead',
                                            description: 'Zero hit points.',
                                            icon: 'Skull'
                                        }
                                    ]
                                });
                            }
                        }}
                        onRevive={(combatantId) => {
                            const combatant = activeEncounter?.combatants.find(c => c.id === combatantId);
                            if (combatant && (combatant.isDead || combatant.currentHp === 0)) {
                                updateCombatant(combatantId, {
                                    currentHp: 1,
                                    isDead: false,
                                    conditions: (combatant.conditions || []).filter(c => c.name !== 'Dead')
                                });
                            }
                        }}
                        onViewStatBlock={(combatantId) => {
                            const combatant = activeEncounter?.combatants.find(c => c.id === combatantId);
                            if (combatant) {
                                setStatBlockTarget(combatant);
                            }
                        }}
                        onApplyCondition={(combatantId, conditionName) => {
                            const combatant = activeEncounter?.combatants.find(c => c.id === combatantId);
                            if (combatant) {
                                const condId = conditionName.toLowerCase();
                                const hasCondition = combatant.conditions?.some(c => c.id === condId);
                                let updatedConditions = combatant.conditions || [];

                                if (hasCondition) {
                                    updatedConditions = updatedConditions.filter(c => c.id !== condId);
                                } else {
                                    // Pull rich data if available
                                    const richData = conditions.find(c => c.name.toLowerCase() === conditionName.toLowerCase());

                                    updatedConditions = [
                                        ...updatedConditions,
                                        {
                                            id: condId,
                                            name: richData?.name || (conditionName.charAt(0).toUpperCase() + conditionName.slice(1)),
                                            icon: richData?.icon,
                                            description: richData?.description || `Applied via Map UI`
                                        }
                                    ];
                                }
                                updateCombatant(combatantId, { conditions: updatedConditions });
                            }
                        }}
                        onActionClick={(combatantId, action) => {
                            const actor = activeEncounter.combatants.find(c => c.id === combatantId);
                            if (actor) handleActionSelect(action, actor);
                        }}
                        onConditionHover={(name, e) => setHoveredCondition({ name, x: e.clientX, y: e.clientY })}
                        onConditionLeave={() => setHoveredCondition(null)}
                        hoveredAction={hoveredAction}
                        contextMenu={contextMenu}
                        onContextMenuOpen={openContextMenu}
                        onContextMenuClose={closeContextMenu}
                        className="w-full h-full"
                    />
                ) : (
                    <div className="w-full h-full flex flex-col items-center justify-center text-center bg-stone-900/50">
                        <MapIcon size={64} className="text-stone-700 mb-4 opacity-30" />
                        <h3 className="text-2xl font-cinzel font-bold text-stone-500">Theater of the Mind</h3>
                        <p className="text-stone-600 max-w-sm mt-2 font-cinzel italic">"The mind's eye sees what the grid cannot hold."</p>
                    </div>
                )}
            </div>

            {/* ═══ LAYER 10: HEADER BAR ═══ */}
            <div className="absolute top-0 left-0 right-0 pointer-events-none" style={{ zIndex: 10 }}>
                <div className="pointer-events-auto bg-gradient-to-b from-stone-950/95 via-stone-950/80 to-transparent px-4 pt-3 pb-8">
                    <div className="flex items-center justify-between">
                        <div>
                            <h2 className="text-lg font-cinzel font-bold text-gold leading-tight">{activeEncounter.title}</h2>
                            {!isActive ? (
                                <p className="text-xs text-stone-400">Roll initiative to begin.</p>
                            ) : (
                                <p className="text-xs text-stone-400">Round {activeEncounter.round} — {activeCombatant?.name}'s Turn</p>
                            )}
                        </div>

                        <div className="flex gap-2">
                            {!isActive ? (
                                <div className="flex gap-1.5">
                                    <button
                                        onClick={rollAllInitiative}
                                        className="bg-stone-800/90 hover:bg-stone-700 text-stone-300 font-bold px-3 py-1.5 rounded text-xs transition-colors"
                                    >
                                        Roll Initiatives
                                    </button>
                                    <button
                                        onClick={beginCombat}
                                        disabled={combatants.some(c => c.initiativeScore === null)}
                                        className="bg-green-600/90 hover:bg-green-500 disabled:bg-stone-800 disabled:text-stone-500 text-white font-bold px-4 py-1.5 rounded text-xs transition-colors flex items-center gap-1.5"
                                    >
                                        <Play size={13} fill="currentColor" /> Start
                                    </button>
                                </div>
                            ) : (
                                <>
                                    {/* Combat Tools Group */}
                                    <div className="flex items-center bg-stone-900/40 border border-stone-800 rounded px-1 gap-1">
                                        <button
                                            onClick={toggleManualRolls}
                                            className={`p-1.5 rounded transition-colors ${manualRollsEnabled ? 'text-gold bg-gold/5' : 'text-stone-500 hover:text-stone-300 hover:bg-stone-800'}`}
                                            title={manualRollsEnabled ? 'Manual Rolls On' : 'Auto-Roll (Click to toggle)'}
                                        >
                                            <span className="text-[10px]">✍️</span>
                                        </button>
                                        <div className="w-px h-3 bg-stone-800" />
                                        <button
                                            onClick={() => setShowDiceRoller(!showDiceRoller)}
                                            className={`p-1.5 rounded transition-colors ${showDiceRoller ? 'text-gold bg-gold/5' : 'text-stone-500 hover:text-stone-300 hover:bg-stone-800'} relative group`}
                                            title="Dice Roller (D)"
                                        >
                                            <span className="text-[10px]">🎲</span>
                                            <span className="absolute -bottom-1 -right-1 text-[8px] font-mono text-stone-500 font-bold bg-stone-900 px-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity">D</span>
                                        </button>
                                    </div>

                                    {/* Management Group */}
                                    <div className="flex items-center gap-1 mx-2 pl-2 border-l border-stone-800">
                                        <button
                                            onClick={() => setShowAddCombatant(true)}
                                            className="h-9 px-4 rounded-lg bg-stone-900 border border-stone-800 text-stone-400 hover:text-gold hover:border-gold/50 transition-all flex items-center gap-2 group shadow-lg"
                                            title="Add a new character or monster to the encounter"
                                        >
                                            <UserPlus size={16} className="group-hover:scale-110 transition-transform" />
                                            <span className="text-xs font-bold uppercase tracking-widest hidden lg:block">Add</span>
                                        </button>

                                        <button
                                            onClick={() => setIsReadyActionFormOpen(true)}
                                            disabled={!activeEncounter.turnState.hasAction}
                                            className="h-9 px-4 rounded-lg bg-stone-900 border border-stone-800 text-stone-400 hover:text-arcane hover:border-arcane/50 transition-all flex items-center gap-2 group shadow-lg disabled:opacity-30 disabled:cursor-not-allowed"
                                            title="Ready an Action (consumes Action for the current turn)"
                                        >
                                            <Zap size={16} className="group-hover:scale-110 transition-transform" />
                                            <span className="text-xs font-bold uppercase tracking-widest hidden lg:block">Ready</span>
                                        </button>

                                        <button
                                            onClick={() => setShowEndConfirm(true)}
                                            className="h-9 px-4 rounded-lg bg-stone-900 border border-stone-800 text-stone-400 hover:text-blood hover:border-blood/50 transition-all flex items-center gap-2 group shadow-lg"
                                            title="Finish the battle and save results"
                                        >
                                            <X size={16} className="group-hover:scale-110 transition-transform" />
                                            <span className="text-xs font-bold uppercase tracking-widest hidden lg:block">End Combat</span>
                                        </button>
                                    </div>

                                    {/* Primary Actions */}
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={undo}
                                            disabled={pastStates.length === 0}
                                            className="bg-stone-800 hover:bg-stone-700 disabled:opacity-30 disabled:cursor-not-allowed text-stone-300 font-bold px-3 py-1.5 rounded text-xs transition-colors flex items-center gap-1.5 shadow-lg shadow-black/20"
                                            title="Undo Last Action (U)"
                                        >
                                            <Undo2 size={13} /> Undo
                                        </button>

                                        <button
                                            onClick={handleEndTurnShortcut}
                                            className="bg-gold hover:bg-gold-light text-stone-950 font-bold px-4 py-1.5 rounded text-xs flex items-center gap-1.5 shadow-lg shadow-gold/10 transition-all hover:scale-105 relative group"
                                            title="Next Turn (N)"
                                        >
                                            Next <SkipForward size={13} fill="currentColor" />
                                            <span className="absolute -top-1 -right-1 text-[8px] font-mono bg-stone-950 text-gold px-1 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity translate-x-1/2 -translate-y-1/2 border border-gold/30">N</span>
                                        </button>
                                    </div>
                                </>
                            )}
                        </div>
                    </div>

                    {/* Initiative Ribbon */}
                    <div className="mt-2">
                        {isActive ? (
                            <PortraitRibbon
                                onConditionHover={(name, e) => setHoveredCondition({ name, x: e.clientX, y: e.clientY })}
                                onConditionLeave={() => setHoveredCondition(null)}
                            />
                        ) : (
                            <InitiativeTracker
                                onConditionHover={(name, e) => setHoveredCondition({ name, x: e.clientX, y: e.clientY })}
                                onConditionLeave={() => setHoveredCondition(null)}
                            />
                        )}
                    </div>
                </div>
            </div>

            {/* ═══ LAYER 20: FLOATING HUDs (Alt+Draggable) ═══ */}

            {/* Turn Economy HUD (Bottom-Left) */}
            {isActive && (
                <DraggablePanel className="absolute bottom-14 left-4 glass-panel" zIndex={40} label="Economy">
                    <TurnEconomyHUD
                        hasAction={activeEncounter.turnState.hasAction}
                        hasBonusAction={activeEncounter.turnState.hasBonusAction}
                        hasReaction={activeEncounter.turnState.hasReaction}
                        extraActions={activeEncounter.turnState.extraActions}
                        hasHasteAction={activeEncounter.turnState.hasHasteAction}
                        movementRemaining={activeEncounter.turnState.movementRemaining}
                        movementTotal={parseSpeed(activeCombatant?.speed)}
                    />
                </DraggablePanel>
            )}

            {/* Quick HP Overlay (Bottom-Right) */}
            {selectedCombatant && (
                <DraggablePanel className="absolute bottom-14 right-[360px] glass-panel" zIndex={40} label="HP">
                    <QuickHPOverlay
                        target={selectedCombatant}
                        activeCombatantId={activeCombatantId || ''}
                        damageCombatant={damageCombatant}
                        healCombatant={healCombatant}
                        setShowMultiTarget={setShowMultiTarget}
                        clearTarget={() => setSelectedCombatant(null)}
                    />
                </DraggablePanel>
            )}

            {/* ═══ LAYER 30: DOCKED PANELS ═══ */}

            {/* Collapsible Sidebar (Right) */}
            {activeCombatant && isActive && !activeCombatant.isLair && (
                <CombatSidebar
                    combatant={activeCombatant}
                    selectedCombatant={selectedCombatant}
                    onActionClick={handleActionSelect}
                    onActionHover={setHoveredAction}
                    setSelectedCombatant={setSelectedCombatant}
                    setConcentration={setConcentration}
                    onConditionHover={(name, e) => setHoveredCondition({ name, x: e.clientX, y: e.clientY })}
                    onConditionLeave={() => setHoveredCondition(null)}
                />
            )}

            {/* Combat Log (Drawer) */}
            <CombatLog
                variant="drawer"
                isExpanded={isLogExpanded}
                onToggle={setIsLogExpanded}
            />

            {/* ═══ LAYER 40: OVERLAYS ═══ */}

            {/* Targeting Indicator */}
            {targetingMode && (
                <div className="absolute top-28 left-1/2 -translate-x-1/2 pointer-events-auto" style={{ zIndex: 40 }}>
                    <div className="bg-gold text-stone-950 px-5 py-1.5 rounded-full font-bold shadow-2xl flex items-center gap-2 text-sm animate-bounce border-2 border-stone-950">
                        <Swords size={15} />
                        Targeting: {targetingMode.action.name}
                        <button
                            onClick={clearTargeting}
                            className="ml-2 bg-stone-950/20 hover:bg-stone-950/40 rounded-full p-0.5 transition-colors"
                        >
                            <X size={14} />
                        </button>
                    </div>
                </div>
            )}

            {/* Floating Dice Roller */}
            {showDiceRoller && (
                <DraggablePanel className="absolute top-24 right-[360px] w-72 glass-panel" zIndex={40} label="Dice">
                    <DiceRoller />
                </DraggablePanel>
            )}

            {/* Lair Action Overlay */}
            {activeCombatant && isActive && activeCombatant.isLair && (
                <div className="absolute inset-0 bg-stone-950/60 backdrop-blur-sm flex items-center justify-center p-12 text-center pointer-events-auto" style={{ zIndex: 45 }}>
                    <div className="bg-stone-900 border-2 border-gold/30 rounded-2xl shadow-[0_0_50px_rgba(255,215,0,0.1)] p-12 max-w-xl">
                        <div className="w-24 h-24 bg-stone-950 border border-gold/50 rounded-full flex items-center justify-center mx-auto mb-8 shadow-[inset_0_0_15px_rgba(255,215,0,0.2)]">
                            <Swords size={48} className="text-gold" />
                        </div>
                        <h2 className="text-5xl font-cinzel font-bold text-gold mb-4 tracking-tighter uppercase">Lair Action</h2>
                        <p className="text-lg text-stone-300 font-cinzel mb-10 leading-relaxed italic opacity-80">The very environment rebels against our heroes...</p>
                        <button
                            onClick={nextTurn}
                            className="bg-gold hover:bg-yellow-400 text-stone-950 font-bold px-10 py-4 rounded-xl text-xl transition-all hover:scale-105 shadow-[0_0_20px_rgba(255,215,0,0.3)] flex items-center justify-center gap-3 mx-auto"
                        >
                            Resolve Lair Action <SkipForward size={24} />
                        </button>
                    </div>
                </div>
            )}

            {/* Ready Action Setup Modal */}
            {isReadyActionFormOpen && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
                    <div className="bg-stone-950 border border-stone-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
                        <div className="bg-arcane/20 p-6 border-b border-arcane/30 flex items-center gap-4 relative">
                            <div className="w-12 h-12 rounded-xl bg-arcane/20 flex items-center justify-center text-arcane shadow-[0_0_20px_rgba(168,85,247,0.3)]">
                                <Zap size={24} />
                            </div>
                            <div>
                                <h3 className="text-arcane font-black text-lg tracking-widest uppercase">Ready Action</h3>
                                <p className="text-stone-400 text-xs font-medium">Prepare an action for a specific trigger.</p>
                            </div>
                            <button
                                onClick={() => setIsReadyActionFormOpen(false)}
                                className="absolute right-6 top-6 text-stone-500 hover:text-parchment transition-colors"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        <div className="p-8 space-y-6">
                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] text-stone-500 uppercase tracking-[0.2em] font-black flex items-center gap-2">
                                        <Swords size={12} className="text-arcane" />
                                        Action Description
                                    </label>
                                    <input
                                        id="ready-desc-board"
                                        autoFocus
                                        type="text"
                                        placeholder="e.g. Shoot my bow at the first enemy..."
                                        className="w-full bg-stone-900 border border-stone-800 rounded-xl px-4 py-3 text-sm text-parchment focus:border-arcane focus:ring-1 focus:ring-arcane outline-none transition-all placeholder:text-stone-600"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] text-stone-500 uppercase tracking-[0.2em] font-black flex items-center gap-2">
                                        <Play size={12} className="text-arcane" />
                                        Trigger Condition
                                    </label>
                                    <input
                                        id="ready-trigger-board"
                                        type="text"
                                        placeholder="e.g. Enemy walks through the door"
                                        className="w-full bg-stone-900 border border-stone-800 rounded-xl px-4 py-3 text-sm text-parchment focus:border-arcane focus:ring-1 focus:ring-arcane outline-none transition-all placeholder:text-stone-600"
                                    />
                                </div>
                            </div>

                            <div className="bg-stone-900/50 border border-stone-800 rounded-xl p-4 flex items-start gap-3">
                                <ShieldAlert size={18} className="text-gold flex-shrink-0 mt-0.5" />
                                <p className="text-[11px] text-stone-500 leading-relaxed italic">
                                    Readied actions <span className="text-arcane font-bold">consume your Action</span> for the current turn. You must use your <span className="text-gold font-bold">Reaction</span> to trigger it when the condition is met.
                                </p>
                            </div>
                        </div>

                        <div className="p-6 bg-stone-900/30 border-t border-stone-800 flex justify-end gap-3">
                            <button
                                onClick={() => setIsReadyActionFormOpen(false)}
                                className="px-6 py-2.5 bg-stone-900 text-stone-400 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-stone-800 border border-stone-800 transition-all hover:text-parchment"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleReadyActionConfirm}
                                className="px-6 py-2.5 bg-arcane/20 text-arcane rounded-xl text-xs font-black uppercase tracking-widest border border-arcane/50 hover:bg-arcane/40 transition-all shadow-[0_0_15px_rgba(168,85,247,0.2)]"
                            >
                                Confirm & Ready
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* End Encounter confirmation */}
            {showEndConfirm && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-stone-950/80 backdrop-blur-sm p-4">
                    <div className="bg-stone-900 border border-stone-700 rounded-lg shadow-2xl max-w-md w-full p-6">
                        <h3 className="text-xl font-cinzel font-bold text-blood mb-2">End Encounter?</h3>
                        <p className="text-stone-400 mb-6">Are you sure you want to end this combat? It will be archived to history and cannot be resumed.</p>
                        <div className="flex justify-end gap-3 flex-wrap">
                            <button
                                onClick={() => setShowEndConfirm(false)}
                                className="px-4 py-2 bg-stone-800 hover:bg-stone-700 text-stone-300 rounded transition-colors font-bold"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => {
                                    setShowEndConfirm(false);
                                    setShowEndSummary(true);
                                }}
                                className="px-4 py-2 bg-blood text-white rounded hover:bg-red-600 transition-colors font-bold"
                            >
                                End Combat
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Multi-Target Modal */}
            {showMultiTarget && (
                <MultiTargetModal onClose={() => setShowMultiTarget(false)} />
            )}
            {/* Add Combatant Modal */}
            {showAddCombatant && (
                <AddCombatantModal onClose={() => setShowAddCombatant(false)} />
            )}

            {/* Global Condition Tooltip */}
            {hoveredCondition && (
                <ConditionTooltip
                    conditionName={hoveredCondition.name}
                    x={hoveredCondition.x}
                    y={hoveredCondition.y}
                />
            )}

            {/* Centralized Action Wizard */}
            {wizardAction && (
                <ActionWizard
                    isOpen={true}
                    onClose={() => setWizardAction(null)}
                    action={wizardAction.action}
                    actor={wizardAction.actor}
                    allCombatants={combatants}
                    initialTargets={wizardAction.initialTargets}
                    onConfirm={(results) => {
                        const { action, actor } = wizardAction;

                        // 0. Handle Special Actions
                        if (action.actionType === 'saving-throw') {
                            const rollResult = results.rollResult;
                            const ability = action.saveAbility?.toUpperCase() || '';
                            const dc = action.saveDc || 0;
                            const isFail = dc > 0 ? (rollResult < dc) : false;

                            addLog({
                                message: `${actor.name} rolls ${ability} Save: ${rollResult}${dc > 0 ? ` vs DC ${dc} (${isFail ? 'FAIL' : 'SUCCESS'})` : ''}`,
                                type: 'roll',
                                combatantId: actor.id
                            });

                            setWizardAction(null);
                            return;
                        }

                        if (action.actionType === 'death-save' || action.id === 'death-save') {
                            const rollResult = results.rollResult || 10;
                            let newSuccesses = actor.deathSaves?.successes || 0;
                            let newFailures = actor.deathSaves?.failures || 0;
                            let wakesUp = false;

                            if (rollResult >= 20) {
                                wakesUp = true;
                            } else if (rollResult <= 1) {
                                newFailures += 2;
                            } else if (rollResult >= 10) {
                                newSuccesses += 1;
                            } else {
                                newFailures += 1;
                            }

                            const msg = `Death Save: ${rollResult}${rollResult >= 20 ? ' (Nat 20! 1 HP restored)' : rollResult <= 1 ? ' (Nat 1! 2 Failures)' : ''} — S:${newSuccesses} F:${newFailures}`;

                            addLog({
                                message: `${actor.name} rolls ${msg}`,
                                type: 'roll',
                                combatantId: actor.id
                            });

                            if (wakesUp) {
                                healCombatant(actor.id, 1);
                            } else {
                                updateCombatant(actor.id, { deathSaves: { successes: newSuccesses, failures: newFailures } });
                                if (newFailures >= 3) {
                                    updateCombatant(actor.id, {
                                        isDead: true,
                                        deathSaves: { successes: newSuccesses, failures: newFailures },
                                        conditions: [
                                            ...(actor.conditions || []),
                                            { id: crypto.randomUUID(), name: 'Dead', description: '3 failed death saves.', icon: 'Skull' }
                                        ]
                                    });
                                    addLog({ message: `💀 ${actor.name} has died! (3 failed death saves)`, type: 'system', combatantId: actor.id });
                                } else if (newSuccesses >= 3) {
                                    updateCombatant(actor.id, {
                                        deathSaves: { successes: newSuccesses, failures: newFailures },
                                        conditions: [
                                            ...(actor.conditions || []),
                                            { id: crypto.randomUUID(), name: 'Stable', description: 'Stabilized at 0 HP. Unconscious but not dying.', icon: 'Heart' }
                                        ]
                                    });
                                    addLog({ message: `${actor.name} has stabilized. (3 successful death saves)`, type: 'system', combatantId: actor.id });
                                }
                            }
                            setWizardAction(null);
                            return;
                        }

                        // Apply Effects Logic
                        addLog({
                            message: `${actor.name} uses ${action.name}${results.rollResult !== null ? ` — Result: ${results.rollResult}${results.isCrit ? ' (CRIT!)' : results.isFumble ? ' (FUMBLE!)' : ''}` : ''}`,
                            type: results.rollResult !== null ? 'roll' : 'action',
                            combatantId: actor.id
                        });

                        // 1. Consume Action Economy
                        const castLevel = results.castLevel || action.spellLevel || 0;
                        const isLeveledSpell = castLevel > 0;
                        const isHasteAction = !!action.isHasteAction;

                        if (action.economy === 'action') {
                            useCombatStore.getState().consumeAction({ isLeveledSpell, isHasteAction });
                        } else if (action.economy === 'bonus') {
                            useCombatStore.getState().consumeBonusAction({ isLeveledSpell });
                        } else if (action.economy === 'reaction') {
                            useCombatStore.getState().consumeReaction();
                        }

                        // 2. Spell Slots
                        if (isLeveledSpell) {
                            useCombatStore.getState().useSpellSlot(actor.id, castLevel);
                        }

                        // 3. Concentration
                        if (results.applyConcentration || action.requiresConcentration) {
                            const shouldConcentrate = results.applyConcentration !== undefined ? results.applyConcentration : action.requiresConcentration;
                            if (shouldConcentrate) {
                                setConcentration(actor.id, { spellId: action.id, name: action.name });
                            }
                        }

                        // 4. Group Resolution (Damage/Conditions)
                        if (results.selectedTargets.length > 0) {
                            // Deduplicate targets if necessary
                            const uniqueTargets = results.selectedTargets.filter((t: any, index: number, self: any[]) =>
                                self.findIndex(x => x.id === t.id) === index
                            );

                            uniqueTargets.forEach((target: any) => {
                                // A. Multi-instance (Magic Missile, etc)
                                const isMultiInstance = action.name.toLowerCase().includes('magic missile') ||
                                    action.name.toLowerCase().includes('scorching ray');

                                if (isMultiInstance && results.multiTargetResults) {
                                    const instances = results.multiTargetResults.filter((r: any) => r.targetId === target.id);
                                    const totalInstanceDmg = instances.reduce((sum: number, r: any) => sum + (r.damage || 0), 0);

                                    if (totalInstanceDmg > 0 || instances.length > 0) {
                                        damageCombatant(target.id, totalInstanceDmg, action.damageType);
                                        addLog({
                                            message: `  → ${target.name} takes ${totalInstanceDmg} ${action.damageType || ''} damage from ${instances.length} items`,
                                            type: 'damage',
                                            combatantId: target.id
                                        });
                                    }
                                } else if (results.damageResult !== null) {
                                    // A. Standard Damage Application
                                    const baseDmg = results.damageResult;
                                    const count = results.selectedTargets.filter((st: any) => st.id === target.id).length;
                                    const saved = results.targetDetails?.[target.id]?.saved || false;

                                    let multiplier = 1.0;
                                    let modSuffix = "";

                                    if (saved) {
                                        multiplier *= 0.5;
                                        modSuffix += " (Saved)";
                                    }

                                    // Check resistances from target
                                    const tObj = combatants.find(c => c.id === target.id);
                                    if (tObj) {
                                        const type = (action.damageType || '').toLowerCase();
                                        if (tObj.immunities?.some(i => i.toLowerCase() === type)) {
                                            multiplier = 0;
                                            modSuffix += " (Immune)";
                                        } else if (tObj.resistances?.some(r => r.toLowerCase() === type)) {
                                            multiplier *= 0.5;
                                            modSuffix += " (Resistant)";
                                        } else if (tObj.vulnerabilities?.some(v => v.toLowerCase() === type)) {
                                            multiplier *= 2;
                                            modSuffix += " (Vulnerable)";
                                        }
                                    }

                                    const targetDmg = Math.floor(baseDmg * count * multiplier);

                                    if (targetDmg > 0 || multiplier === 0) {
                                        damageCombatant(target.id, targetDmg, action.damageType);
                                        addLog({
                                            message: `  → ${target.name}${count > 1 ? ` (x${count})` : ''} takes ${targetDmg} ${action.damageType || ''} damage${modSuffix}`,
                                            type: 'damage',
                                            combatantId: target.id
                                        });
                                    }
                                }

                                // B. Condition Application
                                const targetConditions = results.targetDetails?.[target.id]?.conditions || results.selectedConditions || [];
                                if (targetConditions.length > 0) {
                                    targetConditions.forEach((cond: any) => {
                                        const c = combatants.find(x => x.id === target.id);
                                        const existingConditions = c?.conditions || [];

                                        if (!existingConditions.some(ex => ex.id === cond.id)) {
                                            updateCombatant(target.id, {
                                                conditions: [...existingConditions, {
                                                    id: cond.id,
                                                    name: cond.name,
                                                    icon: cond.icon,
                                                    description: `Applied by ${actor.name} via ${action.name}`
                                                }]
                                            });
                                            addLog({
                                                message: `  → ${target.name} is now ${cond.name}`,
                                                type: 'system',
                                                combatantId: target.id
                                            });
                                        }
                                    });
                                }
                            });
                        }

                        // 5. Handle Item Consumption (Synchronize Inventory)
                        if (action.id.startsWith('item-') && actor.type === 'player' && actor.sourceId) {
                            useCharacterStore.getState().consumeItem(actor.sourceId, action.id.replace('item-', ''));
                        }

                        // 6. Handle Action Surge (Restore an action)
                        if (action.id === 'fighter-action-surge') {
                            useCombatStore.getState().restoreAction(actor.id);
                        }

                        setWizardAction(null);
                    }}
                />
            )}


            {/* Monster Stat Block Popup */}
            {statBlockTarget && (
                <MonsterStatBlock
                    combatant={statBlockTarget}
                    onClose={() => setStatBlockTarget(null)}
                />
            )}

            {/* Post-Combat Summary Modal */}
            {showEndSummary && (
                <CombatSummary
                    encounter={activeEncounter}
                    onClose={() => {
                        setShowEndSummary(false);
                        endEncounter();
                        if (activeEncounter.campaignId) {
                            navigate('/navigator');
                        } else {
                            navigate('/combat/setup');
                        }
                    }}
                />
            )}

            <ConfirmationModal
                isOpen={showEndTurnConfirm}
                title="End Turn Early?"
                message={`${activeCombatant?.name} still has actions remaining. Are you sure you want to end their turn?`}
                confirmText="End Turn"
                onConfirm={() => {
                    nextTurn();
                    setShowEndTurnConfirm(false);
                }}
                onCancel={() => setShowEndTurnConfirm(false)}
            />
        </div>
    );
}

import { useState } from 'react';
import { Play, Users, Ghost, Search, Plus, X, Trash2, Save } from 'lucide-react';
import { useCharacterStore } from '../../store/characterStore';
import { useCombatStore } from '../../store/combatStore';
import { useCampaignStore } from '../../store/campaignStore';
import { FiveEToolsModal } from '../common/FiveEToolsModal';
import { Combatant } from '../../types/combat';
import { parseMonsterSpellSlots } from '../../engine/fiveEToolsParser';
import { calculateEncounterDifficulty, CR_TO_XP, getDifficultyColor } from '../../engine/encounterDifficulty';
import { EncounterLibrary } from './EncounterLibrary';
import { generateRandomEncounter } from '../../engine/randomEncounterEngine';
import { getPrimaryMonsterTokenUrl } from '../../engine/portraitEngine';
import { Dice6, Loader2, Sparkles } from 'lucide-react';

export function CombatSetup() {
    const characters = useCharacterStore((state) => state.characters);
    const startEncounter = useCombatStore((state) => state.startEncounter);
    const activeEncounter = useCombatStore((state) => state.activeEncounter);
    const completeSetup = useCombatStore((state) => state.completeSetup);
    const addCombatant = useCombatStore((state) => state.addCombatant);
    const removeCombatant = useCombatStore((state) => state.removeCombatant);
    const clearCombatants = useCombatStore((state) => state.clearCombatants);
    const cancelEncounter = useCombatStore((state) => state.cancelEncounter);
    const saveEncounterTemplate = useCombatStore((state) => state.saveEncounterTemplate);
    const activeCampaignId = useCampaignStore((state) => state.activeCampaignId);

    const [title, setTitle] = useState('');
    const [isMonsterSearchOpen, setIsMonsterSearchOpen] = useState(false);

    // Quick add ad-hoc monster state
    const [quickMonsterName, setQuickMonsterName] = useState('');
    const [quickMonsterHp, setQuickMonsterHp] = useState('');
    const [quickMonsterAc, setQuickMonsterAc] = useState('');
    const [quickMonsterCount, setQuickMonsterCount] = useState('1');
    const [quickMonsterCr, setQuickMonsterCr] = useState('');
    const [confirmingClear, setConfirmingClear] = useState(false);
    const [savedFeedback, setSavedFeedback] = useState(false);
    const [isRandomizing, setIsRandomizing] = useState(false);
    const [randomDifficulty, setRandomDifficulty] = useState<'Easy' | 'Medium' | 'Hard' | 'Deadly'>('Medium');
    const [showRandomOptions, setShowRandomOptions] = useState(false);

    const campaigns = useCampaignStore((state) => state.campaigns);
    const activeCampaign = campaigns.find(c => c.id === activeCampaignId);

    // Filter characters to only those in the active campaign
    const displayCharacters = activeCampaign
        ? characters.filter(c => activeCampaign.partyIds.includes(c.id))
        : characters;

    if (!activeEncounter) {
        return (
            <div className="bg-combat min-h-[calc(100vh-4rem)] flex flex-col items-center justify-center p-6 space-y-8 animate-in zoom-in-95 duration-500">
                <div className="text-center space-y-3 glass-panel px-12 py-6 rounded-2xl border border-gold/20 shadow-[-5px_15px_30px_rgba(0,0,0,0.8)]">
                    <h2 className="text-4xl font-cinzel font-bold text-engraved-gold tracking-[0.2em] flex items-center justify-center gap-4">
                        <Play className="text-gold w-10 h-10 drop-shadow-md" fill="currentColor" />
                        COMBAT ENCOUNTER
                    </h2>
                    <p className="text-stone-400 font-medium tracking-widest text-xs uppercase opacity-90 drop-shadow-md">Enter the field of initiative and claim your destiny.</p>
                </div>

                <div className="w-full max-w-md glass-panel p-10 space-y-8 relative overflow-hidden group border border-gold/10 rounded-2xl shadow-[-5px_15px_30px_rgba(0,0,0,0.8)]">
                    <div className="absolute top-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-gold/30 to-transparent" />
                    <div className="absolute bottom-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-gold/10 to-transparent" />

                    <div className="space-y-3">
                        <label className="block text-[10px] font-black text-stone-400 uppercase tracking-[0.3em] ml-1 drop-shadow-md">Encounter Designation</label>
                        <input
                            type="text"
                            className="w-full bg-stone-950/80 border border-gold/20 rounded-xl px-6 py-4 text-parchment focus:outline-none focus:border-gold/50 focus:ring-1 focus:ring-gold/30 transition-all placeholder:text-stone-700 font-cinzel text-lg tracking-wide shadow-inner"
                            placeholder="e.g. THE AMBUSH AT OWL'S WATCH"
                            value={title}
                            onChange={(e) => setTitle(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && startEncounter(title || 'New Encounter', [], activeCampaignId || undefined)}
                        />
                    </div>

                    <button
                        onClick={() => startEncounter(title || 'New Encounter', [], activeCampaignId || undefined)}
                        className="w-full bg-gradient-to-b from-gold to-gold-light hover:from-gold-light hover:to-yellow-400 text-stone-950 font-black py-5 rounded-xl transition-all flex items-center justify-center gap-4 shadow-[0_10px_40px_rgba(217,119,6,0.3)] hover:shadow-[0_15px_50px_rgba(217,119,6,0.5)] hover:scale-[1.02] active:scale-95 uppercase tracking-[0.2em] text-xs border border-yellow-200/50"
                    >
                        <Plus size={18} strokeWidth={3} /> Begin Setup
                    </button>
                    <div className="flex flex-col items-center gap-2">
                        <div className="w-12 h-px bg-gradient-to-r from-transparent via-stone-700 to-transparent" />
                        <p className="text-[9px] text-stone-600 text-center uppercase tracking-[0.3em] font-medium italic">You will summon combatants in the next sanctum.</p>
                    </div>
                </div>

                <div className="flex justify-center w-full mt-12 pt-8">
                    <EncounterLibrary campaignId={activeCampaignId || undefined} />
                </div>
            </div>
        );
    }

    const handleAddPlayer = (char: any) => {
        // Check if already in
        if (activeEncounter.combatants.some(c => c.sourceId === char.id)) return;

        // Check for DM overrides on AC, Initiative, Speed
        const getVal = (field: string, fallback: any) => {
            const ov = char.customOverrides?.overrides?.find((o: any) => o.field === field && o.isActive);
            return ov ? ov.value : char[field] ?? fallback;
        };

        const combatant: Combatant = {
            id: crypto.randomUUID(),
            type: 'player',
            name: char.name,
            ac: Number(getVal('ac', 10)),
            maxHp: Number(char.maxHp) || 10,
            currentHp: Number(char.currentHp) || 10,
            tempHp: Number(char.tempHp) || 0,
            speed: getVal('speed', '30 ft'),
            initiativeMod: Number(getVal('initiativeMod', 0)),
            initiativeScore: null,
            dexterityScore: Number(char.abilityScores?.dex) || 10,
            conditions: [...char.conditions],
            abilityScores: char.abilityScores ? {
                str: Number(char.abilityScores.str) || 10,
                dex: Number(char.abilityScores.dex) || 10,
                con: Number(char.abilityScores.con) || 10,
                int: Number(char.abilityScores.int) || 10,
                wis: Number(char.abilityScores.wis) || 10,
                cha: Number(char.abilityScores.cha) || 10,
            } : undefined,
            savingThrowProficiencies: char.savingThrows,
            proficiencyBonus: Number(char.proficiencyBonus) || 2,
            spellcastingAbility: char.spellcastingAbility,
            spellSaveDc: Number(char.spellSaveDc) || 0,
            spellAttackMod: Number(char.spellAttackMod) || 0,
            spellSlots: char.spellSlots ? [...char.spellSlots] : undefined,
            isConcentrating: false,
            exhaustion: char.exhaustion || 0,
            sourceId: char.id,
            portraitUrl: char.portraitUrl
        };

        addCombatant(combatant);
    };

    const handleAddQuickMonster = () => {
        if (!quickMonsterName) return;

        const count = parseInt(quickMonsterCount) || 1;
        const hp = parseInt(quickMonsterHp) || 10;
        const ac = parseInt(quickMonsterAc) || 10;

        for (let i = 0; i < count; i++) {
            const name = count > 1 ? `${quickMonsterName} ${String.fromCharCode(65 + i)}` : quickMonsterName;

            const combatant: Combatant = {
                id: crypto.randomUUID(),
                type: 'monster',
                name,
                ac,
                maxHp: hp,
                currentHp: hp,
                tempHp: 0,
                speed: '30 ft',
                cr: quickMonsterCr || undefined,
                initiativeMod: 0, // Quick monsters get 0 init unless rolled manually
                initiativeScore: null,
                dexterityScore: 10,
                conditions: []
            };
            addCombatant(combatant);
        }

        setQuickMonsterName('');
        setQuickMonsterHp('');
        setQuickMonsterAc('');
        setQuickMonsterCount('1');
        setQuickMonsterCr('');
    };

    const handleImportMonster = (item: any) => {
        const dexMod = Math.floor(((item.dex || 10) - 10) / 2);
        const speed = item.speed && typeof item.speed === 'string' ? item.speed :
            (item.speed ? Object.entries(item.speed).map(([k, v]: [string, any]) =>
                typeof v === 'number' ? `${k} ${v} ft` : (v?.number ? `${k} ${v.number} ft` : '')).filter(Boolean).join(', ') : '30 ft');

        // Calculate proficiency bonus from CR
        const crNum = parseFloat(item.cr) || 0;
        const profBonus = crNum < 5 ? 2 : crNum < 9 ? 3 : crNum < 13 ? 4 : crNum < 17 ? 5 : crNum < 21 ? 6 : crNum < 25 ? 7 : crNum < 29 ? 8 : 9;

        // Legendary actions
        const legendaryMax = item.legendary ? (item.legendaryActions ?? 3) : 0;

        // Saving throw proficiencies
        const saveProfs: string[] = [];
        if (item.save) {
            Object.keys(item.save).forEach(k => saveProfs.push(k));
        }

        const combatant: Combatant = {
            id: crypto.randomUUID(),
            type: 'monster',
            name: item.name,
            ac: item.ac || 10,
            maxHp: item.hp || 10,
            currentHp: item.hp || 10,
            tempHp: 0,
            speed,
            initiativeMod: dexMod,
            initiativeScore: null,
            dexterityScore: item.dex || 10,
            abilityScores: {
                str: item.str || 10, dex: item.dex || 10, con: item.con || 10,
                int: item.int || 10, wis: item.wis || 10, cha: item.cha || 10
            },
            proficiencyBonus: profBonus,
            savingThrowProficiencies: saveProfs,
            legendaryActionsMax: legendaryMax,
            legendaryActionsRemaining: legendaryMax,
            conditions: [],
            monsterData: item,
            cr: item.cr ? (typeof item.cr === 'string' ? item.cr : item.cr.cr) : undefined,
            resistances: item.resistances,
            immunities: item.immunities,
            vulnerabilities: item.vulnerabilities,
            conditionImmunities: item.conditionImmunities,
            damageNotes: item.damageNotes,
            spellSlots: item.spellcasting ? parseMonsterSpellSlots(item.spellcasting) : undefined,
            isConcentrating: false,
            exhaustion: 0,
            portraitUrl: getPrimaryMonsterTokenUrl(item.name, item.source)
        };
        addCombatant(combatant);
        setIsMonsterSearchOpen(false);
    };

    const handleRandomEncounter = async () => {
        if (partyLevels.length === 0) return;

        setIsRandomizing(true);
        try {
            const result = await generateRandomEncounter(partyLevels, randomDifficulty);
            if (result && result.monsters) {
                result.monsters.forEach(m => handleImportMonster(m));
                setShowRandomOptions(false);
            }
        } catch (error) {
            console.error('Randomization failed:', error);
        } finally {
            setIsRandomizing(false);
        }
    };

    const handleClearEncounter = () => {
        clearCombatants();
        setConfirmingClear(false);
    };

    const playerCombatants = activeEncounter?.combatants?.filter(c => c.type === 'player') || [];
    const monsterCombatants = activeEncounter?.combatants?.filter(c => c.type === 'monster') || [];
    const partyLevels = playerCombatants.map(p => {
        const char = characters.find(c => c.id === p.sourceId);
        return char?.level || 1;
    });

    const diff = (partyLevels.length > 0 && monsterCombatants.length > 0)
        ? calculateEncounterDifficulty(partyLevels, monsterCombatants.map(m => m.cr || '0'))
        : null;

    const handleSaveTemplate = () => {
        if (!activeEncounter || monsterCombatants.length === 0) return;

        const templateTitle = activeEncounter.title || 'Untitled Encounter';

        saveEncounterTemplate({
            title: templateTitle,
            description: `Template containing ${monsterCombatants.length} monsters.`,
            enemies: monsterCombatants,
            estimatedDifficulty: diff?.difficulty,
            totalXP: diff?.totalXP,
            campaignId: activeCampaignId || undefined
        });
        setSavedFeedback(true);
        setTimeout(() => setSavedFeedback(false), 2000);
    };

    const playersCount = playerCombatants.length;
    const monsterCount = monsterCombatants.length;

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex items-center justify-between border-b border-white/5 pb-6">
                <div className="flex items-start gap-4">
                    <button
                        onClick={cancelEncounter}
                        className="mt-1 p-2.5 bg-stone-950/50 hover:bg-blood/10 text-stone-500 hover:text-blood rounded-xl transition-all border border-white/5 hover:border-blood/30 group"
                        title="Discard and Exit Setup"
                    >
                        <X size={18} className="group-hover:rotate-90 transition-transform duration-300" />
                    </button>
                    <div>
                        <h2 className="text-3xl font-cinzel font-bold text-white tracking-tight uppercase leading-none">
                            {activeEncounter?.title || 'Encounter'}
                        </h2>
                        <p className="text-[10px] text-stone-500 font-black uppercase tracking-[0.2em] mt-2">Battlefield Summoning Setup</p>
                    </div>
                </div>
                <div className="flex gap-4">
                    <div className="text-center px-6 py-3 glass-panel border-gold/20">
                        <div className="text-2xl font-black text-gold/80 leading-none">{playersCount}</div>
                        <div className="text-[9px] font-black uppercase tracking-widest text-stone-500 mt-2">Adventurers</div>
                    </div>
                    <div className="text-center px-6 py-3 glass-panel border-blood/20">
                        <div className="text-2xl font-black text-blood leading-none">{monsterCount}</div>
                        <div className="text-[9px] font-black uppercase tracking-widest text-stone-500 mt-2">Monsters</div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Left Col: Party Selection */}
                <div className="space-y-4">
                    <h3 className="text-sm font-bold text-stone-400 uppercase tracking-widest flex items-center gap-2">
                        <Users size={16} className="text-gold" /> Party Members
                    </h3>

                    <div className="glass-panel p-2 space-y-1 border-white/5 overflow-hidden">
                        {displayCharacters.length === 0 ? (
                            <div className="px-8 py-12 text-center text-sm text-stone-600 italic">
                                <Users size={40} className="mx-auto mb-4 opacity-10" />
                                {activeCampaignId
                                    ? `No legends found for ${activeCampaign?.title}.`
                                    : "The vault is currently empty."}
                            </div>
                        ) : (
                            <div className="max-h-[500px] overflow-y-auto custom-scrollbar px-1">
                                {!activeCampaignId && (
                                    <div className="px-3 py-2 text-[9px] text-stone-500 font-black uppercase tracking-[0.2em] opacity-60">
                                        Global Character Vault
                                    </div>
                                )}
                                {displayCharacters.map(char => {
                                    const isAdded = activeEncounter.combatants.some(c => c.sourceId === char.id);
                                    return (
                                        <div key={char.id} className={`flex items-center justify-between p-4 rounded-xl transition-all group mb-1 ${isAdded ? 'bg-gold/5 border border-gold/20' : 'hover:bg-white/5 border border-transparent hover:border-white/5'}`}>
                                            <div className="flex items-center gap-4">
                                                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all ${isAdded ? 'bg-gold border-gold text-stone-950 shadow-[0_0_15px_rgba(217,119,6,0.4)]' : 'bg-stone-950 border-stone-800 text-stone-500'}`}>
                                                    <Users size={18} fill={isAdded ? "currentColor" : "none"} />
                                                </div>
                                                <div>
                                                    <div className="font-bold text-parchment font-cinzel text-sm tracking-wide">{char.name}</div>
                                                    <div className="text-[10px] text-stone-500 font-bold uppercase tracking-widest mt-0.5">Level {char.level} {char.className}</div>
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => isAdded ? removeCombatant(activeEncounter.combatants.find(c => c.sourceId === char.id)!.id) : handleAddPlayer(char)}
                                                className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${isAdded
                                                    ? 'bg-blood/10 text-blood hover:bg-blood hover:text-white'
                                                    : 'bg-gold/10 text-gold hover:bg-gold hover:text-stone-950'
                                                    }`}
                                            >
                                                {isAdded ? 'Remove' : '+ Summon'}
                                            </button>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                </div>

                {/* Right Col: Monster Selection */}
                <div className="space-y-4">
                    <h3 className="text-sm font-bold text-stone-400 uppercase tracking-widest flex items-center gap-2">
                        <Ghost size={16} className="text-blood" /> Enemies
                    </h3>

                    <div className="glass-panel p-6 space-y-6">
                        <button
                            onClick={() => setIsMonsterSearchOpen(true)}
                            className="w-full py-4 border border-white/5 border-dashed rounded-xl text-stone-500 hover:text-gold hover:border-gold/30 hover:bg-gold/5 transition-all flex items-center justify-center gap-3 bg-stone-950/30 group tracking-widest uppercase text-[10px] font-black"
                        >
                            <Search size={16} className="group-hover:scale-110 transition-transform" />
                            Manual Archetype Lookup
                        </button>

                        <div className="relative">
                            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-white/5"></div></div>
                            <div className="relative flex justify-center"><span className="bg-[#1c1917]/80 px-4 text-[9px] font-black uppercase tracking-[0.3em] text-stone-600">Summoning Rituals</span></div>
                        </div>

                        {showRandomOptions ? (
                            <div className="bg-stone-950/50 p-5 border border-blood/20 rounded-xl space-y-5 animate-in zoom-in-95 duration-300">
                                <div className="space-y-3">
                                    <span className="block text-[9px] font-black text-stone-500 uppercase tracking-widest ml-1">Manifestation Intensity</span>
                                    <div className="grid grid-cols-2 gap-2">
                                        {(['Easy', 'Medium', 'Hard', 'Deadly'] as const).map(d => (
                                            <button
                                                key={d}
                                                onClick={() => setRandomDifficulty(d)}
                                                className={`px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest border transition-all ${randomDifficulty === d
                                                    ? 'bg-blood text-white border-blood-dark shadow-[0_0_15px_rgba(153,27,27,0.4)]'
                                                    : 'bg-stone-900/50 text-stone-500 border-white/5 hover:border-white/10'
                                                    }`}
                                            >
                                                {d}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div className="flex gap-2 pt-2">
                                    <button
                                        onClick={handleRandomEncounter}
                                        disabled={isRandomizing || playersCount === 0}
                                        className="flex-1 bg-blood hover:bg-red-700 disabled:opacity-30 text-white font-black py-3 rounded-xl text-xs uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-[0_4px_20px_rgba(153,27,27,0.3)]"
                                    >
                                        {isRandomizing ? <Loader2 className="animate-spin" size={16} /> : <Dice6 size={16} />}
                                        Inscribe Encounter
                                    </button>
                                    <button
                                        onClick={() => setShowRandomOptions(false)}
                                        className="px-4 py-3 bg-stone-800 hover:bg-stone-700 text-stone-400 text-xs font-black uppercase tracking-widest rounded-xl transition-all"
                                    >
                                        Abort
                                    </button>
                                </div>
                                {playersCount === 0 && (
                                    <p className="text-[10px] text-blood text-center uppercase font-black tracking-widest">A party is required for synchronization.</p>
                                )}
                            </div>
                        ) : (
                            <button
                                onClick={() => setShowRandomOptions(true)}
                                className="w-full py-4 border border-blood/20 bg-blood/5 rounded-xl text-blood hover:bg-blood hover:text-white transition-all flex items-center justify-center gap-3 group uppercase tracking-[0.2em] text-[10px] font-black"
                            >
                                <Sparkles size={16} className="group-hover:rotate-12 transition-transform text-blood" />
                                Random Manifestation
                                <Dice6 size={16} className="opacity-30" />
                            </button>
                        )}

                        <div className="relative">
                            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-white/5"></div></div>
                            <div className="relative flex justify-center"><span className="bg-[#1c1917]/80 px-4 text-[9px] font-black uppercase tracking-[0.3em] text-stone-600">Quick Summon</span></div>
                        </div>

                        <div className="space-y-4">
                            <div className="grid grid-cols-4 gap-4">
                                <div className="col-span-4 space-y-1.5">
                                    <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest ml-1">Subject Name</label>
                                    <input
                                        type="text"
                                        className="w-full bg-stone-950/50 border border-white/5 rounded-xl px-4 py-2.5 text-sm text-parchment focus:outline-none focus:border-blood/50 transition-all font-cinzel"
                                        value={quickMonsterName}
                                        onChange={e => setQuickMonsterName(e.target.value)}
                                        onKeyDown={e => e.key === 'Enter' && handleAddQuickMonster()}
                                    />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest ml-1 text-center block">CR</label>
                                    <input
                                        type="text"
                                        className="w-full bg-stone-950/50 border border-white/5 rounded-xl px-2 py-2.5 text-xs text-parchment focus:outline-none focus:border-blood/50 text-center font-mono"
                                        value={quickMonsterCr}
                                        onChange={e => setQuickMonsterCr(e.target.value)}
                                        onKeyDown={e => e.key === 'Enter' && handleAddQuickMonster()}
                                    />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest ml-1 text-center block">AC</label>
                                    <input
                                        type="number"
                                        className="w-full bg-stone-950/50 border border-white/5 rounded-xl px-2 py-2.5 text-xs text-parchment focus:outline-none focus:border-blood/50 text-center font-mono"
                                        value={quickMonsterAc}
                                        onChange={e => setQuickMonsterAc(e.target.value)}
                                        onKeyDown={e => e.key === 'Enter' && handleAddQuickMonster()}
                                    />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest ml-1 text-center block">HP</label>
                                    <input
                                        type="number"
                                        className="w-full bg-stone-950/50 border border-white/5 rounded-xl px-2 py-2.5 text-xs text-parchment focus:outline-none focus:border-blood/50 text-center font-mono"
                                        value={quickMonsterHp}
                                        onChange={e => setQuickMonsterHp(e.target.value)}
                                        onKeyDown={e => e.key === 'Enter' && handleAddQuickMonster()}
                                    />
                                </div>
                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-stone-500 uppercase tracking-widest ml-1 text-center block">QTY</label>
                                    <input
                                        type="number"
                                        className="w-full bg-stone-950/50 border border-white/5 rounded-xl px-2 py-2.5 text-xs text-parchment focus:outline-none focus:border-blood/50 text-center font-mono"
                                        value={quickMonsterCount}
                                        onChange={e => setQuickMonsterCount(e.target.value)}
                                        onKeyDown={e => e.key === 'Enter' && handleAddQuickMonster()}
                                    />
                                </div>
                            </div>
                            <button
                                onClick={handleAddQuickMonster}
                                disabled={!quickMonsterName}
                                className="w-full bg-stone-950/50 hover:bg-blood/5 border border-white/5 hover:border-blood/20 disabled:opacity-20 text-stone-300 font-black py-3 rounded-xl flex items-center justify-center transition-all uppercase tracking-widest text-[10px] hover:text-blood"
                            >
                                <Plus size={16} className="mr-2" /> Manifest Soul
                            </button>
                        </div>
                    </div>

                    {/* Added Monsters List */}
                    {activeEncounter.combatants.filter(c => c.type === 'monster').length > 0 && (
                        <div className="glass-panel p-2 space-y-1 border-white/5">
                            <div className="max-h-[300px] overflow-y-auto custom-scrollbar px-1">
                                {activeEncounter.combatants.filter(c => c.type === 'monster').map(m => (
                                    <div className="flex items-center justify-between p-3 hover:bg-blood/5 rounded-xl group transition-all border border-transparent hover:border-blood/10 mb-1">
                                        <div className="flex items-center gap-3">
                                            {m.portraitUrl ? (
                                                <div className="w-10 h-10 rounded-full overflow-hidden border border-blood/50 shadow-[0_0_10px_rgba(153,27,27,0.3)] bg-stone-900 flex-shrink-0 relative">
                                                    <img src={m.portraitUrl} alt={m.name} className="w-full h-full object-cover scale-[1.15]" onError={(e) => { e.currentTarget.style.display = 'none'; e.currentTarget.nextElementSibling?.classList.remove('hidden'); }} />
                                                    <div className="hidden absolute inset-0 flex items-center justify-center text-blood text-xs font-black font-cinzel">{m.name.charAt(0)}</div>
                                                </div>
                                            ) : (
                                                <div className="w-10 h-10 bg-stone-950 rounded-full flex items-center justify-center text-blood text-xs font-black font-cinzel border border-blood/20 shadow-[inset_0_0_10px_rgba(153,27,27,0.2)] flex-shrink-0">
                                                    {m.name.charAt(0)}
                                                </div>
                                            )}
                                            <div>
                                                <div className="flex items-center gap-2">
                                                    <div className="text-sm font-bold text-parchment font-cinzel tracking-wide">{m.name}</div>
                                                    {m.cr && <span className="text-[8px] font-black bg-stone-950/50 text-blood px-1.5 py-0.5 rounded border border-blood/20 uppercase tracking-tighter">CR {m.cr}</span>}
                                                </div>
                                                <div className="text-[10px] text-stone-500 font-bold uppercase tracking-widest mt-0.5">
                                                    AC {m.ac} | HP {m.maxHp}
                                                    {m.cr && ` | ${CR_TO_XP[m.cr] || 0} XP`}
                                                </div>
                                            </div>
                                        </div>
                                        <button
                                            onClick={() => removeCombatant(m.id)}
                                            className="text-stone-700 hover:text-blood p-2 opacity-0 group-hover:opacity-100 transition-all hover:bg-blood/10 rounded-lg"
                                        >
                                            <Trash2 size={14} />
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <FiveEToolsModal
                isOpen={isMonsterSearchOpen}
                onClose={() => setIsMonsterSearchOpen(false)}
                onImport={(item) => handleImportMonster(item)}
                initialCategory="Monsters"
            />

            {/* Proceed to Initiative Footer */}
            <div className="pt-8 mt-12 border-t border-white/5 space-y-8 pb-12">
                {diff && (
                    <div className="glass-panel p-6 flex flex-col lg:flex-row items-center justify-between gap-8 border-white/5 relative overflow-hidden group">
                        <div className="absolute top-0 left-0 w-full h-[1px] bg-gradient-to-r from-transparent via-gold/20 to-transparent" />
                        <div className="flex-1 space-y-3">
                            <div className="flex items-center gap-4">
                                <h4 className="text-[10px] font-black text-stone-500 uppercase tracking-[0.2em]">Encounter Complexity</h4>
                                <span className={`text-xs font-black uppercase tracking-[0.2em] px-3 py-1 rounded-lg border shadow-lg ${getDifficultyColor(diff.difficulty)}`}>
                                    {diff.difficulty}
                                </span>
                            </div>
                            <div className="grid grid-cols-3 gap-6">
                                <div className="space-y-1">
                                    <span className="text-[10px] text-stone-600 font-bold uppercase tracking-widest block">Raw Sacrifice</span>
                                    <span className="text-sm font-mono text-stone-300 font-bold tracking-tighter">{diff.totalXP.toLocaleString()} XP</span>
                                </div>
                                <div className="space-y-1">
                                    <span className="text-[10px] text-stone-600 font-bold uppercase tracking-widest block">Adjusted Essence</span>
                                    <span className="text-sm font-mono text-gold-light font-bold tracking-tighter">{diff.adjustedXP.toLocaleString()} XP <span className="text-[10px] opacity-60">(×{diff.multiplier})</span></span>
                                </div>
                                <div className="space-y-1">
                                    <span className="text-[10px] text-stone-600 font-bold uppercase tracking-widest block">Daily Budget</span>
                                    <span className="text-sm font-mono text-stone-400 font-bold tracking-tighter">{diff.dailyBudget.toLocaleString()} XP</span>
                                </div>
                            </div>
                        </div>
                        <div className="flex gap-2">
                            {(['easy', 'medium', 'hard', 'deadly'] as const).map(level => {
                                const isCurrent = diff.difficulty.toLowerCase() === level;
                                const colors: Record<string, string> = {
                                    easy: 'border-green-500/30 text-green-500 bg-green-500/5',
                                    medium: 'border-yellow-500/30 text-yellow-500 bg-yellow-500/5',
                                    hard: 'border-orange-500/30 text-orange-500 bg-orange-500/5',
                                    deadly: 'border-blood/30 text-blood bg-blood/5'
                                };
                                return (
                                    <div key={level} className={`w-16 h-16 rounded-xl border flex flex-col items-center justify-center transition-all duration-500 ${isCurrent ? `${colors[level]} shadow-[0_0_20px_rgba(0,0,0,0.3)] scale-110 z-10 font-bold border-stone-500/50` : 'border-white/5 bg-stone-900/40 text-stone-700 opacity-40 scale-90'}`}>
                                        <span className="text-[8px] uppercase font-black tracking-widest mb-1">{level}</span>
                                        <span className="text-[10px] font-mono">{diff.thresholds[level].toLocaleString()}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                    <div className="flex gap-4 items-center">
                        {confirmingClear ? (
                            <div className="flex items-center gap-3 glass-panel border-blood/30 px-4 py-2 animate-in slide-in-from-left-4 duration-300">
                                <span className="text-[10px] font-black text-blood uppercase tracking-widest">Wipe setup?</span>
                                <button
                                    type="button"
                                    onClick={handleClearEncounter}
                                    className="text-[10px] font-black text-white px-3 py-1.5 rounded-lg bg-blood hover:bg-red-700 transition-all uppercase tracking-widest shadow-lg"
                                >
                                    Confirm
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setConfirmingClear(false)}
                                    className="text-[10px] font-black text-stone-500 hover:text-white px-3 py-1.5 transition-all uppercase tracking-widest"
                                >
                                    Abort
                                </button>
                            </div>
                        ) : (
                            <button
                                type="button"
                                onClick={() => setConfirmingClear(true)}
                                disabled={activeEncounter.combatants.length === 0}
                                className="text-stone-600 hover:text-blood disabled:opacity-30 text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 transition-all px-6 py-3 border border-transparent hover:border-blood/20 rounded-xl"
                            >
                                <X size={16} /> Discard All
                            </button>
                        )}
                        <button
                            type="button"
                            onClick={handleSaveTemplate}
                            disabled={monsterCombatants.length === 0}
                            className={`text-stone-500 hover:text-gold disabled:opacity-30 text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3 transition-all px-6 py-3 glass-panel border-white/5 ${savedFeedback ? 'text-gold-light' : ''}`}
                        >
                            <Save size={16} /> {savedFeedback ? '✓ Inscribed' : 'Save Archetype'}
                        </button>
                    </div>

                    <button
                        type="button"
                        onClick={completeSetup}
                        disabled={activeEncounter.combatants.length === 0}
                        className="bg-gold hover:bg-gold-light disabled:bg-stone-900 disabled:text-stone-700 disabled:border-white/5 text-stone-950 font-black px-12 py-5 rounded-2xl text-xs uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-4 shadow-[0_15px_40px_rgba(217,119,6,0.3)] hover:shadow-[0_20px_50px_rgba(217,119,6,0.4)] hover:scale-[1.02] active:scale-95 border border-gold-light/30"
                    >
                        PROCEED TO INITIATIVE <Play size={20} fill="currentColor" className="text-stone-950/80" />
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import * as LucideIcons from 'lucide-react';
import { useCombatStore } from '../../store/combatStore';

import { Condition } from '../../types/character';
import conditionsData from '../../data/dnd5e/conditions.json';

interface ConditionData {
    name: string;
    icon: string;
    description: string;
    type: 'condition' | 'buff';
    flavor?: string;
    coaching?: {
        instruction: string;
        maths: string;
        save: string;
    };
}

interface ConditionMenuProps {
    targetId?: string;
    onHover?: (name: string, e: React.MouseEvent) => void;
    onLeave?: () => void;
}

export function ConditionMenu({ targetId: propTargetId, onHover, onLeave }: ConditionMenuProps) {
    const activeEncounter = useCombatStore((state) => state.activeEncounter);
    const selectedCombatantId = useCombatStore((state) => state.selectedCombatantId);
    const updateCombatant = useCombatStore((state) => state.updateCombatant);
    const addLog = useCombatStore((state) => state.addLog);

    const [durationInput, setDurationInput] = useState<{ [key: string]: string }>({});
    const [wizardContext, setWizardContext] = useState<{ condId: string, condName: string, targetId: string } | null>(null);

    if (!activeEncounter) return null;

    const activeCombatantId = activeEncounter.activeCombatantId;
    const activeCombatant = activeEncounter.combatants.find(c => c.id === activeCombatantId);
    const targetId = wizardContext?.targetId || propTargetId || selectedCombatantId || activeCombatantId;
    if (!targetId) return null;

    const target = activeEncounter.combatants.find(c => c.id === targetId);
    if (!target) return null;

    const conditions = (conditionsData as ConditionData[]).filter(c => c.type === 'condition');
    const buffs = (conditionsData as ConditionData[]).filter(c => c.type === 'buff');

    const getIcon = (iconName: string) => {
        // Convert kebab-case or descriptive names to PascalCase for Lucide
        const pascalName = iconName
            .split('-')
            .map(part => part.charAt(0).toUpperCase() + part.slice(1))
            .join('');

        const IconComponent = (LucideIcons as any)[pascalName] || LucideIcons.HelpCircle;
        return IconComponent;
    };

    const getConditionSaveInfo = (condId: string) => {
        const attackerStr = activeCombatant?.abilityScores?.str || 10;
        const attackerMod = Math.floor((attackerStr - 10) / 2);
        const attackerProf = activeCombatant?.proficiencyBonus || 2;
        const physicalDC = 8 + attackerMod + attackerProf;
        const spellDC = activeCombatant?.spellSaveDc || (8 + (activeCombatant?.proficiencyBonus || 2) + 3);

        switch (condId.toLowerCase()) {
            case 'grappled':
                return {
                    save: 'Strength (STR) or Dexterity (DEX) Saving Throw (Target\'s Choice)',
                    dcLabel: `Difficulty Class (DC) ${physicalDC} (8 + STR Mod ${attackerMod >= 0 ? '+' : ''}${attackerMod} + Proficiency ${attackerProf})`,
                    ruleTip: '2024 Rule: Grappled creatures have Disadvantage on attacks against anyone except the grappler!'
                };
            case 'prone':
                return {
                    save: 'Dexterity (DEX) Saving Throw (usually from an Unarmed Strike)',
                    dcLabel: `Difficulty Class (DC) ${physicalDC} (8 + STR Mod ${attackerMod >= 0 ? '+' : ''}${attackerMod} + Proficiency ${attackerProf})`,
                    ruleTip: '2024 Rule: Standing up costs half your movement and no longer provokes opportunity attacks.'
                };
            case 'stunned':
            case 'paralyzed':
                return {
                    save: 'Constitution (CON) Saving Throw',
                    dcLabel: `Difficulty Class (DC) ${spellDC} (Typically attacker's Spell Save DC)`,
                    ruleTip: '2024 Rule: Stunned/Paralyzed creatures fail Strength (STR) and Dexterity (DEX) saves automatically.'
                };
            case 'poisoned':
                return {
                    save: 'Constitution (CON) Saving Throw',
                    dcLabel: `Difficulty Class (DC) ${spellDC} or Source DC`,
                    ruleTip: 'Poisoned creatures have Disadvantage on attack rolls and ability checks.'
                };
            case 'exhaustion':
                return {
                    save: 'Constitution (CON) Saving Throw (if recurring)',
                    dcLabel: 'DC Varies',
                    ruleTip: '2024 Rule: Exhaustion is now a penalty (Exhausted 1-6) to D20 tests and Speed.'
                };
            default:
                return null;
        }
    };

    const toggleCondition = (cond: ConditionData, duration?: number, specificTargetId?: string) => {
        const idToUpdate = specificTargetId || wizardContext?.targetId || selectedCombatantId || activeCombatantId;
        if (!idToUpdate) return;

        const targetToUpdate = activeEncounter.combatants.find(c => c.id === idToUpdate);
        if (!targetToUpdate) return;

        const condId = cond.name.toLowerCase();
        const hasCondition = targetToUpdate.conditions.some(c => c.id === condId);

        if (hasCondition) {
            const updated = targetToUpdate.conditions.filter(c => c.id !== condId);
            updateCombatant(idToUpdate, { conditions: updated });
            addLog({
                message: `${targetToUpdate.name} is no longer ${cond.name}.`,
                type: 'status',
                combatantId: idToUpdate
            });
        } else {
            const newCondition: Condition = {
                id: condId,
                name: cond.name,
                duration: duration || undefined,
                description: cond.description
            };
            updateCombatant(idToUpdate, { conditions: [...targetToUpdate.conditions, newCondition] });
            addLog({
                message: `${targetToUpdate.name} is now ${cond.name}${duration ? ` (${duration} rounds)` : ''}.`,
                type: 'status',
                combatantId: idToUpdate
            });
        }
        setWizardContext(null);
    };

    const renderGrid = (items: ConditionData[], title: string, colorClass: string, icon: React.ReactNode) => (
        <div className="space-y-2">
            <h4 className={`text-[9px] font-black uppercase tracking-[0.2em] flex items-center gap-2 ${colorClass}`}>
                {icon}
                {title}
            </h4>
            <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-7 gap-1.5">
                {items.map((cond) => {
                    const condId = cond.name.toLowerCase();
                    const isActive = target.conditions.some(c => c.id === condId);
                    const Icon = getIcon(cond.icon);
                    const duration = target.conditions.find(c => c.id === condId)?.duration;

                    return (
                        <div key={cond.name} className="relative group/item">
                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    if (isActive) {
                                        toggleCondition(cond);
                                    } else {
                                        setWizardContext({ condId: condId, condName: cond.name, targetId: targetId });
                                    }
                                }}
                                onMouseEnter={(e) => onHover?.(cond.name, e)}
                                onMouseLeave={() => onLeave?.()}
                                className={`
                                    w-full aspect-square flex flex-col items-center justify-center p-1 rounded border transition-all relative
                                    ${isActive
                                        ? cond.type === 'buff'
                                            ? 'bg-cyan-500/10 border-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.3)] ring-1 ring-cyan-500/50'
                                            : 'bg-blood/10 border-blood shadow-[0_0_15px_rgba(153,27,27,0.3)] ring-1 ring-red-500/50'
                                        : 'bg-stone-950 border-stone-800/50 hover:border-stone-600 hover:bg-stone-900'}
                                `}
                            >
                                <Icon size={16} className={`${isActive ? cond.type === 'buff' ? 'text-cyan-400' : 'text-blood' : 'text-stone-600 group-hover/item:text-stone-400'} transition-colors`} />
                                {duration && (
                                    <div className="absolute -top-1 -right-1 bg-gold text-stone-950 text-[8px] font-black w-3.5 h-3.5 rounded-full flex items-center justify-center border border-stone-950 shadow-sm">
                                        {duration}
                                    </div>
                                )}
                            </button>
                        </div>
                    );
                })}
            </div>
        </div>
    );

    return (
        <div className="flex flex-col space-y-5 bg-stone-900/30 p-3 rounded-xl border border-stone-800/50 relative">
            {/* Condition Wizard Overlay */}
            {wizardContext && (
                <div className="absolute inset-0 z-[200] animate-in fade-in zoom-in-95 duration-200 pointer-events-auto bg-stone-950 flex flex-col pt-0" onClick={e => e.stopPropagation()}>
                    <div className="flex-1 flex flex-col overflow-hidden">
                        <div className="bg-gold/10 border-b border-gold/20 p-4 flex items-center justify-between shrink-0">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-stone-900 rounded-lg border border-gold/20">
                                    <LucideIcons.Star className="text-gold" size={18} />
                                </div>
                                <div>
                                    <h4 className="text-gold font-bold text-xs uppercase tracking-widest">Status Wizard</h4>
                                    <p className="text-stone-400 text-[10px] uppercase font-bold tracking-tight">PHB 2024 Standards</p>
                                </div>
                            </div>
                            <button onClick={() => setWizardContext(null)} className="text-stone-500 hover:text-white p-1">
                                <LucideIcons.X size={16} />
                            </button>
                        </div>

                        <div className="p-5 space-y-4 overflow-y-auto custom-scrollbar flex-1">
                            <div className="space-y-1">
                                <span className="text-[10px] text-stone-500 font-bold uppercase tracking-widest">Applying To</span>
                                <p className="text-parchment font-bold text-lg leading-tight">{target.name}</p>
                            </div>

                            <div className="bg-stone-900/50 rounded-lg p-4 border border-stone-800/50 space-y-4">
                                {(() => {
                                    const cond = conditionsData.find(c => c.name.toLowerCase() === wizardContext.condId) as ConditionData;
                                    return (
                                        <>
                                            <div className="space-y-1">
                                                <h5 className="text-[9px] text-gold font-black uppercase tracking-widest flex items-center gap-1.5">
                                                    <LucideIcons.MessageSquare size={10} /> How to explain to players
                                                </h5>
                                                <p className="text-xs text-parchment leading-relaxed font-bold">
                                                    {cond?.coaching?.instruction || cond?.flavor || "Inform the player of this change in status."}
                                                </p>
                                            </div>

                                            <div className="space-y-1 pt-2 border-t border-stone-800/50">
                                                <h5 className="text-[9px] text-cyan-400 font-black uppercase tracking-widest flex items-center gap-1.5">
                                                    <LucideIcons.Calculator size={10} /> Core Maths & Rules
                                                </h5>
                                                <p className="text-[10px] text-stone-300 leading-relaxed">
                                                    {cond?.coaching?.maths || cond?.description}
                                                </p>
                                            </div>
                                        </>
                                    );
                                })()}
                            </div>

                            {getConditionSaveInfo(wizardContext.condId) && (
                                <div className="bg-blood/5 border border-blood/20 rounded-lg p-3 space-y-2">
                                    <h5 className="text-blood font-bold text-[10px] uppercase tracking-wider flex items-center gap-1.5">
                                        <LucideIcons.ZapOff size={12} /> Resisting the Condition
                                    </h5>
                                    <div className="space-y-1">
                                        <p className="text-xs text-parchment font-bold">
                                            Roll: <span className="text-gold">{getConditionSaveInfo(wizardContext.condId)?.save}</span>
                                        </p>
                                        <p className="text-[10px] text-stone-400 font-mono">
                                            {getConditionSaveInfo(wizardContext.condId)?.dcLabel}
                                        </p>
                                    </div>
                                    <div className="pt-2 border-t border-blood/10">
                                        <p className="text-[9px] text-stone-400 leading-tight">
                                            <strong className="text-gold">Quick Rule:</strong> {getConditionSaveInfo(wizardContext.condId)?.ruleTip}
                                        </p>
                                    </div>
                                </div>
                            )}

                            <div className="space-y-3 pt-2">
                                <div>
                                    <label className="text-[10px] text-stone-500 font-bold uppercase tracking-widest block mb-2">Duration (Rounds)</label>
                                    <div className="flex gap-2">
                                        <input
                                            autoFocus
                                            type="number"
                                            placeholder="∞"
                                            className="bg-stone-900 border border-stone-800 rounded-lg px-3 py-2 text-sm text-parchment w-20 focus:outline-none focus:border-gold transition-all"
                                            value={durationInput[wizardContext.condId] || ''}
                                            onChange={(e) => setDurationInput({ ...durationInput, [wizardContext.condId]: e.target.value })}
                                        />
                                        <button
                                            onClick={() => {
                                                const cond = conditionsData.find(c => c.name.toLowerCase() === wizardContext.condId);
                                                if (cond) toggleCondition(cond as ConditionData, parseInt(durationInput[wizardContext.condId]) || undefined);
                                            }}
                                            className="flex-1 bg-gold text-stone-950 font-black text-[10px] uppercase tracking-widest py-2 rounded-lg hover:bg-gold-bright transition-all shadow-lg active:scale-95"
                                        >
                                            Confirm Application
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <div className="flex items-center justify-between border-b border-stone-800 pb-2 mb-1">
                <div className="flex items-center gap-2">
                    <LucideIcons.Activity size={14} className="text-stone-500" />
                    <h3 className="text-[10px] font-black text-stone-400 uppercase tracking-[0.2em]">
                        Effects Management
                    </h3>
                </div>
                {target.conditions.length > 0 && (
                    <button
                        onClick={(e) => {
                            e.stopPropagation();
                            updateCombatant(targetId, { conditions: [] });
                        }}
                        className="text-[9px] font-bold text-blood hover:text-red-400 transition-colors flex items-center gap-1 uppercase tracking-tighter"
                    >
                        <LucideIcons.X size={10} />
                        Wipe States
                    </button>
                )}
            </div>

            {/* Buffs Section */}
            {renderGrid(buffs, "Positive Buffs", "text-cyan-400", <LucideIcons.Sparkles size={12} />)}

            {/* Conditions Section */}
            {renderGrid(conditions, "Negative Conditions", "text-blood", <LucideIcons.Skull size={12} />)}

            <div className="pt-2 border-t border-stone-800/50">
                <p className="text-[8px] text-stone-600 italic leading-tight">
                    Hover icons to view tactical details. Click to apply/remove effect to the active target.
                </p>
            </div>
        </div>
    );
}

import React from 'react';
import conditionsData from '../../data/dnd5e/conditions.json';

interface ConditionTooltipProps {
    conditionName: string;
    x: number;
    y: number;
}

export const ConditionTooltip: React.FC<ConditionTooltipProps> = ({
    conditionName,
    x,
    y
}) => {
    const nameLower = conditionName.toLowerCase();
    const [finalX, setFinalX] = React.useState(x + 15);

    React.useEffect(() => {
        const tooltipWidth = 320; // Matches the w-80 class (80 * 4px)
        const padding = 20;
        const rightEdge = x + 15 + tooltipWidth + padding;

        if (rightEdge > window.innerWidth) {
            // Flip to left side
            setFinalX(x - tooltipWidth - 15);
        } else {
            setFinalX(x + 15);
        }
    }, [x]);

    // Find rich data in conditions.json
    const cond = conditionsData.find(c => c.name.toLowerCase() === nameLower) as any;

    if (!cond) {
        // Fallback for custom or unknown conditions
        return (
            <div
                className="fixed z-[200] pointer-events-none animate-in fade-in zoom-in duration-150"
                style={{ left: finalX, top: y - 10 }}
            >
                <div className="bg-stone-900/95 backdrop-blur-md border border-stone-700 rounded shadow-2xl p-3 w-64">
                    <h4 className="text-xs font-black uppercase text-parchment tracking-widest border-b border-stone-800 pb-1 mb-2">
                        {conditionName}
                    </h4>
                    <p className="text-[10px] text-stone-400 italic">No detailed information available.</p>
                </div>
            </div>
        );
    }

    return (
        <div
            className="fixed z-[200] pointer-events-none animate-in fade-in zoom-in duration-150"
            style={{ left: finalX, top: y - 10 }}
        >
            <div className="bg-stone-900/95 backdrop-blur-md border border-stone-700 rounded shadow-2xl overflow-hidden w-80 p-4 flex flex-col gap-4">
                <div className="flex items-center justify-between border-b border-stone-800 pb-2">
                    <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${cond.type === 'buff' ? 'bg-cyan-500 shadow-[0_0_8px_rgba(6,182,212,0.5)]' : 'bg-blood shadow-[0_0_8px_rgba(153,27,27,0.5)]'}`} />
                        <h4 className="text-[11px] font-black uppercase text-parchment tracking-[0.2em]">
                            {cond.name}
                        </h4>
                    </div>
                    <span className={`text-[8px] font-black px-1.5 py-0.5 rounded border ${cond.type === 'buff' ? 'text-cyan-400 border-cyan-900/50 bg-cyan-900/20' : 'text-blood border-red-950/50 bg-red-950/20'} uppercase`}>
                        {cond.type}
                    </span>
                </div>

                {cond.coaching?.instruction && (
                    <div className="space-y-1">
                        <h5 className="text-[8px] text-gold font-black uppercase tracking-widest flex items-center gap-1.5">
                            <span className="opacity-50">DM INSTRUCTION</span>
                        </h5>
                        <p className="text-[11px] text-parchment leading-relaxed font-bold">
                            {cond.coaching.instruction}
                        </p>
                    </div>
                )}

                <div className="space-y-2">
                    <div className="p-2.5 rounded bg-stone-950/50 border border-stone-800/50 space-y-1.5">
                        <h5 className="text-[8px] text-cyan-400 font-black uppercase tracking-widest">Rules & Maths</h5>
                        <p className="text-[10px] text-stone-300 leading-relaxed">
                            {cond.coaching?.maths || cond.description}
                        </p>
                    </div>

                    {cond.coaching?.save && (
                        <div className="p-2.5 rounded bg-stone-950/50 border border-stone-800/50 space-y-1.5">
                            <h5 className="text-[8px] text-blood font-black uppercase tracking-widest">Ending the Effect</h5>
                            <p className="text-[10px] text-stone-300 leading-relaxed font-medium">
                                {cond.coaching.save}
                            </p>
                        </div>
                    )}
                </div>

                <p className="text-[9px] text-stone-500 italic leading-snug opacity-60">
                    {cond.flavor}
                </p>
            </div>
        </div>
    );
};

import { useState } from 'react';
import { useCombatStore } from '../../store/combatStore';
import { rollDice } from '../../engine/diceEngine';
import { Dice5, Send } from 'lucide-react';

export function DiceRoller() {
    const addLog = useCombatStore(state => state.addLog);
    const activeEncounter = useCombatStore(state => state.activeEncounter);

    const [notation, setNotation] = useState('');
    const [advantageMode, setAdvantageMode] = useState<'normal' | 'advantage' | 'disadvantage'>('normal');
    const [lastRoll, setLastRoll] = useState<any>(null);

    const handleRoll = () => {
        if (!notation) return;

        try {
            const result = rollDice(notation, advantageMode);
            setLastRoll(result);
        } catch (e) {
            console.error(e);
        }
    };

    const broadcastRoll = () => {
        if (!lastRoll || !activeEncounter) return;

        const modeText = lastRoll.advantageMode !== 'normal' ? ` (w/ ${lastRoll.advantageMode})` : '';
        addLog({
            message: `DM rolled ${lastRoll.notation}${modeText}: **${lastRoll.total}**`,
            type: 'roll',
            details: lastRoll
        });
    };

    const handleQuickRoll = (flat: string) => {
        try {
            const result = rollDice(flat, 'normal');
            setLastRoll(result);
            setNotation(flat);
        } catch {
            return;
        }
    };

    return (
        <div className="bg-stone-900 border border-stone-800 rounded-lg p-4 shadow-xl space-y-4">
            <h3 className="text-xs font-bold text-stone-400 uppercase tracking-widest flex items-center gap-2 border-b border-stone-800 pb-2">
                <Dice5 size={16} className="text-arcane" /> DM Dice Roller
            </h3>

            <div className="flex gap-2">
                <input
                    type="text"
                    value={notation}
                    onChange={(e) => setNotation(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleRoll()}
                    placeholder="e.g. 2d6+3"
                    className="flex-1 bg-stone-950 border border-stone-800 rounded px-3 py-2 text-parchment font-mono focus:outline-none focus:border-arcane"
                />
                <button
                    onClick={handleRoll}
                    className="bg-stone-800 hover:bg-stone-700 text-stone-300 font-bold px-4 rounded transition-colors"
                >
                    Roll
                </button>
            </div>

            <div className="flex gap-1">
                {['normal', 'advantage', 'disadvantage'].map((mode) => (
                    <button
                        key={mode}
                        onClick={() => setAdvantageMode(mode as any)}
                        className={`flex-1 py-1 text-[10px] uppercase font-bold tracking-wider rounded border transition-colors ${advantageMode === mode
                                ? 'bg-arcane/20 border-arcane text-arcane-light'
                                : 'bg-stone-950 border-stone-800 text-stone-500 hover:bg-stone-900'
                            }`}
                    >
                        {mode === 'normal' ? 'Norm' : mode === 'advantage' ? 'Adv' : 'Disadv'}
                    </button>
                ))}
            </div>

            <div className="flex gap-1 overflow-x-auto custom-scrollbar pb-1">
                {['d20', 'd12', 'd10', 'd8', 'd6', 'd4', 'd100'].map(die => (
                    <button
                        key={die}
                        onClick={() => handleQuickRoll(`1${die}`)}
                        className="bg-stone-950 border border-stone-800 hover:border-gold text-stone-400 hover:text-gold px-2 py-1 rounded text-xs font-mono transition-colors"
                    >
                        {die}
                    </button>
                ))}
            </div>

            {lastRoll && (
                <div className="mt-4 pt-3 border-t border-stone-800 bg-stone-950/50 p-3 rounded flex flex-col items-center animate-in slide-in-from-bottom-2">
                    <div className="text-[10px] text-stone-500 uppercase tracking-widest mb-1">Result</div>
                    <div className={`text-3xl font-bold font-cinzel leading-none mb-2 ${lastRoll.isCrit ? 'text-gold drop-shadow-[0_0_8px_rgba(255,215,0,0.5)]' :
                            lastRoll.isFumble ? 'text-blood' : 'text-parchment'
                        }`}>
                        {lastRoll.total}
                    </div>

                    <div className="flex flex-wrap items-center justify-center gap-1 mb-3">
                        {lastRoll.rolls.map((r: number, i: number) => (
                            <span key={i} className="text-xs bg-stone-900 border border-stone-700 font-mono text-stone-300 px-1.5 py-0.5 rounded">
                                {r}
                            </span>
                        ))}
                        {lastRoll.droppedRolls && lastRoll.droppedRolls.map((r: number, i: number) => (
                            <span key={`drop-${i}`} className="text-xs bg-stone-900/50 border border-stone-800/50 font-mono text-stone-600 px-1.5 py-0.5 rounded line-through">
                                {r}
                            </span>
                        ))}
                        {lastRoll.modifier !== 0 && (
                            <span className="text-xs text-stone-400 font-mono px-1">
                                {lastRoll.modifier > 0 ? '+' : ''}{lastRoll.modifier}
                            </span>
                        )}
                    </div>

                    <button
                        onClick={broadcastRoll}
                        disabled={!activeEncounter}
                        className="w-full bg-arcane/20 hover:bg-arcane/30 text-arcane-light text-xs font-bold py-1.5 rounded flex items-center justify-center gap-2 border border-arcane/50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        title="Broadcast to Combat Log"
                    >
                        <Send size={12} /> Send to Log
                    </button>
                </div>
            )}
        </div>
    );
}

import React, { useState, useCallback, useEffect } from 'react';
import { BattleMap } from './BattleMap';
import { ShapeControls, DrawingMode } from './ShapeControls';
import { BattleMapState, GridPosition, MapToken, MapShape, FreehandPath } from '../../types/battleMap';
import { Combatant } from '../../types/combat';
import { syncCombatantsToTokens } from '../../engine/battleMapEngine';
import { Settings, Maximize2, Move, ArrowRight, X, Users, Plus, Layout, RotateCcw, Pencil } from 'lucide-react';
import mapTemplates from '../../data/maps/templates.json';

interface MapSetupProps {
    initialState?: Partial<BattleMapState>;
    combatants: Combatant[];
    onComplete: (state: BattleMapState) => void;
    onCancel: () => void;
}

type RightPanelTab = 'tools' | 'inspector';

export const MapSetup: React.FC<MapSetupProps> = ({
    initialState,
    combatants,
    onComplete,
    onCancel
}) => {
    // Initialize tokens from combatants if not already present
    const initialTokens = initialState?.tokens && initialState.tokens.length > 0
        ? initialState.tokens
        : syncCombatantsToTokens(combatants);

    const [mapState, setMapState] = useState<BattleMapState>({
        gridWidth: initialState?.gridWidth || 20,
        gridHeight: initialState?.gridHeight || 20,
        cellSizePx: initialState?.cellSizePx || 40,
        gridColor: initialState?.gridColor || 'rgba(75, 85, 99, 0.4)',
        backgroundColor: initialState?.backgroundColor || '#111827',
        tokens: initialTokens,
        shapes: initialState?.shapes || [],
        freehandPaths: initialState?.freehandPaths || [],
        backgroundImageUrl: initialState?.backgroundImageUrl,
        backgroundOffset: initialState?.backgroundOffset,
        backgroundScaleX: initialState?.backgroundScaleX,
        backgroundScaleY: initialState?.backgroundScaleY,
        fogOfWar: initialState?.fogOfWar || [],
        fogOfWarFreehand: initialState?.fogOfWarFreehand || []
    });

    const [drawingMode, setDrawingMode] = useState<DrawingMode>('select');
    const [zoom, setZoom] = useState(1);
    const [hoverPos, setHoverPos] = useState<GridPosition | null>(null);
    const [history, setHistory] = useState<BattleMapState[]>([]);
    const [rightTab, setRightTab] = useState<RightPanelTab>('tools');
    const [rightPanelCollapsed, setRightPanelCollapsed] = useState(false);

    const toggleMode = (mode: DrawingMode) => {
        setDrawingMode(prev => prev === mode ? 'select' : mode);
    };

    const pushToHistory = () => {
        setHistory(prev => [...prev.slice(-19), mapState]);
    };

    const handleApplyTemplate = (template: any) => {
        pushToHistory();
        setMapState(prev => ({
            ...prev,
            gridWidth: template.gridWidth,
            gridHeight: template.gridHeight,
            backgroundColor: template.backgroundColor,
            gridColor: template.gridColor,
            shapes: template.shapes.map((s: any) => ({ ...s, id: crypto.randomUUID() })),
            freehandPaths: [],
            fogOfWar: [],
            fogOfWarFreehand: []
        }));
    };

    const handleUndo = useCallback(() => {
        if (history.length === 0) return;
        const previous = history[history.length - 1];
        setMapState(previous);
        setHistory(prev => prev.slice(0, -1));
    }, [history]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

            const key = e.key.toLowerCase();
            if (key === '1') setDrawingMode('select');
            if (key === '2') setDrawingMode('rectangle');
            if (key === '3') setDrawingMode('circle');
            if (key === '4') setDrawingMode('line');
            if (key === '5') setDrawingMode('freehand');
            if (key === 'c') setDrawingMode('calibrate');
            if (key === '6' || key === 'e') setDrawingMode('eraser');
            if (key === 'g') setDrawingMode('fow-hide');
            if (key === 'f') setDrawingMode('fow-reveal');
            if (key === 'escape') setDrawingMode('select');

            if (key === 'z' && (e.ctrlKey || e.metaKey)) {
                e.preventDefault();
                handleUndo();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [handleUndo]);

    const handleBackgroundUpdate = (updates: { offsetDelta?: { dx: number, dy: number }, offset?: { x: number, y: number }, scaleX?: number, scaleY?: number }) => {
        setMapState(prev => {
            let newOffset = prev.backgroundOffset || { x: 0, y: 0 };
            if (updates.offsetDelta) {
                newOffset = { x: newOffset.x + updates.offsetDelta.dx, y: newOffset.y + updates.offsetDelta.dy };
            } else if (updates.offset) {
                newOffset = updates.offset;
            }

            return {
                ...prev,
                backgroundOffset: newOffset,
                backgroundScaleX: updates.scaleX !== undefined ? updates.scaleX : prev.backgroundScaleX,
                backgroundScaleY: updates.scaleY !== undefined ? updates.scaleY : prev.backgroundScaleY
            };
        });
    };



    const handleCellSizeChange = (val: number) => {
        setMapState((prev: BattleMapState) => ({ ...prev, cellSizePx: Math.max(16, Math.min(128, val)) }));
    };

    const handleTokenMove = (tokenId: string, position: GridPosition) => {
        setMapState((prev: BattleMapState) => ({
            ...prev,
            tokens: prev.tokens.map((t: MapToken) => t.id === tokenId ? { ...t, position } : t)
        }));
    };

    const handleResizeGrid = (side: 'top' | 'bottom' | 'left' | 'right', delta: number) => {
        setMapState((prev: BattleMapState) => {
            const isHorizontal = side === 'left' || side === 'right';
            const newWidth = isHorizontal ? Math.max(5, prev.gridWidth + delta) : prev.gridWidth;
            const newHeight = !isHorizontal ? Math.max(5, prev.gridHeight + delta) : prev.gridHeight;

            const appliedDelta = isHorizontal ? (newWidth - prev.gridWidth) : (newHeight - prev.gridHeight);
            const colShift = side === 'left' ? appliedDelta : 0;
            const rowShift = side === 'top' ? appliedDelta : 0;

            const shiftGridPos = (p: GridPosition) => ({
                col: p.col + colShift,
                row: p.row + rowShift
            });

            const updatedTokens = prev.tokens.map(token => ({
                ...token,
                position: {
                    col: Math.max(0, Math.min(token.position.col + colShift, newWidth - (token.size || 1))),
                    row: Math.max(0, Math.min(token.position.row + rowShift, newHeight - (token.size || 1)))
                }
            }));

            const updatedShapes = prev.shapes.map(s => ({
                ...s,
                points: s.points.map(shiftGridPos)
            }));

            const pxColShift = colShift * prev.cellSizePx;
            const pxRowShift = rowShift * prev.cellSizePx;
            const updatedPaths = prev.freehandPaths.map(path => ({
                ...path,
                points: path.points.map(p => ({ x: p.x + pxColShift, y: p.y + pxRowShift }))
            }));

            const updatedFoW = prev.fogOfWar.map(s => ({
                ...s,
                points: s.points.map(shiftGridPos)
            }));
            const updatedFoWFree = prev.fogOfWarFreehand.map(path => ({
                ...path,
                points: path.points.map(p => ({ x: p.x + pxColShift, y: p.y + pxRowShift }))
            }));

            // Sync background image so it doesn't move visually when Origin shifts
            let newBackgroundOffset = prev.backgroundOffset;
            if (newBackgroundOffset) {
                newBackgroundOffset = {
                    x: newBackgroundOffset.x + pxColShift,
                    y: newBackgroundOffset.y + pxRowShift
                };
            }

            return {
                ...prev,
                gridWidth: newWidth,
                gridHeight: newHeight,
                tokens: updatedTokens,
                shapes: updatedShapes,
                freehandPaths: updatedPaths,
                fogOfWar: updatedFoW,
                fogOfWarFreehand: updatedFoWFree,
                backgroundOffset: newBackgroundOffset
            };
        });
    };

    const handleShapeAdd = (shape: MapShape) => {
        pushToHistory();
        setMapState((prev: BattleMapState) => ({
            ...prev,
            shapes: [...prev.shapes, shape]
        }));
    };

    const handleFreehandAdd = (path: FreehandPath) => {
        pushToHistory();
        setMapState((prev: BattleMapState) => ({
            ...prev,
            freehandPaths: [...prev.freehandPaths, path]
        }));
    };

    const handleClearDrawings = () => {
        pushToHistory();
        setMapState((prev: BattleMapState) => ({
            ...prev,
            shapes: [],
            freehandPaths: [],
            fogOfWar: [],
            fogOfWarFreehand: []
        }));
    };

    const handleFogOfWarAdd = (shape: MapShape) => {
        pushToHistory();
        setMapState((prev: BattleMapState) => ({
            ...prev,
            fogOfWar: [...prev.fogOfWar, shape]
        }));
    };

    const handleFogOfWarFreehandAdd = (path: FreehandPath) => {
        pushToHistory();
        setMapState((prev: BattleMapState) => ({
            ...prev,
            fogOfWarFreehand: [...prev.fogOfWarFreehand, path]
        }));
    };

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const base64 = event.target?.result as string;
            setMapState(prev => ({ ...prev, backgroundImageUrl: base64 }));
        };
        reader.readAsDataURL(file);
    };

    const handleRemoveBackground = () => {
        pushToHistory();
        setMapState(prev => ({ ...prev, backgroundImageUrl: undefined, backgroundOffset: undefined, backgroundScaleX: undefined, backgroundScaleY: undefined }));
    };

    const handleUndoImageReset = () => {
        if (history.length > 0) handleUndo();
    };

    return (
        <div className="flex flex-col h-full w-full overflow-hidden bg-stone-950 font-cinzel text-stone-300">
            {/* ═══ HEADER: ACTION BAR ═══ */}
            <header className="h-16 border-b border-white/5 bg-stone-900/40 backdrop-blur-xl flex items-center justify-between px-6 z-30 shrink-0">
                <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-blue-500/10 border border-blue-500/30 rounded-xl flex items-center justify-center text-blue-400 shadow-[0_0_20px_rgba(59,130,246,0.2)]">
                        <Maximize2 size={20} />
                    </div>
                    <div>
                        <h2 className="text-lg font-bold text-white tracking-tight uppercase leading-tight">Map Setup</h2>
                        <p className="text-[9px] text-stone-500 font-black uppercase tracking-widest">Cartography Studio</p>
                    </div>
                </div>

                <div className="flex gap-3">
                    <button
                        onClick={onCancel}
                        className="px-5 py-2.5 bg-stone-900/40 backdrop-blur-md hover:bg-red-500/10 hover:text-red-400 text-stone-300 rounded-xl flex items-center gap-2 transition-all border border-white/5 hover:border-red-500/30 font-bold uppercase tracking-widest text-xs"
                    >
                        <X size={16} />
                        Discard
                    </button>
                    <button
                        onClick={() => onComplete(mapState)}
                        className="px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-xl flex items-center gap-3 transition-all active:scale-95 shadow-[0_10px_30px_rgba(37,99,235,0.3)] uppercase tracking-widest text-xs"
                    >
                        Start Battle
                        <ArrowRight size={16} />
                    </button>
                </div>
            </header>

            <div className="flex flex-row flex-grow overflow-hidden relative">
                {/* ═══ CENTER: THE CANVAS (no left sidebar!) ═══ */}
                <main className="flex-grow relative bg-stone-950">
                    <BattleMap
                        mapState={mapState}
                        tokens={mapState.tokens}
                        drawingMode={drawingMode}
                        onDrawingModeChange={setDrawingMode}
                        onTokenMove={handleTokenMove}
                        onShapeAdd={handleShapeAdd}
                        onFreehandPathAdd={handleFreehandAdd}
                        onFogOfWarAdd={handleFogOfWarAdd}
                        onFogOfWarFreehandAdd={handleFogOfWarFreehandAdd}
                        onResizeGrid={handleResizeGrid}
                        onZoomChange={setZoom}
                        onHoverGridChange={setHoverPos}
                        onBackgroundUpdate={handleBackgroundUpdate}
                        className="w-full h-full border-0 rounded-none"
                    />

                    {/* DOCKED STATUS (Center-Bottom) */}
                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-30 pointer-events-none">
                        <div className="pointer-events-auto bg-stone-900/80 backdrop-blur-xl border border-white/10 py-2.5 px-6 rounded-2xl shadow-2xl flex items-center gap-6">
                            <div className="flex items-center gap-2">
                                <Users size={14} className="text-blue-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-white/90">{mapState.tokens.length} Tokens</span>
                            </div>
                            <div className="w-px h-4 bg-white/10" />
                            <div className="flex items-center gap-2 min-w-[120px]">
                                <Move size={14} className="text-blue-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-white/90">
                                    {drawingMode === 'select' ? 'Neutral' : drawingMode.toUpperCase()}
                                    {hoverPos && <span className="ml-2 text-stone-500">[{String.fromCharCode(65 + hoverPos.col)}{hoverPos.row + 1}]</span>}
                                </span>
                            </div>
                            <div className="w-px h-4 bg-white/10" />
                            <div className="text-[10px] font-mono text-blue-400 font-black">
                                {Math.round(zoom * 100)}%
                            </div>
                        </div>
                    </div>
                </main>

                {/* ═══ RIGHT SIDEBAR: TABBED (Tools + Inspector) ═══ */}
                <aside className={`${rightPanelCollapsed ? 'w-0 overflow-hidden' : 'w-80'} border-l border-white/5 bg-stone-900/20 backdrop-blur-sm flex flex-col z-20 transition-all duration-300 relative shrink-0`}>
                    <button
                        onClick={() => setRightPanelCollapsed(!rightPanelCollapsed)}
                        className="absolute -left-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-stone-900 border border-white/10 rounded-full flex items-center justify-center text-stone-500 hover:text-white z-30 shadow-xl"
                    >
                        {rightPanelCollapsed ? <Plus size={10} /> : <X size={10} />}
                    </button>

                    {!rightPanelCollapsed && (
                        <>
                            {/* ═══ TAB HEADER ═══ */}
                            <div className="flex border-b border-white/5 shrink-0">
                                <button
                                    onClick={() => setRightTab('tools')}
                                    className={`flex-1 py-3 px-4 flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-[0.15em] transition-all ${rightTab === 'tools'
                                        ? 'text-blue-400 border-b-2 border-blue-500 bg-blue-500/5'
                                        : 'text-stone-500 hover:text-stone-300 hover:bg-white/5'
                                        }`}
                                >
                                    <Pencil size={12} />
                                    Tools
                                </button>
                                <button
                                    onClick={() => setRightTab('inspector')}
                                    className={`flex-1 py-3 px-4 flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-[0.15em] transition-all ${rightTab === 'inspector'
                                        ? 'text-blue-400 border-b-2 border-blue-500 bg-blue-500/5'
                                        : 'text-stone-500 hover:text-stone-300 hover:bg-white/5'
                                        }`}
                                >
                                    <Settings size={12} />
                                    Inspector
                                </button>
                            </div>

                            {/* ═══ TAB CONTENT ═══ */}
                            <div className="flex-grow overflow-y-auto custom-scrollbar">

                                {/* TOOLS TAB */}
                                {rightTab === 'tools' && (
                                    <div className="p-4">
                                        <ShapeControls
                                            currentMode={drawingMode}
                                            onModeChange={toggleMode}
                                            onClearAll={handleClearDrawings}
                                            onUndo={handleUndo}
                                            canUndo={history.length > 0}
                                            className="w-full"
                                        />
                                    </div>
                                )}

                                {/* INSPECTOR TAB */}
                                {rightTab === 'inspector' && (
                                    <div className="p-6 space-y-10">
                                        <section className="space-y-4">
                                            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/80">Grid Geometry</h3>
                                            <div className="bg-stone-950/40 p-4 rounded-xl border border-white/5 space-y-4">
                                                <div className="flex justify-between items-center px-4">
                                                    <div className="text-center">
                                                        <div className="text-[10px] text-stone-500 font-bold uppercase">Columns</div>
                                                        <div className="text-sm font-mono text-blue-400">{mapState.gridWidth}</div>
                                                    </div>
                                                    <div className="text-center">
                                                        <div className="text-[10px] text-stone-500 font-bold uppercase">Rows</div>
                                                        <div className="text-sm font-mono text-blue-400">{mapState.gridHeight}</div>
                                                    </div>
                                                </div>

                                                <div className="flex flex-col items-center gap-1 mt-2">
                                                    {/* TOP */}
                                                    <div className="flex gap-1 border-b border-white/10 pb-1 mb-1">
                                                        <button onClick={() => handleResizeGrid('top', 1)} className="p-1 px-3 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">+1</button>
                                                        <div className="text-[9px] uppercase font-black text-stone-600 self-center px-2">Top</div>
                                                        <button onClick={() => handleResizeGrid('top', -1)} className="p-1 px-3 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">-1</button>
                                                    </div>
                                                    <div className="flex justify-between w-full">
                                                        {/* LEFT */}
                                                        <div className="flex flex-col gap-1 border-r border-white/10 pr-2 mr-1">
                                                            <div className="text-[9px] uppercase font-black text-stone-600 text-center">Left</div>
                                                            <div className="flex gap-1 justify-center">
                                                                <button onClick={() => handleResizeGrid('left', 1)} className="p-1 px-2 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">+</button>
                                                                <button onClick={() => handleResizeGrid('left', -1)} className="p-1 px-2 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">-</button>
                                                            </div>
                                                        </div>
                                                        {/* RIGHT */}
                                                        <div className="flex flex-col gap-1 border-l border-white/10 pl-2 ml-1">
                                                            <div className="text-[9px] uppercase font-black text-stone-600 text-center">Right</div>
                                                            <div className="flex gap-1 justify-center">
                                                                <button onClick={() => handleResizeGrid('right', -1)} className="p-1 px-2 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">-</button>
                                                                <button onClick={() => handleResizeGrid('right', 1)} className="p-1 px-2 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">+</button>
                                                            </div>
                                                        </div>
                                                    </div>
                                                    {/* BOTTOM */}
                                                    <div className="flex gap-1 border-t border-white/10 pt-1 mt-1">
                                                        <button onClick={() => handleResizeGrid('bottom', 1)} className="p-1 px-3 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">+1</button>
                                                        <div className="text-[9px] uppercase font-black text-stone-600 self-center px-2">Bottom</div>
                                                        <button onClick={() => handleResizeGrid('bottom', -1)} className="p-1 px-3 bg-stone-900 hover:bg-stone-800 text-stone-400 rounded-md text-xs font-mono">-1</button>
