                                        </section>

                                        <section className="space-y-4">
                                            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500/80">Map Layouts</h3>
                                            <div className="grid grid-cols-1 gap-2">
                                                {mapTemplates.map(template => (
                                                    <button
                                                        key={template.id}
                                                        onClick={() => handleApplyTemplate(template)}
                                                        className="flex flex-col items-start p-3 rounded-xl bg-stone-950/40 border border-white/5 hover:border-blue-500/50 hover:bg-blue-500/5 transition-all text-left group"
                                                    >
                                                        <div className="flex items-center gap-2">
                                                            <Layout size={10} className="text-blue-500 opacity-50 group-hover:opacity-100 transition-opacity" />
                                                            <span className="text-[11px] font-bold text-white group-hover:text-blue-400 transition-colors uppercase tracking-wider">{template.name}</span>
                                                        </div>
                                                        <span className="text-[9px] text-stone-500 leading-tight mt-1">{template.description}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        </section>
                                    </div>
                                )}
                            </div>

                            <div className="p-4 border-t border-white/5 bg-stone-950/20 shrink-0">
                                <p className="text-[9px] text-stone-600 leading-relaxed italic">
                                    Right-click tokens for properties. Scroll to zoom. MMB to pan.
                                </p>
                            </div>
                        </>
                    )}
                </aside>
            </div>
        </div>
    );
};

import React from 'react';
import { Combatant } from '../../types/combat';
import { DraggablePanel } from '../common/DraggablePanel';
import { X } from 'lucide-react';
import { flattenEntries } from '../../engine/fiveEToolsParser';

// Simple markdown renderer for the stat block
function renderMarkdown(text: string): React.ReactNode[] {
    if (!text) return [];

    // Split on double newlines for paragraphs
    return text.split('\n\n').map((paragraph, pIdx) => {
        // Handle bolding
        const parts = paragraph.split(/(\*\*.*?\*\*)/g);

        return (
            <p key={pIdx} className="mb-2 text-sm leading-snug">
                {parts.map((part, i) => {
                    if (part.startsWith('**') && part.endsWith('**')) {
                        return <strong key={i} className="font-bold text-stone-900">{part.slice(2, -2)}</strong>;
                    }
                    return <span key={i}>{part}</span>;
                })}
            </p>
        );
    });
}

const getModifier = (score: number) => {
    const mod = Math.floor((score - 10) / 2);
    return mod >= 0 ? `+${mod}` : `${mod}`;
};

interface MonsterStatBlockProps {
    combatant: Combatant;
    onClose: () => void;
}

export const MonsterStatBlock: React.FC<MonsterStatBlockProps> = ({ combatant, onClose }) => {
    const m = combatant.monsterData;

    // Fallback if no monster data
    if (!m) {
        return null;
    }

    const name = m.name || combatant.name;
    const typeStr = [
        m.size,
        m.type?.type || m.type || 'unknown',
        m.alignment ? `(${m.alignment.join(', ')})` : ''
    ].filter(Boolean).join(' ');

    const acStr = combatant.ac;
    const hpStr = `${combatant.maxHp} ${m.hp?.formula ? `(${m.hp.formula})` : ''}`;
    const speedStr = combatant.speed;

    const renderActionSection = (title: string, actions: any[]) => {
        if (!actions || actions.length === 0) return null;
        return (
            <div className="mt-4">
                <h3 className="text-xl font-bold font-serif text-[#7a200d] border-b border-[#7a200d] mb-2 uppercase">{title}</h3>
                {actions.map((action, idx) => (
                    <div key={idx} className="mb-2">
                        <p className="text-sm leading-snug text-stone-900">
                            <strong className="font-bold text-stone-900 italic">{action.name}. </strong>
                            {action.entries ? <span className="inline-block">{renderMarkdown(flattenEntries(action.entries))}</span> : null}
                        </p>
                    </div>
                ))}
            </div>
        );
    };

    return (
        <DraggablePanel
            className="fixed top-24 right-24 w-[400px]"
            zIndex={150}
        >
            <div className="bg-[#fdf1dc] p-4 text-stone-900 shadow-inner overflow-y-auto max-h-[70vh] custom-scrollbar border-4 border-[#e69a28] relative">
                {/* Close Button manually added since DraggablePanel doesn't have it natively */}
                <button
                    onClick={onClose}
                    className="absolute top-2 right-2 p-1 text-[#7a200d] hover:bg-[#7a200d]/10 rounded transition-colors"
                >
                    <X size={20} />
                </button>
                {/* Header Phase */}
                <div className="border-b-4 border-[#7a200d] pb-2 mb-2">
                    <h1 className="text-3xl font-serif font-bold text-[#7a200d] uppercase">{name}</h1>
                    <p className="text-sm italic">{typeStr}</p>
                </div>

                {/* Core Stats */}
                <div className="text-sm leading-snug mb-2">
                    <p><strong className="text-[#7a200d]">Armor Class</strong> {acStr}</p>
                    <p><strong className="text-[#7a200d]">Hit Points</strong> {hpStr}</p>
                    <p><strong className="text-[#7a200d]">Speed</strong> {speedStr}</p>
                </div>

                <div className="border-t-2 border-b-2 border-[#7a200d] py-2 mb-2 flex justify-between text-center">
                    {['STR', 'DEX', 'CON', 'INT', 'WIS', 'CHA'].map(attr => {
                        const score = combatant.abilityScores ? combatant.abilityScores[attr.toLowerCase() as keyof typeof combatant.abilityScores] : 10;
                        return (
                            <div key={attr} className="flex flex-col">
                                <span className="font-bold text-[#7a200d] text-sm">{attr}</span>
                                <span className="text-sm">{score} ({getModifier(score)})</span>
                            </div>
                        );
                    })}
                </div>

                {/* Details */}
                <div className="text-sm leading-snug border-b-4 border-[#7a200d] pb-2 mb-2">
                    {m.save && (
                        <p><strong className="text-[#7a200d]">Saving Throws</strong> {
                            Object.entries(m.save).map(([k, v]) => `${k.toUpperCase()} ${v}`).join(', ')
                        }</p>
                    )}
                    {m.skill && (
                        <p><strong className="text-[#7a200d]">Skills</strong> {
                            Object.entries(m.skill).map(([k, v]) => `${k.charAt(0).toUpperCase() + k.slice(1)} ${v}`).join(', ')
                        }</p>
                    )}
                    {combatant.vulnerabilities?.length ? <p><strong className="text-[#7a200d]">Damage Vulnerabilities</strong> {combatant.vulnerabilities.join(', ')}</p> : null}
                    {combatant.resistances?.length ? <p><strong className="text-[#7a200d]">Damage Resistances</strong> {combatant.resistances.join(', ')}</p> : null}
                    {combatant.immunities?.length ? <p><strong className="text-[#7a200d]">Damage Immunities</strong> {combatant.immunities.join(', ')}</p> : null}
                    {combatant.conditionImmunities?.length ? <p><strong className="text-[#7a200d]">Condition Immunities</strong> {combatant.conditionImmunities.join(', ')}</p> : null}
                    <p><strong className="text-[#7a200d]">Senses</strong> {m.senses ? m.senses.join(', ') : combatant.senses}</p>
                    <p><strong className="text-[#7a200d]">Languages</strong> {m.languages ? m.languages.join(', ') : '—'}</p>
                    <p><strong className="text-[#7a200d]">Challenge</strong> {combatant.cr || m.cr || '?'}</p>
                </div>

                {/* Traits */}
                {m.trait?.map((trait: any, idx: number) => (
                    <div key={`trait-${idx}`} className="mb-2">
                        <p className="text-sm leading-snug text-stone-900">
                            <strong className="font-bold text-stone-900 italic">{trait.name}. </strong>
                            {trait.entries ? <span className="inline-block">{renderMarkdown(flattenEntries(trait.entries))}</span> : null}
                        </p>
                    </div>
                ))}

                {/* Actions */}
                {renderActionSection('Actions', m.action)}

                {/* Bonus Actions */}
                {renderActionSection('Bonus Actions', m.bonus)}

                {/* Reactions */}
                {renderActionSection('Reactions', m.reaction)}

                {/* Legendary Actions */}
                {m.legendary && m.legendary.length > 0 && (
                    <div className="mt-4">
                        <h3 className="text-xl font-bold font-serif text-[#7a200d] border-b border-[#7a200d] mb-2 uppercase">Legendary Actions</h3>
                        <p className="text-sm leading-snug mb-2">The monster can take 3 legendary actions, choosing from the options below. Only one legendary action option can be used at a time and only at the end of another creature's turn. The monster regains spent legendary actions at the start of its turn.</p>
                        {m.legendary.map((action: any, idx: number) => (
                            <div key={`leg-${idx}`} className="mb-2">
                                <p className="text-sm leading-snug text-stone-900">
                                    <strong className="font-bold text-stone-900 italic">{action.name}. </strong>
                                    {action.entries ? <span className="inline-block">{renderMarkdown(flattenEntries(action.entries))}</span> : null}
                                </p>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </DraggablePanel>
    );
};

import { useState, useEffect, useRef } from 'react';
import { MapToken } from '../../types/battleMap';
import conditionsData from '../../data/dnd5e/conditions.json';

interface TokenProps {
    token: MapToken;
    combatant?: import('../../types/combat').Combatant;
    cellSize: number;
    isActive?: boolean;
    isAffected?: boolean;
    onClick?: () => void;
    onMouseDown?: (e: React.MouseEvent) => void;
    movementRemaining?: number;
    movementMax?: number;
    className?: string;
    style?: React.CSSProperties;
    isDragging?: boolean;
    onMouseEnter?: (e: React.MouseEvent) => void;
    onMouseLeave?: (e: React.MouseEvent) => void;
    onConditionHover?: (name: string, e: React.MouseEvent) => void;
    onConditionLeave?: () => void;
}

export const Token: React.FC<TokenProps> = ({
    token,
    combatant,
    cellSize,
    isActive = false,
    isAffected = false,
    onClick,
    onMouseDown,
    movementRemaining,
    movementMax,
    className = "",
    style = {},
    isDragging = false,
    onMouseEnter,
    onMouseLeave,
    onConditionHover,
    onConditionLeave
}) => {
    interface Particle {
        id: number;
        x: number;
        y: number;
        vx: number;
        vy: number;
        life: number;
        color: string;
        size: number;
    }

    const [animState, setAnimState] = useState<'none' | 'damage' | 'heal'>('none');
    const [particles, setParticles] = useState<Particle[]>([]);
    const prevHpRef = useRef<number | undefined>(combatant?.currentHp);

    useEffect(() => {
        if (combatant?.currentHp === undefined) return;
        const prevHp = prevHpRef.current;
        const currHp = combatant.currentHp;

        if (prevHp !== undefined && currHp !== prevHp) {
            const isDamage = currHp < prevHp;
            setAnimState(isDamage ? 'damage' : 'heal');

            // Spawn particles
            const count = isDamage ? 8 : 6;
            const newParticles: Particle[] = [];
            for (let i = 0; i < count; i++) {
                newParticles.push({
                    id: Math.random(),
                    x: 50, // center %
                    y: 50,
                    vx: (Math.random() - 0.5) * 8,
                    vy: (Math.random() - 0.5) * 8,
                    life: 1.0,
                    color: isDamage ? '#991b1b' : '#4ade80',
                    size: Math.random() * 4 + 2
                });
            }
            setParticles(prev => [...prev, ...newParticles]);

            const timer = setTimeout(() => {
                setAnimState('none');
            }, 600);

            prevHpRef.current = currHp;
            return () => clearTimeout(timer);
        }

        prevHpRef.current = currHp;
    }, [combatant?.currentHp]);

    // Particle animation loop
    useEffect(() => {
        if (particles.length === 0) return;

        const interval = setInterval(() => {
            setParticles(prev => prev
                .map(p => ({
                    ...p,
                    x: p.x + p.vx,
                    y: p.y + p.vy,
                    life: p.life - 0.05
                }))
                .filter(p => p.life > 0)
            );
        }, 30);

        return () => clearInterval(interval);
    }, [particles.length]);

    // Calculate pixel position based on grid coordinates
    const left = token.position.col * cellSize;
    const top = token.position.row * cellSize;
    const size = token.size * cellSize;

    // Faction colors
    const colors: Record<MapToken['faction'], string> = {
        player: 'bg-blue-600 border-blue-400 text-white shadow-blue-500/20',
        enemy: 'bg-red-700 border-red-500 text-white shadow-red-500/20',
        neutral: 'bg-stone-600 border-stone-400 text-white shadow-stone-500/20',
        ally: 'bg-green-600 border-green-400 text-white shadow-green-500/20'
    };

    const factionStyle = colors[token.faction] || colors.neutral;

    let animClass = '';
    if (animState === 'damage') {
        animClass = 'animate-[shake_0.5s_ease-in-out] ring-4 ring-blood shadow-[0_0_30px_rgba(220,38,38,1)] z-50';
    } else if (animState === 'heal') {
        animClass = 'animate-[heal-glow_0.6s_ease-out] ring-4 ring-green-400 shadow-[0_0_30px_rgba(74,222,128,1)] z-50';
    }

    return (
        <div
            className={`absolute flex items-center justify-center rounded-full border-2 cursor-pointer select-none shadow-xl 
                ${factionStyle} 
                ${isActive && animState === 'none' ? 'ring-4 ring-gold scale-105 z-10 shadow-[0_0_20px_rgba(255,215,0,0.6)] animate-[token-pulse_2s_infinite]' : animState === 'none' ? 'hover:scale-110 active:scale-95 z-0' : ''} 
                ${isAffected && animState === 'none' ? 'animate-pulse ring-4 ring-red-500 shadow-[0_0_25px_rgba(239,68,68,0.9)] z-20' : ''} 
                ${isDragging ? 'transition-none opacity-90 scale-110 z-[100]' : 'transition-[left,top,transform] duration-500 ease-out'}
                ${animClass}
                ${className}`}
            style={{
                left: `${left}px`,
                top: `${top}px`,
                width: `${size}px`,
                height: `${size}px`,
                transform: isDragging
                    ? `translate3d(0, 0, 0)`
                    : (token.elevation > 0 ? `translateY(-${Math.min(20, token.elevation / 2)}px)` : undefined),
                boxShadow: isDragging
                    ? `0 20px 40px rgba(0,0,0,0.4)`
                    : (token.elevation > 0 ? `0 ${Math.min(30, token.elevation)}px ${Math.min(40, token.elevation * 1.5)}px rgba(0,0,0,0.6)` : undefined),
                ...style
            }}
            onClick={onClick}
            onMouseDown={onMouseDown}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
            title={`${token.name} (${token.faction})`}
        >
            {/* Active/Targeted Indicator Rings (Floating outside) */}
            {isActive && animState === 'none' && (
                <div className="absolute inset-[-4px] rounded-full border-2 border-gold/50 animate-[token-pulse_2s_cubic-bezier(0.4,0,0.6,1)_infinite] pointer-events-none" />
            )}
            {isAffected && animState === 'none' && (
                <div className="absolute inset-[-6px] rounded-full border-2 border-blood/60 animate-ping pointer-events-none" />
            )}

            {/* Particles */}
            {particles.map(p => (
                <div
                    key={p.id}
                    className="absolute pointer-events-none rounded-full"
                    style={{
                        left: `${p.x}%`,
                        top: `${p.y}%`,
                        width: `${p.size}px`,
                        height: `${p.size}px`,
                        backgroundColor: p.color,
                        opacity: p.life,
                        transform: 'translate(-50%, -50%)',
                        zIndex: 100
                    }}
                />
            ))}

            {/* Movement Progress Ring */}
            {movementMax !== undefined && movementRemaining !== undefined && movementMax > 0 && (
                <svg
                    className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 -rotate-90 pointer-events-none overflow-visible"
                    width="125%"
                    height="125%"
                    viewBox="0 0 100 100"
                >
                    <circle
                        cx="50"
                        cy="50"
                        r="46"
                        fill="none"
                        stroke="rgba(0,0,0,0.3)"
                        strokeWidth="4"
                    />
                    <circle
                        cx="50"
                        cy="50"
                        r="46"
                        fill="none"
                        stroke={movementRemaining > 0 ? "rgba(34, 197, 94, 0.8)" : "rgba(239, 68, 68, 0.8)"}
                        strokeWidth="4"
                        strokeDasharray={Math.PI * 92}
                        strokeDashoffset={Math.PI * 92 * (1 - movementRemaining / movementMax)}
                        className="transition-all duration-500 ease-out"
                        strokeLinecap="round"
                    />
                </svg>
            )}

            {combatant?.portraitUrl ? (
                <div className="absolute inset-[2px] rounded-full overflow-hidden bg-stone-900 pointer-events-none origin-center transform scale-[0.98]">
                    <img
                        src={combatant.portraitUrl}
                        alt={token.name}
                        className="w-full h-full object-cover scale-[1.15] -translate-y-[5%]"
                        onError={(e) => {
                            e.currentTarget.style.display = 'none';
                            e.currentTarget.nextElementSibling?.classList.remove('hidden');
                        }}
                    />
                    <span
                        className="hidden font-bold font-cinzel leading-none pointer-events-none absolute inset-0 flex items-center justify-center bg-stone-900"
                        style={{ fontSize: `${size * 0.4}px` }}
                    >
                        {token.label || token.name.substring(0, 2).toUpperCase()}
                    </span>
                </div>
            ) : (
                <span
                    className="font-bold font-cinzel leading-none pointer-events-none"
                    style={{ fontSize: `${size * 0.4}px` }}
                >
                    {token.label || token.name.substring(0, 2).toUpperCase()}
                </span>
            )}

            {/* Condition Badge Tray (Top Right) */}
            {combatant && combatant.conditions && combatant.conditions.length > 0 && (
                <div className="absolute -top-1 -right-1 flex gap-0.5 pointer-events-none">
                    {combatant.conditions.slice(0, 3).map((cond, i) => {
                        const name = cond.name.toLowerCase();
                        let bgColor = '#ef4444'; // default condition red
                        let label = cond.name.charAt(0);
                        let isBuff = false;

                        // Identify if it's a buff from data or name matching
                        const conditionData = (conditionsData as any[]).find(c => c.name.toLowerCase() === name);
                        if (conditionData?.type === 'buff') {
                            isBuff = true;
                            bgColor = '#22d3ee'; // cyan for buffs
                        }

                        // Specific Aesthetic overrides
                        if (name.includes('dead')) { bgColor = '#000000'; label = '💀'; }
                        else if (name.includes('stun')) { bgColor = '#eab308'; label = '⚡'; }
                        else if (name.includes('poison')) { bgColor = '#22c55e'; label = '🧪'; }
                        else if (name.includes('blind')) { bgColor = '#6b7280'; label = '👁️'; }
                        else if (name.includes('charm')) { bgColor = '#ec4899'; label = '❤️'; }
                        else if (name.includes('fright')) { bgColor = '#a855f7'; label = '👻'; }
                        else if (name.includes('grapp')) { bgColor = '#f97316'; label = '⛓️'; }
                        else if (name.includes('incap')) { bgColor = '#64748b'; label = '✖️'; }
                        else if (name.includes('invis')) { bgColor = '#3b82f6'; label = '🌫️'; }
                        else if (name.includes('paralyz')) { bgColor = '#facc15'; label = '🔒'; }
                        else if (name.includes('petrif')) { bgColor = '#78716c'; label = '🗿'; }
                        else if (name.includes('prone')) { bgColor = '#7c2d12'; label = '⬇️'; }
                        else if (name.includes('restrain')) { bgColor = '#ea580c'; label = '🕸️'; }
                        else if (name.includes('unconsc')) { bgColor = '#1e3a8a'; label = '💤'; }
                        else if (name.includes('bless')) { bgColor = '#fbbf24'; label = '✨'; }
                        else if (name.includes('bardic')) { bgColor = '#ec4899'; label = '🎵'; }
                        else if (name.includes('faith')) { bgColor = '#3b82f6'; label = '🛡️'; }
                        else if (name.includes('haste')) { bgColor = '#22d3ee'; label = '🏃'; }
                        else if (name.includes('heroism')) { bgColor = '#ef4444'; label = '🛡️'; }
                        else if (name.includes('enlarge')) { bgColor = '#f97316'; label = '↗️'; }
                        else if (name.includes('guidan')) { bgColor = '#22c55e'; label = '🧭'; }
                        else if (name.includes('resist')) { bgColor = '#10b981'; label = '🛡️'; }

                        return (
                            <div
                                key={cond.id}
                                className={`w-4 h-4 rounded-full border border-stone-900 shadow-sm flex items-center justify-center overflow-hidden transition-all duration-300
                                    ${isBuff ? 'ring-2 ring-cyan-400/30' : ''}
                                `}
                                style={{
                                    backgroundColor: bgColor,
                                    zIndex: 10 - i,
                                    transform: `translateX(${i * -6}px)`,
                                    boxShadow: isBuff ? '0 0 8px rgba(34, 211, 238, 0.4)' : undefined
                                }}
                                title={cond.name}
                                onMouseEnter={(e) => {
                                    e.stopPropagation();
                                    onConditionHover?.(cond.name, e);
                                }}
                                onMouseLeave={(e) => {
                                    e.stopPropagation();
                                    onConditionLeave?.();
                                }}
                            >
                                <span className={`text-[8px] leading-none ${isBuff ? 'text-stone-950 font-black' : 'text-white'}`}>
                                    {label}
                                </span>
                            </div>
                        );
                    })}
                    {combatant.conditions.length > 3 && (
                        <div
                            className="w-3.5 h-3.5 rounded-full bg-stone-700 border border-stone-900 text-[6px] text-white flex items-center justify-center font-bold"
                            style={{ transform: `translateX(-18px)` }}
                        >
                            +{combatant.conditions.length - 3}
                        </div>
                    )}
                </div>
            )}

            {/* Health Bar */}
            {token.showHealthBar !== false && combatant && (
                <div
                    className="absolute -top-3 left-1/2 -translate-x-1/2 w-[120%] h-1.5 bg-stone-900 border border-stone-800 rounded-full overflow-hidden shadow-sm"
                    title={`${combatant.currentHp}/${combatant.maxHp} HP`}
                >
                    <div
                        className={`h-full transition-all duration-500 ${(combatant.currentHp / combatant.maxHp) > 0.5 ? 'bg-green-500' :
                            (combatant.currentHp / combatant.maxHp) > 0.2 ? 'bg-orange-500' : 'bg-red-500'
                            }`}
                        style={{ width: `${(combatant.currentHp / combatant.maxHp) * 100}%` }}
                    />
                </div>
            )}

            {/* Name Label */}
            {token.showNameLabel !== false && (
                <div className="absolute -bottom-5 left-1/2 -translate-x-1/2 whitespace-nowrap bg-stone-950/80 backdrop-blur-sm px-1.5 py-0.5 rounded text-[9px] font-bold text-parchment border border-stone-800 shadow-lg pointer-events-none">
                    {token.name}
                </div>
            )}

            {/* Elevation indicator if > 0 */}
            {token.elevation > 0 && (
                <div className="absolute -bottom-1 -right-2 bg-stone-900 border border-gold/50 text-gold text-[8px] font-bold px-1.5 py-0.5 rounded shadow-xl flex items-center gap-1 z-30">
                    <span className="opacity-70 text-[6px]">▲</span>
                    {token.elevation}ft
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { Shield, Skull, LogOut, Zap, Swords, HeartPulse, X, Sparkles, Brain, Eye, User, Dice5 } from 'lucide-react';
import { MapToken } from '../../types/battleMap';
import { Combatant, CombatAction } from '../../types/combat';
import { getPlayerCombatActions, getMonsterCombatActions } from '../../engine/combatActions';
import { useCharacterStore } from '../../store/characterStore';
import { useCombatStore } from '../../store/combatStore';
import conditionsData from '../../data/dnd5e/conditions.json';

interface TokenContextMenuProps {
    x: number;
    y: number;
    tokenId: string;
    combatant?: Combatant;
    onClose: () => void;
    onApplyCondition: (conditionId: string) => void;
    onMarkDead: () => void;
    onRevive: () => void;
    onRemove: () => void;
    onUpdate: (updates: Partial<MapToken>) => void;
    onActionClick?: (action: CombatAction) => void;
    onConditionHover?: (name: string, e: React.MouseEvent) => void;
    onConditionLeave?: () => void;
    onViewStatBlock?: () => void;
}

export const TokenContextMenu: React.FC<TokenContextMenuProps> = ({
    x,
    y,
    tokenId,
    combatant,
    onClose,
    onApplyCondition,
    onMarkDead,
    onRevive,
    onRemove,
    onUpdate,
    onActionClick,
    onConditionHover,
    onConditionLeave,
    onViewStatBlock
}) => {
    const characters = useCharacterStore(s => s.characters);
    const activeEncounter = useCombatStore(s => s.activeEncounter);

    // Get the LIVE token from the store, not the stale prop
    const liveToken = activeEncounter?.battleMap?.tokens.find(t => t.id === tokenId);

    // If token was removed while menu is open, close it
    React.useEffect(() => {
        if (!liveToken) {
            onClose();
        }
    }, [liveToken, onClose]);

    const actions = React.useMemo(() => {
        if (!combatant) return [];
        if (combatant.type === 'player') {
            const char = characters.find(c => c.id === combatant.sourceId);
            return char ? getPlayerCombatActions(char) : [];
        }
        return getMonsterCombatActions(combatant.monsterData);
    }, [combatant, characters]);

    // Group relevant quick actions
    const quickActions = actions.filter(a =>
        ['action', 'bonus', 'reaction'].includes(a.economy) &&
        ['Attacks', 'Spells', 'Actions', 'Standard', 'Bonus', 'Reactions'].includes(a.category)
    ).slice(0, 14);

    const isDead = combatant?.isDead || (combatant && combatant.currentHp <= 0);

    if (!liveToken) return null;

    const conditions = conditionsData.filter(c => c.type === 'condition');
    const buffs = conditionsData.filter(c => c.type === 'buff');

    return (
        <div
            className="fixed z-[100] w-64 bg-stone-950 border border-stone-800 rounded-lg shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-100"
            style={{ left: x, top: y }}
        >
            <div className="px-3 py-2 bg-stone-900 border-b border-stone-800 flex justify-between items-center">
                <div className="flex items-center gap-2 max-w-[180px]">
                    <div className={`w-2 h-2 shrink-0 rounded-full ${liveToken.faction === 'player' ? 'bg-arcane' :
                        liveToken.faction === 'enemy' ? 'bg-blood' :
                            liveToken.faction === 'ally' ? 'bg-green-500' : 'bg-stone-500'
                        }`} />
                    <p className="text-[10px] font-black uppercase text-stone-300 tracking-widest truncate">{liveToken.name}</p>
                </div>
                <button onClick={onClose} className="text-stone-500 hover:text-white p-0.5 rounded hover:bg-stone-800 transition-colors">
                    <X size={12} />
                </button>
            </div>

            <div className="p-1 max-h-[500px] overflow-y-auto custom-scrollbar">
                {/* Buffs Section */}
                <div className="px-3 py-1 text-[9px] font-bold text-cyan-500 uppercase flex items-center gap-1.5 mt-1">
                    <Sparkles size={10} /> Apply Buff
                </div>
                <div className="grid grid-cols-2 gap-0.5 mb-2">
                    {buffs.slice(0, 6).map(b => {
                        const condId = b.name.toLowerCase();
                        const isActive = combatant?.conditions.some(c => c.id === condId);
                        return (
                            <button
                                key={b.name}
                                onClick={() => { onApplyCondition(condId); onClose(); }}
                                onMouseEnter={(e) => onConditionHover?.(b.name, e)}
                                onMouseLeave={onConditionLeave}
                                className={`text-left px-2 py-1 text-[10px] rounded transition-colors flex items-center gap-1.5 group ${isActive ? 'bg-cyan-500/10 text-cyan-400 border border-cyan-500/30' : 'text-parchment hover:bg-stone-800'}`}
                            >
                                <Sparkles size={10} className={`${isActive ? 'text-cyan-400' : 'text-cyan-500/50 group-hover:text-cyan-400'}`} /> {b.name}
                            </button>
                        );
                    })}
                </div>

                {combatant?.type === 'monster' && combatant.monsterData && (
                    <>
                        <div className="h-px bg-stone-800/50 my-1 mx-2" />
                        <button
                            onClick={() => { onViewStatBlock?.(); onClose(); }}
                            className="w-full text-left px-3 py-1.5 text-[10px] text-amber-500 hover:bg-amber-500/10 rounded flex items-center gap-2 transition-colors uppercase font-black tracking-tighter"
                        >
                            <Eye size={12} /> View Stat Block
                        </button>
                    </>
                )}

                <div className="h-px bg-stone-800/50 my-1 mx-2" />

                {/* Conditions Section */}
                <div className="px-3 py-1 text-[9px] font-bold text-blood uppercase flex items-center gap-1.5">
                    <Skull size={10} /> Apply Condition
                </div>
                <div className="grid grid-cols-2 gap-0.5 mb-2">
                    {conditions.slice(0, 14).map(c => {
                        const condId = c.name.toLowerCase();
                        const isActive = combatant?.conditions.some(cond => cond.id === condId);
                        return (
                            <button
                                key={c.name}
                                onClick={() => { onApplyCondition(condId); onClose(); }}
                                onMouseEnter={(e) => onConditionHover?.(c.name, e)}
                                onMouseLeave={onConditionLeave}
                                className={`text-left px-2 py-1 text-[10px] rounded transition-colors flex items-center gap-1.5 group ${isActive ? 'bg-blood/10 text-blood border border-blood/30' : 'text-parchment hover:bg-stone-800'}`}
                            >
                                <Zap size={10} className={`${isActive ? 'text-gold' : 'text-gold/50 group-hover:text-gold'}`} /> {c.name}
                            </button>
                        );
                    })}
                </div>

                <div className="h-px bg-stone-800 my-1" />

                {isDead ? (
                    <button
                        onClick={() => { onMarkDead(); onClose(); }} // Wait, MarkDead logic might be inverted if it's already dead, but the parent uses onRevive separately
                        className="w-full text-left px-3 py-1.5 text-xs text-blood hover:bg-blood/10 rounded flex items-center gap-2 transition-colors"
                    >
                        <Skull size={14} /> Mark as Dead
                    </button> // Fallback if isDead check fails
                ) : (
                    <button
                        onClick={() => { onMarkDead(); onClose(); }}
                        className="w-full text-left px-3 py-1.5 text-xs text-blood hover:bg-blood/10 rounded flex items-center gap-2 transition-colors"
                    >
                        <Skull size={14} /> Mark as Dead
                    </button>
                )}

                {isDead && (
                    <button
                        onClick={() => { onRevive(); onClose(); }}
                        className="w-full text-left px-3 py-1.5 text-xs text-green-500 hover:bg-green-500/10 rounded flex items-center gap-2 transition-colors font-bold"
                    >
                        <HeartPulse size={14} /> Revive Combatant
                    </button>
                )}

                <div className="h-px bg-stone-800 my-1" />

                <div className="px-3 py-1 text-[9px] font-bold text-stone-600 uppercase">Change Faction</div>
                <div className="grid grid-cols-2 gap-0.5">
                    {(['player', 'enemy', 'ally', 'neutral'] as const).map(f => (
                        <button
                            key={f}
                            onClick={() => { onUpdate({ faction: f }); onClose(); }}
                            className={`text-left px-2 py-1 text-[10px] capitalize hover:bg-stone-800 rounded flex items-center gap-1.5 ${liveToken.faction === f ? 'text-gold' : 'text-stone-400'}`}
                        >
                            <Shield size={10} /> {f}
                        </button>
                    ))}
                </div>

                <div className="h-px bg-stone-800 my-1" />

                <button
                    onClick={() => { onRemove(); onClose(); }}
                    className="w-full text-left px-3 py-1.5 text-xs text-stone-500 hover:text-white hover:bg-blood/20 rounded flex items-center gap-2 transition-colors uppercase font-bold tracking-tighter"
                >
                    <LogOut size={14} /> Remove Token
                </button>

                {!isDead && (
                    <>
                        <div className="h-px bg-stone-800 my-1 font-black" />
                        <div className="px-3 py-1 text-[9px] font-black text-amber-500 uppercase flex items-center gap-1.5" title="For traps, environmental effects, or standalone resistance rolls.">
                            <Dice5 size={10} className="text-amber-500" /> Environmental Saves
                        </div>
                        <div className="grid grid-cols-3 gap-1 px-1.5 py-1">
                            {[
                                { id: 'str', name: 'Strength', icon: <Shield size={10} />, color: 'text-orange-500' },
                                { id: 'dex', name: 'Dexterity', icon: <Zap size={10} />, color: 'text-yellow-500' },
                                { id: 'con', name: 'Constitution', icon: <HeartPulse size={10} />, color: 'text-red-500' },
                                { id: 'int', name: 'Intelligence', icon: <Brain size={10} />, color: 'text-blue-500' },
                                { id: 'wis', name: 'Wisdom', icon: <Eye size={10} />, color: 'text-green-500' },
                                { id: 'cha', name: 'Charisma', icon: <User size={10} />, color: 'text-purple-500' }
                            ].map(save => (
                                <button
                                    key={save.id}
                                    onClick={() => {
                                        if (onActionClick) {
                                            onActionClick({
                                                id: `save-${save.id}`,
                                                name: `${save.name} Save`,
                                                actionType: 'saving-throw',
                                                saveAbility: save.id,
                                                economy: 'free',
                                                range: 'Self',
                                                category: 'Standard'
                                            } as any);
                                        }
                                        onClose();
                                    }}
                                    className="bg-stone-900 border border-stone-800 hover:border-amber-500/50 p-1.5 rounded flex flex-col items-center justify-center gap-1 transition-all group"
                                    title={`Roll a ${save.name} Saving Throw`}
                                >
                                    <span className={`${save.color} opacity-70 group-hover:opacity-100`}>{save.icon}</span>
                                    <span className="text-[8px] font-black text-stone-400 group-hover:text-parchment uppercase tracking-tighter">{save.id}</span>
                                </button>
                            ))}
                        </div>
                    </>
                )}

                {quickActions.length > 0 && !isDead && (
                    <>
                        <div className="h-px bg-stone-800 my-1" />
                        <div className="px-3 py-1 text-[9px] font-bold text-stone-500 uppercase flex items-center gap-1">
                            <Swords size={10} /> Actions
                        </div>
                        <div className="grid grid-cols-2 gap-1 px-1 py-1">
                            {quickActions.map(action => (
                                <button
                                    key={action.id}
                                    onClick={() => { onActionClick?.(action); onClose(); }}
                                    className="text-left px-2 py-1 text-[9px] text-parchment bg-stone-900 border border-stone-800 hover:border-gold/50 rounded transition-all flex flex-col gap-0.5 group"
                                >
                                    <div className="flex items-center gap-1 truncate w-full">
                                        <span className="opacity-70 group-hover:opacity-100">{action.icon}</span>
                                        <span className="truncate group-hover:text-gold">{action.name}</span>
                                    </div>
                                    <span className={`text-[7px] font-black uppercase opacity-60 ${action.economy === 'action' ? 'text-gold' :
                                        action.economy === 'bonus' ? 'text-arcane' : 'text-blood'
                                        }`}>
                                        {action.economy === 'action' ? 'Action' : action.economy === 'bonus' ? 'Bonus' : 'Reaction'}
                                    </span>
                                </button>
                            ))}
                        </div>
                    </>
                )}

                <div className="h-px bg-stone-800 my-1" />

                <div className="px-3 py-1 text-[9px] font-bold text-stone-600 uppercase">Auras & Display</div>
                <div className="px-2 py-1 flex flex-col gap-1.5">
                    <div className="flex gap-1">
                        <button
                            onClick={() => { onUpdate({ showNameLabel: !liveToken.showNameLabel }); onClose(); }}
                            className={`flex-1 px-2 py-1 text-[9px] rounded border transition-all flex items-center justify-center gap-1 ${liveToken.showNameLabel !== false ? 'bg-gold/10 border-gold/30 text-gold' : 'bg-stone-900 border-stone-800 text-stone-500'}`}
                        >
                            <span className="text-[10px]">Name</span>
                        </button>
                        <button
                            onClick={() => { onUpdate({ showHealthBar: !liveToken.showHealthBar }); onClose(); }}
                            className={`flex-1 px-2 py-1 text-[9px] rounded border transition-all flex items-center justify-center gap-1 ${liveToken.showHealthBar !== false ? 'bg-arcane/10 border-arcane/30 text-arcane' : 'bg-stone-900 border-stone-800 text-stone-500'}`}
                        >
                            <span className="text-[10px]">HP Bar</span>
                        </button>
                    </div>

                    <div className="grid grid-cols-4 gap-1">
                        {[
                            { r: 10, c: '#3b82f6', n: '10ft Blue' },
                            { r: 30, c: '#ef4444', n: '30ft Red' },
                            { r: 10, c: '#eab308', n: '10ft Gold' },
                            { r: 30, c: '#22c55e', n: '30ft Green' }
                        ].map(preset => {
                            const isActive = liveToken.auras?.some(a => a.radiusFt === preset.r && a.color === preset.c);
                            return (
                                <button
                                    key={`${preset.r}-${preset.c}`}
                                    onClick={() => {
                                        let newAuras = liveToken.auras || [];
                                        if (isActive) {
                                            newAuras = newAuras.filter(a => !(a.radiusFt === preset.r && a.color === preset.c));
                                        } else {
                                            newAuras = [...newAuras, {
                                                id: crypto.randomUUID(),
                                                name: preset.n,
                                                radiusFt: preset.r,
                                                color: preset.c,
                                                opacity: 0.3
                                            }];
                                        }
                                        onUpdate({ auras: newAuras });
                                        onClose();
                                    }}
                                    className={`h-7 rounded border flex items-center justify-center transition-all ${isActive ? 'bg-stone-800 border-gold shadow-[0_0_8px_rgba(255,215,0,0.3)]' : 'bg-stone-900 border-stone-800 hover:border-stone-600'}`}
                                    title={`Toggle ${preset.n}`}
                                >
                                    <div className="w-3 h-3 rounded-full border-2" style={{ backgroundColor: `${preset.c}44`, borderColor: preset.c }} />
                                    <span className="text-[8px] ml-1 font-mono">{preset.r}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
};

import { useState } from 'react';
import { X, ChevronRight, ChevronLeft, Check } from 'lucide-react';
import { InfoTooltip } from './InfoTooltip';

export interface WizardOption {
    label: string;
    value: any;
    description?: string;
    is2024?: boolean;
}

export interface WizardStep {
    id: string;
    title: string;
    description?: string;
    options: WizardOption[];
    maxChoices: number;
    minChoices?: number; // defaults to maxChoices if undefined
    type?: 'choice' | 'text';
    textPlaceholder?: string;
}

interface Props {
    title: string;
    steps: WizardStep[];
    characterLanguages?: string;
    characterSkills?: { name: string, proficient: boolean }[];
    onComplete: (selections: Record<string, any[]>) => void;
    onCancel: () => void;
}

export function ChoiceWizardModal({
    title,
    steps,
    characterLanguages = '',
    characterSkills = [],
    onComplete,
    onCancel
}: Props) {
    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [selections, setSelections] = useState<Record<string, any[]>>({});

    // If there are no steps, complete immediately with empty selections
    if (!steps || steps.length === 0) {
        onComplete({});
        return null;
    }

    const currentStep = steps[currentStepIndex];
    const currentSelections = selections[currentStep.id] || [];
    const isTextStep = currentStep.type === 'text';
    const minRequired = currentStep.minChoices !== undefined ? currentStep.minChoices : currentStep.maxChoices;
    const canProceed = isTextStep
        ? true // Text steps are optional
        : currentSelections.length >= minRequired && currentSelections.length <= currentStep.maxChoices;

    const handleToggleOption = (value: any) => {
        setSelections(prev => {
            const stepSelections = prev[currentStep.id] || [];
            const isSelected = stepSelections.some(v => JSON.stringify(v) === JSON.stringify(value));

            let newSelections;
            if (isSelected) {
                // Remove
                newSelections = stepSelections.filter(v => JSON.stringify(v) !== JSON.stringify(value));
            } else {
                // Add (if under max)
                if (stepSelections.length < currentStep.maxChoices) {
                    newSelections = [...stepSelections, value];
                } else if (currentStep.maxChoices === 1) {
                    // Auto-replace if it's a single choice
                    newSelections = [value];
                } else {
                    newSelections = stepSelections; // Can't add more
                }
            }
            return { ...prev, [currentStep.id]: newSelections };
        });
    };

    const handleNext = () => {
        if (canProceed) {
            if (currentStepIndex < steps.length - 1) {
                setCurrentStepIndex(prev => prev + 1);
            } else {
                onComplete(selections);
            }
        }
    };

    return (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50 animate-in fade-in duration-200 font-lato">
            <div className="bg-stone-900 border border-stone-700 rounded-xl w-full max-w-2xl flex flex-col max-h-[90vh] shadow-2xl overflow-hidden">
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-stone-800 bg-stone-950/50">
                    <div>
                        <h2 className="text-xl font-cinzel font-bold text-parchment tracking-wide">{title}</h2>
                        <p className="text-sm text-stone-400">
                            Step {currentStepIndex + 1} of {steps.length}: <span className="text-gold/80">{currentStep.title}</span>
                        </p>
                    </div>
                    <button
                        onClick={onCancel}
                        className="p-2 hover:bg-stone-800 rounded-lg text-stone-400 hover:text-parchment transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Progress Bar */}
                <div className="h-1 bg-stone-800 w-full overflow-hidden">
                    <div
                        className="h-full bg-blood transition-all duration-300 ease-out"
                        style={{ width: `${((currentStepIndex + 1) / steps.length) * 100}%` }}
                    />
                </div>

                {/* Content */}
                <div className="p-6 overflow-y-auto flex-1 custom-scrollbar">
                    {currentStep.description && (
                        <p className="text-stone-300 mb-6 text-sm">{currentStep.description}</p>
                    )}

                    <div className="space-y-3">
                        {isTextStep ? (
                            <textarea
                                value={currentSelections[0] || ''}
                                onChange={(e) => setSelections(prev => ({ ...prev, [currentStep.id]: [e.target.value] }))}
                                placeholder={currentStep.textPlaceholder || 'Enter details here...'}
                                className="w-full h-32 bg-stone-900 border border-stone-700 rounded-lg p-4 text-parchment resize-none focus:border-gold focus:ring-1 focus:ring-gold focus:outline-none transition-all placeholder:text-stone-600"
                            />
                        ) : (
                            currentStep.options
                                .filter(option => {
                                    // 1. Cross-step deduplication: Filter if already selected in a PREVIOUS step of this wizard
                                    const allPreviousSelections = Object.entries(selections)
                                        .filter(([stepId]) => stepId !== currentStep.id)
                                        .flatMap(([, vals]) => vals);

                                    if (allPreviousSelections.some(v => JSON.stringify(v) === JSON.stringify(option.value))) {
                                        return false;
                                    }

                                    // 2. Global character state filtering (existing)
                                    // Language filtering
                                    if (currentStep.title.toLowerCase().includes('language') || currentStep.id.includes('lang')) {
                                        const knownLangs = characterLanguages.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
                                        if (knownLangs.includes(option.label.toLowerCase())) return false;
                                    }

                                    // Skill filtering
                                    if (currentStep.title.toLowerCase().includes('skill') || currentStep.id.includes('skill')) {
                                        const isKnown = characterSkills.some(s => s.name.toLowerCase() === option.label.toLowerCase() && s.proficient);
                                        if (isKnown) return false;
                                    }

                                    return true;
                                })
                                .map((option, idx) => {
                                    const isSelected = currentSelections.some(v => JSON.stringify(v) === JSON.stringify(option.value));
                                    const isMaxed = !isSelected && currentSelections.length >= currentStep.maxChoices;

                                    return (
                                        <button
                                            key={idx}
                                            onClick={() => handleToggleOption(option.value)}
                                            disabled={isMaxed && currentStep.maxChoices > 1}
                                            className={`w-full text-left p-4 rounded-lg border transition-all duration-200 flex items-start gap-4
                                        ${isSelected
                                                    ? 'bg-blood/10 border-blood shadow-[0_0_10px_rgba(139,0,0,0.2)]'
                                                    : 'bg-stone-800/30 border-stone-700 hover:border-gold hover:bg-stone-800'}
                                        ${(isMaxed && currentStep.maxChoices > 1) ? 'opacity-50 cursor-not-allowed grayscale' : 'cursor-pointer'}
                                    `}
                                        >
                                            <div className={`mt-0.5 w-5 h-5 rounded border flex-shrink-0 flex items-center justify-center transition-colors
                                        ${isSelected ? 'bg-blood border-blood' : 'border-stone-600 bg-stone-900'}
                                        ${currentStep.maxChoices === 1 ? 'rounded-full' : 'rounded'}
                                    `}>
                                                {isSelected && <Check className="w-3.5 h-3.5 text-white" />}
                                            </div>
                                            <div>
                                                <div className={`font-medium flex items-center justify-between gap-2 ${isSelected ? 'text-white' : 'text-parchment'}`}>
                                                    <div className="flex items-center gap-2">
                                                        {option.label}
                                                        {option.is2024 && (
                                                            <span className="text-[9px] bg-gold/20 text-gold-light px-1.5 py-0.5 rounded border border-gold/40 flex items-center gap-1 shadow-[0_0_8px_rgba(212,175,55,0.2)]">
                                                                2024
                                                            </span>
                                                        )}
                                                    </div>
                                                    <InfoTooltip query={option.label} />
                                                </div>
                                                {option.description && (
                                                    <div className="text-sm text-stone-400 mt-1 leading-snug max-w-[90%]">
                                                        {option.description}
                                                    </div>
                                                )}
                                            </div>
                                        </button>
                                    );
                                })
                        )}
                    </div>
                </div>

                {/* Footer Controls */}
                <div className="p-4 border-t border-stone-800 bg-stone-950 flex justify-between items-center rounded-b-xl">
                    <button
                        onClick={() => setCurrentStepIndex(prev => Math.max(0, prev - 1))}
                        disabled={currentStepIndex === 0}
                        className="px-4 py-2 flex items-center gap-2 text-stone-400 hover:text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        <ChevronLeft className="w-4 h-4" />
                        Back
                    </button>

                    <div className="flex flex-col items-center">
                        {!isTextStep && (
                            <div className="text-xs text-stone-500 font-medium mb-1.5">
                                Selected <span className={currentSelections.length === currentStep.maxChoices ? 'text-gold' : 'text-parchment'}>{currentSelections.length}</span> of {currentStep.maxChoices}
                            </div>
                        )}
                        <div className="flex gap-1.5">
                            {steps.map((_, i) => (
                                <div key={i} className={`w-1.5 h-1.5 rounded-full ${i === currentStepIndex ? 'bg-gold shadow-[0_0_5px_rgba(250,204,21,0.5)]' : i < currentStepIndex ? 'bg-blood/70' : 'bg-stone-800 border border-stone-700'}`} />
                            ))}
                        </div>
                    </div>

                    <button
                        onClick={handleNext}
                        disabled={!canProceed}
                        className={`px-6 py-2 flex items-center gap-2 rounded-lg font-cinzel font-bold tracking-wide transition-all shadow-lg
                            ${canProceed
                                ? 'bg-blood text-white hover:bg-red-800 hover:shadow-blood/20'
                                : 'bg-stone-800 text-stone-500 cursor-not-allowed shadow-none'}
                        `}
                    >
                        {currentStepIndex === steps.length - 1 ? 'COMPLETE' : 'NEXT STEP'}
                        {currentStepIndex < steps.length - 1 && <ChevronRight className="w-4 h-4" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { Search, Loader2, Plus, ExternalLink, X, BookOpen, Sparkles, Sword, Skull, Users, ChevronDown, GraduationCap, Bug, Package, Link } from 'lucide-react';
import { searchSpells, searchFeats, searchItems, searchConditions, searchRaces, searchClasses, searchMonsters, searchBackgrounds, searchSubclasses, fetchCustomUrl, parseHomebrew } from '../../engine/fiveEToolsParser';
import { fetchHomebrewCatalog, HomebrewPack } from '../../engine/homebrewCatalog';

export type Category = 'Spells' | 'Feats' | 'Items' | 'Conditions' | 'Races' | 'Classes' | 'Monsters' | 'Backgrounds' | 'Subclasses';

interface FiveEToolsModalProps {
    isOpen: boolean;
    onClose: () => void;
    onImport: (item: any, category: Category) => void;
    initialCategory?: Category;
    fixedCategory?: boolean;
    classNameForSubclass?: string; // Needed for subclass lookup
    classNameFilter?: string;      // Filter spells by class
    levelFilter?: number;          // Initial level filter
}

const CATEGORIES: { id: Category; label: string; icon: any }[] = [
    { id: 'Spells', label: 'Spells', icon: BookOpen },
    { id: 'Feats', label: 'Feats', icon: Sparkles },
    { id: 'Items', label: 'Items', icon: Sword },
    { id: 'Conditions', label: 'Conditions', icon: Skull },
    { id: 'Races', label: 'Races', icon: Users },
    { id: 'Classes', label: 'Classes', icon: GraduationCap },
    { id: 'Backgrounds', label: 'Backgrounds', icon: Users },
    { id: 'Subclasses', label: 'Subclasses', icon: GraduationCap },
    { id: 'Monsters', label: 'Monsters', icon: Bug },
];

export function FiveEToolsModal({
    isOpen,
    onClose,
    onImport,
    initialCategory = 'Spells',
    fixedCategory = false,
    classNameForSubclass,
    classNameFilter,
    levelFilter: initialLevelFilter
}: FiveEToolsModalProps) {
    const [query, setQuery] = useState('');
    const [category, setCategory] = useState<Category>(initialCategory);
    const [results, setResults] = useState<any[]>([]);
    const [isSearching, setIsSearching] = useState(false);
    const [error, setError] = useState('');
    const [searchMode, setSearchMode] = useState<'official' | 'homebrew'>('official');
    const [homebrewUrl, setHomebrewUrl] = useState('');
    const [selectedLevel, setSelectedLevel] = useState<number | 'all'>(initialLevelFilter !== undefined ? initialLevelFilter : 'all');

    const [selectedIndex, setSelectedIndex] = useState(0);
    const [expandedId, setExpandedId] = useState<string | null>(null);

    // Homebrew catalog states
    const [catalogPacks, setCatalogPacks] = useState<HomebrewPack[]>([]);
    const [isCatalogLoading, setIsCatalogLoading] = useState(false);
    const [selectedPack, setSelectedPack] = useState<HomebrewPack | null>(null);
    const [catalogFilter, setCatalogFilter] = useState('');

    // reset selected index on results change
    useEffect(() => {
        setSelectedIndex(0);
        setExpandedId(null);
    }, [results]);

    // keyboard nav
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (!isOpen || results.length === 0) return;

            const isInputFocused = document.activeElement?.tagName === 'INPUT';

            if (e.key === 'ArrowDown') {
                if (isInputFocused) e.preventDefault();
                setSelectedIndex(prev => (prev + 1) % results.length);
            } else if (e.key === 'ArrowUp') {
                if (isInputFocused) e.preventDefault();
                setSelectedIndex(prev => (prev - 1 + results.length) % results.length);
            } else if (e.key === 'Enter') {
                if (isInputFocused) return; // Let form submit handle it
                e.preventDefault();
                const item = results[selectedIndex];
                if (item) {
                    onImport(item, category);
                    onClose();
                }
            } else if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
                if (isInputFocused) return; // Let user move text cursor
                e.preventDefault();
                const item = results[selectedIndex];
                if (item) {
                    const itemId = item.id || item.name;
                    if (expandedId === itemId) setExpandedId(null);
                    else setExpandedId(itemId);
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, results, selectedIndex, category, onImport, onClose, expandedId]);

    useEffect(() => {
        if (isOpen) {
            if (initialCategory) setCategory(initialCategory);
        } else {
            setQuery('');
            setResults([]);
            setError('');
            setSelectedPack(null);
            setCatalogPacks([]);
            setCatalogFilter('');
        }
    }, [isOpen, initialCategory]);

    // Auto-load catalog when switching to homebrew mode or changing category
    useEffect(() => {
        if (searchMode === 'homebrew' && isOpen) {
            setIsCatalogLoading(true);
            setSelectedPack(null);
            setResults([]);
            setCatalogFilter('');
            fetchHomebrewCatalog(category).then(packs => {
                setCatalogPacks(packs);
                setIsCatalogLoading(false);
            });
        }
    }, [searchMode, category, isOpen]);

    const handleSearch = async (e?: React.FormEvent, forceShowAll: boolean = false) => {
        if (e) e.preventDefault();

        const activeQuery = forceShowAll ? '' : query;

        if (searchMode === 'official' && !activeQuery.trim() && !forceShowAll) return;
        if (searchMode === 'homebrew' && !selectedPack && !homebrewUrl.trim()) {
            setError('Select a community pack or paste a custom URL.');
            return;
        }

        setIsSearching(true);
        setError('');
        try {
            let data: any[] = [];

            if (searchMode === 'homebrew') {
                const url = selectedPack ? selectedPack.url : homebrewUrl.trim();
                const rawData = await fetchCustomUrl(url);
                data = parseHomebrew(rawData, activeQuery, category);
            } else {
                switch (category) {
                    case 'Spells':
                        data = await searchSpells(activeQuery, {
                            className: classNameFilter,
                            level: selectedLevel === 'all' ? undefined : selectedLevel
                        });
                        break;
                    case 'Feats': data = await searchFeats(activeQuery); break;
                    case 'Items': data = await searchItems(activeQuery); break;
                    case 'Conditions': data = await searchConditions(activeQuery); break;
                    case 'Races': data = await searchRaces(activeQuery); break;
                    case 'Classes': data = await searchClasses(activeQuery); break;
                    case 'Backgrounds': data = await searchBackgrounds(activeQuery); break;
                    case 'Subclasses':
                        if (classNameForSubclass) {
                            data = await searchSubclasses(classNameForSubclass);
                            // Filter by activeQuery since searchSubclasses gets all for a class
                            if (activeQuery) {
                                data = data.filter((sc: any) => sc.name.toLowerCase().includes(activeQuery.toLowerCase()));
                            }
                        } else {
                            setError('A Class must be selected first to search for Subclasses.');
                            setIsSearching(false);
                            return;
                        }
                        break;
                    case 'Monsters': data = await searchMonsters(activeQuery); break;
                }
            }
            setResults(data);

            if (data.length === 0) {
                if (searchMode === 'homebrew') {
                    setError(`No ${category.toLowerCase()} found in that homebrew pack matching your filter.`);
                } else {
                    setError(`No ${category.toLowerCase()} found in 5e.tools database for that name.`);
                }
            }
        } catch (err) {
            console.error('5e.tools search error:', err);
            setError('Failed to reach 5e.tools database. Are you connected to the internet?');
        } finally {
            setIsSearching(false);
        }
    };

    const renderResultMeta = (item: any) => {
        if (category === 'Spells') {
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    <span><strong className="text-stone-400 font-medium">Time:</strong> {item.castingTime}</span>
                    <span><strong className="text-stone-400 font-medium">Range:</strong> {item.range}</span>
                    <span><strong className="text-stone-400 font-medium">Duration:</strong> {item.duration} {item.concentration && '(C)'}</span>
                </div>
            );
        }
        if (category === 'Feats') {
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    {item.abilityScoreBonuses && (
                        <span><strong className="text-gold font-medium">Stat Bonuses:</strong> {Object.keys(item.abilityScoreBonuses).join(', ').toUpperCase()}</span>
                    )}
                </div>
            );
        }
        if (category === 'Items') {
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    <span className="capitalize"><strong className="text-stone-400 font-medium">Type:</strong> {item.type}</span>
                    <span><strong className="text-stone-400 font-medium">Weight:</strong> {item.weight} lb</span>
                </div>
            );
        }
        if (category === 'Races') {
            const speedStr = typeof item.speed === 'object' ? (item.speed?.walk || 30) : (item.speed || 30);
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    <span><strong className="text-stone-400 font-medium">Speed:</strong> {speedStr} ft.</span>
                </div>
            );
        }
        if (category === 'Classes') {
            const hdStr = item.hitDice || (item.hd ? `1d${item.hd.faces}` : 'Unknown');
            const savesStr = Array.isArray(item.saves) ? item.saves.join(', ') : item.saves;
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    <span><strong className="text-stone-400 font-medium">Hit Dice:</strong> {hdStr}</span>
                    {savesStr && <span><strong className="text-stone-400 font-medium">Saves:</strong> {savesStr}</span>}
                    {item.armorProficiencies && <span><strong className="text-stone-400 font-medium">Armor:</strong> {item.armorProficiencies}</span>}
                    {item.weaponProficiencies && <span><strong className="text-stone-400 font-medium">Weapons:</strong> {item.weaponProficiencies}</span>}
                </div>
            );
        }
        if (category === 'Backgrounds') {
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    {item.skillProficiencies && <span><strong className="text-stone-400 font-medium">Skills:</strong> Includes choices</span>}
                    {item.startingEquipment && <span><strong className="text-stone-400 font-medium">Equipment:</strong> Included</span>}
                </div>
            );
        }
        if (category === 'Subclasses') {
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    <span><strong className="text-stone-400 font-medium">Class:</strong> {item.className}</span>
                    <span><strong className="text-stone-400 font-medium">Short Name:</strong> {item.shortName}</span>
                </div>
            );
        }
        if (category === 'Monsters') {
            return (
                <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-stone-500 mb-2">
                    <span className="capitalize"><strong className="text-stone-400 font-medium">Type:</strong> {item.type}</span>
                    <span><strong className="text-stone-400 font-medium">CR:</strong> {item.cr}</span>
                    <span><strong className="text-stone-400 font-medium">AC:</strong> {item.ac}</span>
                    <span><strong className="text-stone-400 font-medium">HP:</strong> {item.hp}</span>
                </div>
            );
        }
        return null;
    };

    const getPrimaryLabel = (item: any) => {
        if (category === 'Spells') return `Level ${item.level === 0 ? 'Cantrip' : item.level} ${item.school}`;
        return item.source || '5e.tools';
    };

    if (!isOpen) return null;

    const CurrentIcon = CATEGORIES.find(c => c.id === category)?.icon || Search;

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-stone-900 border border-stone-700 w-full max-w-2xl rounded-lg shadow-2xl flex flex-col max-h-[85vh] overflow-hidden">

                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-stone-800 bg-stone-950/50">
                    <div className="flex items-center gap-3">
                        <div className="p-1.5 bg-arcane/20 text-arcane rounded">
                            <CurrentIcon size={20} />
                        </div>
                        <div>
                            <h2 className="text-lg font-cinzel font-bold text-parchment leading-none">5e Database Search</h2>
                            <p className="text-xs text-parchment-muted mt-1">Import directly from 5e.tools</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-1 text-stone-500 hover:text-parchment transition-colors">
                        <X size={20} />
                    </button>
                </div>

                {/* Search Mode Toggle */}
                <div className="flex border-b border-stone-800 bg-stone-950">
                    <button
                        onClick={() => { setSearchMode('official'); setResults([]); setError(''); }}
                        className={`flex-1 py-2 text-sm font-medium transition-colors ${searchMode === 'official' ? 'text-parchment border-b-2 border-arcane bg-stone-900' : 'text-stone-500 hover:text-stone-300'}`}
                    >
                        Official 5e.tools
                    </button>
                    <button
                        onClick={() => { setSearchMode('homebrew'); setResults([]); setError(''); }}
                        className={`flex-1 py-2 text-sm font-medium transition-colors flex items-center justify-center gap-2 ${searchMode === 'homebrew' ? 'text-teal-400 border-b-2 border-teal-500 bg-stone-900' : 'text-stone-500 hover:text-stone-300'}`}
                    >
                        <Package size={14} /> Community Homebrew
                    </button>
                </div>

                {/* Search Bar & Category Select */}
                <div className="p-4 border-b border-stone-800 bg-stone-950/20 space-y-3">
                    {searchMode === 'homebrew' && (
                        <div className="space-y-2">
                            {/* Pack Browser */}
                            {isCatalogLoading ? (
                                <div className="flex items-center gap-2 text-teal-400 text-xs py-2">
                                    <Loader2 size={14} className="animate-spin" />
                                    Loading {category.toLowerCase()} packs...
                                </div>
                            ) : catalogPacks.length > 0 ? (
                                <div>
                                    <label className="block text-[10px] text-teal-500 font-bold mb-1 uppercase tracking-wider">Select a Homebrew Pack ({catalogPacks.length} available)</label>
                                    <input
                                        type="text"
                                        placeholder="Filter packs..."
                                        value={catalogFilter}
                                        onChange={e => setCatalogFilter(e.target.value)}
                                        className="w-full bg-stone-950 border border-stone-700 text-parchment rounded-md py-1.5 px-3 focus:ring-1 focus:outline-none focus:ring-teal-500 focus:border-teal-500 text-xs mb-2"
                                    />
                                    <div className="max-h-32 overflow-y-auto custom-scrollbar border border-stone-800 rounded-md bg-stone-950">
                                        {catalogPacks
                                            .filter(p => !catalogFilter || p.title.toLowerCase().includes(catalogFilter.toLowerCase()) || p.author.toLowerCase().includes(catalogFilter.toLowerCase()))
                                            .map(pack => (
                                                <button
                                                    key={pack.filename}
                                                    onClick={() => { setSelectedPack(pack); setResults([]); setError(''); }}
                                                    className={`w-full text-left px-3 py-2 text-xs flex items-center justify-between transition-colors border-b border-stone-800/50
                                                    ${selectedPack?.filename === pack.filename ? 'bg-teal-900/30 text-teal-300' : 'text-stone-400 hover:bg-stone-800/50 hover:text-parchment'}
                                                `}
                                                >
                                                    <span className="truncate flex-1 font-medium">{pack.title}</span>
                                                    <span className="text-[10px] text-stone-600 ml-2 flex-shrink-0">by {pack.author}</span>
                                                </button>
                                            ))}
                                    </div>
                                    {selectedPack && (
                                        <div className="mt-1 text-[10px] text-teal-400 flex items-center gap-1">
                                            <Package size={10} /> Selected: <strong>{selectedPack.title}</strong> by {selectedPack.author}
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div className="text-stone-500 text-xs italic py-2">No community packs found for {category}.</div>
                            )}

                            {/* Custom URL fallback */}
                            <details className="text-stone-500">
                                <summary className="text-[10px] cursor-pointer hover:text-teal-400 transition-colors flex items-center gap-1 pt-1">
                                    <Link size={10} /> Or paste a direct JSON URL
                                </summary>
                                <input
                                    type="url"
                                    value={homebrewUrl}
                                    onChange={(e) => { setHomebrewUrl(e.target.value); setSelectedPack(null); }}
                                    placeholder="https://raw.githubusercontent.com/.../homebrew.json"
                                    className="w-full bg-stone-950 border border-stone-700 text-parchment rounded-md py-1.5 px-3 focus:ring-1 focus:outline-none focus:ring-teal-500 focus:border-teal-500 text-xs mt-1"
                                />
                            </details>
                        </div>
                    )}
                    <form onSubmit={handleSearch} className="flex gap-3">
                        {!fixedCategory && (
                            <div className="relative flex-shrink-0">
                                <select
                                    value={category}
                                    onChange={(e) => {
                                        setCategory(e.target.value as Category);
                                        setResults([]);
                                        setError('');
                                    }}
                                    className={`appearance-none bg-stone-900 border border-stone-700 text-stone-300 rounded-md py-2.5 pl-4 pr-10 focus:ring-1 focus:outline-none transition-colors text-sm h-full cursor-pointer
                                        ${searchMode === 'homebrew' ? 'focus:ring-teal-500 focus:border-teal-500' : 'focus:ring-arcane focus:border-arcane'}
                                    `}
                                >
                                    {CATEGORIES.map(c => (
                                        <option key={c.id} value={c.id}>{c.label}</option>
                                    ))}
                                </select>
                                <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-stone-500 pointer-events-none" />
                            </div>
