                                                            <span className="text-[10px] bg-teal-900/30 text-teal-400 px-1.5 py-0.5 rounded border border-teal-800 truncate max-w-[150px]" title={`Source: ${item.homebrewSource}`}>
                                                                HB: {item.homebrewSource}
                                                            </span>
                                                        ) : (
                                                            <span className="text-xs bg-stone-800 text-stone-400 px-1.5 py-0.5 rounded border border-stone-700">
                                                                {getPrimaryLabel(item)}
                                                            </span>
                                                        )}
                                                    </div>

                                                    {renderResultMeta(item)}

                                                    {!isExpanded && item.description && (
                                                        <p className="text-xs text-stone-400 line-clamp-2 mt-1">
                                                            {item.description.substring(0, 150)}{item.description.length > 150 ? '...' : ''}
                                                        </p>
                                                    )}
                                                </div>
                                                <button
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        onImport(item, category);
                                                        onClose();
                                                    }}
                                                    className="flex-shrink-0 flex items-center gap-1.5 px-3 py-1.5 bg-arcane/20 hover:bg-arcane/30 text-arcane-light border border-arcane/30 rounded text-xs font-medium transition-colors"
                                                >
                                                    <Plus size={14} /> Import
                                                </button>
                                            </div>

                                            {isExpanded && item.description && (
                                                <div className="mt-2 text-sm text-stone-300 border-t border-stone-800/50 pt-3 whitespace-pre-wrap animate-in slide-in-from-top-2">
                                                    {item.description}
                                                </div>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {results.length === 0 && !isSearching && !error && (
                        <div className="p-12 text-center opacity-50 flex flex-col items-center">
                            <ExternalLink size={32} className="text-stone-600 mb-3" />
                            <p className="text-sm text-parchment">Search for {category.toLowerCase()} directly from 5e.tools.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import { useState, useRef, useEffect, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { Info } from 'lucide-react';
import { lookupByName } from '../../engine/fiveEToolsParser';
import { useAltKey } from '../../hooks/useAltKey';

// Simple markdown-style parser for bold and lists
function renderMarkdownText(text: string): ReactNode[] {
    const lines = text.split('\n');
    return lines.map((line, lineIndex) => {
        // Handle list items
        if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
            const content = line.trim().substring(2);
            return (
                <div key={lineIndex} className="flex gap-2 mt-1">
                    <span className="text-gold">•</span>
                    <span>{renderInlineMarkdown(content)}</span>
                </div>
            );
        }

        // Render normal line with a break
        return (
            <span key={lineIndex}>
                {renderInlineMarkdown(line)}
                {lineIndex < lines.length - 1 && <br />}
            </span>
        );
    });
}

function renderInlineMarkdown(text: string): ReactNode[] {
    // Split by **text** and *text* or _text_ for bold/italic parsing
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*|_.*?_)/g);

    return parts.map((part, index) => {
        if (part.startsWith('**') && part.endsWith('**')) {
            return <strong key={index} className="font-bold text-parchment">{part.slice(2, -2)}</strong>;
        }
        if ((part.startsWith('*') && part.endsWith('*')) || (part.startsWith('_') && part.endsWith('_'))) {
            return <em key={index} className="italic text-stone-300">{part.slice(1, -1)}</em>;
        }
        return <span key={index}>{part}</span>;
    });
}

export function getSourceBadgeColor(source: string) {
    if (!source) return 'bg-stone-800 text-stone-500 border-stone-700';
    const s = source.toLowerCase();
    if (s.includes('phb') || s.includes('core')) return 'bg-red-900/30 text-red-400 border-red-800/50';
    if (s.includes('tce') || s.includes('tasha')) return 'bg-blue-900/30 text-blue-400 border-blue-800/50';
    if (s.includes('xge') || s.includes('xanathar')) return 'bg-purple-900/30 text-purple-400 border-purple-800/50';
    if (s.includes('mm') || s.includes('monster')) return 'bg-orange-900/30 text-orange-400 border-orange-800/50';
    if (s.includes('hb') || s.includes('homebrew') || s.includes('wiki')) return 'bg-teal-900/30 text-teal-400 border-teal-800/50';
    if (s.includes('dmg')) return 'bg-indigo-900/30 text-indigo-400 border-indigo-800/50';
    return 'bg-stone-800 text-stone-400 border-stone-700';
}

interface Props {
    query: string;
    label?: string; // Optional label to display alongside the icon
}

export function InfoTooltip({ query, label }: Props) {
    const [info, setInfo] = useState<{ name: string, description: string, source?: string } | null>(null);
    const [isOpen, setIsOpen] = useState(false);
    const [loading, setLoading] = useState(false);
    const [hasFetched, setHasFetched] = useState(false);
    const timeoutRef = useRef<ReturnType<typeof setTimeout>>();
    const triggerRef = useRef<HTMLDivElement>(null);
    const tooltipRef = useRef<HTMLDivElement>(null);
    const [triggerRect, setTriggerRect] = useState<DOMRect | null>(null);

    const altPressed = useAltKey();
    const isHoveredRef = useRef(false);

    const fetchInfo = async () => {
        if (hasFetched || loading) return;
        setLoading(true);
        try {
            const result = await lookupByName(query);
            if (result) setInfo(result);
        } catch (e) {
            console.error("Failed to fetch tooltip info", e);
        } finally {
            setLoading(false);
            setHasFetched(true);
        }
    };

    const handleMouseEnter = () => {
        isHoveredRef.current = true;
        if (triggerRef.current) {
            setTriggerRect(triggerRef.current.getBoundingClientRect());
        }
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => {
            setIsOpen(true);
            fetchInfo();
        }, 300); // 300ms hover delay so we don't spam popups on quick mouse passes
    };

    const handleMouseLeave = () => {
        isHoveredRef.current = false;
        if (timeoutRef.current) clearTimeout(timeoutRef.current);

        // Return if they are holding alt, effectively ignoring the leave event.
        if (altPressed) return;
        setIsOpen(false);
    };

    // Close when Alt is released IF we are no longer hovering
    useEffect(() => {
        if (!altPressed && !isHoveredRef.current) {
            setIsOpen(false);
        }
    }, [altPressed]);

    // Update position on scroll/resize if open
    useEffect(() => {
        if (!isOpen) return;
        const updatePosition = () => {
            if (triggerRef.current) {
                setTriggerRect(triggerRef.current.getBoundingClientRect());
            }
        };
        window.addEventListener('scroll', updatePosition, true); // true for capture phase to catch all scrolls
        window.addEventListener('resize', updatePosition);
        return () => {
            window.removeEventListener('scroll', updatePosition, true);
            window.removeEventListener('resize', updatePosition);
        };
    }, [isOpen]);

    let tooltipStyle = {};
    if (triggerRect) {
        let left = triggerRect.left + triggerRect.width / 2;
        const top = triggerRect.top - 10;

        // Boundaries
        const maxW = window.innerWidth;
        const ttW = window.innerWidth < 768 ? 288 : 384; // 72 or 96 tailwind w

        if (left - ttW / 2 < 10) {
            left = ttW / 2 + 10;
        } else if (left + ttW / 2 > maxW - 10) {
            left = maxW - ttW / 2 - 10;
        }

        tooltipStyle = { left: `${left}px`, top: `${top}px`, transform: `translate(-50%, -100%)` };
    }

    return (
        <div ref={triggerRef} className="relative inline-flex items-center gap-1.5" onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
            {label && <span>{label}</span>}
            <Info size={14} className="text-stone-500 hover:text-gold cursor-help transition-colors shrink-0" />

            {isOpen && createPortal(
                <div
                    ref={tooltipRef}
                    style={tooltipStyle}
                    className={`fixed z-[99999] w-72 md:w-96 bg-stone-900 border rounded shadow-2xl p-3 text-sm animate-in fade-in duration-200 
                        ${altPressed ? 'pointer-events-auto shadow-gold/10' : 'pointer-events-none'}
                        ${(info?.description?.length || 0) > 300 ? 'border-arcane shadow-[0_0_15px_rgba(79,70,229,0.15)] shadow-arcane/20' : 'border-stone-600'}
                    `}
                    onMouseEnter={() => { isHoveredRef.current = true; }}
                    onMouseLeave={handleMouseLeave}
                >
                    {loading ? (
                        <div className="animate-pulse flex space-x-4">
                            <div className="flex-1 space-y-4 py-1">
                                <div className="h-4 bg-stone-700 rounded w-3/4"></div>
                                <div className="space-y-2">
                                    <div className="h-3 bg-stone-800 rounded"></div>
                                    <div className="h-3 bg-stone-800 rounded w-5/6"></div>
                                </div>
                            </div>
                        </div>
                    ) : info ? (
                        <div className="space-y-2">
                            <div className="font-bold text-gold border-b border-stone-700 pb-1 flex justify-between items-center">
                                <span>{info.name}</span>
                                {info.source && <span className={`text-[10px] font-normal px-1.5 py-0.5 rounded border ${getSourceBadgeColor(info.source)}`}>{info.source}</span>}
                            </div>
                            <div className="text-stone-300 max-h-[300px] overflow-y-auto custom-scrollbar text-[11px] leading-relaxed pr-1">
                                {renderMarkdownText(info.description)}
                            </div>
                        </div>
                    ) : (
                        <div className="text-stone-500 italic text-xs text-center py-2">No data available.</div>
                    )}
                    <div className={`mt-2 text-[9px] uppercase tracking-wider text-center pt-1 border-t border-stone-800 transition-colors ${altPressed ? 'text-gold' : 'text-stone-600'}`}>
                        Hold [ALT] to interact & scroll
                    </div>
                </div>,
                document.body
            )}
        </div>
    );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { Search, X, BookOpen, Sparkles, Swords, Shield, Skull, ScrollText, Star } from 'lucide-react';
import { lookupByName, searchSpells, searchConditions, searchFeats, searchItems } from '../../engine/fiveEToolsParser';

interface RulesResult {
    name: string;
    category: string;
    description: string;
    source?: string;
    // Original data from parser
    originalData?: any;
}

const CATEGORY_CONFIG: Record<string, { icon: any; color: string }> = {
    'Rule': { icon: BookOpen, color: 'text-parchment' },
    'Spell': { icon: Sparkles, color: 'text-arcane-light' },
    'Condition': { icon: Skull, color: 'text-blood' },
    'Feat': { icon: Star, color: 'text-gold' },
    'Item': { icon: Shield, color: 'text-veil' },
    'Action': { icon: Swords, color: 'text-blood-light' },
    'Other': { icon: ScrollText, color: 'text-stone-400' },
};

interface Props {
    isOpen: boolean;
    onClose: () => void;
    title?: string;
    category?: 'spells' | 'items' | 'feats' | 'conditions' | 'all';
    onSelect?: (item: any) => void;
}

export function RulesSearchModal({ isOpen, onClose, title, category = 'all', onSelect }: Props) {
    const [query, setQuery] = useState('');
    const [results, setResults] = useState<RulesResult[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [expandedIdx, setExpandedIdx] = useState<number | null>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const debounceRef = useRef<number | null>(null);

    // Focus input when modal opens
    useEffect(() => {
        if (isOpen) {
            setTimeout(() => inputRef.current?.focus(), 100);
            setQuery('');
            setResults([]);
            setExpandedIdx(null);
        }
    }, [isOpen]);

    // Close on Escape
    useEffect(() => {
        const handler = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && isOpen) onClose();
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [isOpen, onClose]);

    const performSearch = useCallback(async (searchQuery: string) => {
        if (searchQuery.trim().length < 2) {
            setResults([]);
            return;
        }

        setIsLoading(true);
        const allResults: RulesResult[] = [];

        try {
            // 1. Local rules lookup
            if (category === 'all') {
                const localResult = await lookupByName(searchQuery);
                if (localResult) {
                    allResults.push({
                        name: localResult.name,
                        category: 'Rule',
                        description: localResult.description,
                        source: localResult.source,
                        originalData: localResult
                    });
                }
            }

            // 2. Conditions
            if (category === 'all' || category === 'conditions') {
                const conditions = await searchConditions(searchQuery);
                for (const c of conditions.slice(0, 10)) {
                    if (!allResults.some(r => r.name.toLowerCase() === c.name.toLowerCase())) {
                        allResults.push({
                            name: c.name,
                            category: 'Condition',
                            description: c.description || 'No description available.',
                            source: c.source,
                            originalData: c
                        });
                    }
                }
            }

            // 3. Spells
            if (category === 'all' || category === 'spells') {
                const spells = await searchSpells(searchQuery);
                for (const s of spells.slice(0, 10)) {
                    if (!allResults.some(r => r.name.toLowerCase() === s.name.toLowerCase())) {
                        allResults.push({
                            name: s.name,
                            category: 'Spell',
                            description: `**Level ${s.level} ${s.school}** | ${s.castingTime} | ${s.range} | ${s.duration}${s.concentration ? ' (C)' : ''}\n\n${s.description}`,
                            source: 'PHB',
                            originalData: s
                        });
                    }
                }
            }

            // 4. Feats
            if (category === 'all' || category === 'feats') {
                const feats = await searchFeats(searchQuery);
                for (const f of feats.slice(0, 10)) {
                    if (!allResults.some(r => r.name.toLowerCase() === f.name.toLowerCase())) {
                        allResults.push({
                            name: f.name,
                            category: 'Feat',
                            description: f.description,
                            source: f.source5eTools,
                            originalData: f
                        });
                    }
                }
            }

            // 5. Items
            if (category === 'all' || category === 'items') {
                const items = await searchItems(searchQuery);
                for (const i of items.slice(0, 10)) {
                    if (!allResults.some(r => r.name.toLowerCase() === i.name.toLowerCase())) {
                        allResults.push({
                            name: i.name,
                            category: 'Item',
                            description: i.description || 'No description available.',
                            originalData: i
                        });
                    }
                }
            }
        } catch (e) {
            console.warn('Rules search error:', e);
        }

        setResults(allResults);
        setIsLoading(false);
    }, [category]);

    const handleQueryChange = (val: string) => {
        setQuery(val);
        if (debounceRef.current) clearTimeout(debounceRef.current);
        debounceRef.current = window.setTimeout(() => performSearch(val), 400);
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[99999] flex items-start justify-center pt-[15vh]" onClick={onClose}>
            <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" />

            <div
                className="relative w-full max-w-2xl bg-modal border border-stone-700/50 rounded-xl shadow-[0_10px_40px_rgba(0,0,0,0.8)] overflow-hidden animate-in fade-in slide-in-from-top-4 duration-200"
                onClick={(e) => e.stopPropagation()}
            >
                <div className="absolute inset-0 bg-stone-950/60 pointer-events-none" />

                {/* Search Bar */}
                <div className="flex items-center gap-3 p-4 border-b border-stone-800 bg-obsidian/40 backdrop-blur-sm relative z-10">
                    <Search size={20} className="text-stone-500" />
                    <input
                        ref={inputRef}
                        type="text"
                        value={query}
                        onChange={(e) => handleQueryChange(e.target.value)}
                        placeholder={title || "Search rules, spells, feats..."}
                        className="flex-1 bg-transparent text-parchment text-lg placeholder-stone-600 outline-none"
                    />
                    <kbd className="hidden md:inline-flex items-center gap-1 text-xs text-stone-600 bg-stone-800 border border-stone-700 rounded px-1.5 py-0.5">ESC</kbd>
                    <button onClick={onClose} className="p-1 hover:bg-stone-800 rounded text-stone-500 hover:text-parchment transition-colors">
                        <X size={18} />
                    </button>
                </div>

                {/* Results */}
                <div className="max-h-[50vh] overflow-y-auto custom-scrollbar relative z-10">
                    {isLoading && (
                        <div className="p-6 text-center text-stone-500 animate-pulse">
                            <BookOpen size={24} className="mx-auto mb-2 opacity-50" />
                            <span className="font-cinzel tracking-wider">Scouring the Tomes...</span>
                        </div>
                    )}

                    {!isLoading && query.length >= 2 && results.length === 0 && (
                        <div className="p-6 text-center text-stone-500">
                            No rules found for "<span className="text-parchment font-cinzel">{query}</span>"
                        </div>
                    )}

                    {!isLoading && results.map((result, idx) => {
                        const config = CATEGORY_CONFIG[result.category] || CATEGORY_CONFIG['Other'];
                        const Icon = config.icon;
                        const isExpanded = expandedIdx === idx;

                        return (
                            <div
                                key={idx}
                                className="border-b border-stone-800/50 last:border-0 cursor-pointer hover:bg-stone-800/40 transition-colors"
                            >
                                <div className="flex items-center gap-3 px-4 py-3" onClick={() => setExpandedIdx(isExpanded ? null : idx)}>
                                    <Icon size={16} className={config.color} />
                                    <span className="font-cinzel text-parchment font-bold">{result.name}</span>
                                    <span className={`text-[10px] uppercase font-bold tracking-wider px-1.5 py-0.5 rounded ${config.color} bg-stone-800`}>
                                        {result.category}
                                    </span>
                                    {result.source && (
                                        <span className="ml-auto text-[10px] text-stone-600">{result.source}</span>
                                    )}
                                    {onSelect && (
                                        <button
                                            onClick={(e) => { e.stopPropagation(); onSelect(result.originalData); }}
                                            className="ml-4 px-2 py-0.5 bg-stone-700 hover:bg-gold hover:text-stone-950 text-gold text-[10px] font-bold rounded transition-colors"
                                        >
                                            SELECT
                                        </button>
                                    )}
                                </div>
                                {isExpanded && (
                                    <div className="px-4 pb-4 text-sm text-stone-400 whitespace-pre-wrap leading-relaxed border-t border-stone-800/50 pt-3 mx-4 animate-in fade-in duration-150">
                                        {result.description}
                                    </div>
                                )}
                            </div>
                        );
                    })}

                    {!isLoading && query.length < 2 && (
                        <div className="p-8 text-center text-stone-600 space-y-3 opacity-60">
                            <BookOpen size={32} className="mx-auto text-stone-700" />
                            <p className="font-cinzel text-sm tracking-wider">Type at least 2 characters to search</p>
                            <p className="text-xs text-stone-700">Rules · Spells · Conditions · Feats · Items</p>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-4 py-3 border-t border-stone-800 text-[10px] text-stone-500 flex justify-between bg-obsidian-dark/80 backdrop-blur-sm relative z-10">
                    <span>Powered by 5e.tools</span>
                    <span>Press <kbd className="bg-stone-800 px-1 rounded">↑↓</kbd> to navigate · <kbd className="bg-stone-800 px-1 rounded">Enter</kbd> to expand</span>
                </div>
            </div>
        </div>
    );
}

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { Info, CheckCircle, AlertTriangle, XCircle, X } from 'lucide-react';

export type ToastType = 'info' | 'success' | 'warning' | 'error';

interface Toast {
    id: string;
    message: string;
    type: ToastType;
    duration?: number;
}

interface ToastContextType {
    addToast: (message: string, type?: ToastType, duration?: number) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const useToast = () => {
    const context = useContext(ToastContext);
    if (!context) {
        throw new Error("useToast must be used within a ToastProvider");
    }
    return context;
};

export const ToastProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [toasts, setToasts] = useState<Toast[]>([]);

    const addToast = useCallback((message: string, type: ToastType = 'info', duration: number = 4000) => {
        const id = crypto.randomUUID();
        const newToast = { id, message, type, duration };

        setToasts(prev => [...prev, newToast]);

        if (duration > 0) {
            setTimeout(() => {
                removeToast(id);
            }, duration);
        }
    }, []);

    const removeToast = useCallback((id: string) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    }, []);

    return (
        <ToastContext.Provider value={{ addToast }}>
            {children}
            {createPortal(
                <div className="fixed bottom-4 right-4 z-[100000] flex flex-col gap-2 pointer-events-none">
                    {toasts.map(toast => (
                        <ToastMessage key={toast.id} toast={toast} onDismiss={() => removeToast(toast.id)} />
                    ))}
                </div>,
                document.body
            )}
        </ToastContext.Provider>
    );
};

// --- Internal Component ---

const ToastMessage: React.FC<{ toast: Toast, onDismiss: () => void }> = ({ toast, onDismiss }) => {

    const getStyles = () => {
        const baseStyle = "bg-modal border bg-obsidian/40 backdrop-blur-md shadow-[0_5px_20px_rgba(0,0,0,0.8)]";

        switch (toast.type) {
            case 'success':
                return {
                    container: `${baseStyle} border-green-800/50 shadow-[inset_0_0_15px_rgba(34,197,94,0.1)]`,
                    icon: <CheckCircle className="text-green-500 w-5 h-5 flex-shrink-0 drop-shadow-[0_0_8px_rgba(34,197,94,0.6)]" />
                };
            case 'error':
                return {
                    container: `${baseStyle} border-red-800/50 shadow-[inset_0_0_15px_rgba(239,68,68,0.1)]`,
                    icon: <XCircle className="text-blood w-5 h-5 flex-shrink-0 drop-shadow-[0_0_8px_rgba(220,38,38,0.8)]" />
                };
            case 'warning':
                return {
                    container: `${baseStyle} border-yellow-800/50 shadow-[inset_0_0_15px_rgba(234,179,8,0.1)]`,
                    icon: <AlertTriangle className="text-yellow-500 w-5 h-5 flex-shrink-0 drop-shadow-[0_0_8px_rgba(234,179,8,0.6)]" />
                };
            case 'info':
            default:
                return {
                    container: `${baseStyle} border-blue-800/50 shadow-[inset_0_0_15px_rgba(96,165,250,0.1)]`,
                    icon: <Info className="text-arcane-light w-5 h-5 flex-shrink-0 drop-shadow-[0_0_8px_rgba(96,165,250,0.6)]" />
                };
        }
    };

    const styles = getStyles();

    return (
        <div className={`pointer-events-auto flex items-start gap-3 p-4 pr-10 rounded-lg animate-in slide-in-from-right-8 fade-in duration-300 min-w-[300px] max-w-sm relative group ${styles.container}`}>
            <div className="absolute inset-0 bg-stone-950/70 rounded-lg pointer-events-none" /> {/* Darken texture */}
            <div className="relative z-10 flex items-start gap-3 w-full">
                {styles.icon}
                <div className="text-sm font-medium text-parchment leading-tight pt-0.5 drop-shadow-sm">
                    {toast.message}
                </div>
            </div>
            <button
                onClick={onDismiss}
                className="absolute top-4 right-3 text-stone-500 opacity-0 group-hover:opacity-100 transition-opacity hover:text-parchment"
            >
                <X size={14} />
            </button>
        </div>
    );
};

import { DungeonMap, MapRoom } from '../../types/campaignNavigator';
import { useState, useRef, useCallback, useMemo } from 'react';
import { MapPin, Lock, Footprints, Layers, Settings, Search, Swords, Users, UserPlus } from 'lucide-react';
import { MapSetupEditor } from './MapSetupEditor';
import { BattleMap } from '../combat/BattleMap';
import { dungeonMapToBattleMapState, DEFAULT_DUNGEON_GRID } from '../../engine/mapBridge';
import { useNavigatorStore } from '../../store/navigatorStore';
import { useCombatStore } from '../../store/combatStore';
import { useCharacterStore } from '../../store/characterStore';
import { useNavigate } from 'react-router-dom';
import { MapToken } from '../../types/battleMap';

interface Props {
    maps: DungeonMap[];
    activeFloorId: string | null;
    partyRoomId: string | null;
    onRoomClick: (room: MapRoom) => void;
    onFloorChange: (floorId: string) => void;
}

export function DungeonMapView({ maps, activeFloorId, partyRoomId, onRoomClick, onFloorChange }: Props) {
    const navigate = useNavigate();
    const updateDungeonMapToken = useNavigatorStore(state => state.updateDungeonMapToken);
    const addDungeonMapToken = useNavigatorStore(state => state.addDungeonMapToken);
    const initializeEncounterFromNavigator = useCombatStore(state => state.initializeEncounterFromNavigator);
    const characters = useCharacterStore(state => state.characters);

    const [hoveredRoom, setHoveredRoom] = useState<MapRoom | null>(null);
    const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });
    const [isEditing, setIsEditing] = useState(false);
    const [showHeroDropdown, setShowHeroDropdown] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    // Sort maps by floor order
    const sortedMaps = [...maps].sort((a, b) => a.floorOrder - b.floorOrder);
    const activeMap = sortedMaps.find(m => m.floorId === activeFloorId) || sortedMaps[0];

    // Determine which floor the party is currently on
    const partyFloorId = sortedMaps.find(m => m.rooms.some(r => r.id === partyRoomId))?.floorId;

    const handleRoomMouseMove = useCallback((e: React.MouseEvent, room: MapRoom) => {
        setTooltipPos({ x: e.clientX, y: e.clientY });
        setHoveredRoom(room);
    }, []);

    const handlePlaceHero = (character: any) => {
        if (!activeMap) return;

        // Don't add if already on map
        if (activeMap.tokens.some(t => t.combatantId === character.id)) {
            setShowHeroDropdown(false);
            return;
        }

        const newToken: MapToken = {
            id: crypto.randomUUID(),
            combatantId: character.id,
            name: character.name,
            position: { col: 5, row: 5 }, // Default spawn position
            elevation: 0,
            color: '#fbbf24', // Amber
            faction: 'player',
            size: 1
        };

        addDungeonMapToken(activeMap.id, newToken);
        setShowHeroDropdown(false);
    };

    const getRoomStyles = (room: MapRoom): string => {
        const isPartyHere = room.id === partyRoomId;
        const base = 'absolute rounded transition-all duration-300 cursor-pointer border-2 backdrop-blur-sm';

        if (isPartyHere) {
            return `${base} bg-amber-500/5 border-amber-400 shadow-[0_0_15px_rgba(245,158,11,0.4)] hover:bg-amber-500/10`;
        }

        switch (room.status) {
            case 'current':
                return `${base} bg-amber-500/5 border-amber-300 hover:bg-amber-500/10 shadow-[0_0_10px_rgba(245,158,11,0.3)]`;
            case 'explored':
                return `${base} bg-stone-500/5 border-stone-200 hover:bg-stone-500/10`;
            case 'locked':
                return `${base} bg-red-500/5 border-red-300 hover:bg-red-500/10`;
            case 'unexplored':
            default:
                return room.isRevealed
                    ? `${base} bg-stone-500/5 border-white/40 hover:bg-stone-500/10 border-dashed`
                    : `${base} bg-transparent border-stone-500/60 hover:bg-stone-800/10 border-dotted opacity-70`;
        }
    }

    // Unified Map Integration: Convert DungeonMap to BattleMapState
    const battleMapState = useMemo(() => {
        if (!activeMap || !activeMap.id) return null;

        // Defensive defaults in case the persist layer hasn't caught up
        const safeMap = {
            ...activeMap,
            gridWidth: activeMap.gridWidth || DEFAULT_DUNGEON_GRID.gridWidth,
            gridHeight: activeMap.gridHeight || DEFAULT_DUNGEON_GRID.gridHeight,
            cellSizePx: activeMap.cellSizePx || DEFAULT_DUNGEON_GRID.cellSizePx,
            gridColor: activeMap.gridColor || DEFAULT_DUNGEON_GRID.gridColor,
            tokens: activeMap.tokens || DEFAULT_DUNGEON_GRID.tokens,
            shapes: activeMap.shapes || DEFAULT_DUNGEON_GRID.shapes,
            freehandPaths: activeMap.freehandPaths || DEFAULT_DUNGEON_GRID.freehandPaths,
            fogOfWar: activeMap.fogOfWar || DEFAULT_DUNGEON_GRID.fogOfWar,
            fogOfWarFreehand: activeMap.fogOfWarFreehand || DEFAULT_DUNGEON_GRID.fogOfWarFreehand,
        };

        return dungeonMapToBattleMapState(safeMap);
    }, [activeMap]);

    if (!activeMap || !battleMapState) {
        return (
            <div className="flex-1 flex flex-col items-center justify-center bg-stone-950 text-stone-500 font-cinzel gap-4">
                <Search size={48} className="animate-pulse text-stone-800" />
                <div className="text-center">
                    <p className="text-lg tracking-widest uppercase">No Floor Data Detected</p>
                    <p className="text-xs text-stone-600 mt-1 uppercase">Select a floor or check narrative context</p>
                </div>
            </div>
        );
    }

    return (
        <div className="h-full flex flex-col bg-stone-950/60 rounded-lg border border-stone-800/40 overflow-hidden">
            {/* Map Header */}
            <div className="flex items-center justify-between px-4 py-2.5 border-b border-stone-800/30 bg-stone-900/40 shrink-0">
                <div className="flex items-center gap-2">
                    <MapPin size={14} className="text-amber-500" />
                    <h4 className="font-cinzel text-xs font-bold text-amber-400 tracking-wider font-outline-sm">{activeMap.name}</h4>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                    <button
                        onClick={() => {/* rules search placeholder */ }}
                        className="p-1.5 bg-stone-800 hover:bg-stone-700 text-stone-400 rounded border border-stone-700 transition-colors"
                        title="Search Rules / Entities"
                    >
                        <Search size={12} />
                    </button>
                    <div className="relative">
                        <button
                            onClick={() => setShowHeroDropdown(!showHeroDropdown)}
                            className="flex items-center gap-1.5 px-2.5 py-1 bg-stone-800 hover:bg-stone-700 hover:text-white rounded border border-stone-700 transition-colors text-stone-300 text-[10px] font-bold uppercase tracking-wider"
                        >
                            <Users size={12} /> Place Heroes
                        </button>

                        {showHeroDropdown && (
                            <div className="absolute top-full right-0 mt-1 w-48 bg-stone-900 border border-stone-700 rounded shadow-xl z-50 py-1">
                                {characters.length === 0 ? (
                                    <div className="px-3 py-2 text-xs text-stone-500 italic">No heroes available</div>
                                ) : (
                                    characters.map(char => {
                                        const isPlaced = activeMap.tokens.some(t => t.combatantId === char.id);
                                        return (
                                            <button
                                                key={char.id}
                                                onClick={() => handlePlaceHero(char)}
                                                disabled={isPlaced}
                                                className={`w-full text-left px-3 py-1.5 flex items-center justify-between text-xs transition-colors
                                                    ${isPlaced
                                                        ? 'opacity-50 cursor-not-allowed text-stone-500'
                                                        : 'hover:bg-stone-800 text-stone-300'}`}
                                            >
                                                <span className="truncate">{char.name}</span>
                                                <UserPlus size={12} className={isPlaced ? 'text-stone-600' : 'text-amber-500'} />
                                            </button>
                                        );
                                    })
                                )}
                            </div>
                        )}
                    </div>
                    <button
                        onClick={() => setIsEditing(true)}
                        className="flex items-center gap-1.5 px-2.5 py-1 bg-stone-800 hover:bg-stone-700 hover:text-white rounded border border-stone-700 transition-colors text-stone-300 text-[10px] font-bold uppercase tracking-wider"
                    >
                        <Settings size={12} /> Edit Map
                    </button>
                    <button
                        onClick={() => {
                            initializeEncounterFromNavigator(activeMap);
                            navigate('/combat');
                        }}
                        className="flex items-center gap-1.5 px-3 py-1 bg-amber-600 hover:bg-amber-500 text-stone-950 rounded border border-amber-500 transition-colors text-[10px] font-black uppercase tracking-wider shadow-lg shadow-amber-900/20"
                    >
                        <Swords size={12} /> Engage Combat
                    </button>
                </div>
            </div>

            {/* Floor Tabs */}
            {sortedMaps.length > 1 && (
                <div className="flex items-center gap-1 px-3 py-2 border-b border-stone-800/20 bg-stone-900/20 shrink-0">
                    <Layers size={12} className="text-stone-500 mr-1" />
                    {sortedMaps.map(m => {
                        const isActive = m.floorId === activeMap.floorId;
                        const hasParty = m.floorId === partyFloorId;
                        return (
                            <button
                                key={m.floorId}
                                type="button"
                                onClick={() => onFloorChange(m.floorId)}
                                className={`px-3 py-1 rounded text-[10px] font-bold tracking-wide transition-all
                                    ${isActive
                                        ? 'bg-amber-900/40 text-amber-300 border border-amber-700/50'
                                        : 'text-stone-500 hover:text-stone-300 hover:bg-stone-800/40 border border-transparent'
                                    }
                                `}
                            >
                                {m.floorLabel}
                                {hasParty && !isActive && (
                                    <span className="ml-1.5 inline-block w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />
                                )}
                            </button>
                        );
                    })}
                </div>
            )}

            {/* Tactical Map Engine */}
            <div className="flex-1 relative overflow-hidden" ref={containerRef}>
                <BattleMap
                    mapState={battleMapState}
                    tokens={activeMap.tokens}
                    onTokenMove={(tid, pos) => updateDungeonMapToken(activeMap.id, tid, { position: pos })}
                    className="w-full h-full"
                >
                    {/* Narrative Rooms Overlay — positioned relative to the map content (fixed size) */}
                    <div className="absolute inset-0 pointer-events-none" style={{ width: activeMap.gridWidth * activeMap.cellSizePx, height: activeMap.gridHeight * activeMap.cellSizePx }}>
                        {activeMap.rooms.map(room => (
                            <div
                                key={room.id}
                                className={`${getRoomStyles(room)} pointer-events-auto shadow-black/80 shadow-lg`}
                                style={{
                                    left: `${room.x}%`,
                                    top: `${room.y}%`,
                                    width: `${room.width}%`,
                                    height: `${room.height}%`,
                                    borderRadius: room.shape === 'circle' ? '50%' : undefined,
                                }}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onRoomClick(room);
                                }}
                                onMouseMove={(e) => handleRoomMouseMove(e, room)}
                                onMouseLeave={() => setHoveredRoom(null)}
                            >
                                <div className="absolute inset-0 flex flex-col items-center justify-center gap-0.5">
                                    <span className="text-[14px] font-cinzel font-black tracking-widest text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)] brightness-110">
                                        {room.label}
                                    </span>
                                    <span className="text-[10px] text-stone-100 font-bold max-w-full truncate px-1 drop-shadow-[0_2px_4px_rgba(0,0,0,1)] brightness-110">
                                        {room.name}
                                    </span>
                                    {room.id === partyRoomId && (
                                        <Footprints size={16} className="text-amber-400 drop-shadow-[0_2px_4px_rgba(0,0,0,1)] animate-pulse mt-1" />
                                    )}
                                </div>
                            </div>
                        ))}

                        {/* Connections */}
                        <svg className="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 100 100" preserveAspectRatio="none">
                            {activeMap.connections.filter(c => c.isRevealed).map(conn => {
                                const from = activeMap.rooms.find(r => r.id === conn.fromRoomId);
                                const to = activeMap.rooms.find(r => r.id === conn.toRoomId);
                                if (!from || !to) return null;

                                const fx = from.x + from.width / 2;
                                const fy = from.y + from.height / 2;
                                const tx = to.x + to.width / 2;
                                const ty = to.y + to.height / 2;

                                return (
                                    <line
                                        key={`${conn.fromRoomId}-${conn.toRoomId}`}
                                        x1={fx} y1={fy}
                                        x2={tx} y2={ty}
                                        stroke={conn.type === 'secret' ? 'rgba(168,85,247,0.3)' : 'rgba(168,162,158,0.25)'}
                                        strokeWidth="0.4"
                                        strokeDasharray={conn.type === 'secret' ? '1 1' : conn.type === 'trap' ? '0.5 0.5' : 'none'}
                                    />
                                );
                            })}
                        </svg>
                    </div>
                </BattleMap>
            </div>

            {/* Room Tooltip */}
            {hoveredRoom && (
                <div
                    className="fixed z-[1000] pointer-events-none"
                    style={{
                        left: tooltipPos.x,
                        top: tooltipPos.y,
                        transform: 'translate(-50%, -100%)'
                    }}
                >
                    <div className="bg-stone-900/95 border border-stone-700/60 rounded-lg px-3 py-2 shadow-2xl backdrop-blur-md max-w-[220px]">
                        <div className="flex items-center gap-2 mb-1">
                            <span className="text-amber-500 font-cinzel text-xs font-bold font-outline-sm">{hoveredRoom.label}</span>
                            <span className="text-stone-100 text-xs font-bold drop-shadow-md">{hoveredRoom.name}</span>
                        </div>
                        {hoveredRoom.description && (
                            <p className="text-stone-300 text-[10px] leading-relaxed italic">{hoveredRoom.description}</p>
                        )}
                        <div className="flex items-center gap-2 mt-1.5 pt-1.5 border-t border-stone-800/50">
                            {hoveredRoom.status === 'locked' && <Lock size={10} className="text-red-400" />}
                            <span className="text-[9px] text-stone-400 font-bold uppercase tracking-wider">{hoveredRoom.status}</span>
                            {hoveredRoom.sceneId && hoveredRoom.isRevealed && (
                                <span className="text-[9px] text-amber-500 ml-auto font-black italic">Go to Scene</span>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Editor Overlay */}
            {isEditing && (
                <MapSetupEditor
                    map={activeMap}
                    onClose={() => setIsEditing(false)}
                />
            )}
        </div>
    );
}

import { useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useAltKey } from '../../hooks/useAltKey';
import { Info, Shield, Sparkles, Swords, Gem, HeartPulse, Loader2, BookOpen } from 'lucide-react';
import { useNavigatorStore } from '../../store/navigatorStore';
import {
    searchMonsters,
    searchSpells,
    searchItems,
    lookupByName,
    flattenEntries,
    searchAdventureLore
} from '../../engine/fiveEToolsParser';
import { EntityStatBlock } from '../../types/campaignNavigator';

export type EntityCategory = 'monster' | 'spell' | 'item' | 'condition' | 'npc' | 'location' | 'lore';

export interface EntityLinkProps {
    text: string;           // The text to display
    lookupKey: string;      // The exact 5e.tools or internal key (e.g. "Longsword", "Fireball")
    category: EntityCategory;
}

const CATEGORY_COLORS: Record<EntityCategory, string> = {
    monster: 'text-red-400 border-red-500/30 hover:border-red-400/80 hover:bg-red-500/10',
    spell: 'text-purple-400 border-purple-500/30 hover:border-purple-400/80 hover:bg-purple-500/10',
    item: 'text-amber-400 border-amber-500/30 hover:border-amber-400/80 hover:bg-amber-500/10',
    condition: 'text-teal-400 border-teal-500/30 hover:border-teal-400/80 hover:bg-teal-500/10',
    npc: 'text-blue-400 border-blue-500/30 hover:border-blue-400/80 hover:bg-blue-500/10',
    location: 'text-emerald-400 border-emerald-500/30 hover:border-emerald-400/80 hover:bg-emerald-500/10',
    lore: 'text-cyan-400 border-cyan-500/30 hover:border-cyan-400/80 hover:bg-cyan-500/10'
};

const CATEGORY_ICONS: Record<EntityCategory, any> = {
    monster: Swords,
    spell: Sparkles,
    item: Gem,
    condition: HeartPulse,
    npc: BookOpen,
    location: Shield,
    lore: Info
};

export function EntityLink({ text, lookupKey, category }: EntityLinkProps) {
    const [isHovered, setIsHovered] = useState(false);
    const [isTooltipHovered, setIsTooltipHovered] = useState(false);
    const elementRef = useRef<HTMLSpanElement | null>(null);
    const [hoverRect, setHoverRect] = useState<DOMRect | null>(null);
    const altPressed = useAltKey();
    const hideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const { enrichmentCache, cacheEntity } = useNavigatorStore();
    const cachedEntity = enrichmentCache[lookupKey];
    const [isLoading, setIsLoading] = useState(false);
    const fetchAttemptedRef = useRef(false);

    // Determine if the tooltip should be visible:
    // - Normal hover: show while mouse is over the span only
    // - Alt mode: show while mouse is over span OR tooltip (persists for interaction)
    const shouldShowTooltip = isHovered || (altPressed && isTooltipHovered);

    // Reset isTooltipHovered when Alt is released or tooltip is hidden
    // This prevents stale state from leaking (tooltip unmounts → onMouseLeave never fires)
    useEffect(() => {
        if (!altPressed) {
            setIsTooltipHovered(false);
        }
    }, [altPressed]);

    useEffect(() => {
        if (!shouldShowTooltip) {
            setIsTooltipHovered(false);
        }
    }, [shouldShowTooltip]);

    // Debounced hide — gives the user time to move from span to tooltip
    const scheduleHide = useCallback(() => {
        hideTimerRef.current = setTimeout(() => {
            setIsHovered(false);
        }, 150); // 150ms grace period
    }, []);

    const cancelHide = useCallback(() => {
        if (hideTimerRef.current) {
            clearTimeout(hideTimerRef.current);
            hideTimerRef.current = null;
        }
    }, []);

    // Update tooltip position on scroll/resize
    useEffect(() => {
        if (!shouldShowTooltip || !elementRef.current) return;
        const updateRect = () => {
            if (elementRef.current) {
                setHoverRect(elementRef.current.getBoundingClientRect());
            }
        };
        updateRect();
        window.addEventListener('scroll', updateRect, true);
        window.addEventListener('resize', updateRect);
        return () => {
            window.removeEventListener('scroll', updateRect, true);
            window.removeEventListener('resize', updateRect);
        };
    }, [shouldShowTooltip]);

    // Fetch data if needed — triggers on hover or alt press
    useEffect(() => {
        if (!shouldShowTooltip) return;
        if (cachedEntity) return;
        if (fetchAttemptedRef.current) return;

        // Synchronous check for local adventure lore — PRIORITY 1
        const localLore = searchAdventureLore(lookupKey);
        if (localLore) {
            cacheEntity(lookupKey, {
                id: lookupKey,
                name: localLore.name,
                type: category as any,
                lookupKey,
                description: localLore.description,
                statBlock: undefined
            });
            return;
        }

        fetchAttemptedRef.current = true;

        const fetchData = async () => {
            setIsLoading(true);
            try {
                let description = '';
                let statBlock: EntityStatBlock | undefined;

                if (category === 'monster') {
                    // Search bestiary for monsters
                    const monsters = await searchMonsters(lookupKey);
                    if (monsters.length > 0) {
                        const m = monsters.find(x => x.name.toLowerCase() === lookupKey.toLowerCase()) || monsters[0];

                        if (m.entries) description = flattenEntries(m.entries);
                        else if (m.fluff && m.fluff.entries) description = flattenEntries(m.fluff.entries);
                        else description = `A creature of type ${m.type?.type || m.type || 'unknown'}.`;

                        statBlock = {
                            ac: typeof m.ac[0] === 'number' ? m.ac[0] : (m.ac[0]?.ac || m.ac),
                            hp: typeof m.hp?.average === 'number' ? `${m.hp.average} (${m.hp.formula})` : m.hp?.special,
                            cr: typeof m.cr === 'string' ? m.cr : (m.cr?.cr || '?'),
                            type: typeof m.type === 'string' ? m.type : m.type?.type,
                            abilities: `STR ${m.str} DEX ${m.dex} CON ${m.con} INT ${m.int} WIS ${m.wis} CHA ${m.cha}`
                        };
                    }
                } else if (category === 'spell') {
                    // Search spells database
                    const spells = await searchSpells(lookupKey);
                    if (spells.length > 0) {
                        const s = spells.find(x => x.name.toLowerCase() === lookupKey.toLowerCase()) || spells[0];
                        description = s.description;
                    }
                } else if (category === 'item') {
                    // Search items database DIRECTLY — don't go through lookupByName
                    const items = await searchItems(lookupKey);
                    if (items.length > 0) {
                        const match = items.find(i => i.name.toLowerCase() === lookupKey.toLowerCase()) || items[0];
                        description = match.description || '';
                        // Build a pseudo stat block for weapons/armor
                        if (match.damage || match.acBonus) {
                            const parts: string[] = [];
                            if (match.damage) parts.push(`Damage: ${match.damage}`);
                            if (match.acBonus) parts.push(`AC: ${match.acBonus}`);
                            if (match.weight) parts.push(`Weight: ${match.weight} lb.`);
                            if (description) description += '\n\n';
                            description += parts.join(' | ');
                        }
                        if (!description && match.type) {
                            description = `A ${match.type} item. Weight: ${match.weight || 0} lb.`;
                        }
                    }
                } else if (category === 'npc') {
                    // NPCs: first try lookupByName (lore, rules), then fall back to bestiary
                    const res = await lookupByName(lookupKey);
                    if (res) {
                        description = res.description;
                    } else {
                        // Many named NPCs (Strahd, etc.) are in the bestiary
                        const monsters = await searchMonsters(lookupKey);
                        if (monsters.length > 0) {
                            const m = monsters.find(x => x.name.toLowerCase() === lookupKey.toLowerCase()) || monsters[0];
                            if (m.entries) description = flattenEntries(m.entries);
                            else if (m.fluff && m.fluff.entries) description = flattenEntries(m.fluff.entries);
                            else description = `A creature of type ${m.type?.type || m.type || 'unknown'}.`;
                            statBlock = {
                                ac: typeof m.ac?.[0] === 'number' ? m.ac[0] : (m.ac?.[0]?.ac || '?'),
                                hp: typeof m.hp?.average === 'number' ? `${m.hp.average} (${m.hp.formula})` : m.hp?.special || '?',
                                cr: typeof m.cr === 'string' ? m.cr : (m.cr?.cr || '?'),
                                type: typeof m.type === 'string' ? m.type : m.type?.type,
                                abilities: `STR ${m.str} DEX ${m.dex} CON ${m.con} INT ${m.int} WIS ${m.wis} CHA ${m.cha}`
                            };
                        }
                    }
                } else {
                    // Conditions, locations, lore — generic lookup
                    const res = await lookupByName(lookupKey);
                    if (res) description = res.description;
                }

                // Cache the result — even if empty, to prevent re-fetching
                cacheEntity(lookupKey, {
                    id: lookupKey,
                    name: lookupKey,
                    type: category as any,
                    lookupKey,
                    description: description || `No specific data found for ${lookupKey} in the archives.`,
                    statBlock
                });
            } catch (err) {
                console.error(`[EntityLink] Failed to fetch data for "${lookupKey}":`, err);
                // Cache the error so we don't keep retrying
                cacheEntity(lookupKey, {
                    id: lookupKey,
                    name: lookupKey,
                    type: category as any,
                    lookupKey,
                    description: `Failed to retrieve data for ${lookupKey}. Check your connection.`,
                    statBlock: undefined
                });
            } finally {
                setIsLoading(false);
            }
        };

        fetchData();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [shouldShowTooltip, lookupKey, category, cachedEntity]);

    const Icon = CATEGORY_ICONS[category];

    const description = cachedEntity?.description || (isLoading ? 'Fetching lore...' : `No specific data found for ${lookupKey} in the archives.`);

    return (
        <>
            <span
                ref={elementRef}
                onMouseEnter={() => {
                    cancelHide();
                    setIsHovered(true);
                }}
                onMouseLeave={() => {
                    // When Alt is held, give a small grace period to move to the tooltip
                    // When Alt is NOT held, hide immediately
                    if (altPressed) {
                        scheduleHide();
                    } else {
                        setIsHovered(false);
                        setIsTooltipHovered(false);
                    }
                }}
                className={`
                    relative inline-block cursor-help transition-colors
                    border-b border-dashed font-semibold px-0.5 rounded-sm
                    ${CATEGORY_COLORS[category]}
                `}
            >
                {text}
            </span>

            {/* Tooltip Portal */}
            {shouldShowTooltip && hoverRect && createPortal(
                <div
                    onMouseEnter={() => {
                        cancelHide();
                        setIsTooltipHovered(true);
                        setIsHovered(false); // The mouse is on the tooltip, not the text span anymore
                    }}
                    onMouseLeave={() => {
                        setIsTooltipHovered(false);
                    }}
                    className={`
                        fixed z-[99999] p-4 rounded-xl shadow-[0_20px_50px_rgba(0,0,0,0.7)]
                        bg-stone-950/95 backdrop-blur-xl border border-stone-700/50
                        w-80 max-h-[400px] overflow-y-auto custom-scrollbar
                        animate-in fade-in zoom-in-95 duration-200
                        ${altPressed ? 'pointer-events-auto' : 'pointer-events-none'}
                    `}
                    style={{
                        left: `${Math.max(10, Math.min(window.innerWidth - 330, hoverRect.left + hoverRect.width / 2 - 160))}px`,
                        top: hoverRect.top < 420 ? `${hoverRect.bottom + 10}px` : `${hoverRect.top - 10}px`,
                        transform: hoverRect.top < 420 ? 'none' : 'translateY(-100%)'
                    }}
                >
                    <div className="flex items-start gap-3 mb-3 border-b border-stone-800 pb-3">
                        <div className={`p-2 rounded-lg bg-stone-900 border border-stone-800 ${CATEGORY_COLORS[category].split(' ')[0]}`}>
                            <Icon size={18} />
                        </div>
                        <div>
                            <h4 className="font-cinzel font-bold text-stone-200 text-base tracking-wide leading-tight">
                                {cachedEntity?.name || lookupKey}
                            </h4>
                            <span className="text-[9px] uppercase tracking-widest text-stone-500 font-bold">
                                {category} Reference
                            </span>
                        </div>
                    </div>

                    <div className="text-sm text-stone-300 leading-relaxed font-serif">
                        {isLoading ? (
                            <div className="flex items-center gap-2 text-stone-500 italic pb-2">
                                <Loader2 size={14} className="animate-spin" />
                                Indexing ancient tomes...
                            </div>
                        ) : (
                            <div className={altPressed ? "" : "line-clamp-6"}>
                                {description}
                            </div>
                        )}
                    </div>

                    {altPressed ? (
                        <div className="mt-4 pt-3 border-t border-stone-800 flex justify-between items-center">
                            <span className="text-[10px] text-stone-500 italic">Scrolling enabled</span>
                            {cachedEntity?.statBlock ? (
                                <div className="text-[11px] text-amber-500 font-bold bg-amber-950/30 px-2 py-1 rounded border border-amber-900/50">
                                    AC {cachedEntity.statBlock.ac} | HP {cachedEntity.statBlock.hp} | CR {cachedEntity.statBlock.cr}
                                </div>
                            ) : (
                                <span className="text-xs text-stone-600 italic">No combat statistics</span>
                            )}
                        </div>
                    ) : (
                        <div className="mt-4 pt-3 border-t border-stone-800 text-[10px] text-stone-500 italic flex items-center justify-center gap-2">
                            <Info size={12} className="text-stone-600" />
                            Hold [ALT] to interact & scroll
                        </div>
                    )}
                </div>,
                document.body
            )}
        </>
    );
}

import React, { useState, useCallback, useEffect } from 'react';
import { DungeonMap } from '../../types/campaignNavigator';
import { Settings, X, Upload, Save, Maximize2, Move, Layout, Pencil, Grid, Palette, Eye, EyeOff } from 'lucide-react';
import { useNavigatorStore } from '../../store/navigatorStore';
import { BattleMap } from '../combat/BattleMap';
import { ShapeControls, DrawingMode } from '../combat/ShapeControls';
import { dungeonMapToBattleMapState } from '../../engine/mapBridge';
import { GridPosition, MapShape, FreehandPath } from '../../types/battleMap';

interface Props {
    map: DungeonMap;
    onClose: () => void;
}

type EditorTab = 'rooms' | 'grid' | 'draw' | 'fog';

export function MapSetupEditor({ map, onClose }: Props) {
    const { updateRoomPosition, updateDungeonMapBattleState, updateDungeonMapGrid } = useNavigatorStore();

    // Local state for the entirety of the map being edited
    const [localMap, setLocalMap] = useState<DungeonMap>({ ...map });
    const [activeTab, setActiveTab] = useState<EditorTab>('rooms');
    const [drawingMode, setDrawingMode] = useState<DrawingMode>('select');
    const [draggingRoom, setDraggingRoom] = useState<string | null>(null);

    // Bridge local state to BattleMap component
    const battleMapState = dungeonMapToBattleMapState(localMap);

    // --- Actions ---
    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const url = event.target?.result as string;
            setLocalMap(prev => ({ ...prev, imageUrl: url }));
        };
        reader.readAsDataURL(file);
    };

    const handleUpdateGrid = (updates: Partial<Pick<DungeonMap, 'gridWidth' | 'gridHeight' | 'cellSizePx'>>) => {
        setLocalMap(prev => ({ ...prev, ...updates }));
    };

    const handleBackgroundUpdate = (updates: { offsetDelta?: { dx: number, dy: number }, offset?: { x: number, y: number }, scaleX?: number, scaleY?: number }) => {
        setLocalMap(prev => {
            let newOffset = prev.backgroundOffset || { x: 0, y: 0 };
            if (updates.offsetDelta) {
                newOffset = { x: newOffset.x + updates.offsetDelta.dx, y: newOffset.y + updates.offsetDelta.dy };
            } else if (updates.offset) {
                newOffset = updates.offset;
            }

            return {
                ...prev,
                backgroundOffset: newOffset,
                backgroundScaleX: updates.scaleX !== undefined ? updates.scaleX : prev.backgroundScaleX,
                backgroundScaleY: updates.scaleY !== undefined ? updates.scaleY : prev.backgroundScaleY
            };
        });
    };

    const handleShapeAdd = (shape: MapShape) => {
        setLocalMap(prev => ({ ...prev, shapes: [...prev.shapes, shape] }));
    };

    const handleFreehandAdd = (path: FreehandPath) => {
        setLocalMap(prev => ({ ...prev, freehandPaths: [...prev.freehandPaths, path] }));
    };

    const handleFogAdd = (shape: MapShape) => {
        setLocalMap(prev => ({ ...prev, fogOfWar: [...prev.fogOfWar, shape] }));
    };

    const handleFogFreehandAdd = (path: FreehandPath) => {
        setLocalMap(prev => ({ ...prev, fogOfWarFreehand: [...prev.fogOfWarFreehand, path] }));
    };

    const handleClearDrawings = () => {
        setLocalMap(prev => ({
            ...prev,
            shapes: [],
            freehandPaths: [],
            fogOfWar: [],
            fogOfWarFreehand: []
        }));
    };

    const handleResizeGrid = (side: 'top' | 'bottom' | 'left' | 'right', delta: number) => {
        setLocalMap(prev => {
            const isHorizontal = side === 'left' || side === 'right';
            const newWidth = isHorizontal ? Math.max(5, prev.gridWidth + delta) : prev.gridWidth;
            const newHeight = !isHorizontal ? Math.max(5, prev.gridHeight + delta) : prev.gridHeight;

            const appliedDelta = isHorizontal ? (newWidth - prev.gridWidth) : (newHeight - prev.gridHeight);
            const colShift = side === 'left' ? appliedDelta : 0;
            const rowShift = side === 'top' ? appliedDelta : 0;

            const shiftGridPos = (p: GridPosition) => ({
                col: p.col + colShift,
                row: p.row + rowShift
            });

            const updatedTokens = prev.tokens.map(token => ({
                ...token,
                position: {
                    col: Math.max(0, Math.min(token.position.col + colShift, newWidth - (token.size || 1))),
                    row: Math.max(0, Math.min(token.position.row + rowShift, newHeight - (token.size || 1)))
                }
            }));

            const updatedShapes = prev.shapes.map(s => ({
                ...s,
                points: s.points.map(shiftGridPos)
            }));

            const pxColShift = colShift * prev.cellSizePx;
            const pxRowShift = rowShift * prev.cellSizePx;
            const updatedPaths = prev.freehandPaths.map(path => ({
                ...path,
                points: path.points.map(p => ({ x: p.x + pxColShift, y: p.y + pxRowShift }))
            }));

            const updatedFoW = prev.fogOfWar.map(s => ({
                ...s,
                points: s.points.map(shiftGridPos)
            }));
            const updatedFoWFree = prev.fogOfWarFreehand.map(path => ({
                ...path,
                points: path.points.map(p => ({ x: p.x + pxColShift, y: p.y + pxRowShift }))
            }));

            let newBackgroundOffset = prev.backgroundOffset;
            if (newBackgroundOffset) {
                newBackgroundOffset = {
                    x: newBackgroundOffset.x + pxColShift,
                    y: newBackgroundOffset.y + pxRowShift
                };
            }

            return {
                ...prev,
                gridWidth: newWidth,
                gridHeight: newHeight,
                tokens: updatedTokens,
                shapes: updatedShapes,
                freehandPaths: updatedPaths,
                fogOfWar: updatedFoW,
                fogOfWarFreehand: updatedFoWFree,
                backgroundOffset: newBackgroundOffset
            };
        });
    };

    // --- Room Dragging (using grid-relative positioning if we wanted, but keeping % for now for compatibility) ---
    const handleRoomMouseDown = (e: React.MouseEvent, roomId: string) => {
        if (activeTab !== 'rooms') return;
        e.stopPropagation();
        setDraggingRoom(roomId);
    };

    // Simplified percentage-based dragging for the editor
    const handleRoomMouseMove = useCallback((e: MouseEvent) => {
        if (!draggingRoom) return;

        // In the new editor, rooms sit on the grid container
        // We can just use the BattleMap's internal cursor logic if we wanted,
        // but for now let's just use mouse coords relative to the transformed div.
        // Actually, let's keep it simple: rooms are % based on the total grid size.
        const gridEl = document.querySelector('.battle-map-grid');
        if (!gridEl) return;

        const rect = gridEl.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        // rect.width/height already accounts for zoom transforms
        const pctX = (mouseX / rect.width) * 100;
        const pctY = (mouseY / rect.height) * 100;

        setLocalMap(prev => ({
            ...prev,
            rooms: prev.rooms.map(r => r.id === draggingRoom ? {
                ...r,
                x: Math.max(0, Math.min(100 - r.width, pctX - (r.width / 2))),
                y: Math.max(0, Math.min(100 - r.height, pctY - (r.height / 2)))
            } : r)
        }));
    }, [draggingRoom, localMap.gridWidth, localMap.gridHeight, localMap.cellSizePx]);

    useEffect(() => {
        if (draggingRoom) {
            const up = () => setDraggingRoom(null);
            window.addEventListener('mousemove', handleRoomMouseMove);
            window.addEventListener('mouseup', up);
            return () => {
                window.removeEventListener('mousemove', handleRoomMouseMove);
                window.removeEventListener('mouseup', up);
            };
        }
    }, [draggingRoom, handleRoomMouseMove]);

    const handleSave = () => {
        // 1. Update Grid
        updateDungeonMapGrid(map.id, {
            gridWidth: localMap.gridWidth,
            gridHeight: localMap.gridHeight,
            cellSizePx: localMap.cellSizePx,
            gridColor: localMap.gridColor
        });

        // 2. Update Battle State (Bulk)
        updateDungeonMapBattleState(map.id, {
            shapes: localMap.shapes,
            freehandPaths: localMap.freehandPaths,
            fogOfWar: localMap.fogOfWar,
            fogOfWarFreehand: localMap.fogOfWarFreehand,
            backgroundOffset: localMap.backgroundOffset,
            backgroundScaleX: localMap.backgroundScaleX,
            backgroundScaleY: localMap.backgroundScaleY,
            imageUrl: localMap.imageUrl,
            tokens: localMap.tokens
        });

        // 3. Update Rooms
        localMap.rooms.forEach(r => {
            updateRoomPosition(map.id, r.id, { x: r.x, y: r.y, width: r.width, height: r.height });
        });

        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100000] bg-stone-950 flex flex-col font-cinzel overflow-hidden">
            {/* ═══ TOP HEADER ═══ */}
            <header className="h-16 border-b border-white/5 bg-stone-900/60 backdrop-blur-xl flex items-center justify-between px-6 z-50 shrink-0">
                <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-amber-500/10 border border-amber-500/30 rounded-xl flex items-center justify-center text-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.2)]">
                        <Settings size={20} />
                    </div>
                    <div>
                        <h2 className="text-lg font-bold text-white tracking-tight uppercase leading-tight">Cartography Studio</h2>
                        <p className="text-[9px] text-stone-500 font-black uppercase tracking-widest">{map.name} — Editor</p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    <div className="relative">
                        <input type="file" accept="image/*" onChange={handleImageUpload} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                        <button className="px-4 py-2 bg-stone-800 hover:bg-stone-700 text-stone-200 border border-stone-600 rounded-xl text-xs font-bold uppercase tracking-widest flex items-center gap-2 transition-all transition-colors cursor-pointer">
                            <Upload size={14} />
                            Source Image
                        </button>
                    </div>
                    <div className="w-px h-6 bg-white/10 mx-2" />
                    <button onClick={onClose} className="px-4 py-2 bg-stone-900/40 hover:bg-red-500/10 hover:text-red-400 text-stone-400 rounded-xl flex items-center gap-2 transition-all border border-white/5 text-xs font-bold uppercase tracking-widest">
                        <X size={14} /> Cancel
                    </button>
                    <button onClick={handleSave} className="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-stone-950 font-black rounded-xl flex items-center gap-2 transition-all active:scale-95 shadow-[0_10px_30px_rgba(245,158,11,0.2)] text-xs uppercase tracking-widest">
                        <Save size={14} /> Save Changes
                    </button>
                </div>
            </header>

            <div className="flex flex-1 overflow-hidden">
                {/* ═══ SIDEBAR: TOOLS ═══ */}
                <aside className="w-80 border-r border-white/5 bg-stone-900/20 backdrop-blur-md flex flex-col z-40 shrink-0">
                    <div className="flex border-b border-white/5 shrink-0">
                        <button
                            onClick={() => { setActiveTab('rooms'); setDrawingMode('select'); }}
                            className={`flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'rooms' ? 'text-amber-500 bg-amber-500/10' : 'text-stone-500 hover:text-stone-300'}`}
                        >
                            <Layout size={14} />
                            Rooms
                        </button>
                        <button
                            onClick={() => { setActiveTab('grid'); setDrawingMode('select'); }}
                            className={`flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'grid' ? 'text-amber-500 bg-amber-500/10' : 'text-stone-500 hover:text-stone-300'}`}
                        >
                            <Grid size={14} />
                            Grid
                        </button>
                        <button
                            onClick={() => { setActiveTab('draw'); setDrawingMode('select'); }}
                            className={`flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'draw' ? 'text-amber-500 bg-amber-500/10' : 'text-stone-500 hover:text-stone-300'}`}
                        >
                            <Pencil size={14} />
                            Draw
                        </button>
                        <button
                            onClick={() => { setActiveTab('fog'); setDrawingMode('select'); }}
                            className={`flex-1 py-3 flex flex-col items-center gap-1 text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === 'fog' ? 'text-amber-500 bg-amber-500/10' : 'text-stone-500 hover:text-stone-300'}`}
                        >
                            <EyeOff size={14} />
                            Fog
                        </button>
                    </div>

                    <div className="flex-1 overflow-y-auto p-5 custom-scrollbar space-y-8">
                        {activeTab === 'rooms' && (
                            <div className="space-y-4">
                                <h3 className="text-[10px] font-black uppercase tracking-widest text-amber-500/80">Narrative Overlays</h3>
                                <p className="text-[10px] text-stone-500 leading-relaxed italic border-l-2 border-stone-800 pl-3">
                                    Click and drag the room labels to position them on the map. These will be visible to you during exploration.
                                </p>
                                <div className="space-y-2 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                    {localMap.rooms.map(r => (
                                        <div key={r.id} className="p-3 bg-stone-950/40 border border-white/5 rounded-xl flex items-center justify-between group hover:border-amber-500/30 transition-all">
                                            <div className="flex items-center gap-2">
                                                <span className="text-[11px] font-black text-amber-500">{r.label}</span>
                                                <span className="text-[11px] text-stone-300 truncate max-w-[120px]">{r.name}</span>
                                            </div>
                                            <Move size={12} className="text-stone-600 group-hover:text-amber-500 transition-colors" />
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {activeTab === 'grid' && (
                            <div className="space-y-8">
                                <section className="space-y-4">
                                    <h3 className="text-[10px] font-black uppercase tracking-widest text-amber-500/80">Grid Geometry</h3>
                                    <div className="grid grid-cols-2 gap-3">
                                        <div className="space-y-2">
                                            <label className="text-[9px] font-black uppercase text-stone-500">Columns</label>
                                            <input
                                                type="number" value={localMap.gridWidth}
                                                onChange={(e) => handleUpdateGrid({ gridWidth: parseInt(e.target.value) })}
                                                className="w-full bg-stone-950 border border-white/5 rounded-xl p-3 text-xs font-mono text-amber-500 hover:bg-black focus:border-amber-500/50 outline-none transition-all"
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[9px] font-black uppercase text-stone-500">Rows</label>
                                            <input
                                                type="number" value={localMap.gridHeight}
                                                onChange={(e) => handleUpdateGrid({ gridHeight: parseInt(e.target.value) })}
                                                className="w-full bg-stone-950 border border-white/5 rounded-xl p-3 text-xs font-mono text-amber-500 hover:bg-black focus:border-amber-500/50 outline-none transition-all"
                                            />
                                        </div>
                                    </div>
                                    <div className="space-y-3 pt-2">
                                        <div className="flex justify-between items-center text-[9px] font-black uppercase text-stone-500 tracking-widest">
                                            <span>Cell Size</span>
                                            <span className="text-amber-500 font-mono">{localMap.cellSizePx}px</span>
                                        </div>
                                        <input
                                            type="range" min="16" max="128" value={localMap.cellSizePx}
                                            onChange={(e) => handleUpdateGrid({ cellSizePx: parseInt(e.target.value) })}
                                            className="w-full accent-amber-600 h-1 bg-stone-900 rounded-lg appearance-none cursor-pointer"
                                        />
                                    </div>
                                </section>

                                {localMap.imageUrl && (
                                    <section className="space-y-4">
                                        <h3 className="text-[10px] font-black uppercase tracking-widest text-amber-500/80">Calibration</h3>
                                        <div className="space-y-4 bg-stone-950/40 p-4 rounded-2xl border border-white/5">
                                            <button
                                                onClick={() => setDrawingMode(prev => prev === 'calibrate' ? 'select' : 'calibrate')}
                                                className={`w-full py-3 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all flex items-center justify-center gap-2 ${drawingMode === 'calibrate' ? 'bg-amber-600 border-amber-400 text-stone-950 shadow-lg' : 'bg-stone-900 border-white/5 text-stone-500 hover:text-stone-300'}`}
                                            >
                                                {drawingMode === 'calibrate' ? <Maximize2 size={14} /> : <Move size={14} />}
                                                {drawingMode === 'calibrate' ? 'Stop Positioning' : 'Move Background'}
                                            </button>

                                            <div className="space-y-3">
                                                <div className="flex justify-between text-[9px] font-black uppercase text-stone-500">
                                                    <span>Stretch Width</span>
                                                    <span className="text-amber-500">{Math.round((localMap.backgroundScaleX || 1) * 100)}%</span>
                                                </div>
                                                <input type="range" min="0.5" max="3" step="0.01" value={localMap.backgroundScaleX || 1} onChange={(e) => handleBackgroundUpdate({ scaleX: parseFloat(e.target.value) })} className="w-full accent-amber-600 h-1 bg-stone-900 rounded-lg" />

                                                <div className="flex justify-between text-[9px] font-black uppercase text-stone-500">
                                                    <span>Stretch Height</span>
                                                    <span className="text-amber-500">{Math.round((localMap.backgroundScaleY || 1) * 100)}%</span>
                                                </div>
                                                <input type="range" min="0.5" max="3" step="0.01" value={localMap.backgroundScaleY || 1} onChange={(e) => handleBackgroundUpdate({ scaleY: parseFloat(e.target.value) })} className="w-full accent-amber-600 h-1 bg-stone-900 rounded-lg" />
                                            </div>

                                            <button
                                                onClick={() => setLocalMap(prev => ({ ...prev, backgroundOffset: { x: 0, y: 0 }, backgroundScaleX: 1, backgroundScaleY: 1 }))}
                                                className="w-full py-2 bg-stone-900 border border-white/5 rounded-xl text-[9px] font-black uppercase text-stone-600 hover:text-stone-400 transition-all"
                                            >
                                                Reset Positioning
                                            </button>
                                        </div>
                                    </section>
                                )}
                            </div>
                        )}

                        {(activeTab === 'draw' || activeTab === 'fog') && (
                            <div className="space-y-4">
                                <h3 className="text-[10px] font-black uppercase tracking-widest text-amber-500/80">
                                    {activeTab === 'draw' ? 'Strategic Markings' : 'Fog of War Tools'}
                                </h3>
                                <ShapeControls
                                    currentMode={drawingMode}
                                    onModeChange={(m) => setDrawingMode(prev => prev === m ? 'select' : m)}
                                    onClearAll={handleClearDrawings}
                                    onUndo={() => { }}
                                    canUndo={false}
                                    className="w-full border-none p-0 bg-transparent shadow-none"
                                />
                                {activeTab === 'fog' && (
                                    <div className="pt-4 space-y-3">
                                        <button
                                            onClick={() => setDrawingMode('fow-hide')}
                                            className={`w-full py-3 rounded-xl border flex items-center justify-center gap-3 transition-all ${drawingMode === 'fow-hide' ? 'bg-stone-950 border-white text-white' : 'bg-stone-900 border-white/5 text-stone-500'}`}
                                        >
                                            <EyeOff size={16} />
                                            <span className="text-[10px] font-black uppercase tracking-widest">Add Fog (Hide)</span>
                                        </button>
                                        <button
                                            onClick={() => setDrawingMode('fow-reveal')}
                                            className={`w-full py-3 rounded-xl border flex items-center justify-center gap-3 transition-all ${drawingMode === 'fow-reveal' ? 'bg-white border-white text-stone-950' : 'bg-stone-900 border-white/5 text-stone-500'}`}
                                        >
                                            <Eye size={16} />
                                            <span className="text-[10px] font-black uppercase tracking-widest">Clear Fog (Reveal)</span>
                                        </button>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="p-4 border-t border-white/5 bg-stone-950/20 text-[9px] text-stone-600 italic leading-relaxed text-center">
                        Scroll to zoom • RMB to pan • Shift+Drag to measure
                    </div>
                </aside>

                {/* ═══ CANVAS AREA ═══ */}
                <main className="flex-1 relative bg-black overflow-hidden">
                    <BattleMap
                        mapState={battleMapState}
                        tokens={localMap.tokens}
                        drawingMode={drawingMode}
                        onDrawingModeChange={setDrawingMode}
                        onBackgroundUpdate={handleBackgroundUpdate}
                        onShapeAdd={handleShapeAdd}
                        onFreehandPathAdd={handleFreehandAdd}
                        onFogOfWarAdd={handleFogAdd}
                        onFogOfWarFreehandAdd={handleFogFreehandAdd}
                        onResizeGrid={handleResizeGrid}
                        className="w-full h-full"
                    >
                        {/* THE BATTLE MAP GRID CLASS IS USED BY ROOM DRAGGING LOGIC */}
                        <div className="battle-map-grid absolute inset-0 pointer-events-none" style={{ width: localMap.gridWidth * localMap.cellSizePx, height: localMap.gridHeight * localMap.cellSizePx }}>
                            {activeTab === 'rooms' && localMap.rooms.map(room => (
                                <div
                                    key={room.id}
                                    onMouseDown={(e) => handleRoomMouseDown(e, room.id)}
                                    className={`
                                        absolute rounded border-2 shadow-2xl transition-all backdrop-blur-sm pointer-events-auto
                                        ${draggingRoom === room.id
                                            ? 'bg-amber-600/60 border-amber-400 z-[100] scale-105 cursor-grabbing'
                                            : 'bg-amber-950/20 border-amber-500/60 hover:border-amber-400 cursor-grab hover:bg-amber-900/30'}
                                    `}
                                    style={{
                                        left: `${room.x}%`,
                                        top: `${room.y}%`,
                                        width: `${room.width}%`,
                                        height: `${room.height}%`,
                                        borderRadius: room.shape === 'circle' ? '50%' : undefined,
                                    }}
                                >
                                    <div className="absolute inset-0 flex flex-col items-center justify-center font-cinzel font-black text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)] text-[11px] text-center pointer-events-none px-1 leading-tight tracking-widest uppercase brightness-125">
                                        {room.label}
                                        <span className="text-[8px] font-bold text-amber-300/80 truncate max-w-full">{room.name}</span>
                                    </div>
                                    {draggingRoom !== room.id && (
                                        <div className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 pointer-events-none">
                                            <Move size={10} className="text-amber-400/60" />
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </BattleMap>

                    {/* Status HUD (Left Bottom) */}
                    <div className="absolute bottom-6 left-6 z-50 flex items-center gap-3">
                        <div className="bg-stone-900/80 backdrop-blur-xl border border-white/5 h-10 px-4 rounded-xl flex items-center gap-4 shadow-2xl">
                            <div className="flex items-center gap-2">
                                <Layout size={14} className="text-amber-500" />
                                <span className="text-[10px] font-black uppercase text-white/90">{localMap.rooms.length} Rooms</span>
                            </div>
                            <div className="w-px h-4 bg-white/10" />
                            <div className="flex items-center gap-2">
                                <Palette size={14} className="text-amber-500" />
                                <span className="text-[10px] font-black uppercase text-white/90">{localMap.shapes.length + localMap.freehandPaths.length} Drawings</span>
                            </div>
                            <div className="w-px h-4 bg-white/10" />
                            <div className="flex items-center gap-2">
                                <EyeOff size={14} className="text-amber-500" />
                                <span className="text-[10px] font-black uppercase text-white/90">{localMap.fogOfWar.length} Fog Points</span>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { NarrationBlock as NarrationBlockType, SceneEncounter } from '../../types/campaignNavigator';
import { Scroll, MessageCircle, Wind, Lightbulb, Swords, Gem, ShieldQuestion, ArrowRight, Loader2, FileUp, Edit2, Save, X } from 'lucide-react';
import { parseNarrationText } from '../../engine/entityEnrichment';
import { useCombatStore } from '../../store/combatStore';
import { searchMonsters } from '../../engine/fiveEToolsParser';
import { convertMonsterToCombatant } from '../../engine/combatEngine';
import { useCampaignStore } from '../../store/campaignStore';
import { useCharacterStore } from '../../store/characterStore';

import { useNavigatorStore } from '../../store/navigatorStore';

interface Props {
    block: NarrationBlockType;
    isAnimating?: boolean;
    sceneEncounter?: SceneEncounter;
}


export function NarrationBlock({ block, isAnimating, sceneEncounter }: Props) {
    const navigate = useNavigate();
    const startEncounter = useCombatStore(state => state.startEncounter);
    const addCombatant = useCombatStore(state => state.addCombatant);
    const [isLoadingEncounter, setIsLoadingEncounter] = useState(false);
    const campaigns = useCampaignStore(state => state.campaigns);
    const activeCampaignId = useCampaignStore(state => state.activeCampaignId);
    const characters = useCharacterStore(state => state.characters);
    const addItem = useCharacterStore(state => state.addItem);
    const updateNarrationBlock = useNavigatorStore(state => state.updateNarrationBlock);
    const currentSceneId = useNavigatorStore(state => state.currentSceneId);

    const [isEditingNote, setIsEditingNote] = useState(false);
    const [noteText, setNoteText] = useState(block.text);

    useEffect(() => {
        setNoteText(block.text);
    }, [block.text]);

    const handleSaveNote = () => {
        if (currentSceneId) {
            updateNarrationBlock(currentSceneId, block.id, noteText);
        }
        setIsEditingNote(false);
    };

    const handleCancelNote = () => {
        setNoteText(block.text);
        setIsEditingNote(false);
    };

    // ── Read-Aloud Box ──────────────────────────────────────
    if (block.type === 'read-aloud') {
        return (
            <div className={`
                relative my-6 p-6 rounded-lg
                bg-gradient-to-br from-amber-950/40 to-stone-900/60
                border border-amber-700/40
                shadow-[0_0_20px_rgba(217,119,6,0.08)]
                transition-all duration-700
                ${isAnimating ? 'opacity-0 translate-y-4' : 'opacity-100 translate-y-0'}
            `}>
                {/* Gold accent bar */}
                <div className="absolute left-0 top-0 bottom-0 w-1 bg-gradient-to-b from-amber-500 via-amber-600 to-amber-800 rounded-l-lg" />

                <div className="flex items-center gap-2 mb-3">
                    <Scroll size={14} className="text-amber-500" />
                    <span className="text-[10px] uppercase tracking-[0.2em] text-amber-500/70 font-cinzel font-bold">Read Aloud</span>
                </div>

                <p className="text-amber-100/90 leading-[1.9] text-[15px] italic font-serif pl-4">
                    {parseNarrationText(block.text)}
                </p>
            </div>
        );
    }

    // ── Dialog Box ───────────────────────────────────────────
    if (block.type === 'dialog') {
        return (
            <div className={`
                my-5 pl-5 border-l-2 border-teal-600/40
                transition-all duration-700
                ${isAnimating ? 'opacity-0 translate-x-4' : 'opacity-100 translate-x-0'}
            `}>
                {block.speaker && (
                    <div className="flex items-center gap-2 mb-1.5">
                        <MessageCircle size={13} className="text-teal-400" />
                        <span className="text-teal-300 font-cinzel text-sm font-bold tracking-wide">
                            {block.speaker}
                        </span>
                        {block.emotion && (
                            <span className="text-stone-500 text-xs italic">— {block.emotion}</span>
                        )}
                    </div>
                )}
                <p className="text-stone-200 leading-[1.8] text-[15px] italic">
                    "{parseNarrationText(block.text)}"
                </p>
            </div>
        );
    }

    // ── Atmosphere ───────────────────────────────────────────
    if (block.type === 'atmosphere') {
        return (
            <div className={`
                my-5 px-6 py-4
                bg-gradient-to-r from-teal-950/20 via-transparent to-purple-950/20
                border-y border-stone-700/20
                transition-all duration-700
                ${isAnimating ? 'opacity-0' : 'opacity-100'}
            `}>
                <div className="flex items-start gap-3">
                    <Wind size={16} className="text-teal-500/60 mt-1 shrink-0" />
                    <p className="text-stone-400 leading-[1.9] text-sm italic tracking-wide">
                        {parseNarrationText(block.text)}
                    </p>
                </div>
            </div>
        );
    }

    // ── DM Note (Hidden Tip) ──────────────────────────────
    if (block.type === 'dm-note') {
        return (
            <div className={`
                my-4 p-4 rounded-md
                bg-purple-950/20 border border-purple-800/30
                group relative transition-all duration-700
                ${isAnimating ? 'opacity-0 translate-y-2' : 'opacity-100 translate-y-0'}
            `}>
                <div className="flex items-start gap-3">
                    <Lightbulb size={15} className="text-purple-400 mt-0.5 shrink-0" />
                    <div className="flex-1">
                        <div className="flex items-center justify-between mb-1">
                            <span className="text-[10px] uppercase tracking-[0.15em] text-purple-400/70 font-bold">DM Confidential</span>
                            {!isEditingNote && (
                                <button
                                    onClick={() => setIsEditingNote(true)}
                                    className="opacity-0 group-hover:opacity-100 p-1 hover:bg-stone-800 rounded transition-all text-stone-500 hover:text-gold"
                                >
                                    <Edit2 size={12} />
                                </button>
                            )}
                        </div>

                        {isEditingNote ? (
                            <div className="space-y-2 animate-in fade-in duration-300">
                                <textarea
                                    value={noteText}
                                    onChange={(e) => setNoteText(e.target.value)}
                                    className="w-full bg-stone-950 border border-stone-700 rounded p-2 text-sm text-stone-200 focus:border-gold/50 outline-none min-h-[80px] font-sans"
                                    autoFocus
                                />
                                <div className="flex justify-end gap-2">
                                    <button onClick={handleCancelNote} className="px-2 py-1 text-[10px] font-bold uppercase text-stone-500 hover:text-stone-300 flex items-center gap-1">
                                        <X size={10} /> Cancel
                                    </button>
                                    <button onClick={handleSaveNote} className="px-2 py-1 bg-gold/10 hover:bg-gold/20 border border-gold/30 text-gold text-[10px] font-bold uppercase rounded flex items-center gap-1">
                                        <Save size={10} /> Save Changes
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <p className="text-purple-200/70 leading-[1.7] text-sm">{parseNarrationText(block.text)}</p>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    // ── Encounter Reference ─────────────────────────────────
    if (block.type === 'encounter-ref') {
        const handleRunEncounter = async () => {
            if (!sceneEncounter || sceneEncounter.monsters.length === 0) return;
            setIsLoadingEncounter(true);

            try {
                // If there's an active encounter already, maybe clear it or warn?
                // For now, let's just start a new one, overriding.
                startEncounter(`Encounter: ${sceneEncounter.monsters.map(m => m.name).join(', ')}`, [], activeCampaignId || undefined);

                // Add party members if in a campaign
                const activeCampaign = campaigns.find(c => c.id === activeCampaignId);
                if (activeCampaign) {
                    for (const charId of activeCampaign.partyIds) {
                        const char = characters.find(c => c.id === charId);
                        if (char) {
                            const getVal = (field: string, fallback: any) => {
                                const ov = char.customOverrides?.overrides?.find((o: any) => o.field === field && o.isActive);
                                return ov ? ov.value : (char as any)[field] ?? fallback;
                            };

                            addCombatant({
                                id: crypto.randomUUID(),
                                sourceId: char.id,
                                type: 'player',
                                name: char.name,
                                ac: Number(getVal('ac', 10)),
                                maxHp: Number(char.maxHp) || 10,
                                currentHp: Number(char.currentHp) || 10,
                                tempHp: Number(char.tempHp) || 0,
                                speed: getVal('speed', '30 ft'),
                                initiativeMod: Number(getVal('initiativeMod', 0)),
                                initiativeScore: null,
                                dexterityScore: Number(char.abilityScores?.dex) || 10,
                                conditions: char.conditions ? [...char.conditions] : [],
                                abilityScores: char.abilityScores ? { ...char.abilityScores } : undefined,
                                savingThrowProficiencies: char.savingThrows || [],
                                proficiencyBonus: Number(char.proficiencyBonus) || 2,
                                spellcastingAbility: char.spellcastingAbility,
                                spellSaveDc: Number(char.spellSaveDc) || 0,
                                spellAttackMod: Number(char.spellAttackMod) || 0,
                                portraitUrl: char.portraitUrl, // using portraitUrl from character type
                            });
                        }
                    }
                }

                // Fetch and parse all monsters
                for (const monsterReq of sceneEncounter.monsters) {
                    // Try to find exact match first
                    const results = await searchMonsters(monsterReq.name);
                    const bestMatch = results.find(r => r.name.toLowerCase() === monsterReq.name.toLowerCase()) || results[0];

                    if (bestMatch) {
                        for (let i = 0; i < monsterReq.count; i++) {
                            const customName = monsterReq.count > 1 ? `${bestMatch.name} ${String.fromCharCode(65 + i)}` : bestMatch.name;
                            const combatant = convertMonsterToCombatant(bestMatch, customName);
                            addCombatant(combatant);
                        }
                    } else {
                        console.warn(`Could not find monster: ${monsterReq.name}`);
                    }
                }

                // Navigate to combat tracker
                navigate('/combat');
            } catch (error) {
                console.error("Failed to run encounter:", error);
            } finally {
                setIsLoadingEncounter(false);
            }
        };

        return (
            <div className={`
                my-5 p-4 rounded-lg
                bg-gradient-to-r from-red-950/30 to-stone-900/40
                border border-red-800/30
                transition-all duration-700
                ${isAnimating ? 'opacity-0 scale-95' : 'opacity-100 scale-100'}
            `}>
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-red-900/40 rounded-md border border-red-700/30">
                            <Swords size={16} className="text-red-400" />
                        </div>
                        <div>
                            <span className="text-[10px] uppercase tracking-[0.15em] text-red-400/70 font-bold">Combat Encounter</span>
                            <p className="text-stone-300 text-sm mt-0.5">{parseNarrationText(block.text)}</p>
                            {block.encounterDetails && (
                                <p className="text-stone-500 text-xs mt-1">{parseNarrationText(block.encounterDetails)}</p>
                            )}
                        </div>
                    </div>
                    {sceneEncounter && (
                        <button
                            type="button"
                            onClick={handleRunEncounter}
                            disabled={isLoadingEncounter}
                            className={`px-4 py-2 flex items-center gap-2 bg-red-900/50 hover:bg-red-800/60 text-red-300 text-xs font-bold uppercase tracking-wider rounded-md border border-red-700/40 hover:border-red-600/50 transition-all hover:shadow-[0_0_15px_rgba(220,38,38,0.15)] ${isLoadingEncounter ? 'opacity-50 cursor-not-allowed' : ''}`}
                        >
                            {isLoadingEncounter ? <Loader2 size={14} className="animate-spin" /> : '⚔️'}
                            {isLoadingEncounter ? 'Summoning...' : 'Run Encounter'}
                        </button>
                    )}
                </div>
            </div>
        );
    }

    // ── Loot Reference ──────────────────────────────────────
    if (block.type === 'loot-ref') {
        const activeCampaign = campaigns.find(c => c.id === activeCampaignId);
        const partyMembers = activeCampaign ? characters.filter(c => activeCampaign.partyIds.includes(c.id)) : [];

        return (
            <div className={`
                my-4 p-4 rounded-md
                bg-amber-950/15 border border-amber-800/25
                transition-all duration-700
                ${isAnimating ? 'opacity-0 translate-y-2' : 'opacity-100 translate-y-0'}
            `}>
                <div className="flex items-start gap-3">
                    <Gem size={15} className="text-amber-400 mt-0.5 shrink-0" />
                    <div className="flex-1 w-full">
                        <span className="text-[10px] uppercase tracking-[0.15em] text-amber-500/70 font-bold">Treasure Found</span>
                        <p className="text-amber-200/80 leading-[1.7] text-sm mt-1">{parseNarrationText(block.text)}</p>

                        <LootDispatcher block={block} partyMembers={partyMembers} addItem={addItem} />
                    </div>
                </div>
            </div>
        );
    }

    // ── Skill Check ─────────────────────────────────────────
    if (block.type === 'skill-check') {
        const activeCampaign = campaigns.find(c => c.id === activeCampaignId);
        const partyMembers = activeCampaign ? characters.filter(c => activeCampaign.partyIds.includes(c.id)) : [];

        return (
            <div className={`
                my-4 p-4 rounded-md
                bg-blue-950/20 border border-blue-800/30
                transition-all duration-700
                ${isAnimating ? 'opacity-0 translate-y-2' : 'opacity-100 translate-y-0'}
            `}>
                <div className="flex items-start gap-3">
                    <ShieldQuestion size={15} className="text-blue-400 mt-0.5 shrink-0" />
                    <div className="flex-1">
                        <span className="text-[10px] uppercase tracking-[0.15em] text-blue-400/70 font-bold">Skill Check</span>
                        <p className="text-blue-200/80 leading-[1.7] text-sm mt-1">{parseNarrationText(block.text)}</p>

                        <SkillCheckRoller block={block} partyMembers={partyMembers} />
                    </div>
                </div>
            </div>
        );
    }

    // ── Transition ──────────────────────────────────────────
    if (block.type === 'transition') {
        return (
            <div className={`
                my-8 flex items-center gap-4
                transition-all duration-700
                ${isAnimating ? 'opacity-0' : 'opacity-100'}
            `}>
                <div className="flex-1 h-px bg-gradient-to-r from-transparent via-stone-600/40 to-transparent" />
                <p className="text-stone-500 text-xs italic tracking-wide flex items-center gap-2">
                    <ArrowRight size={12} />
                    {parseNarrationText(block.text)}
                </p>
                <div className="flex-1 h-px bg-gradient-to-r from-transparent via-stone-600/40 to-transparent" />
            </div>
        );
    }

    // ── Default Description ─────────────────────────────────
    return (
        <div className={`
            my-4
            transition-all duration-700
            ${isAnimating ? 'opacity-0 translate-y-3' : 'opacity-100 translate-y-0'}
        `}>
            <p className="text-stone-300 leading-[1.9] text-[15px]">
                {parseNarrationText(block.text)}
            </p>
        </div>
    );
}

function SkillCheckRoller({ block, partyMembers }: any) {
    const [selectedChar, setSelectedChar] = useState<any>(null);
    const [charModifier, setCharModifier] = useState<number>(0);
    const [inputValue, setInputValue] = useState<string>('');
    const [result, setResult] = useState<any>(null);

    // Extract DC and Skill from text
    const dcMatch = block.text.match(/DC\s*(\d+)/i);
    const dc = dcMatch ? parseInt(dcMatch[1]) : 10;

    const skills = ['Athletics', 'Acrobatics', 'Sleight of Hand', 'Stealth', 'Arcana', 'History', 'Investigation', 'Nature', 'Religion', 'Animal Handling', 'Insight', 'Medicine', 'Perception', 'Survival', 'Deception', 'Intimidation', 'Performance', 'Persuasion'];
    const skillMatch = skills.find((s: string) => block.text.toLowerCase().includes(s.toLowerCase()));

    const handleSelectChar = (char: any) => {
        // Find modifier
        let modifier = 0;
        if (skillMatch) {
            const charSkill = char.skills?.find((s: any) => s.name.toLowerCase() === skillMatch.toLowerCase());
            if (charSkill) {
                // Calculate modifier from skill (simplified: ability mod + proficiency)
                const stat = charSkill.stat?.toLowerCase() || 'str';
                const abilityMod = Math.floor(((char.abilityScores?.[stat] || 10) - 10) / 2);
                const prof = charSkill.proficient ? (char.proficiencyBonus || 2) : 0;
                const expert = charSkill.expertise ? (char.proficiencyBonus || 2) : 0;
                modifier = abilityMod + prof + expert + (charSkill.bonus || 0);
            } else {
                // Fallback to raw ability
                const statMap: Record<string, string> = {
                    'Athletics': 'str', 'Acrobatics': 'dex', 'Sleight of Hand': 'dex', 'Stealth': 'dex',
                    'Arcana': 'int', 'History': 'int', 'Investigation': 'int', 'Nature': 'int', 'Religion': 'int',
                    'Animal Handling': 'wis', 'Insight': 'wis', 'Medicine': 'wis', 'Perception': 'wis', 'Survival': 'wis',
                    'Deception': 'cha', 'Intimidation': 'cha', 'Performance': 'cha', 'Persuasion': 'cha'
                };
                const stat = statMap[skillMatch] || 'str';
                modifier = Math.floor(((char.abilityScores?.[stat] || 10) - 10) / 2);
            }
        }

        setSelectedChar(char);
        setCharModifier(modifier);
        setInputValue('');
        setResult(null);
    };

    const handleResolve = () => {
        const d20 = parseInt(inputValue);
        if (isNaN(d20)) return;

        const total = d20 + charModifier;
        setResult({
            d20,
            modifier: charModifier,
            total,
            success: total >= dc,
            charName: selectedChar.name
        });
    };

    if (partyMembers.length === 0) return null;

    return (
        <div className="mt-4 pt-3 border-t border-blue-800/20">
            {result ? (
                <div className={`p-2 rounded flex items-center justify-between ${result.success ? 'bg-green-900/20 border border-green-800/30' : 'bg-red-900/20 border border-red-800/30'}`}>
                    <div className="text-xs">
                        <span className="font-bold text-parchment">{result.charName}</span> rolled:
                        <span className={`ml-2 font-bold text-lg ${result.success ? 'text-green-400' : 'text-red-400'}`}>{result.total}</span>
                        <span className="text-[10px] text-stone-500 ml-1">({result.d20} + {result.modifier >= 0 ? '+' : ''}{result.modifier})</span>
                    </div>
                    <div className={`text-[10px] font-bold uppercase tracking-widest ${result.success ? 'text-green-500' : 'text-red-500'}`}>
                        {result.success ? 'Success' : 'Failure'} (DC {dc})
                    </div>
                    <button onClick={() => { setResult(null); setSelectedChar(null); }} className="text-[10px] text-stone-500 hover:text-stone-300 ml-2">Reset</button>
                </div>
            ) : selectedChar ? (
                <div className="p-3 rounded bg-stone-900/50 border border-stone-800 flex flex-col gap-2">
                    <div className="text-xs text-stone-300">
                        Ask <span className="font-bold text-blue-400">{selectedChar.name}</span> to roll <span className="font-bold text-amber-400">{skillMatch || 'a check'}</span> (DC {dc}).
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-xs text-stone-400 flex-shrink-0">Natural D20 roll:</span>
                        <input
                            type="number"
                            min="1" max="20"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleResolve()}
                            className="bg-stone-950 border border-stone-700 rounded px-2 py-1 w-16 text-sm text-center font-bold text-white focus:outline-none focus:border-blue-500"
                            autoFocus
                        />
                        <span className="text-xs text-stone-500 flex-shrink-0">
                            {charModifier >= 0 ? `+ ${charModifier}` : `- ${Math.abs(charModifier)}`} mod
                        </span>
                        <button
                            onClick={handleResolve}
                            disabled={!inputValue}
                            className="ml-auto px-3 py-1 bg-blue-900/50 hover:bg-blue-800 border border-blue-700 rounded text-xs font-bold text-blue-200 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            Resolve
                        </button>
                        <button onClick={() => setSelectedChar(null)} className="p-1 text-stone-500 hover:text-stone-300 ml-1">
                            <X size={14} />
                        </button>
                    </div>
                </div>
            ) : (
                <div className="flex flex-wrap gap-2 items-center">
                    <span className="text-xs text-blue-500/60 uppercase tracking-widest font-bold">Roll for:</span>
                    {partyMembers.map((char: any) => (
                        <button
                            key={char.id}
                            onClick={() => handleSelectChar(char)}
                            className="px-3 py-1 bg-stone-900 border border-stone-700 hover:border-blue-600 hover:text-blue-400 rounded text-xs font-bold text-stone-300 transition-colors shadow-sm"
                        >
                            {char.name}
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
}

function LootDispatcher({ block, partyMembers, addItem }: any) {
    const [isOpen, setIsOpen] = useState(false);
    const [justGivenTo, setJustGivenTo] = useState<string | null>(null);

    const handleGive = (char: any) => {
        const itemData = {
            name: block.lootDetails || 'Discovered Loot',
            quantity: 1,
            weight: 0,
            isEquipped: false,
            isAttuned: false,
            description: block.text,
            type: 'other' as const,
        };
        addItem(char.id, itemData);
        setJustGivenTo(char.name);
        setIsOpen(false);
        setTimeout(() => setJustGivenTo(null), 3500);
    };

    if (partyMembers.length === 0) return null;

    return (
        <div className="mt-4 pt-3 border-t border-amber-800/20">
            {justGivenTo ? (
                <div className="text-xs text-amber-500/80 italic animate-pulse">
                    Successfully added to {justGivenTo}'s inventory.
                </div>
            ) : isOpen ? (
                <div className="flex flex-wrap gap-2 items-center animate-in fade-in duration-300">
                    <span className="text-xs text-amber-500/60 uppercase tracking-widest font-bold">Give to:</span>
                    {partyMembers.map((char: any) => (
                        <button
                            key={char.id}
                            onClick={() => handleGive(char)}
                            className="px-3 py-1 bg-stone-900 border border-stone-700 hover:border-amber-600 hover:text-amber-400 rounded text-xs font-bold text-stone-300 transition-colors shadow-sm"
                        >
                            {char.name}
                        </button>
                    ))}
                    <button onClick={() => setIsOpen(false)} className="px-2 py-1 text-xs text-stone-500 hover:text-stone-300 ml-2 transition-colors">Cancel</button>
                </div>
            ) : (
                <button
                    onClick={() => setIsOpen(true)}
                    className="flex items-center gap-2 px-3 py-1.5 bg-amber-900/30 hover:bg-amber-800/50 border border-amber-800/40 hover:border-amber-500/60 rounded text-xs font-bold text-amber-500 transition-all hover:shadow-[0_0_15px_rgba(245,158,11,0.15)]"
                >
                    <FileUp size={14} /> Add to Party Inventory
                </button>
            )}
        </div>
    );
}

