            .filter((r: any) => !queryLower || r.name.toLowerCase().includes(queryLower))
            // Avoid duplicates
            .filter((r: any) => !results.some(res => res.name.toLowerCase() === r.name.toLowerCase()))
            .sort((a: any, b: any) => {
