export async function extractCharacterFromPdf(file: File, onProgress?: (msg: string) => void): Promise<Partial<Character>> {
    const arrayBuffer = await file.arrayBuffer();

    const loadingTask = pdfjsLib.getDocument({
        data: arrayBuffer,
        standardFontDataUrl: `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/standard_fonts/`,
    });
    const pdfDocument = await loadingTask.promise;

    const extractedFields: Record<string, string> = {};

    // Standard D&D 5e PDFs usually have important fields on the first 1-3 pages
    const numPages = pdfDocument.numPages;
    for (let i = 1; i <= numPages; i++) {
        const page = await pdfDocument.getPage(i);
        const annotations = await page.getAnnotations();

        for (const annotation of annotations) {
            if (annotation.subtype === 'Widget' && annotation.fieldName) {
                const value = annotation.fieldValue ?? annotation.buttonValue ?? '';
                extractedFields[annotation.fieldName] = typeof value === 'string' ? value : String(value);
            }
        }
    }

    if (onProgress) onProgress('Mapping PDF fields to character...');
    return await mapPdfFieldsToCharacter(extractedFields, onProgress);
}

// ─────────────────────────────────────────────────────────
// MAIN MAPPING FUNCTION
// ─────────────────────────────────────────────────────────
async function mapPdfFieldsToCharacter(fields: Record<string, string>, onProgress?: (msg: string) => void): Promise<Partial<Character>> {
    const character: Partial<Character> = {};

    const parseNum = (val: string | undefined, fallback: number = 0): number => {
        if (!val) return fallback;
        const parsed = parseFloat(val.replace(/[^\d.-]/g, ''));
        return isNaN(parsed) ? fallback : parsed;
    };

    // Resolve a field using the expanded alias dictionary
    const getField = (aliasKey: string): string | undefined => {
        const aliases = FIELD_ALIASES[aliasKey];
        if (!aliases) return undefined;
        for (const key of aliases) {
            if (fields[key] !== undefined && fields[key].trim() !== '') return fields[key];
            if (fields[key + ' '] !== undefined && fields[key + ' '].trim() !== '') return fields[key + ' '];
        }
        return undefined;
    };

    // Also allow direct field lookup for dynamic keys (weapons, equipment, spells)
    const getFieldDirect = (keys: string[]): string | undefined => {
        for (const key of keys) {
            if (fields[key] !== undefined && fields[key].trim() !== '') return fields[key];
            if (fields[key + ' '] !== undefined && fields[key + ' '].trim() !== '') return fields[key + ' '];
        }
        return undefined;
    };

    // Helper: parse "Fighter 1" or "Paladin 3 / Warlock 2"
    const parseClassAndLevel = (classLevelString: string | undefined): { className: string, level: number } | null => {
        if (!classLevelString) return null;
        // Handle multiclass strings like "Paladin 3 / Warlock 2" — take first class, sum levels
        const parts = classLevelString.split(/[/,]/).map(p => p.trim()).filter(Boolean);
        let totalLevel = 0;
        let primaryClass = '';
        for (const part of parts) {
            const match = part.match(/([a-zA-Z\s]+)\s+(\d+)/);
            if (match) {
                if (!primaryClass) primaryClass = match[1].trim();
                totalLevel += parseInt(match[2]);
            } else if (!primaryClass) {
                primaryClass = part.trim();
            }
        }
        return { className: primaryClass || classLevelString.trim(), level: totalLevel || 1 };
    };

    // ── Core Identity ──
    const charName = getField('name');
    if (charName) character.name = charName;
    const playerName = getField('playerName');
    if (playerName) character.playerName = playerName;

    const classLevelValue = getField('classLevel');
    if (classLevelValue) {
        const parsed = parseClassAndLevel(classLevelValue);
        if (parsed) {
            character.className = parsed.className;
            character.level = parsed.level;
        }
    }

    const raceVal = getField('race');
    if (raceVal) character.race = raceVal;
    const bgVal = getField('background');
    if (bgVal) character.background = bgVal;
    const alignVal = getField('alignment');
    if (alignVal) character.alignment = alignVal;

    // ── Ability Scores ──
    const abilityScores: Partial<Character['abilityScores']> = {};
    for (const stat of ['str', 'dex', 'con', 'int', 'wis', 'cha'] as const) {
        const val = getField(stat);
        if (val) abilityScores[stat] = parseNum(val, 10);
    }
    if (Object.keys(abilityScores).length > 0) {
        character.abilityScores = { str: 10, dex: 10, con: 10, int: 10, wis: 10, cha: 10, ...abilityScores };
    }

    // ── Combat Stats ──
    const hpMaxVal = getField('maxHp');
    if (hpMaxVal) {
        character.maxHp = parseNum(hpMaxVal);
        character.currentHp = character.maxHp;
    }

    const speedVal = getField('speed');
    if (speedVal) {
        let normalized = speedVal.replace(/\s*(ft\.?\s*)+/gi, ' ft').trim();
        const speedNum = parseInt(normalized.replace(/[^0-9]/g, ''));
        if (speedNum > 120) normalized = '30 ft';
        character.speed = normalized;
    }

    const hitDiceVal = getField('hitDice');
    if (hitDiceVal) character.hitDice = hitDiceVal;
    const expVal = getField('experience');
    if (expVal) character.experience = parseNum(expVal, 0) || 0;
    const acVal = getField('ac');
    if (acVal) character.ac = parseNum(acVal, 10);
    const profVal = getField('profBonus');
    if (profVal) character.proficiencyBonus = parseNum(profVal, 2);
    const initVal = getField('initiative');
    if (initVal) character.initiativeMod = parseNum(initVal, 0);

    // ── Saving Throws ──
    const saves: Array<keyof Character['abilityScores']> = [];
    const saveMap: Record<string, keyof Character['abilityScores']> = {
        strSaveProf: 'str', dexSaveProf: 'dex', conSaveProf: 'con',
        intSaveProf: 'int', wisSaveProf: 'wis', chaSaveProf: 'cha',
    };
    for (const [aliasKey, stat] of Object.entries(saveMap)) {
        const val = getField(aliasKey);
        if (val && val.trim() !== '') saves.push(stat);
    }
    if (saves.length > 0) character.savingThrows = saves;

    // ── Passives ──
    const pPerc = getField('passivePerception');
    if (pPerc) character.passivePerception = parseNum(pPerc, 10);
    const pInv = getField('passiveInvestigation');
    if (pInv) character.passiveInvestigation = parseNum(pInv, 10);
    const pIns = getField('passiveInsight');
    if (pIns) character.passiveInsight = parseNum(pIns, 10);
    const sensesVal = getField('senses');
    if (sensesVal) character.senses = sensesVal;

    // ── Flavor ──
    const personality = getField('personality');
    if (personality) character.personalityTraits = personality;
    const ideals = getField('ideals');
    if (ideals) character.ideals = ideals;
    const bonds = getField('bonds');
    if (bonds) character.bonds = bonds;
    const flaws = getField('flaws');
    if (flaws) character.flaws = flaws;
    const backstory = getField('backstory');
    if (backstory) character.backstory = backstory;

    // ── Proficiencies & Languages ──
    const profsLangs = getField('profsLangs');
    if (profsLangs) {
        character.proficiencies = profsLangs;
        const langMatch = profsLangs.split(/===\s*LANGUAGES\s*===/i);
        if (langMatch.length > 1) {
            character.languages = langMatch[1].trim();
        } else {
            const langFallback = profsLangs.split(/languages?\s*:/i);
            if (langFallback.length > 1) {
                character.languages = langFallback[1].trim();
            }
        }
    }

    const alliesOrgs = getField('alliesOrganizations');
    if (alliesOrgs) character.backstory = (character.backstory ? character.backstory + '\n\n' : '') + alliesOrgs;

    const addNotes1 = getField('additionalNotes1');
    const addNotes2 = getField('additionalNotes2');
    if (addNotes1 || addNotes2) {
        character.notes = [addNotes1, addNotes2].filter(Boolean).join('\n\n');
    }

    // ── Currencies ──
    const cp = getField('cp'), sp = getField('sp'), ep = getField('ep'), gp = getField('gp'), pp = getField('pp');
    if (cp || sp || ep || gp || pp) {
        character.currencies = {
            cp: parseNum(cp || '0'), sp: parseNum(sp || '0'), ep: parseNum(ep || '0'),
            gp: parseNum(gp || '0'), pp: parseNum(pp || '0'),
        };
    }

    // ── Inventory & Equipment ──
    if (onProgress) onProgress('Extracting inventory...');
    const inventory: Character['inventory'] = [];

    for (let i = 0; i <= 30; i++) {
        const eqName = getFieldDirect([`Eq Name${i}`, `EquipmentName${i}`, `Equipment Name ${i}`]);
        const eqQty = getFieldDirect([`Eq Qty${i}`, `EquipmentQty${i}`, `Equipment Quantity ${i}`]);
        const eqWeight = getFieldDirect([`Eq Weight${i}`, `EquipmentWeight${i}`]);
        if (eqName && eqName.trim() !== '') {
            inventory.push({
                id: crypto.randomUUID(),
                name: eqName,
                quantity: parseNum(eqQty || '1', 1),
                weight: parseNum((eqWeight || '0').replace('lb.', '').replace('lb', '').trim(), 0),
                isEquipped: false, isAttuned: false, description: '', type: 'gear',
            });
        }
    }

    // Weapons
    for (let i = 1; i <= 6; i++) {
        const nameSuffix = i === 1 ? ['', ' 1'] : [` ${i}`];
        let wpnName;
        for (const suffix of nameSuffix) { wpnName = wpnName || getFieldDirect([`Wpn Name${suffix}`]); }
        const wpnAtk = getFieldDirect([`Wpn${i} AtkBonus`, `Wpn${i} AtkBonus `]);
        const wpnDmg = getFieldDirect([`Wpn${i} Damage`, `Wpn${i} Damage `]);
        const wpnNotes = getFieldDirect([`Wpn Notes ${i}`]);
        if (wpnName && wpnName.trim() !== '') {
            if (wpnName.toLowerCase().includes('unarmed strike')) continue;
            let dmgStr = wpnDmg ? wpnDmg.trim() : '';
            if (wpnAtk && wpnAtk.trim() !== '') dmgStr += ` (Atk: ${wpnAtk})`;
            const cleanWpnName = wpnName.trim();
            const existingItem = inventory.find(i => i.name.toLowerCase() === cleanWpnName.toLowerCase() || i.name.toLowerCase() === cleanWpnName.toLowerCase() + 's');
            if (existingItem) {
                existingItem.type = 'weapon';
                existingItem.isEquipped = true;
                existingItem.damage = dmgStr;
                if (existingItem.description && wpnNotes) existingItem.description += `\n${wpnNotes}`;
                else if (wpnNotes) existingItem.description = wpnNotes;
            } else {
                inventory.push({
                    id: crypto.randomUUID(), name: cleanWpnName, quantity: 1, weight: 0,
                    isEquipped: true, isAttuned: false, description: wpnNotes || '',
                    type: 'weapon', damage: dmgStr,
                });
            }
        }
    }

    // Enrich items from 5e.tools
    if (inventory.length > 0) {
        let itemsEnriched = 0;
        for (let i = 0; i < inventory.length; i++) {
            const item = inventory[i];
            const cleanName = item.name.replace(/\s*\(.*\)/, '').replace(/^\d+x?\s+/, '').replace(/,\s*\d+$/, '').trim();
            if (cleanName) {
                itemsEnriched++;
                if (onProgress) onProgress(`Enriching item: ${cleanName} (${itemsEnriched}/${inventory.length})...`);
                try {
                    const searchResults = await searchItems(cleanName);
                    if (searchResults && searchResults.length > 0) {
                        const match = searchResults.find(r => r.name.toLowerCase() === cleanName.toLowerCase()) || searchResults[0];
                        if (match) {
                            item.type = match.type;
                            if (!item.description && match.description) item.description = match.description;
                            if (match.weight > 0) item.weight = match.weight;
                            if (item.quantity > 1 && (item.name.includes(item.quantity.toString()) || item.name.includes(item.quantity.toLocaleString()))) {
                                item.quantity = 1;
                            }
                            if (match.damage && !item.damage) item.damage = match.damage;
                            if (match.acBonus && !item.acBonus) item.acBonus = match.acBonus;
                        }
                    }
                } catch (e) {
                    console.warn(`Failed to enrich equipment: ${cleanName}`, e);
                }
            }
        }
        character.inventory = inventory;

        // Smart AC Deduction (auto-equip armor/shield)
        if (character.ac) {
            const dexMod = Math.floor(((character.abilityScores?.dex || 10) - 10) / 2);
            const unarmoredAC = 10 + dexMod;
            if (character.ac > unarmoredAC) {
                let shieldEquipped = false;
                for (const item of character.inventory) {
                    if (item.name.toLowerCase().includes('shield')) {
                        item.isEquipped = true;
                        shieldEquipped = true;
                    }
                }
                const targetAC = character.ac - (shieldEquipped ? 2 : 0);
                if (targetAC > unarmoredAC) {
                    for (const item of character.inventory) {
                        if (item.type === 'armor' && !item.name.toLowerCase().includes('shield')) {
                            const acBase = item.acBonus || 11;
                            if (acBase === targetAC || (acBase + dexMod) === targetAC ||
                                (acBase + Math.min(dexMod, 2)) === targetAC || (acBase + Math.min(dexMod, 2)) <= targetAC) {
                                item.isEquipped = true;
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    // ── Spellcasting ──
    if (onProgress) onProgress('Extracting spells...');
    const spellAbility = getField('spellAbility');
    if (spellAbility) {
        const abilityMap: Record<string, keyof Character['abilityScores']> = {
            'STR': 'str', 'DEX': 'dex', 'CON': 'con', 'INT': 'int', 'WIS': 'wis', 'CHA': 'cha',
        };
        const mapped = abilityMap[spellAbility.trim().toUpperCase()];
        if (mapped) character.spellcastingAbility = mapped;
    }

    const spellDC = getField('spellDC');
    if (spellDC) character.spellSaveDc = parseNum(spellDC.replace(/[^\d]/g, ''), 0);
    const spellAtkMod = getField('spellAtkMod');
    if (spellAtkMod) {
        const cleaned = spellAtkMod.replace(/[^\d+-]/g, '');
        if (cleaned) character.spellAttackMod = parseNum(cleaned, 0);
    }

    // Parse spell slots
    const spellSlots: { current: number; max: number }[] = Array.from({ length: 10 }, () => ({ current: 0, max: 0 }));
    let hasAnySlots = false;
    for (let lvl = 0; lvl <= 9; lvl++) {
        const header = getFieldDirect([`spellSlotHeader${lvl}`]);
        if (!header) continue;
        if (header.toLowerCase().includes('at will') || header.toLowerCase().includes('cantrip')) continue;
        const slotMatch = header.match(/(\d+)\s*Slot/i);
        if (slotMatch) {
            const maxSlots = parseInt(slotMatch[1]);
            if (maxSlots > 0 && lvl < 10) {
                spellSlots[lvl] = { current: maxSlots, max: maxSlots };
                hasAnySlots = true;
            }
        }
    }
    if (hasAnySlots) character.spellSlots = spellSlots;

    // Extract spell names and enrich from 5e.tools
    const extractedSpellNames: { name: string; source: string; level: number }[] = [];
    const levelBoundaries: { level: number; startIdx: number }[] = [];
    let spellIdx = 0;
    for (let headerIdx = 0; headerIdx <= 9; headerIdx++) {
        const header = getFieldDirect([`spellSlotHeader${headerIdx}`]);
        if (!header) continue;
        const level = header.toLowerCase().includes('at will') || header.toLowerCase().includes('cantrip') ? 0 : headerIdx;
        levelBoundaries.push({ level, startIdx: spellIdx });
        for (let i = spellIdx; i < 50; i++) {
            const name = getFieldDirect([`spellName${i}`]);
            if (!name || !name.trim()) break;
            spellIdx = i + 1;
        }
    }
    for (let i = 0; i < 50; i++) {
        const name = getFieldDirect([`spellName${i}`, `SpellName${i}`]);
        if (!name || !name.trim()) continue;
        let spellLevel = 0;
        for (const boundary of levelBoundaries) {
            if (i >= boundary.startIdx) spellLevel = boundary.level;
        }
        const source = getFieldDirect([`spellSource${i}`, `SpellSource${i}`]) || '';
        extractedSpellNames.push({ name: name.trim(), source: source.trim(), level: spellLevel });
    }

    if (extractedSpellNames.length > 0) {
        const spells: Spell[] = [];
        const knownSpellNames = new Set<string>();
        for (const spellInfo of extractedSpellNames) {
            if (knownSpellNames.has(spellInfo.name.toLowerCase())) continue;
            knownSpellNames.add(spellInfo.name.toLowerCase());
            if (onProgress) onProgress(`Enriching spell: ${spellInfo.name}...`);
            let spell: Spell = {
                id: crypto.randomUUID(), name: spellInfo.name, level: spellInfo.level,
                school: '', castingTime: '', range: '',
                components: { v: false, s: false, m: false },
                duration: '', concentration: false, ritual: false,
                description: '', prepared: true,
            };
            try {
                const results = await searchSpells(spellInfo.name);
                if (results.length > 0) {
                    const match = results.find(r => r.name.toLowerCase() === spellInfo.name.toLowerCase()) || results[0];
                    spell = { ...match, id: crypto.randomUUID(), prepared: true };
                }
            } catch (e) { console.warn(`Failed to enrich spell: ${spellInfo.name}`, e); }
            spells.push(spell);
        }
        character.spells = spells;
        // Remove cantrips from inventory if incorrectly added as weapons
        if (character.inventory) {
            character.inventory = character.inventory.filter(item =>
                !spells.some(s => s.level === 0 && s.name.toLowerCase() === item.name.toLowerCase())
            );
        }
    }

    // ── Skills ──
    if (onProgress) onProgress('Parsing skills...');
    const pdfSkills: Character['skills'] = [];
    for (const skillDf of SKILL_MAP) {
        const baseKey = skillDf.keys[0].trim();
        const profStr = getFieldDirect([`${baseKey}Prof`]);
        let isProf = false;
        let isExp = false;
        if (profStr) {
            const p = profStr.trim().toUpperCase();
            if (p === 'P' || p === '•' || p === 'X' || p === 'TRUE' || p === 'YES' || p === '1') isProf = true;
            if (p === 'E' || p === 'EXPERTISE') { isProf = true; isExp = true; }
        }
        pdfSkills.push({ name: skillDf.label, stat: skillDf.stat, proficient: isProf, expertise: isExp, bonus: 0 });
    }
    if (pdfSkills.length > 0) character.skills = pdfSkills;

    // ═══════════════════════════════════════════════════════
    // SMART FEATURES/TRAITS TEXT SPLITTER
    // Parses the Features & Traits text blocks and auto-categorizes
    // ═══════════════════════════════════════════════════════
    if (onProgress) onProgress('Smart-parsing Features & Traits...');
    const featuresText = [
        getField('featuresTraits1'),
        getField('featuresTraits2'),
        getField('featuresTraits3'),
    ].filter(Boolean).join('\n\n');

    const parsedTraits: Feature[] = [];
    const parsedFeats: Feature[] = [];
    const parsedRacialTraits: Feature[] = [];
    const unmatchedNotes = '';

    if (featuresText.trim()) {
        const entries = splitFeaturesText(featuresText);

        for (const entry of entries) {
            if (onProgress) onProgress(`Identifying: ${entry.title}...`);

            const titleLower = entry.title.toLowerCase().trim();

            // Check if it's a well-known racial trait
            if (WELL_KNOWN_RACIAL_TRAITS.has(titleLower)) {
                parsedRacialTraits.push({
                    id: crypto.randomUUID(),
                    name: entry.title,
                    source: `Race: ${character.race || 'Unknown'}`,
                    description: entry.body,
                    hasUses: false,
                });
                continue;
            }

            // Check if it's a well-known feat
            if (WELL_KNOWN_FEATS.has(titleLower)) {
                // Try to enrich from 5e.tools
                let enrichedFeat: Feature | null = null;
                try {
                    const results = await searchFeats(entry.title);
                    if (results.length > 0) {
                        const match = results.find(r => r.name.toLowerCase() === titleLower) || results[0];
                        enrichedFeat = { ...match, id: crypto.randomUUID() };
                    }
                } catch (e) { console.warn(`Failed to enrich feat: ${entry.title}`, e); }

                if (enrichedFeat) {
                    parsedFeats.push(enrichedFeat);
                } else {
                    parsedFeats.push({
                        id: crypto.randomUUID(),
                        name: entry.title,
                        source: 'Feat',
                        description: entry.body,
                        hasUses: false,
                        isFeat: true,
                    });
                }
                continue;
            }

            // Try 5e.tools feat lookup as a fallback for any unknown entry
            try {
                const featResults = await searchFeats(entry.title);
                if (featResults.length > 0 && featResults[0].name.toLowerCase() === titleLower) {
                    parsedFeats.push({ ...featResults[0], id: crypto.randomUUID() });
                    continue;
                }
            } catch { /* Silently continue */ }

            // If it doesn't match anything known, treat it as a class feature
            parsedTraits.push({
                id: crypto.randomUUID(),
                name: entry.title,
                source: `Class: ${character.className || 'Unknown'}`,
                description: entry.body,
                hasUses: false,
            });
        }
    }

    // Start building the final features arrays — will be enriched further below
    character.features = [...parsedTraits];
    character.feats = [...parsedFeats];
    character.racialTraits = [...parsedRacialTraits];

    if (unmatchedNotes) {
        character.notes = (character.notes ? character.notes + '\n\n' : '') + unmatchedNotes;
    }

    // ═══════════════════════════════════════════════════════
    // AUTOMATED RACIAL TRAIT INJECTION (from 5e.tools)
    // Only injects traits not already found by the smart splitter
    // ═══════════════════════════════════════════════════════
    if (character.race) {
        if (onProgress) onProgress(`Looking up ${character.race} racial traits...`);
        try {
            const racialData = await getRacialTraits(character.race);
            if (racialData.features.length > 0) {
                const existingNames = new Set([
                    ...(character.racialTraits || []).map(f => f.name.toLowerCase()),
                    ...(character.features || []).map(f => f.name.toLowerCase()),
                ]);
                const newTraits = racialData.features.filter(f => !existingNames.has(f.name.toLowerCase()));
                character.racialTraits = [...(character.racialTraits || []), ...newTraits];
            }
            if (racialData.speed && !character.speed) character.speed = racialData.speed;
            if (racialData.senses && !character.senses) character.senses = racialData.senses;
            if (racialData.languages && (!character.languages || character.languages === 'Common')) {
                character.languages = racialData.languages;
            }
            if (racialData.skillProficiencies && character.skills) {
                for (const skillName of racialData.skillProficiencies) {
                    const skill = character.skills.find(s => s.name.toLowerCase() === skillName.toLowerCase());
                    if (skill && !skill.proficient) skill.proficient = true;
                }
            }
        } catch (e) { console.warn('Failed to fetch racial traits:', e); }
    }

    // ═══════════════════════════════════════════════════════
    // AUTOMATED CLASS FEATURE INJECTION (from 5e.tools)
    // Fills in any class features not already parsed from the text
    // ═══════════════════════════════════════════════════════
    if (character.className && character.level) {
        if (onProgress) onProgress(`Looking up ${character.className} class features...`);
        try {
            const classData: any = await getClassFeatures(character.className, character.level);
            if (classData && classData.features && classData.features.length > 0) {
                const existingNames = new Set([
                    ...(character.features || []).map(f => f.name.toLowerCase()),
                    ...(character.racialTraits || []).map(f => f.name.toLowerCase()),
                    ...(character.feats || []).map(f => f.name.toLowerCase()),
                ]);
                const newFeatures = classData.features.filter((f: any) => f && f.name && !existingNames.has(f.name.toLowerCase()));
                character.features = [...(character.features || []), ...newFeatures];
            }
            if (classData && classData.savingThrows && classData.savingThrows.length > 0 && (!character.savingThrows || character.savingThrows.length === 0)) {
                character.savingThrows = classData.savingThrows as any;
            }
            if (classData.proficiencies && !character.proficiencies) {
                character.proficiencies = classData.proficiencies;
            }
        } catch (e) { console.warn('Failed to fetch class features:', e); }
    }

    if (onProgress) onProgress('Import complete!');
    return character;
}

// ─────────────────────────────────────────────────────────
// SMART TEXT SPLITTER
// Splits a Features & Traits text block into structured entries
// Detects patterns like: "Feature Name. Description text..."
// or "FEATURE NAME\nDescription text..."
// ─────────────────────────────────────────────────────────
function splitFeaturesText(text: string): Array<{ title: string; body: string }> {
    const entries: Array<{ title: string; body: string }> = [];
    if (!text || !text.trim()) return entries;

    // Normalize line endings
    const normalized = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    // Strategy 1: Split on "Title. Body" pattern (most common in 5e sheets)
    // Pattern: A line starting with a capitalized word/phrase followed by a period and space
    const titleDotPattern = /(?:^|\n)([A-Z][A-Za-z'\-\s,/]+)\.\s+/g;
    const matches: Array<{ title: string; start: number; end: number }> = [];
    let match;

    while ((match = titleDotPattern.exec(normalized)) !== null) {
        // Only if the title is reasonable length (1-60 chars)
        const title = match[1].trim();
        if (title.length >= 2 && title.length <= 60) {
            matches.push({
                title,
                start: match.index + match[0].length,
                end: 0, // Filled in next step
            });
        }
    }

    if (matches.length > 0) {
        // Fill in end positions
        for (let i = 0; i < matches.length; i++) {
            if (i + 1 < matches.length) {
                // End at the start of the next match's full match
                matches[i].end = normalized.indexOf(matches[i + 1].title, matches[i].start) - 2; // -2 for the \n before next title
            } else {
                matches[i].end = normalized.length;
            }
        }

        for (const m of matches) {
            const body = normalized.substring(m.start, Math.max(m.start, m.end)).trim();
            if (body.length > 0 || m.title.length > 2) {
                entries.push({ title: m.title, body });
            }
        }
    }

    // Strategy 2: If no "Title. Body" patterns found, try splitting on blank lines
    // and treating first line of each block as a title
    if (entries.length === 0) {
        const blocks = normalized.split(/\n\s*\n/).filter(b => b.trim().length > 0);
        for (const block of blocks) {
            const lines = block.trim().split('\n');
            if (lines.length >= 1) {
                const firstLine = lines[0].trim();
                // If the first line looks like a title (short, capitalized)
                if (firstLine.length <= 60 && firstLine.length >= 2 && /^[A-Z]/.test(firstLine)) {
                    entries.push({
                        title: firstLine.replace(/\.\s*$/, ''), // Strip trailing period
                        body: lines.slice(1).join('\n').trim(),
                    });
                }
            }
        }
    }

    // Strategy 3: If still nothing, try splitting on lines that are ALL CAPS
    if (entries.length === 0) {
        const lines = normalized.split('\n');
        let currentTitle = '';
        let currentBody: string[] = [];

        for (const line of lines) {
            const trimmed = line.trim();
            if (trimmed.length >= 2 && trimmed === trimmed.toUpperCase() && /[A-Z]/.test(trimmed)) {
                if (currentTitle) {
                    entries.push({ title: currentTitle, body: currentBody.join('\n').trim() });
                }
                // Convert from ALL CAPS to Title Case
                currentTitle = trimmed.split(/\s+/).map(w => w.charAt(0) + w.slice(1).toLowerCase()).join(' ');
                currentBody = [];
            } else if (trimmed) {
                currentBody.push(trimmed);
            }
        }
        if (currentTitle) {
            entries.push({ title: currentTitle, body: currentBody.join('\n').trim() });
        }
    }

    return entries;
}

import { fetch5eData } from './fiveEToolsParser';
import { calculateEncounterDifficulty, CR_TO_XP } from './encounterDifficulty';

export interface RandomEncounterResult {
    monsters: any[];
    difficulty: string;
    totalXP: number;
    adjustedXP: number;
}

/**
 * Generates a random set of monsters that fit a specific difficulty for a party.
 */
export async function generateRandomEncounter(
    partyLevels: number[],
    difficulty: 'Easy' | 'Medium' | 'Hard' | 'Deadly'
): Promise<RandomEncounterResult | null> {
    if (partyLevels.length === 0) return null;

    // 1. Calculate the target XP budget
    const dummy = calculateEncounterDifficulty(partyLevels, []);
    const targetXP = dummy.thresholds[difficulty.toLowerCase() as keyof typeof dummy.thresholds];

    // Calculate a "safety cap" to avoid infinite loops or crazy high CRs
    const avgPartyLevel = partyLevels.reduce((a, b) => a + b, 0) / partyLevels.length;
    const maxCr = Math.ceil(avgPartyLevel * 1.5);

    // 2. Fetch a pool of potential monsters
    // We'll focus on the core books for "random" encounters to keep it thematic
    const mmData = await fetch5eData('bestiary/bestiary-mm.json');
    const xmmData = await fetch5eData('bestiary/bestiary-xmm.json'); // 2024 MM

    let monsterPool = [...(mmData?.monster || []), ...(xmmData?.monster || [])];

    // Filter out very high CRs and non-combatants
    monsterPool = monsterPool.filter(m => {
        const crValue = typeof m.cr === 'string' ? m.cr : (m.cr?.cr || '0');
        // Simple numeric conversion for comparison
        let numericCr = 0;
        if (crValue.includes('/')) {
            const [num, den] = crValue.split('/').map(Number);
            numericCr = num / den;
        } else {
            numericCr = Number(crValue) || 0;
        }
        return numericCr <= maxCr && numericCr > 0;
    });

    if (monsterPool.length === 0) return null;

    // 3. Filling Algorithm
    const selectedMonsters: any[] = [];
    let currentDifficultyData = calculateEncounterDifficulty(partyLevels, []);

    // Limit attempts to avoid infinite loops
    let attempts = 0;
    const MAX_ATTEMPTS = 20;

    while (currentDifficultyData.adjustedXP < targetXP && attempts < MAX_ATTEMPTS) {
        attempts++;

        // Pick a monster that roughly fits the remaining budget
        const remainingXP = targetXP - currentDifficultyData.adjustedXP;

        // Find monsters in the pool that could fit
        // Note: multiplier changes as we add more, so this is an approximation
        const potentialNext = monsterPool.filter(m => {
            const crValue = typeof m.cr === 'string' ? m.cr : (m.cr?.cr || '0');
            const xp = CR_TO_XP[crValue] || 0;
            return xp <= remainingXP || selectedMonsters.length === 0;
        });

        if (potentialNext.length === 0) break;

        const picked = potentialNext[Math.floor(Math.random() * potentialNext.length)];
        selectedMonsters.push(picked);

        // Recalculate
        currentDifficultyData = calculateEncounterDifficulty(
            partyLevels,
            selectedMonsters.map(m => typeof m.cr === 'string' ? m.cr : (m.cr?.cr || '0'))
        );

        // If we are significantly over the target, maybe remove the last one and stop
        // unless it's the first monster
        if (currentDifficultyData.adjustedXP > targetXP * 1.5 && selectedMonsters.length > 1) {
            selectedMonsters.pop();
            break;
        }
    }

    // 4. Final mapping to our internal format
    const finalMonsters = selectedMonsters.map(m => {
        const cr = typeof m.cr === 'string' ? m.cr : (m.cr?.cr || '0');
        const ac = m.ac ? (typeof m.ac[0] === 'number' ? m.ac[0] : m.ac[0]?.ac || 10) : 10;
        const hp = m.hp ? m.hp.average || 10 : 10;

        return {
            ...m,
            cr,
            ac,
            hp,
            currentHp: hp,
            maxHp: hp,
        };
    });

    const finalDiff = calculateEncounterDifficulty(partyLevels, finalMonsters.map(m => m.cr));

    return {
        monsters: finalMonsters,
        difficulty: finalDiff.difficulty,
        totalXP: finalDiff.totalXP,
        adjustedXP: finalDiff.adjustedXP
    };
}

import { WizardStep } from '../components/common/ChoiceWizardModal';
import { FLAVOR_DESCRIPTIONS } from '../data/dnd5e/flavorDescriptions';
import { is2024Source, decomposePack, fetchFeat } from './fiveEToolsParser';
import { Character, StatBlock } from '../types/character';
import EQUIP_DATA_2024 from '../data/rules2024/equipment.json';

/**
 * RULES CHOICE ENGINE
 * 
 * This engine analyzes raw D&D 5e data to detect required user choices
 * and provides definitions for the UI Wizard to present these choices.
 * It also handles the "resolution" of these choices into character updates.
 */

interface Option {
    label: string;
    value: any;
    description?: string;
    is2024?: boolean;
}

export interface DetectedChoice {
    id: string;
    title: string;
    description: string;
    type: 'skill' | 'language' | 'tool' | 'ability' | 'equipment' | 'feature' | 'spell' | 'feat' | 'weaponMastery';
    count: number;
    options: any[];
    originalChoiceBlock: any;
    is2024?: boolean;
}

const STANDARD_LANGUAGES = ['Common', 'Dwarvish', 'Elvish', 'Giant', 'Gnomish', 'Goblin', 'Halfling', 'Orc'];
const EXOTIC_LANGUAGES = ['Abyssal', 'Celestial', 'Draconic', 'Deep Speech', 'Infernal', 'Primordial', 'Sylvan', 'Undercommon'];
const ALL_LANGUAGES = [...STANDARD_LANGUAGES, ...EXOTIC_LANGUAGES];

const ALL_SKILLS = [
    'acrobatics', 'animal handling', 'arcana', 'athletics', 'deception', 'history',
    'insight', 'intimidation', 'investigation', 'medicine', 'nature', 'perception',
    'performance', 'persuasion', 'religion', 'sleight of hand', 'stealth', 'survival'
];

/**
 * Recursive formatter for starting equipment packages.
 */
function formatEqPackage(pkg: any): string {
    if (!pkg) return 'Unknown';
    if (typeof pkg === 'string') return pkg.split('|')[0];

    if (Array.isArray(pkg)) {
        return pkg.map(item => formatEqPackage(item)).join(' and ');
    }

    if (typeof pkg === 'object') {
        const qty = pkg.quantity || 1;
        const qtyStr = qty > 1 ? `${qty}x ` : '';

        if (pkg.item) {
            const itemName = pkg.item.split('|')[0];
            return `${qtyStr}${itemName}`;
        }
        if (pkg.special) return pkg.special;
        if (pkg.displayName) return pkg.displayName;
        if (pkg.equipmentType) {
            // "weaponMartialMelee" -> "Martial Melee Weapon"
            return pkg.equipmentType
                .replace(/([A-Z])/g, ' $1')
                .replace(/^./, (str: string) => str.toUpperCase());
        }
        if (pkg.containsValue) {
            return `Pouch with ${pkg.containsValue / 100} gp`;
        }
    }
    return 'Equipment';
}

export function detectChoices(
    data: any,
    is2024: boolean,
    type: 'race' | 'class' | 'background' | 'feat'
): DetectedChoice[] {
    const choices: DetectedChoice[] = [];

    // 1. Ability Scores (Race & Background)
    if ((type === 'race' || type === 'background') && data.ability && Array.isArray(data.ability)) {
        data.ability.forEach((ab: any, i: number) => {
            if (ab.choose) {
                choices.push({
                    id: `race_ability_${i}`,
                    title: 'Ability Score Increase',
                    description: `Choose ${ab.choose.count || 1} ability score(s) to increase by ${ab.choose.amount || 1}.`,
                    type: 'ability',
                    count: ab.choose.count || 1,
                    options: (ab.choose.from || ['str', 'dex', 'con', 'int', 'wis', 'cha']).map((s: string) => ({
                        label: s.toUpperCase(),
                        value: { stat: s, bonus: ab.choose.amount || 1 },
                        is2024: is2024
                    })),
                    originalChoiceBlock: ab
                });
            }
        });
    }

    // 2. Skill Proficiencies
    const skillSource = type === 'class' ? data.startingProficiencies?.skills : data.skillProficiencies;
    if (skillSource && Array.isArray(skillSource)) {
        skillSource.forEach((sp: any, i: number) => {
            if (sp.choose || sp.any) {
                const count = sp.choose?.count || sp.any || 1;
                const from = sp.choose?.from || ALL_SKILLS;
                choices.push({
                    id: `${type}_skills_${i}`,
                    title: 'Skill Proficiencies',
                    description: `Choose ${count} skill(s).`,
                    type: 'skill',
                    count,
                    options: from.map((s: string) => ({
                        label: s.charAt(0).toUpperCase() + s.slice(1),
                        value: s,
                        description: FLAVOR_DESCRIPTIONS[s.toLowerCase()],
                        is2024: is2024
                    })),
                    originalChoiceBlock: sp
                });
            }
        });
    }

    // 3. Language Proficiencies
    if (data.languageProficiencies && Array.isArray(data.languageProficiencies)) {
        data.languageProficiencies.forEach((lp: any, i: number) => {
            if (lp.anyStandard || lp.anyExotic || lp.any || lp.choose) {
                const count = (lp.anyStandard || 0) + (lp.anyExotic || 0) + (lp.any || 0) + (lp.choose?.count || 0) || 1;
                let availableOptions = ALL_LANGUAGES;
                if (lp.anyStandard && !lp.anyExotic && !lp.any && !lp.choose) availableOptions = STANDARD_LANGUAGES;
                if (lp.anyExotic && !lp.anyStandard && !lp.any && !lp.choose) availableOptions = EXOTIC_LANGUAGES;
                if (lp.choose?.from) availableOptions = lp.choose.from;

                choices.push({
                    id: `${type}_lang_${i}`,
                    title: 'Languages',
                    description: `Choose ${count} language(s).`,
                    type: 'language',
                    count,
                    options: availableOptions.map(l => ({
                        label: l,
                        value: l,
                        description: FLAVOR_DESCRIPTIONS[l.toLowerCase()],
                        is2024: is2024
                    })),
                    originalChoiceBlock: lp
                });
            }
        });
    }

    // 3b. FALLBACK: Many 5e.tools traits have choices hidden in entries (text)
    if (data.entries) {
        data.entries.forEach((e: any, i: number) => {
            if (typeof e !== 'object' || !e.name) return;
            const nameLower = e.name.toLowerCase();
            const desc = JSON.stringify(e.entries || []).toLowerCase();

            if ((nameLower.includes('language') || nameLower.includes('skill')) && desc.includes('choice')) {
                let count = 1;
                if (desc.includes('two') || desc.includes(' 2 ') || desc.includes('both')) count = 2;
                if (desc.includes('three') || desc.includes(' 3 ')) count = 3;
                if (desc.includes('four') || desc.includes(' 4 ')) count = 4;
                if (desc.includes('five') || desc.includes(' 5 ')) count = 5;
                if (desc.includes('any number') || desc.includes('any other')) count = 2; // Default for 2024 Elf if "any other"

                const choiceType = nameLower.includes('language') ? 'language' : 'skill';
                const id = `extra_${choiceType}_${i}`;

                if (!choices.some(c => c.type === choiceType)) {
                    choices.push({
                        id,
                        title: e.name,
                        description: `Choose ${count} ${choiceType}(s).`,
                        type: choiceType as any,
                        count,
                        options: choiceType === 'language' ? ALL_LANGUAGES.map(l => ({
                            label: l,
                            value: l,
                            description: FLAVOR_DESCRIPTIONS[l.toLowerCase()],
                            is2024: is2024
                        })) : ALL_SKILLS.map(s => ({
                            label: s.charAt(0).toUpperCase() + s.slice(1),
                            value: s,
                            is2024: is2024
                        })),
                        originalChoiceBlock: e
                    });
                }
            }
        });
    }

    // 3c. Background Feats (2024 Rules)
    if (type === 'background' && data.feats && Array.isArray(data.feats)) {
        data.feats.forEach((f: any, i: number) => {
            Object.keys(f).forEach(featKey => {
                const featName = featKey.split('|')[0].split(';')[0].trim().replace(/\b\w/g, l => l.toUpperCase());
                choices.push({
                    id: `bg_feat_${i}`,
                    title: 'Background Feat',
                    description: `You gain the ${featName} feat from your background.`,
                    type: 'feature',
                    count: 1,
                    options: [{
                        label: featName,
                        value: featName,
                        is2024: is2024
                    }],
                    originalChoiceBlock: f
                });
            });
        });
    }

    // 3d. Background Gold / Currency
    if (type === 'background' && data.entries) {
        const entryStr = JSON.stringify(data.entries);
        const goldMatch = entryStr.match(/(\d+)\s*gp/i);
        if (goldMatch) {
            const amount = parseInt(goldMatch[1]);
            choices.push({
                id: `bg_gold`,
                title: 'Starting Gold',
                description: `Your background provides you with ${amount} gold pieces.`,
                type: 'equipment',
                count: 1,
                options: [{
                    label: `${amount} GP`,
                    value: { name: 'Gold Pieces', quantity: amount, isCurrency: true },
                    is2024: is2024
                }],
                originalChoiceBlock: data.entries
            });
        }
    }

    // 4. Equipment Packages (Class)
    if (type === 'class' && data.startingEquipment) {
        const se = data.startingEquipment;

        // Handle 2024 choiceA/choiceB format
        if (se.choiceA || se.choiceB) {
            const options = [];
            if (se.choiceA) options.push({ label: formatEqPackage(se.choiceA), value: se.choiceA, is2024: true });
            if (se.choiceB) options.push({ label: formatEqPackage(se.choiceB), value: se.choiceB, is2024: true });

            choices.push({
                id: 'class_eq_2024',
                title: 'Starting Equipment Choice',
                description: 'Select your starting equipment package (A) or starting gold (B).',
                type: 'equipment',
                count: 1,
                options,
                originalChoiceBlock: se
            });
        }

        // Handle Legacy defaultData format
        if (se.defaultData) {
            se.defaultData.forEach((eqChoice: any, i: number) => {
                const options = [];
                if (eqChoice.a) options.push({ label: formatEqPackage(eqChoice.a), value: eqChoice.a, is2024: is2024Source(data.source) });
                if (eqChoice.b) options.push({ label: formatEqPackage(eqChoice.b), value: eqChoice.b, is2024: is2024Source(data.source) });
                if (eqChoice.c) options.push({ label: formatEqPackage(eqChoice.c), value: eqChoice.c, is2024: is2024Source(data.source) });
                if (eqChoice.d) options.push({ label: formatEqPackage(eqChoice.d), value: eqChoice.d, is2024: is2024Source(data.source) });

                if (options.length > 0) {
                    choices.push({
                        id: `class_eq_${i}`,
                        title: `Equipment Choice ${i + 1}`,
                        description: 'Choose your starting equipment package.',
                        type: 'equipment',
                        count: 1,
                        options,
                        originalChoiceBlock: eqChoice
                    });
                }
            });
        }

        if (se.goldAlternative) {
            choices.push({
                id: `class_gold_alt`,
                title: 'Starting Wealth',
                description: 'Instead of equipment choices, you can choose to start with gold based on a class-specific formula (usually 4d4 x 10).',
                type: 'equipment',
                count: 1,
                options: [{
                    label: `Start with Gold (approx. ${se.goldAlternative.includes('x 10') ? '100' : '50'} gp)`,
                    value: { isGoldAlt: true, formula: se.goldAlternative },
                    is2024: is2024Source(data.source)
                }],
                originalChoiceBlock: se.goldAlternative
            });
        }
    }

    // 5. Class Features
    const featuresSource = data.levels ? (data.levels["1"]?.features || []) : (data.classFeature || []);
    if (type === 'class' && featuresSource.length > 0) {
        featuresSource.forEach((cf: any) => {
            const nameLower = cf.name.toLowerCase();
            // Detect common 2024 choices: Weapon Mastery, Fighting Style, Eldritch Invocation, Metamagic
            if (nameLower.includes('fighting style') ||
                nameLower.includes('eldritch invocation') ||
                nameLower.includes('metamagic') ||
                nameLower.includes('weapon mastery') ||
                nameLower.includes('expertise') ||
                nameLower.includes('divine order') ||
                nameLower.includes('primal order')) {

                const isFighter = data.name === 'Fighter';
                // 2024 Fighter gets 3, Barbarian gets 2 at level 1.
                // We'll try to parse it from description if possible, fallback to 2.
                let count = 2;
                if (isFighter) count = 3;

                const descLower = cf.description?.toLowerCase() || '';
                if (descLower.includes('three')) count = 3;
                else if (descLower.includes('two')) count = 2;
                else if (descLower.includes('four')) count = 4;

                const choiceType = nameLower.includes('weapon mastery') ? 'weaponMastery' : 'feature';

                choices.push({
                    id: `feature_${cf.name.replace(/\s+/g, '_').toLowerCase()}`,
                    title: cf.name,
                    description: `Choose ${count} option(s) for your ${cf.name} feature.`,
                    type: choiceType,
                    count,
                    options: (choiceType === 'weaponMastery'
                        ? getWeaponOptions2024()
                        : getMockOptionsForFeature(cf.name)
                    ).map((o: Option) => ({ ...o, is2024: o.is2024 ?? is2024Source(data.source) })),
                    originalChoiceBlock: cf
                });
            }
        });
    }

    // 2024 Rule: Languages are now "Common + 2 choices of Standard languages"
    if (is2024 && type === 'race' && (!data.languageProficiencies || data.languageProficiencies.length === 0)) {
        choices.push({
            id: 'race_languages_2024',
            title: 'Languages',
            description: 'You know Common and two other languages of your choice.',
            type: 'language',
            count: 2,
            options: STANDARD_LANGUAGES.map(l => ({ label: l, value: l, is2024: true })),
            is2024: true,
            originalChoiceBlock: { isSynthetic2024: true }
        });
    }

    // 6. Generic Feat Selection (Level 4+, ASI replacement)
    if (type === 'feat') {
        // This is a special case triggered by the Level-Up Wizard
        // It returns the entire catalog of available feats (filtered by 2024 if preferred)
        // Since detectChoices is synchronous but searchFeats might be async in some contexts,
        // we use the local 2024 feats data directly or wait for the implementation.
        // Actually, for now, let's assume we pass the feat data or use a mock that will be replaced.
        // Wait, searchFeats IS async. I should probably refactor detectChoices to be async or handle it.
        // For now, I'll add a placeholder that the UI can then populate with searchFeats.
        choices.push({
            id: 'feat_selection',
            title: 'Choose a Feat',
            description: 'Select a feat to gain. You must meet the prerequisites.',
            type: 'feat',
            count: 1,
            options: [], // UI will fetch these via searchFeats('')
            originalChoiceBlock: { isFeatSelection: true }
        });
    }

    return choices;
}

export function detectFixedProficiencies(data: any, is2024: boolean): { languages: string[], skills: string[] } {
    const languages: string[] = [];
    const skills: string[] = [];

    if (data.entries) {
        data.entries.forEach((e: any) => {
            if (typeof e !== 'object' || !e.entries) return;
            const entriesText = JSON.stringify(e.entries).toLowerCase();
            const titleLower = (e.name || '').toLowerCase();

            ALL_LANGUAGES.forEach(l => {
                const lLower = l.toLowerCase();
                const knownPatterns = [`know ${lLower}`, `speak ${lLower}`, `read, and write ${lLower}`];
                const matchesPattern = knownPatterns.some(p => entriesText.includes(p));
                const isChoice = entriesText.includes('choice') || entriesText.includes('choose');
                const isLanguageTrait = titleLower.includes('language');

                if (matchesPattern && !isChoice && isLanguageTrait) {
                    if (!languages.includes(l)) languages.push(l);
                }
            });

            if (entriesText.includes('"common"') || titleLower.includes('common') || (is2024 && languages.length === 0)) {
                if (!languages.includes('Common')) languages.push('Common');
            }

            ALL_SKILLS.forEach(s => {
                const sLower = s.toLowerCase();
                const skillPatterns = [`proficiency in ${sLower}`, `proficient in ${sLower}`, `gain proficiency in ${sLower}`];
                const matchesSkill = skillPatterns.some(p => entriesText.includes(p));
                const isSkillChoice = entriesText.includes('choice') || entriesText.includes('choose');
                if (matchesSkill && !isSkillChoice) {
                    const sName = s.charAt(0).toUpperCase() + s.slice(1);
                    if (!skills.includes(sName)) skills.push(sName);
                }
            });
        });
    }

    return { languages, skills };
}

function getMockOptionsForFeature(featureName: string): Option[] {
    const nameLower = featureName.toLowerCase();
    if (nameLower.includes('fighting style')) {
        return [
            { label: 'Archery', value: 'Archery', description: '+2 bonus to attack rolls with ranged weapons.', is2024: true },
            { label: 'Defense', value: 'Defense', description: '+1 bonus to AC while wearing armor.', is2024: true },
            { label: 'Dueling', value: 'Dueling', description: '+2 bonus to damage rolls with one-handed melee weapons.', is2024: true },
            { label: 'Great Weapon Fighting', value: 'Great Weapon Fighting', description: 'Reroll 1s and 2s on damage dice for two-handed weapons.', is2024: true },
            { label: 'Protection', value: 'Protection', description: 'Use reaction to impose disadvantage on attacks against allies.', is2024: true },
            { label: 'Two-Weapon Fighting', value: 'Two-Weapon Fighting', description: 'Add ability modifier to second attack damage.', is2024: true }
        ];
