    }));
}

export async function resolveAllChoices(
    character: Character,
    selections: Record<string, any[]>,
    originalData: any,
    type: 'race' | 'class' | 'background'
): Promise<Character> {
    let updated = { ...character };

    if (type === 'race') {
        updated.race = originalData.name;

        // Ability scores (Fixed - Legacy Only, 2024 uses Background)
        if (!originalData.is2024 && originalData.ability && Array.isArray(originalData.ability) && originalData.ability[0]) {
            Object.entries(originalData.ability[0]).forEach(([stat, bonus]) => {
                const s = stat.toLowerCase() as keyof StatBlock;
                if (typeof bonus === 'number' && (updated.abilityScores as any)[s] !== undefined) {
                    (updated.abilityScores as any)[s] += bonus;
                }
            });
        }

        // Languages (Fixed)
        if (originalData.languageProficiencies && originalData.languageProficiencies[0]) {
            Object.keys(originalData.languageProficiencies[0]).forEach(l => {
                if (originalData.languageProficiencies[0][l] === true) {
                    const name = l.charAt(0).toUpperCase() + l.slice(1);
                    const currentLangs = updated.languages ? updated.languages.split(',').map((s: string) => s.trim()) : [];
                    if (!currentLangs.includes(name)) currentLangs.push(name);
                    updated.languages = currentLangs.join(', ');
                }
            });
        }

        updated.speed = typeof originalData.speed === 'number' ? `${originalData.speed} ft` : `${originalData.speed?.walk || 30} ft`;
        if (originalData.darkvision) {
            updated.senses = (updated.senses || '') + ` Darkvision ${originalData.darkvision} ft`;
            updated.darkvision = originalData.darkvision;
        }

        // Extract Racial Traits
        if (originalData.entries) {
            const racialTraits = originalData.entries
                .filter((e: any) => typeof e === 'object' && e.name)
                .map((e: any) => ({
                    id: crypto.randomUUID(),
                    name: e.name,
                    source: `Race: ${originalData.name}`,
                    description: typeof e.entries === 'string' ? e.entries : JSON.stringify(e.entries || [e]),
                    is2024: originalData.source?.startsWith('X') || false
                }));
            updated.racialTraits = [...(updated.racialTraits || []), ...racialTraits];
        }
    }

    if (type === 'background') {
        updated.background = originalData.name;

        // Fixed Skill Proficiencies
        if (originalData.skillProficiencies && Array.isArray(originalData.skillProficiencies)) {
            originalData.skillProficiencies.forEach((sp: any) => {
                const skillNames = typeof sp === 'string' ? [sp] : Object.keys(sp).filter(k => sp[k] === true);
                skillNames.forEach(skillName => {
                    const skill = updated.skills.find((s: any) => s.name.toLowerCase() === skillName.toLowerCase());
                    if (skill) {
                        skill.proficient = true;
                        skill.source = `Background: ${originalData.name}`;
                    }
                });
            });
        }

        // Background Feature
        if (originalData.entries) {
            const features = originalData.entries
                .filter((e: any) => typeof e === 'object' && e.name)
                .map((e: any) => ({
                    id: crypto.randomUUID(),
                    name: e.name,
                    source: `Background: ${originalData.name}`,
                    description: typeof e.entries === 'string' ? e.entries : JSON.stringify(e.entries || [e]),
                    is2024: originalData.source?.startsWith('X') || false
                }));
            updated.features = [...(updated.features || []), ...features];
        }

        // Background Starting Gold
        if (originalData.startingGold && updated.currencies) {
            updated.currencies.gp += originalData.startingGold;
        } else {
            // Fallback to text parsing
            const entriesText = JSON.stringify(originalData.entries || []).toLowerCase();
            const goldMatch = entriesText.match(/(\d+)\s+gp/);
            if (goldMatch && updated.currencies) {
                updated.currencies.gp += parseInt(goldMatch[1]);
            }
        }
    }

    if (type === 'class') {
        updated.className = originalData.name;
        updated.hitDice = originalData.hitDice;

        // Fixed Class Features (Level 1)
        const level1Data = originalData.levels?.["1"] || {};
        const fixedFeatures = level1Data.features || [];
        fixedFeatures.forEach((ff: any) => {
            if (!updated.features.some(f => f.name === ff.name)) {
                updated.features.push({
                    id: crypto.randomUUID(),
                    name: ff.name,
                    source: `Class: ${originalData.name}`,
                    description: ff.description,
                    is2024: true,
                    hasUses: false
                });
            }
        });
    }

    // Process Selections
    for (const choiceId of Object.keys(selections)) {
        const selectedOptions = selections[choiceId];
        if (!selectedOptions || selectedOptions.length === 0) continue;

        updated = await applySelection(updated, choiceId, selectedOptions);
    }

    return updated;
}

async function applySelection(character: Character, choiceId: string, selections: any[]): Promise<Character> {
    const updated = { ...character };

    if (choiceId === 'flavor_customization') {
        const flavor = selections[0];
        if (flavor) updated.notes = (updated.notes || '') + '\n\n' + flavor;
        return updated;
    }

    if (choiceId.includes('lang')) {
        const currentLangs = updated.languages ? updated.languages.split(',').map((s: string) => s.trim()) : [];
        selections.forEach(l => {
            if (!currentLangs.includes(l)) currentLangs.push(l);
        });
        updated.languages = currentLangs.join(', ');
    }
    else if (choiceId.includes('skills')) {
        const newSkills = [...(updated.skills || [])];
        const sourceLabel = choiceId.split('_')[0];
        const finalSource = sourceLabel.charAt(0).toUpperCase() + sourceLabel.slice(1);

        selections.forEach(skillName => {
            const skill = newSkills.find((s: any) => s.name.toLowerCase() === skillName.toLowerCase());
            if (skill) {
                skill.proficient = true;
                skill.source = finalSource;
                skill.sourceId = choiceId;
            }
        });
        updated.skills = newSkills;
    }
    else if (choiceId.includes('ability')) {
        const newAbilityScores = { ...updated.abilityScores };
        selections.forEach(sel => {
            const statKey = sel.stat?.toLowerCase() as keyof StatBlock;
            if (statKey && (newAbilityScores as any)[statKey] !== undefined) {
                (newAbilityScores as any)[statKey] += sel.bonus;
            }
        });
        updated.abilityScores = newAbilityScores;
    }
    else if (choiceId.includes('eq')) {
        const selection = selections[0];
        if (!selection) return updated;

        const newInventory = [...(updated.inventory || [])];
        const newCurrencies = { ...(updated.currencies || { cp: 0, sp: 0, ep: 0, gp: 0, pp: 0 }) };

        const processEntry = async (entry: any) => {
            if (typeof entry === 'string') {
                const name = entry.split('|')[0];
                if (name.toLowerCase().includes('pack')) {
                    const expanded = await decomposePack(name);
                    if (expanded.length > 0) {
                        newInventory.push(...expanded);
                        return;
                    }
                }
                newInventory.push({
                    id: crypto.randomUUID(),
                    name,
                    quantity: 1,
                    type: 'gear',
                    weight: 0,
                    description: 'Starting equipment',
                    isEquipped: false,
                    isAttuned: false
                });
            } else if (Array.isArray(entry)) {
                for (const sub of entry) {
                    await processEntry(sub);
                }
            } else if (typeof entry === 'object') {
                if (entry.isGoldAlt) {
                    // Extract dice or use average (e.g., "4d4 x 10")
                    const match = entry.formula?.match(/(\d+)d(\d+)(?:\s*x\s*(\d+))?/i);
                    let amount = 100; // default average
                    if (match) {
                        const count = parseInt(match[1]);
                        const sides = parseInt(match[2]);
                        const multiplier = parseInt(match[3] || '1');
                        amount = Math.floor(count * (sides + 1) / 2) * multiplier;
                    }
                    newCurrencies.gp += amount;
                } else if (entry.isCurrency || entry.containsValue) {
                    const amount = entry.quantity || (entry.containsValue / 100) || 0;
                    newCurrencies.gp += amount;
                } else if (entry.item) {
                    const name = entry.item.split('|')[0];
                    if (name.toLowerCase().includes('pack')) {
                        const expanded = await decomposePack(name);
                        if (expanded.length > 0) {
                            newInventory.push(...expanded);
                            return;
                        }
                    }
                    newInventory.push({
                        id: crypto.randomUUID(),
                        name,
                        quantity: entry.quantity || 1,
                        type: 'gear',
                        weight: 0,
                        description: 'Starting equipment',
                        isEquipped: false,
                        isAttuned: false
                    });
                } else if (entry.equipmentType) {
                    const name = entry.equipmentType.replace(/([A-Z])/g, ' $1').replace(/^./, (str: string) => str.toUpperCase());
                    newInventory.push({
                        id: crypto.randomUUID(),
                        name,
                        quantity: 1,
                        type: 'gear',
                        weight: 0,
                        description: 'Generic selection',
                        isEquipped: false,
                        isAttuned: false
                    });
                }
            }
        };

        await processEntry(selection);
        updated.inventory = newInventory;
        updated.currencies = newCurrencies;
    }
    else if (choiceId.includes('feature')) {
        const newFeatures = [...(updated.features || [])];
        selections.forEach(optionName => {
            newFeatures.push({
                id: crypto.randomUUID(),
                name: optionName,
                description: 'Selected during character creation.',
                source: 'Choice',
                hasUses: false
            });
        });
        updated.features = newFeatures;
    }
    else if (choiceId.includes('feat')) {
        const newFeats = [...(updated.feats || [])];
        for (const featName of selections) {
            // Fetch the full feat data to get its effects
            const featData = await fetchFeat(featName);
            if (featData) {
                newFeats.push(featData);
            } else {
                // Fallback if not found
                newFeats.push({
                    id: crypto.randomUUID(),
                    name: featName,
                    description: 'Feat selected.',
                    source: 'Feat',
                    hasUses: false,
                    isFeat: true
                });
            }
        }
        updated.feats = newFeats;
    }
    else if (choiceId.includes('weaponMastery')) {
        const newMastery = [...(updated.masteredWeapons || [])];
        selections.forEach(weaponName => {
            if (!newMastery.includes(weaponName)) {
                newMastery.push(weaponName);
            }
        });
        updated.masteredWeapons = newMastery;
    }

    return updated;
}

export function enrichFeaturesWithChoices(features: any[]): any[] {
    return features.map(f => {
        const desc = f.description?.toLowerCase() || '';
        if (f.requiresChoice || f.choiceType) return f;

        const detectCount = (text: string) => {
            if (text.includes('two') || text.includes(' 2 ')) return 2;
            if (text.includes('three') || text.includes(' 3 ')) return 3;
            if (text.includes('four') || text.includes(' 4 ')) return 4;
            return 1;
        };

        if ((desc.includes('language') || f.name.toLowerCase().includes('language')) &&
            (desc.includes('of your choice') || desc.includes('choose') || desc.includes('any two') || desc.includes('any one'))) {
            return {
                ...f,
                requiresChoice: true,
                choiceType: 'language',
                count: detectCount(desc)
            };
        }

        if ((desc.includes('skill') || f.name.toLowerCase().includes('skill')) &&
            (desc.includes('of your choice') || desc.includes('choose') || desc.includes('any two') || desc.includes('any one'))) {
            return {
                ...f,
                requiresChoice: true,
                choiceType: 'skill',
                count: detectCount(desc)
            };
        }

        if (desc.includes('tool proficiency') && (desc.includes('of your choice') || desc.includes('choose'))) {
            return {
                ...f,
                requiresChoice: true,
                choiceType: 'tool',
                count: detectCount(desc)
            };
        }

        if (desc.includes('of your choice') && (desc.includes('skill') || desc.includes('language') || desc.includes('tool') || desc.includes('proficiency') || desc.includes('proficiencies'))) {
            const isLang = desc.includes('language');
            const isSkill = desc.includes('skill');
            return {
                ...f,
                requiresChoice: true,
                choiceType: isLang ? 'language' : (isSkill ? 'skill' : 'tool'),
                count: detectCount(desc)
            };
        }

        return f;
    });
}

export function choicesToWizardSteps(choices: DetectedChoice[]): WizardStep[] {
    return choices.map(c => ({
        id: c.id,
        title: c.title,
        description: c.description,
        maxChoices: c.count,
        minChoices: c.count,
        options: c.options.map(o => ({ ...o, is2024: o.is2024 ?? c.is2024 }))
    }));
}

export function getSkillAllowance(character: any): number {
    const className = character.className?.toLowerCase() || '';
    if (className === 'rogue') return 4;
    if (className === 'bard' || className === 'ranger') return 3;
    return 2;
}

export function validateSkillSelection(character: any, skillName: string, currentlyProficient: boolean): { allowed: boolean; reason?: string } {
    if (currentlyProficient) {
        const skill = character.skills.find((s: any) => s.name.toLowerCase() === skillName.toLowerCase());
        if (skill?.source && (skill.source.includes('Background') || skill.source.includes('Race'))) {
            return { allowed: false, reason: `This proficiency is fixed by your ${skill.source}.` };
        }
        return { allowed: true };
    }

    const chosenSkills = character.skills.filter((s: any) => s.proficient && (!s.source || s.source === 'Class' || s.source === 'Manual'));
    const allowance = getSkillAllowance(character);

    if (chosenSkills.length >= allowance) {
        return {
            allowed: false,
            reason: `You have already selected the maximum of ${allowance} skills for your class.`
        };
    }

    return { allowed: true };
}

import { Character } from '../types/character';
import { getHighestAcSet, sumBonus, getActiveEffects } from './mechanicsEngine';

export function getAbilityModifier(score: number): number {
    return Math.floor((score - 10) / 2);
}

export function getEffectiveAbilityScore(character: Character, stat: keyof Character['abilityScores']): number {
    let score = character.abilityScores[stat] || 10;

    // 1. Legacy bonuses (Features/Feats)
    for (const feat of character.feats || []) {
        if (feat.abilityScoreBonuses && feat.abilityScoreBonuses[stat]) {
            score += feat.abilityScoreBonuses[stat]!;
        }
    }

    // 2. Effect System bonuses (summing flat modifiers and finding highest SET value)
    const effects = getActiveEffects(character);
    const bonuses = effects.filter((e: any) => e.type === 'modify_ability_score' && e.target === stat);

    let flatBonus = 0;
    let setVal = -1;

    bonuses.forEach((b: any) => {
        if (typeof b.value === 'string' && b.value.startsWith('SET:')) {
            const v = parseInt(b.value.split(':')[1]);
            if (!isNaN(v) && v > setVal) setVal = v;
        } else {
            flatBonus += Number(b.value) || 0;
        }
    });

    let total = score + flatBonus;
    if (setVal > total) total = setVal;

    return total;
}

export function getProficiencyBonus(character: Character): number {
    const profOverride = character.customOverrides?.overrides?.find(o => o.field === 'proficiencyBonus' && o.isActive);
    if (profOverride) return Number(profOverride.value);

    const base = Math.ceil(character.level / 4) + 1;
    const modifier = character.customOverrides?.modifiers?.proficiencyBonus || 0;
    return base + modifier;
}

export function getInitiative(character: Character): number {
    const initOverride = character.customOverrides?.overrides?.find(o => o.field === 'initiativeMod' && o.isActive);
    if (initOverride) return Number(initOverride.value);

    const dexMod = getAbilityModifier(getEffectiveAbilityScore(character, 'dex'));
    const itemBonus = sumBonus(character, 'add_initiative_bonus');
    const modifier = character.customOverrides?.modifiers?.initiativeMod || 0;

    return dexMod + itemBonus + modifier;
}

export interface ArmorClassBreakdown {
    base: number;
    source: string;
    dexBonus: number;
    dexCap: number | null;
    shieldBonus: number;
    modifierBonus: number;
    total: number;
    isOverridden: boolean;
}

export function getArmorClassBreakdown(character: Character): ArmorClassBreakdown {
    // 1. DM Override check
    const acOverride = character.customOverrides?.overrides?.find(o => o.field === 'ac' && o.isActive);
    if (acOverride) {
        return {
            base: Number(acOverride.value),
            source: 'DM Override: ' + (acOverride.reason || 'None'),
            dexBonus: 0,
            dexCap: null,
            shieldBonus: 0,
            modifierBonus: 0,
            total: Number(acOverride.value),
            isOverridden: true
        };
    }

    // 2. Base AC from Mechanics Engine (handles Armor vs Unarmored Defense)
    const res = getHighestAcSet(character);

    // 3. Shield & Magic Bonuses
    const shieldBonus = sumBonus(character, 'add_ac_bonus', 'ac');
    const flatModifier = character.customOverrides?.modifiers?.ac || 0;

    const total = res.value + shieldBonus + flatModifier;

    return {
        base: res.base,
        source: res.source,
        dexBonus: res.dex,
        dexCap: res.dexCap,
        shieldBonus: shieldBonus,
        modifierBonus: flatModifier,
        total: total,
        isOverridden: false
    };
}

export function getArmorClass(character: Character): number {
    return getArmorClassBreakdown(character).total;
}

export function getSpellSaveDc(character: Character): number {
    const dcOverride = character.customOverrides?.overrides?.find(o => o.field === 'spellSaveDc' && o.isActive);
    if (dcOverride) return Number(dcOverride.value);

    if (character.spellcastingAbility === 'none') return 10;
    const prof = getProficiencyBonus(character);
    const mod = getAbilityModifier(getEffectiveAbilityScore(character, character.spellcastingAbility as any));
    return 8 + prof + mod + (character.customOverrides?.modifiers?.spellSaveDc || 0);
}

export function getSpellAttackMod(character: Character): number {
    const attackOverride = character.customOverrides?.overrides?.find(o => o.field === 'spellAttackMod' && o.isActive);
    if (attackOverride) return Number(attackOverride.value);

    if (character.spellcastingAbility === 'none') return 0;
    const prof = getProficiencyBonus(character);
    const mod = getAbilityModifier(getEffectiveAbilityScore(character, character.spellcastingAbility as any));
    return prof + mod + (character.customOverrides?.modifiers?.spellAttackMod || 0);
}

export function getSkillTotal(character: Character, skillName: string): number {
    const skillOverride = character.customOverrides?.overrides?.find(o => o.field.toLowerCase() === skillName.toLowerCase() && o.isActive);
    if (skillOverride) return Number(skillOverride.value);

    const skill = character.skills.find(s => s.name.toLowerCase() === skillName.toLowerCase());
    if (!skill) return 0;

    let tot = getAbilityModifier(getEffectiveAbilityScore(character, skill.stat));
    // When calculating skill total, we use the effective proficiency bonus. 
    // If the DM overridden proficiency bonus, that's what we use.
    const profBonus = getProficiencyBonus(character);

    if (skill.proficient) tot += profBonus;
    if (skill.expertise) tot += profBonus;

    return tot + (skill.bonus || 0) + (character.customOverrides?.modifiers?.[skillName] || 0);
}

export function getPassiveScore(character: Character, skillName: string): number {
    const passiveOverride = character.customOverrides?.overrides?.find(o => o.field.toLowerCase() === `passive${skillName.toLowerCase()}` && o.isActive);
    if (passiveOverride) return Number(passiveOverride.value);

    const base = 10 + getSkillTotal(character, skillName);
    const modifier = character.customOverrides?.modifiers?.[`passive${skillName}`] || 0;
    return base + modifier;
}

// D&D 5e Official Experience Points Thresholds (Levels 1-20)
export const XP_THRESHOLDS = [
    0,      // Level 1
    300,    // Level 2
    900,    // Level 3
    2700,   // Level 4
    6500,   // Level 5
    14000,  // Level 6
    23000,  // Level 7
    34000,  // Level 8
    48000,  // Level 9
    64000,  // Level 10
    85000,  // Level 11
    100000, // Level 12
    120000, // Level 13
    140000, // Level 14
    165000, // Level 15
    195000, // Level 16
    225000, // Level 17
    265000, // Level 18
    305000, // Level 19
    355000  // Level 20
];

/**
 * Returns the XP required to reach the NEXT level based on the character's current level.
 * If the character is level 20 or higher, it returns the cap (Level 20 XP requirement).
 */
export function getXpRequiredForNextLevel(currentLevel: number): number {
    if (currentLevel < 1) return XP_THRESHOLDS[1]; // Fallback to level 2 if current is 0
    if (currentLevel >= 20) return XP_THRESHOLDS[19]; // Level 20 cap
    return XP_THRESHOLDS[currentLevel]; // Array is 0-indexed, so index 1 represents level 2
}

import { Character } from '../types/character';
import EQUIP_DATA from '../data/rules2024/equipment.json';

export interface MasteryProperty {
    name: string;
    description: string;
}

/**
 * Normalizes a weapon name for lookup (removes (2024) suffixes, trims, lowercase).
 */
export function normalizeWeaponName(name: string): string {
    if (!name) return '';
    return name.replace(/\s*\(?\s*2024\s*\)?\s*/gi, '').trim().toLowerCase();
}

/**
 * Checks if a character has mastery over a specific weapon.
 * In the 2024 rules, this is usually granted by a class feature.
 */
export function hasMastery(character: Character, weaponName: string): boolean {
    if (!character.masteredWeapons) return false;
    const normalizedTarget = normalizeWeaponName(weaponName);
    return character.masteredWeapons.some(w => normalizeWeaponName(w) === normalizedTarget);
}

/**
 * Retrieves the mastery property for a given weapon from the 2024 equipment data.
 */
export function getMasteryProperty(weaponName: string): MasteryProperty | null {
    const normalizedTarget = normalizeWeaponName(weaponName);
    const weapon = (EQUIP_DATA.weapons as any[]).find(w => normalizeWeaponName(w.name) === normalizedTarget);
    if (!weapon || !weapon.mastery) return null;

    const prop = (EQUIP_DATA.masteryProperties as any[]).find(p => p.name.toLowerCase() === weapon.mastery.toLowerCase());
    return prop || null;
}

/**
 * Resolves the mechanical trigger for a weapon mastery.
 * Some masteries are automatic (Graze, Slow, Vex) while others require choices or saves (Topple, Push).
 */
export function resolveMasteryEffect(
    character: Character,
    weaponName: string,
    isHit: boolean,
    attackRoll: number,
    targetAC: number
): {
    type: 'automatic' | 'save' | 'choice';
    propertyName: string;
    description: string;
    trigger?: string;
} | null {
    void attackRoll;
    void targetAC;
    if (!hasMastery(character, weaponName)) return null;

    const prop = getMasteryProperty(weaponName);
    if (!prop) return null;

    // Handle specific property triggers
    switch (prop.name) {
        case 'Graze':
            if (!isHit) return { type: 'automatic', propertyName: prop.name, description: prop.description, trigger: 'miss' };
            break;
        case 'Cleave':
            if (isHit) return { type: 'choice', propertyName: prop.name, description: prop.description, trigger: 'hit' };
            break;
        case 'Topple':
            if (isHit) return { type: 'save', propertyName: prop.name, description: prop.description, trigger: 'hit' };
            break;
        case 'Push':
        case 'Sap':
        case 'Slow':
        case 'Vex':
            if (isHit) return { type: 'automatic', propertyName: prop.name, description: prop.description, trigger: 'hit' };
            break;
        case 'Nick':
            // Nick is a passive modification to the Light property (no trigger needed during attack resolution)
            return null;
    }

    return null;
}

import { useState } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { useCampaignStore } from '../store/campaignStore';
import { useCharacterStore } from '../store/characterStore';
import { Map, Users, Swords, BookOpen, Clock, ChevronLeft, Trash2, Edit2, X, Plus } from 'lucide-react';
import { Campaign } from '../types/campaign';
import { CharacterCard } from '../components/character/CharacterCard';
import { EncounterLibrary } from '../components/combat/EncounterLibrary';
import { ConfirmationModal } from '../components/common/ConfirmationModal';
import { useToast } from '../components/common/ToastProvider';

type Tab = 'overview' | 'party' | 'notes' | 'encounters' | 'npcs' | 'locations';

export function CampaignDetail() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const { addToast } = useToast();

    const campaigns = useCampaignStore((state) => state.campaigns);
    const setActiveCampaign = useCampaignStore((state) => state.setActiveCampaign);
    const activeCampaignId = useCampaignStore((state) => state.activeCampaignId);

    // Time management
    const advanceTime = useCampaignStore((state) => state.advanceTime);

    // Notes management
    const addSessionNote = useCampaignStore((state) => state.addSessionNote);
    const deleteSessionNote = useCampaignStore((state) => state.deleteSessionNote);

    // All characters (for assigning)
    const allCharacters = useCharacterStore((state) => state.characters);
    const longRestParty = useCharacterStore((state) => state.longRestParty);
    // Methods to assign
    const addCharacterToCampaign = useCampaignStore((state) => state.addCharacterToCampaign);
    const removeCharacterFromCampaign = useCampaignStore((state) => state.removeCharacterFromCampaign);
    const addNpc = useCampaignStore((state) => state.addNpc);
    const deleteNpc = useCampaignStore((state) => state.deleteNpc);
    const addLocation = useCampaignStore((state) => state.addLocation);
    const deleteLocation = useCampaignStore((state) => state.deleteLocation);

    const [activeTab, setActiveTab] = useState<Tab>('overview');

    // Modal state
    const [confirmAction, setConfirmAction] = useState<{
        type: 'rest' | 'deleteNote';
        data?: any;
    } | null>(null);

    // Notes state
    const [isWritingNote, setIsWritingNote] = useState(false);
    const [noteTitle, setNoteTitle] = useState('');
    const [noteContent, setNoteContent] = useState('');
    const [noteSessionNum, setNoteSessionNum] = useState(1);

    // NPC State
    const [isAddingNpc, setIsAddingNpc] = useState(false);
    const [npcForm, setNpcForm] = useState({ name: '', faction: '', location: '', description: '' });

    // Location State
    const [isAddingLocation, setIsAddingLocation] = useState(false);
    const [locForm, setLocForm] = useState({ name: '', region: '', description: '' });

    const campaign = campaigns.find(c => c.id === id);

    if (!campaign) {
        return (
            <div className="max-w-6xl mx-auto flex flex-col items-center justify-center py-20 animate-in fade-in duration-300">
                <Map size={48} className="text-stone-600 mb-4" />
                <h2 className="text-2xl font-cinzel text-parchment mb-2">Campaign Not Found</h2>
                <p className="text-stone-400 mb-6">The campaign you are looking for does not exist or has been deleted.</p>
                <Link to="/campaigns" className="px-4 py-2 bg-stone-800 text-parchment rounded hover:bg-stone-700 transition-colors">
                    Back to Campaigns
                </Link>
            </div>
        );
    }

    const partyCharacters = allCharacters.filter(c => campaign.partyIds.includes(c.id));
    const availableCharacters = allCharacters.filter(c => !campaign.partyIds.includes(c.id));

    const handleSaveNote = () => {
        if (!noteTitle.trim() || !noteContent.trim()) return;

        addSessionNote(campaign.id, {
            title: noteTitle,
            content: noteContent,
            sessionNumber: noteSessionNum,
        });

        setIsWritingNote(false);
        setNoteTitle('');
        setNoteContent('');
        setNoteSessionNum(campaign.sessionNotes.length + 2); // default to next
        addToast(`Session Note scribed in the archives.`, 'success');
    };

    const handleAddNpc = () => {
        if (!npcForm.name.trim()) return;
        addNpc(campaign.id, npcForm);
        setNpcForm({ name: '', faction: '', location: '', description: '' });
        setIsAddingNpc(false);
        addToast(`NPC '${npcForm.name}' added to campaign.`, 'success');
    };

    const handleAddLocation = () => {
        if (!locForm.name.trim()) return;
        addLocation(campaign.id, locForm);
        setLocForm({ name: '', region: '', description: '' });
        setIsAddingLocation(false);
        addToast(`Location '${locForm.name}' charted.`, 'success');
    };

    const renderTimeDisplay = (time: Campaign['timeTracking']) => {
        const d = String(time.currentDay).padStart(2, '0');
        const h = String(time.currentHour).padStart(2, '0');
        const m = String(time.currentMinute).padStart(2, '0');
        return `Day ${d} — ${h}:${m}`;
    };

    return (
        <div className="max-w-6xl mx-auto space-y-6 animate-in fade-in duration-300 pb-20">
            {/* Header / Breadcrumb */}
            <div className="flex items-center gap-2 text-stone-400 mb-2 text-sm">
                <Link to="/campaigns" className="hover:text-parchment flex items-center gap-1 transition-colors">
                    <ChevronLeft size={16} /> All Campaigns
                </Link>
                <span>/</span>
                <span className="text-parchment font-medium">{campaign.title}</span>
            </div>

            <header className="flex items-start justify-between border-b border-stone-700/50 pb-6 relative group">
                <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                        <h1 className="text-4xl font-cinzel font-bold text-parchment">{campaign.title}</h1>
