                                        onClick={handleAddNpc}
                                        disabled={!npcForm.name.trim()}
                                        className="px-6 py-2 bg-arcane text-stone-950 font-bold rounded hover:bg-purple-500 transition-colors disabled:opacity-50"
                                    >
                                        Save NPC
                                    </button>
                                </div>
                            </div>
                        )}

