                            {(campaign.npcs || []).map(npc => (
                                <div key={npc.id} className="bg-stone-800/80 border border-stone-700/50 rounded-lg p-5 relative group">
                                    <button
                                        onClick={() => {
                                            if (window.confirm(`Delete ${npc.name}?`)) {
                                                deleteNpc(campaign.id, npc.id);
                                            }
                                        }}
                                        className="absolute top-3 right-3 p-1.5 bg-red-900/40 text-red-400 rounded opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-800 hover:text-white"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                    <h4 className="font-cinzel font-bold text-lg text-parchment mb-2 pr-8">{npc.name}</h4>
                                    <div className="space-y-1 mb-3 text-xs">
                                        {npc.faction && <div className="text-stone-400"><span className="text-stone-500 uppercase tracking-wider">Faction:</span> {npc.faction}</div>}
                                        {npc.location && <div className="text-stone-400"><span className="text-stone-500 uppercase tracking-wider">Location:</span> {npc.location}</div>}
                                    </div>
                                    <p className="text-sm text-stone-300 leading-relaxed whitespace-pre-wrap">{npc.description}</p>
                                </div>
                            ))}
                        </div>
                        {(!campaign.npcs || campaign.npcs.length === 0) && !isAddingNpc && (
                            <div className="text-center py-10 border border-dashed border-stone-700 rounded-lg text-stone-500">
                                No NPCs logged. Are your players truly alone in the world?
                            </div>
                        )}
                    </div>
                )}

                {/* LOCATIONS TAB */}
                {activeTab === 'locations' && (
                    <div className="space-y-6">
                        <div className="flex justify-between items-center">
                            <p className="text-stone-400">Log important settlements, dungeons, and points of interest.</p>
                            <button
                                onClick={() => setIsAddingLocation(!isAddingLocation)}
                                className="flex items-center gap-2 px-4 py-2 bg-stone-800 hover:bg-stone-700 text-green-500 border border-stone-600 rounded-md font-medium transition-colors shadow-sm text-sm"
                            >
                                {isAddingLocation ? <><X size={16} /> Cancel</> : <><Plus size={16} /> New Location</>}
                            </button>
                        </div>

                        {isAddingLocation && (
                            <div className="bg-stone-900 border border-green-500/30 rounded-lg p-6 animate-in slide-in-from-top-4">
                                <h3 className="text-lg font-cinzel text-green-500 mb-4">Chart New Location</h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                    <div>
                                        <label className="block text-xs font-bold text-stone-400 uppercase mb-1">Name</label>
                                        <input
                                            type="text"
                                            value={locForm.name}
                                            onChange={e => setLocForm({ ...locForm, name: e.target.value })}
                                            className="w-full bg-stone-800 border-stone-700 rounded p-2 text-parchment focus:border-green-500 outline-none"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-stone-400 uppercase mb-1">Region / Kingdom</label>
                                        <input
                                            type="text"
                                            value={locForm.region}
                                            onChange={e => setLocForm({ ...locForm, region: e.target.value })}
                                            className="w-full bg-stone-800 border-stone-700 rounded p-2 text-parchment focus:border-green-500 outline-none"
                                        />
                                    </div>
                                </div>
                                <div className="mb-4">
                                    <label className="block text-xs font-bold text-stone-400 uppercase mb-1">Description / Notes</label>
                                    <textarea
                                        value={locForm.description}
                                        onChange={e => setLocForm({ ...locForm, description: e.target.value })}
                                        className="w-full bg-stone-800 border-stone-700 rounded p-2 text-parchment focus:border-green-500 outline-none h-24 custom-scrollbar resize-none"
                                    />
                                </div>
                                <div className="flex justify-end">
                                    <button
                                        onClick={handleAddLocation}
                                        disabled={!locForm.name.trim()}
                                        className="px-6 py-2 bg-green-600 text-stone-950 font-bold rounded hover:bg-green-500 transition-colors disabled:opacity-50"
                                    >
                                        Save Location
                                    </button>
                                </div>
                            </div>
                        )}

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {(campaign.locations || []).map(loc => (
                                <div key={loc.id} className="bg-stone-800/80 border border-stone-700/50 rounded-lg p-5 relative group">
                                    <button
                                        onClick={() => {
                                            if (window.confirm(`Delete ${loc.name}?`)) {
                                                deleteLocation(campaign.id, loc.id);
                                            }
                                        }}
                                        className="absolute top-3 right-3 p-1.5 bg-red-900/40 text-red-400 rounded opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-800 hover:text-white"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                    <div className="flex items-center gap-2 mb-2 pr-8">
                                        <Map size={18} className="text-green-500" />
                                        <h4 className="font-cinzel font-bold text-lg text-parchment">{loc.name}</h4>
                                    </div>
                                    <div className="space-y-1 mb-3 text-xs">
                                        {loc.region && <div className="text-stone-400"><span className="text-stone-500 uppercase tracking-wider">Region:</span> {loc.region}</div>}
                                    </div>
                                    <p className="text-sm text-stone-300 leading-relaxed whitespace-pre-wrap">{loc.description}</p>
                                </div>
                            ))}
                        </div>
                        {(!campaign.locations || campaign.locations.length === 0) && !isAddingLocation && (
                            <div className="text-center py-10 border border-dashed border-stone-700 rounded-lg text-stone-500">
                                No locations charted. The map is blank.
                            </div>
                        )}
                    </div>
                )}

                {/* ENCOUNTERS TAB */}
                {activeTab === 'encounters' && (
                    <div className="space-y-4">
                        <p className="text-stone-400 mb-4">Saved encounters and templates created while this campaign was active.</p>
                        <EncounterLibrary campaignId={campaign.id} />
                    </div>
                )}
            </div>

            <ConfirmationModal
                isOpen={confirmAction?.type === 'rest'}
                title="Trigger Long Rest?"
                message="Are you sure you want to trigger a Long Rest for the entire party? This will restore all HP, half their Hit Dice, and all Spell Slots, while advancing in-game time by 8 hours."
                confirmText="Rest Party"
                onConfirm={() => {
                    advanceTime(campaign.id, 8 * 60);
                    longRestParty(campaign.partyIds);
                    setConfirmAction(null);
                    addToast('The party has completed a Long Rest.', 'info');
                }}
                onCancel={() => setConfirmAction(null)}
            />

            <ConfirmationModal
                isOpen={confirmAction?.type === 'deleteNote'}
                title="Burn these pages?"
                message="Are you sure you want to delete this session note? This action cannot be undone."
                confirmText="Delete Note"
                isDangerous={true}
                onConfirm={() => {
                    if (confirmAction?.data) {
                        deleteSessionNote(campaign.id, confirmAction.data);
                        addToast('Session Note burnt.', 'success');
                    }
                    setConfirmAction(null);
                }}
                onCancel={() => setConfirmAction(null)}
            />

        </div>
    );
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { Character, Item } from '../types/character';
import type { ClassEntry, LevelUpChoices } from '../types/rules';
import { applyShortRest, applyLongRest, RestResult } from '../engine/restEngine';
import { useCampaignStore } from './campaignStore';
import {
    XP_THRESHOLDS,
    getProficiencyBonus,
    getArmorClass,
    getInitiative
} from '../engine/statCalculations';
import {
    getAverageHPGain,
    getHitDie,
    getMulticlassSpellSlots,
    validateMulticlassPrereqs,
    getTotalCharacterLevel,
    buildSpellSlotsForClass,
    getClassSpellcastingAbility,
    calculateMaxHP,
} from '../engine/rulesEngine';

interface CharacterState {
    characters: Character[];
    addCharacter: (character: Character) => void;
    updateCharacter: (id: string, updates: Partial<Character>) => void;
    deleteCharacter: (id: string) => void;
    getCharacter: (id: string) => Character | undefined;
    importCharacters: (characters: Character[]) => void;
    shortRest: (id: string, hitDiceToSpend: number) => RestResult | undefined;
    longRest: (id: string) => RestResult | undefined;
    shortRestParty: (ids: string[], hitDiceMap: Record<string, number>) => void;
    longRestParty: (ids: string[]) => void;
    addExperience: (id: string, amount: number) => void;
    /** Level up the primary class. Pass RulesEngine choices for ASI, feats, spells. */
    levelUpCharacter: (id: string, choices?: LevelUpChoices) => void;
    /** Add a new class to a multiclassed character. Validates prerequisites. */
    addMulticlass: (id: string, newClassName: string) => { success: boolean; reason?: string };
    consumeItem: (characterId: string, itemId: string) => void;
    addItem: (characterId: string, item: Omit<Item, 'id'>) => void;
}

export const useCharacterStore = create<CharacterState>()(
    persist(
        (set, get) => ({
            characters: [],

            addCharacter: (character) => {
                set((state) => ({ characters: [...state.characters, character] }));

                // Auto-assign to active campaign
                const activeCampaignId = useCampaignStore.getState().activeCampaignId;
                if (activeCampaignId) {
                    useCampaignStore.getState().addCharacterToCampaign(activeCampaignId, character.id);
                }
            },

            updateCharacter: (id, updates) => {
                set((state) => ({
                    characters: state.characters.map((char) => {
                        if (char.id !== id) return char;
                        const updated = { ...char, ...updates };
                        // Ensure derived stats are synced
                        return {
                            ...updated,
                            ac: getArmorClass(updated),
                            initiativeMod: getInitiative(updated),
                            maxHp: calculateMaxHP(updated)
                        };
                    })
                }));
            },

            deleteCharacter: (id) =>
                set((state) => {
                    // Clean up campaign associations
                    const campaigns = useCampaignStore.getState().campaigns;
                    campaigns.forEach(c => {
                        if (c.partyIds.includes(id)) {
                            useCampaignStore.getState().removeCharacterFromCampaign(c.id, id);
                        }
                    });

                    return {
                        characters: state.characters.filter((char) => char.id !== id)
                    };
                }),

            getCharacter: (id) => get().characters.find((char) => char.id === id),

            importCharacters: (newCharacters) => {
                set((state) => {
                    // Merge logic: avoid duplicate IDs, simple replace or append
                    const existingIds = new Set(state.characters.map((c) => c.id));
                    const filteredNew = newCharacters.filter((c) => !existingIds.has(c.id));
                    return { characters: [...state.characters, ...filteredNew] };
                });

                // Auto-assign all new characters to active campaign
                const activeCampaignId = useCampaignStore.getState().activeCampaignId;
                if (activeCampaignId) {
                    newCharacters.forEach(char => {
                        useCampaignStore.getState().addCharacterToCampaign(activeCampaignId, char.id);
                    });
                }
            },

            shortRest: (id, hitDiceToSpend) => {
                const char = get().getCharacter(id);
                if (!char) return undefined;
                const result = applyShortRest(char, hitDiceToSpend);
                get().updateCharacter(id, result.updatedCharacter);
                return result;
            },

            longRest: (id) => {
                const char = get().getCharacter(id);
                if (!char) return undefined;
                const result = applyLongRest(char);
                get().updateCharacter(id, result.updatedCharacter);
                return result;
            },

            shortRestParty: (ids, hitDiceMap) =>
                set((state) => ({
                    characters: state.characters.map((char) => {
                        if (!ids.includes(char.id)) return char;
                        const spend = hitDiceMap[char.id] || 0;
                        return applyShortRest(char, spend).updatedCharacter;
                    })
                })),

            longRestParty: (ids) =>
                set((state) => ({
                    characters: state.characters.map((char) =>
                        ids.includes(char.id) ? applyLongRest(char).updatedCharacter : char
                    )
                })),

            addExperience: (id, amount) => {
                const char = get().getCharacter(id);
                if (!char) return;

                const newXp = char.experience + amount;

                set((state) => ({
                    characters: state.characters.map((c) =>
                        c.id === id ? { ...c, experience: newXp } : c
                    )
                }));

                // Auto level up if threshold reached (check for multi-level jumps)
                let currentLevel = char.level;
                const currentXp = newXp;
                while (currentLevel < 20 && currentXp >= (XP_THRESHOLDS[currentLevel] || Infinity)) {
                    get().levelUpCharacter(id);
                    currentLevel++;
                }
            },

            levelUpCharacter: (id, choices) => {
                const char = get().getCharacter(id);
                if (!char) return;

                const totalLevel = getTotalCharacterLevel(char);
                if (totalLevel >= 20) return;

                const newLevel = char.level + 1;

                // Proficiency bonus based on total character level
                const tempChar = { ...char, level: newLevel };
                const newProf = getProficiencyBonus(tempChar);

                // HP gain: use provided value from LevelUpWizard, or fall back to average
                const conMod = Math.floor(((char.abilityScores?.con || 10) - 10) / 2);
                const hpGain = choices?.hpGain ?? getAverageHPGain(char.className, conMod);

                // Hit dice string update (e.g. "5d10")
                const dieSize = getHitDie(char.className);

                // Rebuild spell slots based on new level
                const newSpellSlots = buildSpellSlotsForClass(
                    char.className,
                    newLevel,
                    char.subclass || undefined
                );
                // Preserve current slot usage — only increase maximums
                const mergedSlots = newSpellSlots.map((newSlot, idx) => {
                    const existing = char.spellSlots[idx] ?? { current: 0, max: 0 };
                    return {
                        max: newSlot.max,
                        current: Math.min(existing.current + (newSlot.max - existing.max), newSlot.max)
                    };
                });

                // ASI: apply ability score increases from choices
                const updatedAbilityScores = { ...char.abilityScores };
                if (choices?.abilityScoreIncreases) {
                    for (const [stat, bonus] of Object.entries(choices.abilityScoreIncreases)) {
                        const key = stat as keyof typeof updatedAbilityScores;
                        updatedAbilityScores[key] = Math.min(20, (updatedAbilityScores[key] ?? 10) + (bonus ?? 0));
                    }
                }

                // Apply new feat (if chosen instead of ASI)
                const newFeats = char.feats ? [...char.feats] : [];
                if (choices?.feat) {
                    newFeats.push(choices.feat);
                }

                // Apply new spells
                const newSpells = char.spells ? [...char.spells] : [];
                if (choices?.newSpells) {
                    const existingIds = new Set(newSpells.map(s => s.id));
                    for (const spell of choices.newSpells) {
                        if (!existingIds.has(spell.id)) newSpells.push(spell);
                    }
                }

                // Update the classes array if multiclassing
                let updatedClasses = char.classes ? [...char.classes] : undefined;
                if (updatedClasses) {
                    updatedClasses = updatedClasses.map(c =>
                        c.className.toLowerCase() === char.className.toLowerCase()
                            ? { ...c, level: newLevel }
                            : c
                    );
                }

                set((state) => ({
                    characters: state.characters.map((c) =>
                        c.id === id ? {
                            ...c,
                            level: newLevel,
                            proficiencyBonus: newProf,
                            maxHp: calculateMaxHP({ ...c, level: newLevel, abilityScores: updatedAbilityScores, feats: newFeats, classes: updatedClasses }),
                            currentHp: c.currentHp + hpGain,
                            hitDice: `${newLevel}d${dieSize}`,
                            abilityScores: updatedAbilityScores,
                            spellSlots: mergedSlots,
                            feats: newFeats,
                            spells: newSpells,
                            classes: updatedClasses,
                        } : c
                    )
                }));
            },

            addMulticlass: (id, newClassName) => {
                const char = get().getCharacter(id);
                if (!char) return { success: false, reason: 'Character not found' };

                const existingClasses: ClassEntry[] = char.classes ?? [{
                    className: char.className,
                    subclass: char.subclass,
                    level: char.level,
                    hitDice: getHitDie(char.className),
                    spellcastingAbility: getClassSpellcastingAbility(char.className, char.subclass || undefined),
                    spellcasterType: 'none', // Will be resolved by rulesEngine
                }];

                const validation = validateMulticlassPrereqs(
                    char.abilityScores,
                    newClassName,
                    existingClasses
                );

                if (!validation.valid) {
                    return { success: false, reason: validation.reason };
                }

                const dieSize = getHitDie(newClassName);
                const spellAbility = getClassSpellcastingAbility(newClassName);

                const newClassEntry: ClassEntry = {
                    className: newClassName,
                    subclass: '',
                    level: 1,
                    hitDice: dieSize,
                    spellcastingAbility: spellAbility,
                    spellcasterType: 'none',
                };

                const updatedClasses = [...existingClasses, newClassEntry];

                // Recalculate spell slots with multiclass table
                const multiclassSlots = getMulticlassSpellSlots(updatedClasses);

                // HP gain for the first level in the new class (average method)
                const conMod = Math.floor(((char.abilityScores?.con || 10) - 10) / 2);
                const hpGain = getAverageHPGain(newClassName, conMod);

                set((state) => ({
                    characters: state.characters.map((c) =>
                        c.id === id ? {
                            ...c,
                            classes: updatedClasses,
                            maxHp: c.maxHp + hpGain,
                            currentHp: c.currentHp + hpGain,
                            spellSlots: multiclassSlots,
                        } : c
                    )
                }));

                return { success: true };
            },

            consumeItem: (characterId, itemId) => {
                set((state) => ({
                    characters: state.characters.map((char) => {
                        if (char.id !== characterId) return char;

                        return {
                            ...char,
                            inventory: char.inventory.map((item) => {
                                if (item.id !== itemId) return item;

                                const newQuantity = Math.max(0, item.quantity - 1);
                                return { ...item, quantity: newQuantity };
                            })
                        };
                    })
                }));
            },

            addItem: (characterId, itemData) => {
                set((state) => ({
                    characters: state.characters.map((char) => {
                        if (char.id !== characterId) return char;

                        // Try stacking first
                        const existing = char.inventory.find(i => i.name === itemData.name && i.type === itemData.type);
                        if (existing) {
                            return {
                                ...char,
                                inventory: char.inventory.map(i =>
                                    i.id === existing.id
                                        ? { ...i, quantity: i.quantity + itemData.quantity }
                                        : i
                                )
                            };
                        }

                        // New item
                        const newItem: Item = { ...itemData, id: crypto.randomUUID() } as Item;
                        return {
                            ...char,
                            inventory: [...char.inventory, newItem]
                        };
                    })
                }));
            }
        }),
        {
            name: 'dm-assistant-characters', // unique name for localStorage key
            onRehydrateStorage: () => (state) => {
                // Sanitize corrupted numeric fields on load
                if (!state) return;
                state.characters = state.characters.map(char => {
                    const sanitize = (val: any, fallback: number, max?: number) => {
                        const n = Number(val);
                        if (isNaN(n)) return fallback;
                        if (max !== undefined && n > max) return max;
                        return n;
                    };

                    const clampStat = (val: any) => {
                        const n = Number(val);
                        if (isNaN(n) || n > 30 || n < 1) return 10;
                        return n;
                    };

                    // Sanitize speed: strip duplicate "ft", cap numeric portion
                    let speed = char.speed || '30 ft';
                    if (typeof speed === 'string') {
                        // Fix "3025 ft ft" → extract first number and normalize
                        const speedNum = parseInt(speed.replace(/[^0-9]/g, ''));
                        if (speedNum > 120) speed = '30 ft';
                        else speed = speed.replace(/\s*(ft\.?\s*)+/gi, ' ft').trim();
                    }

                    // Ensure spellSlots always has exactly 10 entries (indices 0-9)
                    let spellSlots = char.spellSlots || [];
                    if (spellSlots.length < 10) {
                        spellSlots = [...spellSlots, ...Array(10 - spellSlots.length).fill({ max: 0, current: 0 })];
                    }
                    spellSlots = spellSlots.slice(0, 10);

                    const sanitizedBase = {
                        ...char,
                        maxHp: sanitize(char.maxHp, 10, 999),
                        currentHp: sanitize(char.currentHp, 10, 999),
                        tempHp: sanitize(char.tempHp, 0, 999),
                        ac: sanitize(char.ac, 10, 30),
                        level: sanitize(char.level, 1, 20),
                        experience: sanitize(char.experience, 0),
                        proficiencyBonus: sanitize(char.proficiencyBonus, 2, 10),
                        speed,
                        spellSlots,
                        racialTraits: char.racialTraits || [],
                        feats: char.feats || [],
                        abilityScores: char.abilityScores ? {
                            str: clampStat(char.abilityScores.str),
                            dex: clampStat(char.abilityScores.dex),
                            con: clampStat(char.abilityScores.con),
                            int: clampStat(char.abilityScores.int),
                            wis: clampStat(char.abilityScores.wis),
                            cha: clampStat(char.abilityScores.cha),
                        } : char.abilityScores,
                        masteredWeapons: char.masteredWeapons || [],
                    };

                    // Final pass: recalculate derived stats from sanitized base stats
                    return {
                        ...sanitizedBase,
                        ac: getArmorClass(sanitizedBase),
                        initiativeMod: getInitiative(sanitizedBase)
                    };
                });
            }
        }
    )
);

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { Encounter, Combatant, CombatLogEntry, SavedEncounter, CombatAction } from '../types/combat';
import { DungeonMap } from '../types/campaignNavigator';
import { dungeonMapToBattleMapState } from '../engine/mapBridge';
import { BattleMapState, MapToken } from '../types/battleMap';
import { createBasicTurnState, getNextCombatant, rollMissingInitiatives, sortCombatantsByInitiative } from '../engine/combatEngine';
import { gridDistance3DFt } from '../engine/gridEngine';
import { useCharacterStore } from './characterStore';
import { CR_TO_XP } from '../engine/encounterDifficulty';
import { getArmorClass, getInitiative, getEffectiveAbilityScore } from '../engine/statCalculations';

interface CombatStore {
    activeEncounter: Encounter | null;
    history: Encounter[];
    savedEncounters: SavedEncounter[];
    manualRollsEnabled: boolean;
    pastStates: Encounter[]; // Undo stack
    selectedCombatantId: string | null;
    wizardAction: {
        action: CombatAction;
        actor: Combatant;
        initialTargets?: Combatant[];
    } | null;

    // Save/Load Encounters
    saveEncounterTemplate: (template: Omit<SavedEncounter, 'id' | 'createdAt'>) => void;
    deleteSavedEncounter: (id: string) => void;
    loadSavedEncounter: (id: string, customTitle?: string) => void;

    // Setup
    startEncounter: (title: string, combatants: Combatant[], campaignId?: string) => void;
    completeSetup: () => void;
    setBattleMap: (state: BattleMapState) => void;
    initializeEncounterFromNavigator: (map: DungeonMap) => void;
    updateBattleMap: (updates: Partial<BattleMapState>) => void;
    updateToken: (tokenId: string, updates: Partial<MapToken>) => void;
    completeMapSetup: () => void;
    skipMapSetup: () => void;
    resizeGrid: (side: 'top' | 'bottom' | 'left' | 'right', delta: number) => void;
    endEncounter: () => void;
    addCombatant: (combatant: Combatant) => void;
    removeCombatant: (id: string) => void;
    clearCombatants: () => void;
    cancelEncounter: () => void;

    // Settings
    toggleManualRolls: () => void;

    // Core flow
    rollAllInitiative: () => void;
    setInitiative: (id: string, score: number) => void;
    beginCombat: () => void;
    nextTurn: () => void;

    // Actions & State
    updateCombatant: (id: string, updates: Partial<Combatant>) => void;
    damageCombatant: (id: string, amount: number, damageType?: string, isMagical?: boolean) => void;
    healCombatant: (id: string, amount: number) => void;
    applyGroupHealthChange: (ids: string[], amount: number, isDamage: boolean, damageType?: string, isMagical?: boolean) => void;
    consumeAction: (flags?: { isLeveledSpell?: boolean; isHasteAction?: boolean }) => void;
    consumeBonusAction: (flags?: { isLeveledSpell?: boolean }) => void;
    consumeReaction: () => void;
    restoreAction: (id: string) => void;
    useLegendaryAction: (id: string) => void;
    toggleCombatantResource: (id: string, resource: 'action' | 'bonus' | 'reaction' | 'legendary' | 'castLeveled' | 'castBonus' | 'usedHaste') => void;
    useSpellSlot: (id: string, level: number) => void;
    setConcentration: (id: string, spell: { spellId: string; name: string } | null) => void;
    setReadiedAction: (id: string, action: { description: string; trigger: string } | null) => void;
    refreshPlayerStats: () => void;

    // Logging & Undo
    addLog: (entry: Omit<CombatLogEntry, 'id' | 'timestamp' | 'round'>) => void;
    undo: () => void;

    // Targeting
    setSelectedCombatant: (id: string | null) => void;
    setWizardAction: (action: { action: CombatAction; actor: Combatant; initialTargets?: Combatant[] } | null) => void;
}

export const useCombatStore = create<CombatStore>()(
    persist(
        (set, get) => ({
            activeEncounter: null,
            history: [],
            savedEncounters: [],
            manualRollsEnabled: false,
            pastStates: [],
            selectedCombatantId: null,
            wizardAction: null,

            toggleManualRolls: () => set(state => ({ manualRollsEnabled: !state.manualRollsEnabled })),

            saveEncounterTemplate: (template) => set(state => ({
                savedEncounters: [
                    ...(state.savedEncounters || []),
                    { ...template, id: crypto.randomUUID(), createdAt: Date.now() }
                ]
            })),

            deleteSavedEncounter: (id) => set(state => ({
                savedEncounters: (state.savedEncounters || []).filter(e => e.id !== id)
            })),

            loadSavedEncounter: (id, customTitle) => set(state => {
                const enc = (state.savedEncounters || []).find(e => e.id === id);
                if (!enc) return state;

                // Create deeply cloned new combatants for the active encounter
                const newCombatants = enc.enemies.map(c => ({
                    ...c,
                    id: crypto.randomUUID(),
                    currentHp: c.maxHp, // Full health
                    tempHp: 0,
                    initiativeScore: null,
                    conditions: []
                }));

                const newEncounter: Encounter = {
                    id: crypto.randomUUID(),
                    title: customTitle || enc.title,
                    isActive: false,
                    isSetupComplete: false,
                    round: 0,
                    campaignId: enc.campaignId,
                    combatants: newCombatants, // Only loads monsters
                    activeCombatantId: null,
                    turnState: createBasicTurnState(undefined),
                    log: [
                        { id: crypto.randomUUID(), timestamp: Date.now(), round: 0, message: `Loaded encounter template "${enc.title}".`, type: 'system' }
                    ]
                };

                return { activeEncounter: newEncounter };
            }),

            startEncounter: (title, combatants, campaignId) => {
                const newEncounter: Encounter = {
                    id: crypto.randomUUID(),
                    title,
                    isActive: false, // Wait for beginCombat
                    isSetupComplete: false, // Setup phase
                    round: 0,
                    campaignId,
                    combatants,
                    activeCombatantId: null,
                    turnState: createBasicTurnState(undefined),
                    log: [
                        { id: crypto.randomUUID(), timestamp: Date.now(), round: 0, message: `Encounter "${title}" created.`, type: 'system' }
                    ]
                };
                set({ activeEncounter: newEncounter });
            },

            completeSetup: () => set((state) => {
                if (!state.activeEncounter) return state;
                return {
                    activeEncounter: { ...state.activeEncounter, isSetupComplete: true }
                };
            }),

            setBattleMap: (mapState) => set((state) => {
                if (!state.activeEncounter) return state;
                return {
                    activeEncounter: { ...state.activeEncounter, battleMap: mapState }
                };
            }),

            initializeEncounterFromNavigator: (mapData) => {
                const charStore = useCharacterStore.getState();
                const battleMap = dungeonMapToBattleMapState(mapData);

                // Resolve tokens to combatants (players only for now, since monsters are added in setup)
                const bridgeCombatants: Combatant[] = mapData.tokens
                    .map(token => {
                        if (token.faction !== 'player') return null;
                        const char = charStore.characters.find(c => c.id === token.combatantId);
                        if (!char) return null;

                        return {
                            id: token.combatantId,
                            sourceId: token.combatantId,
                            name: char.name,
                            type: 'player',
                            maxHp: char.maxHp,
                            currentHp: char.currentHp,
                            tempHp: char.tempHp || 0,
                            ac: char.ac,
                            armorClass: char.ac,
                            speed: char.speed || '30 ft',
                            initiativeMod: char.initiativeMod || 0,
                            dexterityScore: char.abilityScores.dex || 10,
                            initiativeScore: null,
                            conditions: char.conditions || [],
                            faction: 'player',
                            tokenSize: token.size || 1,
                            hasAction: true,
                            hasBonusAction: true,
                            hasReaction: true
                        } as Combatant;
                    })
                    .filter((c): c is Combatant => c !== null);

                const newEncounter: Encounter = {
                    id: crypto.randomUUID(),
                    title: `Tactical Combat - ${mapData.name}`,
                    isActive: false,
                    isSetupComplete: true, // Players and map are ready, proceed to map adjustments
                    mapSetupComplete: false,
                    round: 0,
                    combatants: bridgeCombatants,
                    activeCombatantId: null,
                    battleMap: battleMap,
                    turnState: createBasicTurnState(undefined),
                    log: [
                        { id: crypto.randomUUID(), timestamp: Date.now(), round: 0, message: `Tactical engagement initiated from ${mapData.name}.`, type: 'system' }
                    ]
                };

                set({ activeEncounter: newEncounter });
            },

            updateBattleMap: (updates) => set((state) => {
                if (!state.activeEncounter || !state.activeEncounter.battleMap) return state;
                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        battleMap: { ...state.activeEncounter.battleMap, ...updates }
                    }
                };
            }),

            updateToken: (tokenId, updates) => set((state) => {
                if (!state.activeEncounter || !state.activeEncounter.battleMap) return state;

                const token = state.activeEncounter.battleMap.tokens.find(t => t.id === tokenId);
                if (!token) return state;

                let movementUpdate = {};

                // If moving a token that belongs to the active combatant during combat
                if (state.activeEncounter.isActive && token.combatantId === state.activeEncounter.activeCombatantId) {
                    const newPos = updates.position || token.position;
                    const newElev = updates.elevation !== undefined ? updates.elevation : token.elevation;

                    const dist = Math.round(gridDistance3DFt(token.position, newPos, token.elevation, newElev));

                    if (dist > 0) {
                        const activeCombatant = state.activeEncounter.combatants.find(c => c.id === token.combatantId);

                        // Conditions that reduce speed to 0
                        const zeroSpeedConditions = ['Grappled', 'Restrained', 'Paralyzed', 'Petrified', 'Stunned', 'Unconscious'];
                        const hasZeroSpeed = activeCombatant?.conditions?.some(c => zeroSpeedConditions.includes(c.name)) || false;

                        if (dist > (state.activeEncounter.turnState.movementRemaining || 0) || hasZeroSpeed) {
                            // Prevent movement if not enough movement remains or special condition applies
                            return state;
                        }

                        movementUpdate = {
                            turnState: {
                                ...state.activeEncounter.turnState,
                                movementRemaining: Math.max(0, (state.activeEncounter.turnState.movementRemaining || 0) - dist),
                                movementUsedFt: (state.activeEncounter.turnState.movementUsedFt || 0) + dist
                            }
                        };

                        // Opportunity Attack Warning
                        // Check if moving out of 5ft range of any enemy (assuming not disengaged, but we don't track Disengage yet
                        // so we just warn the DM to check)
                        if (token.faction) {
                            const enemyFactions = token.faction === 'player' || token.faction === 'ally' ? ['enemy'] : ['player', 'ally'];
                            const enemies = state.activeEncounter.battleMap.tokens.filter(t => enemyFactions.includes(t.faction));

                            const wasAdjacent = enemies.filter(e => gridDistance3DFt(token.position, e.position, token.elevation, e.elevation) <= 5);
                            const isAdjacent = enemies.filter(e => gridDistance3DFt(newPos, e.position, newElev, e.elevation) <= 5);

                            // If was adjacent to an enemy, and now isn't, and the enemy isn't dead/unconscious
                            const movedAwayFrom = wasAdjacent.filter(wa =>
                                !isAdjacent.find(ia => ia.id === wa.id) &&
                                !state.activeEncounter?.combatants.find(c => c.id === wa.combatantId)?.isDead &&
                                !(state.activeEncounter?.combatants.find(c => c.id === wa.combatantId)?.conditions.some(c => c.name === 'Unconscious'))
                            );

                            if (movedAwayFrom.length > 0) {
                                const enemyNames = movedAwayFrom.map(e => e.name).join(', ');
                                const combatLogEntry: CombatLogEntry = {
                                    id: crypto.randomUUID(),
                                    timestamp: Date.now(),
                                    round: state.activeEncounter.round,
                                    message: `⚔️ **Opportunity Attack Warning:** ${token.name} moved out of melee range of ${enemyNames}!`,
                                    type: 'system',
                                    combatantId: token.combatantId
                                };

                                // We need to add this to the logs. We can do it in the final return.
                                movementUpdate = {
                                    ...movementUpdate,
                                    log: [...state.activeEncounter.log, combatLogEntry]
                                };
                            }
                        }
                    }
                }

                const tokens = state.activeEncounter.battleMap.tokens.map(t =>
                    t.id === tokenId ? { ...t, ...updates } : t
                );

                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        ...movementUpdate,
                        battleMap: { ...state.activeEncounter.battleMap, tokens }
                    }
                };
            }),

            completeMapSetup: () => set((state) => {
                if (!state.activeEncounter) return state;
                return {
                    activeEncounter: { ...state.activeEncounter, mapSetupComplete: true }
                };
            }),

            skipMapSetup: () => set((state) => {
                if (!state.activeEncounter) return state;
                return {
                    activeEncounter: { ...state.activeEncounter, mapSetupComplete: true, battleMap: undefined }
                };
            }),

            resizeGrid: (side, delta) => set((state) => {
                if (!state.activeEncounter || !state.activeEncounter.battleMap) return state;
                const map = state.activeEncounter.battleMap;

                const isHorizontal = side === 'left' || side === 'right';
                const newWidth = isHorizontal ? Math.max(5, map.gridWidth + delta) : map.gridWidth;
                const newHeight = !isHorizontal ? Math.max(5, map.gridHeight + delta) : map.gridHeight;

                const appliedDelta = isHorizontal ? (newWidth - map.gridWidth) : (newHeight - map.gridHeight);
                const colShift = side === 'left' ? appliedDelta : 0;
                const rowShift = side === 'top' ? appliedDelta : 0;

                // Shift tokens
                const updatedTokens = map.tokens.map(token => ({
                    ...token,
                    position: {
                        col: Math.max(0, Math.min(token.position.col + colShift, newWidth - (token.size || 1))),
                        row: Math.max(0, Math.min(token.position.row + rowShift, newHeight - (token.size || 1)))
                    }
                }));

                // Shift shapes
                const updatedShapes = map.shapes.map(shape => ({
                    ...shape,
                    points: shape.points.map(p => ({
                        col: p.col + colShift,
                        row: p.row + rowShift
                    }))
                }));

                // Shift freehand paths (pixels)
                const pxColShift = colShift * map.cellSizePx;
                const pxRowShift = rowShift * map.cellSizePx;
                const updatedPaths = map.freehandPaths.map(path => ({
                    ...path,
                    points: path.points.map(p => ({
                        x: p.x + pxColShift,
                        y: p.y + pxRowShift
                    }))
                }));

                // Fog of War
                const updatedFoW = map.fogOfWar.map(s => ({
                    ...s,
                    points: s.points.map(p => ({ col: p.col + colShift, row: p.row + rowShift }))
                }));
                const updatedFoWFree = map.fogOfWarFreehand.map(path => ({
                    ...path,
                    points: path.points.map(p => ({ x: p.x + pxColShift, y: p.y + pxRowShift }))
                }));

                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        battleMap: {
                            ...map,
                            gridWidth: newWidth,
                            gridHeight: newHeight,
                            tokens: updatedTokens,
                            shapes: updatedShapes,
                            freehandPaths: updatedPaths,
                            fogOfWar: updatedFoW,
                            fogOfWarFreehand: updatedFoWFree
                        }
                    }
                };
            }),

            applyGroupHealthChange: (ids: string[], amount: number, isDamage: boolean, damageType?: string, isMagical: boolean = false) => set((state) => {
                if (!state.activeEncounter) return state;
                const enc = state.activeEncounter;
                const pastStates = [...(state.pastStates || []), enc].slice(-10);
                const newLogs: CombatLogEntry[] = [];
                const extraLogs: CombatLogEntry[] = [];

                const updatedCombatants = enc.combatants.map(c => {
                    if (!ids.includes(c.id)) return c;

                    if (!isDamage) {
                        // Healing logic
                        const newHp = Math.min(c.maxHp, c.currentHp + amount);
                        const actualHeal = newHp - c.currentHp;
                        newLogs.push({
                            id: crypto.randomUUID(), round: enc.round, timestamp: Date.now(),
                            message: `${c.name} healed for ${actualHeal} HP.`, type: 'heal', combatantId: c.id
                        });
                        return { ...c, currentHp: newHp, isDead: false };
                    }

                    // Damage logic (simplified but consistent with damageCombatant)
                    let finalAmount = amount;
                    let modification = '';
                    if (damageType) {
                        const t = damageType.toLowerCase();
                        if (c.immunities?.some(i => i.toLowerCase() === t)) { finalAmount = 0; modification = ' (Immune)'; }
                        else if (c.resistances?.some(r => r.toLowerCase() === t)) {
                            const isPhys = ['bludgeoning', 'piercing', 'slashing'].includes(t);
                            const nonMag = c.damageNotes?.toLowerCase().includes('nonmagical');
                            if (!(isPhys && nonMag && isMagical)) {
                                finalAmount = Math.floor(finalAmount / 2);
                                modification = ' (Resisted)';
                            }
                        }
                        else if (c.vulnerabilities?.some(v => v.toLowerCase() === t)) { finalAmount = finalAmount * 2; modification = ' (Vulnerable)'; }
                    }

                    let rem = finalAmount;
                    let nTemp = c.tempHp;
                    let nHp = c.currentHp;
                    if (nTemp > 0) {
                        if (nTemp >= rem) { nTemp -= rem; rem = 0; }
                        else { rem -= nTemp; nTemp = 0; }
                    }
                    nHp = Math.max(0, nHp - rem);
                    const isNowDead = nHp === 0;

                    newLogs.push({
                        id: crypto.randomUUID(), round: enc.round, timestamp: Date.now(),
                        message: `${c.name} took ${finalAmount}${damageType ? ` ${damageType}` : ''} damage${modification}.${isNowDead ? ' They are dying/dead!' : ''}`,
                        type: 'damage', combatantId: c.id
                    });

                    // Concentration handling
                    if (c.isConcentrating && finalAmount > 0) {
                        if (isNowDead) {
                            // Auto-drop concentration at 0 HP
                            extraLogs.push({
                                id: crypto.randomUUID(), round: enc.round, timestamp: Date.now(),
                                message: `💥 ${c.name} dropped to 0 HP — Concentration broken!`,
                                type: 'status', combatantId: c.id
                            });
                            return { ...c, currentHp: nHp, tempHp: nTemp, isDead: c.type === 'monster' && isNowDead, isConcentrating: false, concentratingOn: undefined };
                        } else {
                            const dc = Math.max(10, Math.floor(finalAmount / 2));
                            extraLogs.push({
                                id: crypto.randomUUID(), round: enc.round, timestamp: Date.now(),
                                message: `⚠️ CONCENTRATION: ${c.name} must make a DC ${dc} CON Save!`,
                                type: 'system', combatantId: c.id
                            });
                        }
                    }

                    // Death save reminder for players at 0 HP
                    if (isNowDead && c.type === 'player') {
                        extraLogs.push({
                            id: crypto.randomUUID(), round: enc.round, timestamp: Date.now() + 1,
                            message: `💀 ${c.name} is at 0 HP! They will need to make Death Saving Throws.`,
                            type: 'status', combatantId: c.id
                        });
                    }

                    return { ...c, currentHp: nHp, tempHp: nTemp, isDead: c.type === 'monster' && isNowDead };
                });

                return {
                    pastStates,
                    activeEncounter: { ...enc, combatants: updatedCombatants, log: [...enc.log, ...newLogs, ...extraLogs] }
                };
            }),

            endEncounter: () => {
                const { activeEncounter, history } = get();
                if (!activeEncounter) return;

                const charStore = useCharacterStore.getState();

                // Calculate XP Reward
                const defeatedMonsters = activeEncounter.combatants.filter(c => c.type === 'monster' && c.currentHp <= 0);
                const totalXp = defeatedMonsters.reduce((sum, m) => sum + (CR_TO_XP[m.cr || '0'] || 0), 0);
                const players = activeEncounter.combatants.filter(c => c.type === 'player');
                const xpPerPlayer = players.length > 0 ? Math.floor(totalXp / players.length) : 0;

                // Sync player stats and award XP
                activeEncounter.combatants.forEach(c => {
                    if (c.type === 'player' && c.sourceId) {
                        charStore.updateCharacter(c.sourceId, {
                            currentHp: c.currentHp,
                            tempHp: c.tempHp,
                            spellSlots: c.spellSlots,
                            deathSaves: c.deathSaves,
                            conditions: c.conditions,
                            exhaustion: c.exhaustion,
                        });

                        if (xpPerPlayer > 0) {
                            charStore.addExperience(c.sourceId, xpPerPlayer);
                        }
                    }
                });

                const finished = { ...activeEncounter, isActive: false };
                const xpMsg = xpPerPlayer > 0 ? ` Each player gained ${xpPerPlayer} XP.` : "";
                finished.log.push({
                    id: crypto.randomUUID(),
                    timestamp: Date.now(),
                    round: finished.round,
                    message: `Combat ended. Character stats synchronized.${xpMsg}`,
                    type: 'system'
                });

                set({
                    history: [...history, finished],
                    activeEncounter: null,
                    pastStates: [],
                    selectedCombatantId: null
                });
            },

            addCombatant: (combatant) => set((state) => {
                if (!state.activeEncounter) return state;

                let newCombatant = { ...combatant };
                if (state.activeEncounter.isActive) {
                    newCombatant = {
                        ...newCombatant,
                        isJoinedMidRound: true,
                        hasActedThisRound: true // Prevent immediate turn if they roll high
                    };
                }

                const updatedCombatants = sortCombatantsByInitiative([
                    ...state.activeEncounter.combatants,
                    newCombatant
                ]);

                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: updatedCombatants
                    }
                };
            }),

            removeCombatant: (id) => set((state) => {
                if (!state.activeEncounter) return state;
                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: state.activeEncounter.combatants.filter(c => c.id !== id)
                    }
                };
            }),

            clearCombatants: () => set((state) => {
                if (!state.activeEncounter) return state;
                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: []
                    }
                };
            }),

            cancelEncounter: () => set({ activeEncounter: null, pastStates: [], selectedCombatantId: null }),

            rollAllInitiative: () => set((state) => {
                if (!state.activeEncounter) return state;

                const { updatedCombatants, logs } = rollMissingInitiatives(state.activeEncounter.combatants);
                const sorted = sortCombatantsByInitiative(updatedCombatants);

                // Assign current round to new logs
                const roundLogs = logs.map(l => ({ ...l, round: state.activeEncounter!.round }));

                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: sorted,
                        log: [...state.activeEncounter.log, ...roundLogs]
                    }
                };
            }),

            setInitiative: (id, score) => set((state) => {
                if (!state.activeEncounter) return state;

                const updated = state.activeEncounter.combatants.map(c =>
                    c.id === id ? { ...c, initiativeScore: score } : c
                );

                const sorted = sortCombatantsByInitiative(updated);
                const name = updated.find(c => c.id === id)?.name || 'Unknown';

                const logEntry: CombatLogEntry = {
                    id: crypto.randomUUID(),
                    round: state.activeEncounter.round,
                    timestamp: Date.now(),
                    message: `${name} initiative set to ${score}.`,
                    type: 'system',
                    combatantId: id
                };

                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: sorted,
                        log: [...state.activeEncounter.log, logEntry]
                    }
                };
            }),

            beginCombat: () => {
                set((state) => {
                    if (!state.activeEncounter || state.activeEncounter.combatants.length === 0) return state;

                    const firstCombatant = state.activeEncounter.combatants[0];
                    const firstId = firstCombatant.id;

                    const initialLogs = [
                        ...state.activeEncounter.log,
                        { id: crypto.randomUUID(), timestamp: Date.now(), round: 1, message: 'Combat started! Round 1 begins.', type: 'system' },
                        { id: crypto.randomUUID(), timestamp: Date.now(), round: 1, message: `${firstCombatant.name}'s turn.`, type: 'system', combatantId: firstId }
                    ] as CombatLogEntry[];

                    if (firstCombatant.isSurprised) {
                        initialLogs.push({ id: crypto.randomUUID(), timestamp: Date.now(), round: 1, message: `${firstCombatant.name}'s turn is skipped because they are surprised!`, type: 'system', combatantId: firstId });
                    }

                    return {
                        activeEncounter: {
                            ...state.activeEncounter,
                            isActive: true,
                            round: 1,
                            activeCombatantId: firstId,
                            combatants: state.activeEncounter.combatants.map(c =>
                                c.id === firstId
                                    ? { ...c, hasAction: !c.isSurprised, hasBonusAction: !c.isSurprised, hasReaction: !c.isSurprised }
                                    : { ...c, hasAction: true, hasBonusAction: true, hasReaction: true }
                            ),
                            turnState: createBasicTurnState(firstCombatant),
                            log: initialLogs
                        }
                    };
                });

                // If first combatant is surprised, we immediately end their turn so they skip it.
                // The nextTurn function will handle clearing their condition and moving to the next combatant.
                const state = get();
                if (state.activeEncounter?.combatants[0]?.isSurprised) {
                    state.nextTurn();
                }
            },

            nextTurn: () => set((state) => {
                if (!state.activeEncounter || !state.activeEncounter.isActive) return state;

                const enc = state.activeEncounter;

                const logs = [...enc.log];
                let currentCombatants = [...enc.combatants];

                // End of current turn: Condition decrement & Surprise removal
                if (enc.activeCombatantId) {
                    currentCombatants = currentCombatants.map(c => {
                        if (c.id === enc.activeCombatantId) {
                            const newlyRemoved: string[] = [];
                            const updatedConditions = c.conditions.map(cond => {
                                if (cond.duration !== undefined) {
                                    const newDuration = cond.duration - 1;
                                    if (newDuration <= 0) newlyRemoved.push(cond.name);
                                    return { ...cond, duration: newDuration };
                                }
                                return cond;
                            }).filter(cond => cond.duration === undefined || cond.duration > 0);

                            newlyRemoved.forEach(condName => {
                                logs.push({
                                    id: crypto.randomUUID(), timestamp: Date.now(), round: enc.round,
                                    message: `${c.name} is no longer ${condName}.`, type: 'status', combatantId: c.id
                                });
                            });

                            let isSurprised = c.isSurprised;
                            if (isSurprised) {
                                isSurprised = false;
                                logs.push({
                                    id: crypto.randomUUID(), timestamp: Date.now(), round: enc.round,
                                    message: `${c.name} is no longer Surprised.`, type: 'system', combatantId: c.id
                                });
                            }

                            return { ...c, conditions: updatedConditions, isSurprised };
                        }
                        return c;
                    });
                }

                const aliveCombatants = currentCombatants.filter(c => !c.isDead);
                let nextId = getNextCombatant(currentCombatants, enc.activeCombatantId);

                let currentAliveIndex = aliveCombatants.findIndex(c => c.id === enc.activeCombatantId);
                let nextAliveIndex = aliveCombatants.findIndex(c => c.id === nextId);

                let currentRound = enc.round;
                let updatedCombatants = currentCombatants;

                const advanceRoundIfNeeded = () => {
                    if (nextAliveIndex <= currentAliveIndex && nextId !== null) {
                        currentRound++;
                        logs.push({
