            }),

            setReadiedAction: (id, action) => set((state) => {
                if (!state.activeEncounter) return state;
                const pastStates = [...(state.pastStates || []), state.activeEncounter].slice(-10);
                const logEntry: CombatLogEntry | null = action
                    ? { id: crypto.randomUUID(), round: state.activeEncounter.round, timestamp: Date.now(), message: `${state.activeEncounter.combatants.find(c => c.id === id)?.name} readied an action (Trigger: ${action.trigger})`, type: 'system', combatantId: id }
                    : null;
                return {
                    pastStates,
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: state.activeEncounter.combatants.map(c => c.id === id ? { ...c, readiedAction: action || undefined } : c),
                        log: logEntry ? [...state.activeEncounter.log, logEntry] : state.activeEncounter.log
                    }
                };
            }),

            refreshPlayerStats: () => set((state) => {
                if (!state.activeEncounter) return state;
                const pastStates = [...(state.pastStates || []), state.activeEncounter].slice(-10);
                const charStore = useCharacterStore.getState();
                const updatedCombatants = state.activeEncounter.combatants.map(c => {
                    if (c.type !== 'player' || !c.sourceId) return c;
                    const char = charStore.characters.find(ch => ch.id === c.sourceId);
                    if (!char) return c;
                    return {
                        ...c,
                        name: char.name,
                        ac: getArmorClass(char),
                        maxHp: Number(char.maxHp) || c.maxHp,
                        currentHp: Math.min(c.currentHp, Number(char.maxHp) || c.maxHp),
                        speed: char.speed || c.speed,
                        abilityScores: char.abilityScores ? {
                            str: Number(char.abilityScores.str) || 10,
                            dex: Number(char.abilityScores.dex) || 10,
                            con: Number(char.abilityScores.con) || 10,
                            int: Number(char.abilityScores.int) || 10,
                            wis: Number(char.abilityScores.wis) || 10,
                            cha: Number(char.abilityScores.cha) || 10,
                        } : c.abilityScores,
                        dexterityScore: getEffectiveAbilityScore(char, 'dex'),
                        initiativeMod: getInitiative(char),
                        proficiencyBonus: Number(char.proficiencyBonus) || c.proficiencyBonus,
                        savingThrowProficiencies: char.savingThrows || c.savingThrowProficiencies,
                        spellcastingAbility: char.spellcastingAbility || c.spellcastingAbility,
                        spellSaveDc: Number(char.spellSaveDc) || c.spellSaveDc,
                        spellAttackMod: Number(char.spellAttackMod) || c.spellAttackMod,
                        resistances: char.resistances || c.resistances,
                        immunities: char.immunities || c.immunities,
                        vulnerabilities: char.vulnerabilities || c.vulnerabilities,
                        conditionImmunities: char.conditionImmunities || c.conditionImmunities,
                        damageNotes: char.damageNotes || c.damageNotes,
                        spellSlots: char.spellSlots || c.spellSlots,
                    };
                });
                return {
                    pastStates,
                    activeEncounter: {
                        ...state.activeEncounter,
                        combatants: updatedCombatants
                    }
                };
            }),

            addLog: (entry) => set((state) => {
                if (!state.activeEncounter) return state;
                const fullEntry: CombatLogEntry = {
                    ...entry,
                    id: crypto.randomUUID(),
                    timestamp: Date.now(),
                    round: state.activeEncounter.round
                };
                return {
                    activeEncounter: {
                        ...state.activeEncounter,
                        log: [...state.activeEncounter.log, fullEntry]
                    }
                };
            })
        }),
        {
            name: 'dm-assistant-combat',
            partialize: (state) => ({
                activeEncounter: state.activeEncounter,
                history: state.history,
                savedEncounters: state.savedEncounters
            }),
            onRehydrateStorage: () => (state) => {
                if (!state) return;
                const sanitizeCombatants = (combatants: any[]) =>
                    combatants.map(c => ({
                        ...c,
                        maxHp: Math.min(Math.max(Number(c.maxHp) || 1, 1), c.type === 'monster' ? 9999 : 999),
                        currentHp: Math.min(Math.max(Number(c.currentHp) || 0, 0), c.type === 'monster' ? 9999 : 999),
                        tempHp: Math.min(Math.max(Number(c.tempHp) || 0, 0), 999),
                        abilityScores: c.abilityScores ? {
                            str: Math.min(Math.max(Number(c.abilityScores.str) || 10, 1), 30),
                            dex: Math.min(Math.max(Number(c.abilityScores.dex) || 10, 1), 30),
                            con: Math.min(Math.max(Number(c.abilityScores.con) || 10, 1), 30),
                            int: Math.min(Math.max(Number(c.abilityScores.int) || 10, 1), 30),
                            wis: Math.min(Math.max(Number(c.abilityScores.wis) || 10, 1), 30),
                            cha: Math.min(Math.max(Number(c.abilityScores.cha) || 10, 1), 30),
                        } : c.abilityScores,
                    }));

                if (state.activeEncounter) {
                    state.activeEncounter.combatants = sanitizeCombatants(state.activeEncounter.combatants);
                }
                state.history = (state.history || []).map(enc => ({
                    ...enc,
                    combatants: sanitizeCombatants(enc.combatants)
                }));
                state.savedEncounters = state.savedEncounters || [];
            }
        }
    )
);

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { NavigatorState, SourceDocument, NarrativeScene, LinkedEntity, DungeonMap } from '../types/campaignNavigator';
import { MapToken } from '../types/battleMap';
import { indexedDbStorage } from './indexedDbAdapter';
import { MOCK_NARRATIVE, MOCK_DUNGEON_MAPS } from '../data/mockNarrative';
import { DEFAULT_DUNGEON_GRID } from '../engine/mapBridge';

interface NavigatorActions {
    // Basic navigation
    setActiveNarrative: (id: string | null) => void;
    navigateToScene: (sceneId: string) => void;
    goBack: () => void;

    // PDF Handling (WIP)
    addSourceDocument: (doc: SourceDocument) => void;
    setProcessing: (isProcessing: boolean, progress: string) => void;

    // Entity Enrichment
    cacheEntity: (key: string, entity: LinkedEntity) => void;

    // Map Interactions
    setPartyRoom: (roomId: string | null) => void;
    revealRoom: (mapId: string, roomId: string) => void;
    setActiveFloor: (floorId: string) => void;

    // Map Setup Editor
    updateMapImage: (mapId: string, imageUrl?: string) => void;
    updateRoomPosition: (mapId: string, roomId: string, pos: { x: number, y: number, width: number, height: number }) => void;

    // Tactical Grid Actions
    updateDungeonMapGrid: (mapId: string, updates: Partial<Pick<DungeonMap, 'gridWidth' | 'gridHeight' | 'cellSizePx' | 'gridColor'>>) => void;
    updateDungeonMapToken: (mapId: string, tokenId: string, updates: Partial<MapToken>) => void;
    addDungeonMapToken: (mapId: string, token: MapToken) => void;
    removeDungeonMapToken: (mapId: string, tokenId: string) => void;
    updateDungeonMapBattleState: (mapId: string, updates: Partial<Pick<DungeonMap, 'shapes' | 'freehandPaths' | 'fogOfWar' | 'fogOfWarFreehand' | 'backgroundOffset' | 'backgroundScaleX' | 'backgroundScaleY' | 'imageUrl' | 'tokens'>>) => void;

    // Reset/Debug
    loadMockData: () => void;
    updateNarrationBlock: (sceneId: string, blockId: string, text: string) => void;
}

export const useNavigatorStore = create<NavigatorState & NavigatorActions>()(
    persist(
        (set) => ({
            // ─────────────────────────────────────────────────────────
            // STATE
            // ─────────────────────────────────────────────────────────
            sourceDocuments: [],
            narratives: [],
            dungeonMaps: [],
            activeNarrativeId: null,
            currentSceneId: null,
            isProcessing: false,
            processingProgress: '',
            enrichmentCache: {},
            partyRoomId: null,
            sceneHistory: [],
            activeFloorId: null,

            // ─────────────────────────────────────────────────────────
            // ACTIONS
            // ─────────────────────────────────────────────────────────
            setActiveNarrative: (id) => set({ activeNarrativeId: id }),

            navigateToScene: (sceneId) => set((state) => {
                const narrative = state.narratives.find(n => n.id === state.activeNarrativeId);
                if (!narrative) return state;

                // Push current scene to history before navigating
                const newHistory = state.currentSceneId
                    ? [...state.sceneHistory, state.currentSceneId]
                    : state.sceneHistory;

                // Find the scene to determine its floor and room
                let targetScene: NarrativeScene | null = null;
                for (const ch of narrative.chapters) {
                    const found = ch.scenes.find(s => s.id === sceneId);
                    if (found) { targetScene = found; break; }
                }

                // Auto-detect floor and room from scene
                const newFloorId = targetScene?.mapFloorId ?? state.activeFloorId;
                const newPartyRoomId = targetScene?.mapRoomId ?? state.partyRoomId;
                const oldPartyRoomId = state.partyRoomId;

                // Auto-sync map room statuses
                const newDungeonMaps = state.dungeonMaps.map(m => {
                    let changed = false;
                    const newRooms = m.rooms.map(r => {
                        const room = { ...r };
                        if (r.id === oldPartyRoomId && oldPartyRoomId !== newPartyRoomId && r.status === 'current') {
                            room.status = 'explored';
                            changed = true;
                        }
                        if (newPartyRoomId && r.id === newPartyRoomId) {
                            room.isRevealed = true;
                            room.status = 'current';
                            changed = true;
                        }
                        return room;
                    });
                    return changed ? { ...m, rooms: newRooms } : m;
                });

                return {
                    currentSceneId: sceneId,
                    sceneHistory: newHistory,
                    activeFloorId: newFloorId,
                    partyRoomId: newPartyRoomId,
                    dungeonMaps: newDungeonMaps,
                    narratives: state.narratives.map(n =>
                        n.id === state.activeNarrativeId
                            ? { ...n, currentSceneId: sceneId, visitedSceneIds: [...new Set([...n.visitedSceneIds, sceneId])] }
                            : n
                    )
                };
            }),

            goBack: () => set((state) => {
                if (state.sceneHistory.length === 0) return state;

                const newHistory = [...state.sceneHistory];
                const previousSceneId = newHistory.pop()!;

                const narrative = state.narratives.find(n => n.id === state.activeNarrativeId);
                let targetScene: NarrativeScene | null = null;
                if (narrative) {
                    for (const ch of narrative.chapters) {
                        const found = ch.scenes.find(s => s.id === previousSceneId);
                        if (found) { targetScene = found; break; }
                    }
                }

                const newFloorId = targetScene?.mapFloorId ?? state.activeFloorId;
                const newPartyRoomId = targetScene?.mapRoomId ?? state.partyRoomId;
                const oldPartyRoomId = state.partyRoomId;

                // Auto-sync map room statuses
                const newDungeonMaps = state.dungeonMaps.map(m => {
                    let changed = false;
                    const newRooms = m.rooms.map(r => {
                        const room = { ...r };
                        if (r.id === oldPartyRoomId && oldPartyRoomId !== newPartyRoomId && r.status === 'current') {
                            room.status = 'explored';
                            changed = true;
                        }
                        if (newPartyRoomId && r.id === newPartyRoomId) {
                            room.isRevealed = true;
                            room.status = 'current';
                            changed = true;
                        }
                        return room;
                    });
                    return changed ? { ...m, rooms: newRooms } : m;
                });

                return {
                    currentSceneId: previousSceneId,
                    sceneHistory: newHistory,
                    activeFloorId: newFloorId,
                    partyRoomId: newPartyRoomId,
                    dungeonMaps: newDungeonMaps
                };
            }),

            addSourceDocument: (doc) => set((state) => ({
                sourceDocuments: [...state.sourceDocuments, doc]
            })),

            setProcessing: (isProcessing, progress) => set({ isProcessing, processingProgress: progress }),

            cacheEntity: (key, entity) => set((state) => ({
                enrichmentCache: { ...state.enrichmentCache, [key]: entity }
            })),

            setPartyRoom: (roomId) => set({ partyRoomId: roomId }),

            revealRoom: (mapId, roomId) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId
                        ? { ...m, rooms: m.rooms.map(r => r.id === roomId ? { ...r, isRevealed: true } : r) }
                        : m
                )
            })),

            setActiveFloor: (floorId) => set({ activeFloorId: floorId }),

            loadMockData: () => set({
                narratives: [MOCK_NARRATIVE],
                dungeonMaps: MOCK_DUNGEON_MAPS,
                activeNarrativeId: MOCK_NARRATIVE.id,
                currentSceneId: MOCK_NARRATIVE.currentSceneId,
                partyRoomId: MOCK_DUNGEON_MAPS[0].rooms[0].id,
                sceneHistory: [],
                activeFloorId: MOCK_DUNGEON_MAPS[0].floorId,
            }),

            updateNarrationBlock: (sceneId, blockId, text) => set((state) => ({
                narratives: state.narratives.map(n => ({
                    ...n,
                    chapters: n.chapters.map(ch => ({
                        ...ch,
                        scenes: ch.scenes.map(sc =>
                            sc.id === sceneId
                                ? {
                                    ...sc,
                                    narrationBlocks: sc.narrationBlocks.map(b =>
                                        b.id === blockId ? { ...b, text } : b
                                    )
                                }
                                : sc
                        )
                    }))
                }))
            })),

            updateMapImage: (mapId, imageUrl) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? { ...m, imageUrl } : m
                )
            })),

            updateRoomPosition: (mapId, roomId, pos) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? {
                        ...m,
                        rooms: m.rooms.map(r => r.id === roomId ? { ...r, ...pos } : r)
                    } : m
                )
            })),

            // ── Tactical Grid Actions ──

            updateDungeonMapGrid: (mapId, updates) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? { ...m, ...updates } : m
                )
            })),

            updateDungeonMapToken: (mapId, tokenId, updates) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? {
                        ...m,
                        tokens: m.tokens.map(t => t.id === tokenId ? { ...t, ...updates } : t)
                    } : m
                )
            })),

            addDungeonMapToken: (mapId, token) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? { ...m, tokens: [...m.tokens, token] } : m
                )
            })),

            removeDungeonMapToken: (mapId, tokenId) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? {
                        ...m,
                        tokens: m.tokens.filter(t => t.id !== tokenId)
                    } : m
                )
            })),

            updateDungeonMapBattleState: (mapId, updates) => set((state) => ({
                dungeonMaps: state.dungeonMaps.map(m =>
                    m.id === mapId ? { ...m, ...updates } : m
                )
            })),
        }),
        {
            name: 'dm-assistant-navigator',
            storage: createJSONStorage(() => indexedDbStorage),
            partialize: (state) => ({
                sourceDocuments: state.sourceDocuments,
                narratives: state.narratives,
                dungeonMaps: state.dungeonMaps,
                activeNarrativeId: state.activeNarrativeId,
                currentSceneId: state.currentSceneId,
                enrichmentCache: state.enrichmentCache,
                partyRoomId: state.partyRoomId,
                sceneHistory: state.sceneHistory,
                activeFloorId: state.activeFloorId,
            }),
            // Migrate stale DungeonMap data lacking tactical grid fields
            merge: (persisted: any, current: NavigatorState & NavigatorActions) => {
                const merged = { ...current, ...(persisted as object) };
                if (Array.isArray(merged.dungeonMaps)) {
                    merged.dungeonMaps = merged.dungeonMaps.map((m: any) => ({
                        ...m,
                        gridWidth: m.gridWidth || DEFAULT_DUNGEON_GRID.gridWidth,
                        gridHeight: m.gridHeight || DEFAULT_DUNGEON_GRID.gridHeight,
                        cellSizePx: m.cellSizePx || DEFAULT_DUNGEON_GRID.cellSizePx,
                        gridColor: m.gridColor || DEFAULT_DUNGEON_GRID.gridColor,
                        tokens: m.tokens || DEFAULT_DUNGEON_GRID.tokens,
                        shapes: m.shapes || DEFAULT_DUNGEON_GRID.shapes,
                        freehandPaths: m.freehandPaths || DEFAULT_DUNGEON_GRID.freehandPaths,
                        fogOfWar: m.fogOfWar || DEFAULT_DUNGEON_GRID.fogOfWar,
                        fogOfWarFreehand: m.fogOfWarFreehand || DEFAULT_DUNGEON_GRID.fogOfWarFreehand,
                    }));
                }
                return merged;
            }
        }
    )
);

import { Action } from './actions';
export type { Action } from './actions';
import type { ClassEntry, Effect } from './rules';
export type { ClassEntry, Effect } from './rules';

export type SystemType = 'dnd5e' | 'v20';

export interface StatBlock {
    str: number;
    dex: number;
    con: number;
    int: number;
    wis: number;
    cha: number;
}

export interface Skill {
    name: string;
    stat: keyof StatBlock;
    proficient: boolean;
    expertise: boolean;
    bonus: number; // For manual overrides or magic item bonuses
    source?: string; // e.g., "Rogue", "Acolyte", "Elf"
    sourceId?: string; // ID of the feature or background that granted it
}

export interface Resource {
    id: string;
    name: string;
    current: number;
    max: number;
    resetOn: 'short' | 'long' | 'never';
}

export interface Item {
    id: string;
    name: string;
    quantity: number;
    weight: number;
    isEquipped: boolean;
    isAttuned: boolean;
    description: string;
    type: 'weapon' | 'armor' | 'potion' | 'scroll' | 'gear' | 'magic' | 'other';
    damage?: string; // e.g., "1d8+STR"
    acBonus?: number;
    effects?: Effect[];
    isHomebrew?: boolean;
    homebrewSource?: string;
    is2024?: boolean;
}

export interface Spell {
    id: string;
    name: string;
    level: number; // 0 for cantrip
    school: string;
    castingTime: string;
    range: string;
    components: { v: boolean; s: boolean; m: boolean; mDesc?: string };
    duration: string;
    concentration: boolean;
    ritual: boolean;
    description: string;
    higherLevels?: string;
    prepared: boolean;
    isHomebrew?: boolean;
    homebrewSource?: string;
    source?: string;
    is2024?: boolean;
}

export interface Condition {
    id: string;
    name: string;
    type?: 'buff' | 'condition';
    icon?: string;
    duration?: number; // Rounds remaining
    description: string;
}

export interface Feature {
    id: string;
    name: string;
    source: string; // e.g., "Fighter Level 1", "Feat"
    description: string;
    hasUses: boolean;
    usesCurrent?: number;
    usesMax?: number;
    resetOn?: 'short' | 'long' | 'never';
    isFeat?: boolean;
    requiresChoice?: boolean;
    choiceType?: string;
    prerequisite?: any;
    count?: number;
    abilityScoreBonuses?: Partial<StatBlock>;
    grantsProficiency?: string[];
    grantsLanguage?: string[];
    grantsSkillProficiency?: string[];
    grantsResistance?: string[];
    effects?: Effect[];
    source5eTools?: string;
    isHomebrew?: boolean;
    homebrewSource?: string;
    is2024?: boolean;
}

export interface Currencies {
    cp: number;
    sp: number;
    ep: number;
    gp: number;
    pp: number;
}

export interface Character {
    id: string;
    name: string;
    system: SystemType;
    playerName: string;
    portraitUrl?: string;

    // D&D 5e Specific Core
    race: string;
    className: string;
    subclass: string;
    level: number;
    background: string;
    alignment: string;
    experience: number;
    /**
     * Multiclass support: all class entries including primary class.
     * Optional for backward compatibility — single-class characters
     * only use `className` / `subclass` / `level`.
     */
    classes?: ClassEntry[];

    // Stats & Skills
    abilityScores: StatBlock;
    savingThrows: (keyof StatBlock)[];
    skills: Skill[];
    senses: string; // e.g., "Darkvision 60ft"
    darkvision?: number;
    passivePerception: number;
    passiveInvestigation: number;
    passiveInsight: number;
    languages: string;
    proficiencies: string; // Tools, weapons, armor

    // Combat
    ac: number;
    maxHp: number;
    currentHp: number;
    tempHp: number;
    hitDice: string; // e.g., "5d10"
    speed: string; // string to allow "30ft, Fly 60ft"
    initiativeMod: number; // Usually matches DEX mod, but can be altered
    proficiencyBonus: number;

    // Magic
    spellcastingAbility: keyof StatBlock | 'none';
    spellSaveDc: number;
    spellAttackMod: number;
    spellSlots: { current: number; max: number }[]; // Index 0 isCantrips (usually ignored), 1=1st level
    spells: Spell[];

    // Equipment & Economy
    inventory: Item[];
    currencies: Currencies;

    // Abilities
    resources: Resource[];
    actions: Action[];
    features: Feature[];
    feats: Feature[];
    racialTraits: Feature[];
    masteredWeapons: string[]; // List of weapon names (e.g. "Longsword", "Shortbow")

    // State
    conditions: Condition[];
    deathSaves: { successes: number; failures: number };
    exhaustion: number; // 0-6
    resistances: string[];
    immunities: string[];
    vulnerabilities: string[];
    conditionImmunities: string[];
    damageNotes: string;

    // Flavors
    personalityTraits: string;
    ideals: string;
    bonds: string;
    flaws: string;
    backstory: string;
    notes: string;

    // Choice Tracking (Added Phase 8)
    pendingChoices?: Array<{
        id: string;
        type: 'skill' | 'language' | 'feat' | 'subclass' | 'equipment';
        count: number;
        options: string[]; // List of names or categories
        source: string; // e.g. "Rogue level 1"
        isResolved: boolean;
        selected?: string[];
    }>;

    // Custom DM Overrides (Added Phase 3.5, expanded Phase 5)
    customOverrides?: {
        maxAction?: number;
        maxBonusAction?: number;
        maxReaction?: number;
        extraMovement?: number;
        ignoreEconomy?: boolean; // The DM "Make it happen" toggle
        modifiers?: Record<string, number>; // DM Modifiers (e.g. { ac: 2, speed: -10 })
        overrides: Array<{
            id: string;
            field: string;       // e.g. "ac", "maxHp", "speed", "proficiencyBonus"
            label: string;       // Display name
            value: string | number;
            isActive: boolean;
            reason: string;      // DM note for why
        }>;
    };

    // Stored import references (Added Phase 3.6)
    importedData?: {
        race?: any;
        class?: any;
        background?: any;
        subclass?: any;
    };
}

